int main(int argc, char *argv[]) {
    int opt;
    FILE *input_files = NULL;
    FILE *output_file = stdout;
    log_level_t log_level = LOG_INFO;

    while ((opt = getopt(argc, argv, "vdl:")) != -1) {
        switch (opt) {
            case 'v':
                log_level = VERBOSE;
                break;
            case 'd':
                input_files = fopen(optarg, "r");
                if (!input_files) {
                    fprintf(stderr, "Error opening file '%s'\n", optarg);
                    return 1;
                }
                break;
            case 'l':
                log_level = parse_log_level(optarg);
                break;
            default:
                print_usage();
                return 0;
        }
    }

    if (argc <= 1) {
        print_usage();
        return 0;
    }

    int line_count = process_input_files(argc - optind, argv + optind, output_file);

    fclose(input_files);
    return line_count;
}

void print_usage() {
    printf("Usage: %s [-v] [-d file] [-l log_level] [files]\n", argv0);
    printf("-v  verbose mode\n");
    printf("-d  input file path (multiple files allowed)\n");
    printf("-l  log level (NONE, VERBOSE, LOG_INFO, LOG_WARN, LOG_ERROR)\n");
}

