        FILE *input_file = fopen(argv[i], "r");
        if (!input_file) {
            fprintf(stderr, "Error opening file '%s'\n", argv[i]);
            continue;
        }

        char line[1024];
        while (fgets(line, sizeof(line), input_file)) {
            ++line_count;
        }
        fclose(input_file);
    }

    return line_count;
}

int get_delimiter(const char *delim) {
    // implement custom delimiter logic here
    return 0;
}

log_level_t parse_log_level(const char *level) {
    if (strcmp(level, "NONE") == 0)
        return NONE;
    else if (strcmp(level, "VERBOSE") == 0)
        return VERBOSE;
    else if (strcmp(level, "LOG_INFO") == 0)
        return LOG_INFO;
    else if (strcmp(level, "LOG_WARN") == 0)
        return LOG_WARN;
    else if (strcmp(level, "LOG_ERROR") == 0)
        return LOG_ERROR;
    else {
        fprintf(stderr, "Invalid log level '%s'\n", level);
        return NONE;
    }
}
