#define DNS_RESOLUTION_MAX_LENGTH 256
#define DNS_RESOLUTION_CONCURRENT_REQUESTS 5
#define DNS_RESOLUTION_TIMEOUT 10000 // in milliseconds

typedef struct {
    uint8_t ip[INET6_ADDRSTRLEN];
} u_char;

u_char* dns_resolution(const char* hostname) {
    int status;
    struct hostent *he;
    struct in_addr **ip_list;
    int count;
    u_char* result = NULL;
    time_t start_time = time(NULL);

    // Set the limits for DNS resolution
    setrlimit(RLIMIT_NFILE, (struct rlimit){1, 10});
    setrlimit(RLIMIT_CORE, (struct rlimit){0, 100000});

    // Perform the DNS resolution
    he = gethostbyname(hostname);
    if (!he) {
        // If no result found, check for timeouts or errors
        if ((time(NULL) - start_time) > DNS_RESOLUTION_TIMEOUT) {
            return NULL;
        }
        else {
            // Handle other error conditions (e.g., network issues)
            status = -1;
            return NULL;
        }
    }

    // Get the IP addresses from the hostent structure
    ip_list = (struct in_addr **)he->h_addr_list;
    count = he->h_length;

    // Allocate memory for the result array
    if ((result = malloc(count * sizeof(u_char))) == NULL) {
        return NULL;
    }

    // Copy the IP addresses into the result array
    for (int i = 0; i < count; i++) {
        inet_ntop(AF_INET, &ip_list[i], (char*)result->ip, INET6_ADDRSTRLEN);
    }

    free(ip_list);

    return result;
}
