#include <stdio.h>
#include <stdlib.h>

void printLargestAndUnique(int* arr, int size) {
    int max = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("The largest integer is: %d\n", max);

    int uniqueCount = 0;
    for (int i = 0; i < size; i++) {
        int found = 0;
        for (int j = 0; j < size; j++) {
            if (arr[i] == arr[j]) {
                found++;
            }
        }
        if (found == 1) {
            uniqueCount++;
        }
    }
    printf("The number of unique integers is: %d\n", uniqueCount);
}

int main() {
    int maxSize = 1000;
    int maxVal = 10000;

    int* arr = NULL;
    int size = 0;

    while (1) {
        int val;
        if ((scanf("%d", &val)) != 1) {
            break; // invalid input, exit loop
        }
        if (size >= maxSize || val < 0 || val >= maxVal) {
            printf("No integers received.\n");
            return 1;
        }
        size++;
        arr = realloc(arr, sizeof(int) * (size + 1));
        arr[size - 1] = val;
    }

    if (size > 0) {
        printLargestAndUnique(arr, size);
        free(arr);
    }

    return 0;
}
