#define MAX_LOG_ID 64
#define MAX_MESSAGE 1024

typedef struct {
    time_t timestamp;
    int log_id;
    char* message;
} LogEntry;

LogEntry* create_log_entry(int id) {
    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    entry->timestamp = time(NULL);
    entry->log_id = id;
    entry->message = NULL;
    return entry;
}

void free_log_entries(LogEntry** entries, int count) {
    for (int i = 0; i < count; i++) {
        if (entries[i]->message != NULL) {
            free(entries[i]->message);
        }
        free(entries[i]);
    }
    free(entries);
}

void log_error(int condition, char* format, ...) {
    if (!condition) return;

    va_list args;
    va_start(args, format);

    int count = 0;
    while (1) {
        char buffer[MAX_MESSAGE];
        vsnprintf(buffer, MAX_MESSAGE - 1, format, args);
        buffer[MAX_MESSAGE - 1] = '\0';

        LogEntry* entry = create_log_entry(count++);
        entry->message = malloc(strlen(buffer) + 1);
        strcpy(entry->message, buffer);

        // Send log entry to external logging service
        // ...

        free(entry->message);
        free(entry);

        if (!va_arg(args, int)) break;
    }

    va_end(args);
}

int main() {
    log_error(1, "Error: %d", 123, 456, NULL);
    log_error(0, "Info: %s", "hello");
    // ...

    return 0;
}
