bool validate_json(const char* json) {
    cJSON *root = cJSON_Parse(json);
    if (!root) {
        return false;
    }

    cJSON *access_token = cJSON_GetObjectItem(root, "access_token");
    cJSON *expires_in = cJSON_GetObjectItem(root, "expires_in");
    cJSON *token_type = cJSON_GetObjectItem(root, "token_type");

    if (!access_token || !expires_in || !token_type) {
        return false;
    }

    if (strcmp(token_type->valuestring, "Bearer") != 0) {
        cJSON_Delete(root);
        return false;
    }

    int expires_int = atoi(expires_in->valuestring);
    if (expires_int <= 0) {
        cJSON_Delete(root);
        return false;
    }

    cJSON_Delete(root);
    return true;
}
