import java.util.*;

public class PokemonReport {
    public static String generateReport(Pokemon pokemon) {
        StringBuilder report = new StringBuilder();

        // Retrieve name and type from external library functions
        String pokémonName = getSimpleName(pokemon);
        String pokémonType = getType(pokemon);

        report.append("Pokémon Name: ").append(pokémonName).append("\n");
        report.append("Pokémon Type: ").append(pokémonType).append("\n\n");

        // Determine weaknesses and strengths based on the Pokémon's type
        switch (pokémonType) {
            case "Fire":
                report.append("Weaknesses: Water, Rock, Fire-resistant\n");
                report.append("Strengths: Bug, Grass, Steel\n");
                break;
            case "Water":
                report.append("Weaknesses: Electric, Grass, Fire\n");
                report.append("Strengths: Fire, Water-resistant\n");
                break;
            // Add more type combinations as needed
        }

        // Calculate compatibility score for each type combination
        Map<String, Double> compatibilityScores = new HashMap<>();
        for (String otherType : getTypeCombinations()) {
            double sharedWeaknesses = getSharedWeaknessCount(pokemon, otherType);
            double sharedStrengths = getSharedStrengthCount(pokemon, otherType);
            double score = ((double) sharedWeaknesses + sharedStrengths) / 2;
            compatibilityScores.put(otherType, score * 100.0);
        }

        report.append("Compatibility Scores:\n");
        for (Map.Entry<String, Double> entry : compatibilityScores.entrySet()) {
            report.append(entry.getKey()).append(": ").append(String.format("%.2f", entry.getValue())).append("%\n");
        }

        // Fetch additional data from external database
        Map<String, String> typeEffectiveness = getTypeEffectiveness(pokemon);
        Map<String, Integer> rarity = getRarity(pokemon);

        report.append("\nType Effectiveness:\n");
        for (Map.Entry<String, String> entry : typeEffectiveness.entrySet()) {
            report.append(entry.getKey()).append(": ").append(entry.getValue()).append("\n");
        }

        report.append("Rarity: ");
        for (Map.Entry<String, Integer> entry : rarity.entrySet()) {
            report.append(entry.getKey()).append(": ").append(entry.getValue()).append(", ");
        }
        report.append("\n");

        // Log all operations
        logOperations(pokemon);

        return report.toString();
    }

