#include <string.h>

typedef struct {
    unsigned char* data;
    size_t size;
} Chunk;

Chunk* get_chunk(const char* filename, size_t chunk_size) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        return NULL; // Handle error
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    Chunk* chunks = (Chunk*)malloc((file_size / chunk_size + 1) * sizeof(Chunk));
    for (size_t i = 0; i < file_size / chunk_size + 1; ++i) {
        size_t remaining = file_size - i * chunk_size;
        size_t read_size = (remaining > chunk_size ? chunk_size : remaining);
        chunks[i].data = malloc(read_size);
        fread(chunks[i].data, 1, read_size, file);
        chunks[i].size = read_size;
    }

    fclose(file);
    return chunks;
}

int main() {
    const char* filename = "path_to_your_file";
    size_t chunk_size = 1024 * 1024; // Adjust to your desired chunk size
    Chunk* chunks = get_chunk(filename, chunk_size);

    if (!chunks) {
        return -1; // Handle error
    }

    EVP_MD_CTX mdctx;
    EVP_MD_CTX_init(&mdctx);
    EVP_add_hash_digest(&mdctx, "MD5");
    unsigned char hash[16];
    size_t hash_len = EVP_get_digest_length(EVP_md_md5());
    EVP_MDDigest(&mdctx, hash);

    for (size_t i = 0; i < file_size / chunk_size + 1; ++i) {
        for (size_t j = 0; j < chunks[i].size; ++j) {
            unsigned char c = *(unsigned char*)chunks[i].data;
            EVP_update(&mdctx, &c, 1);
        }
    }

    EVP_Finalize();
    free(chunks);

    // Now you can use the 'hash' array as needed
}
