class SandeshClient {
public:
    SandeshClient(int maxThreads, int queueSize)
        : io_(io_service_), threadPool_(maxThreads, queueSize) {}

    void sendGetRequests(int numRequests) {
        for (int i = 0; i < numRequests; ++i) {
            boost::asio::io_service::work work(io_);
            auto request = std::make_shared<boost::asio::io_service::work>(work);
            threadPool_.post([this, request]() {
                try {
                    sendGetRequest(*request);
                } catch (const boost::system::system_error& e) {
                    handleNetworkError(e.what());
                } catch (...) {
                    handleError("Unknown error");
                }
            });
        }
    }

private:
    void sendGetRequest(const boost::asio::io_service::work&) {
        // Send GET request to the server
    }

    void handleNetworkError(const std::string& message) {
        ++networkErrors_;
        logStatistic("Network Error", "Total: " + std::to_string(networkErrors_));
    }

    void handleError(const std::string& message) {
        ++internalErrors_;
        logStatistic("Internal Error", "Total: " + std::to_string(internalErrors_));
    }

    void logStatistic(const std::string& category, const std::string& message) {
        // Log statistics every minute
    }

private:
    boost::asio::io_service io_;
    boost::thread_pool threadPool_;
    int networkErrors_ = 0;
    int internalErrors_ = 0;
};

int main() {
    SandeshClient client(1000, 100);
    client.sendGetRequests(10000);

