#include <string>

namespace LoggingFramework {
    enum class LogLevel { DEBUG, INFO, WARNING, ERROR };

    class Logger {
    public:
        Logger(LogLevel logLevel = LogLevel::INFO,
               std::string destination = "console")
            : logLevel_(logLevel), destination_(destination) {}

        void setLogLevel(LogLevel level) {
            logLevel_ = level;
        }

        template <typename... Args>
        void log(LogLevel level, const char* message, Args&&... args) {
            if (level >= logLevel_) {
                std::string output = message;

                // Append formatted arguments to the output string
                size_t pos = 0;
                do {
                    pos = output.find("{}", pos);
                    if (pos != std::string::npos) {
                        output.replace(pos, 2, std::forward<decltype(args)>(args).as<std::string>());
                        pos += 2;
                    }
                } while (pos != std::string::npos);

                // Write to destinations
                switch (destination_) {
                case "console":
                    std::cout << output << std::endl;
                    break;
                case "file":
                    std::lock_guard<std::mutex> lock(mutex_);
                    file_ << output << std::endl;
                    break;
                }
            }
        }

    private:
        LogLevel logLevel_;
        std::string destination_;
        std::ofstream file_;
        std::mutex mutex_;
    };

    class LogSink {
    public:
        virtual void write(const std::string& message) = 0;

        ~LogSink() {}
    };
}
