resource_data = {
    1: {"name": "Resource 1", "status": "active"},
    2: {"name": "Resource 2", "status": "active"}
}

def get_resource(resource_id):
    return resource_data.get(resource_id)

@app.route('/resources/<int:resource_id>', methods=['GET'])
def retrieve_resource(resource_id):
    resource = get_resource(resource_id)
    if resource:
        return jsonify({"data": resource, "timestamp": str(datetime.datetime.now())})
    else:
        return jsonify({"error": "Resource not found"}), 404

@app.route('/resources/<int:resource_id>', methods=['PATCH'])
def archive_resource(resource_id):
    resource = get_resource(resource_id)
    if resource and resource["status"] == "active":
        resource["status"] = "archived"
        return jsonify({"data": resource, "timestamp": str(datetime.datetime.now())})
    else:
        return jsonify({"error": "Resource not found or already archived"}), 404

if __name__ == '__main__':
    app.run(debug=True)
