using System;
using System.Collections.Generic;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public List<XmlElement> GetElementsByTagName(string xmlDoc, string elementName, string attributeName = null, string attributeValue = null)
    {
        List<XmlElement> elements = new List<XmlElement>();

        XPathDocument document = new XPathDocument(xmlDoc);
        XPathNavigator navigator = document.CreateNavigator();

        XPathExpression expression = navigator.Compile("/" + elementName);

        XPathNodeIterator nodes = navigator.Select(expression);

        while (nodes.MoveNext())
        {
            XmlElement node = nodes.Current as XmlElement;
            elements.Add(node);
        }

        if (!string.IsNullOrEmpty(attributeName) && !string.IsNullOrEmpty(attributeValue))
        {
            for (int i = 0; i < elements.Count; i++)
            {
                XPathNavigator attributeNavigator = navigator.Compile("/" + elementName + "[" + attributeName + "='" + attributeValue + "']");
                XPathNodeIterator attributeNodes = attributeNavigator.Select();

                if (!attributeNodes.MoveNext())
                {
                    elements.RemoveAt(i);
                    i--;
                }
            }
        }

        return elements;
    }
}
