import javax.crypto.Mac;
import javax.crypto.SecretKeyFactory;
import javax.crypto.spec.SecretKeySpec;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.nio.charset.StandardCharsets;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MD5Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5Hasher.class);
    private static final int MAX_INPUT_LENGTH = 256;
    private static final String MD5_ALGORITHM = "MD5";

    public static String getMD5Hash(String input) throws Exception {
        if (input == null || input.length() > MAX_INPUT_LENGTH) {
            if (input.length() > MAX_INPUT_LENGTH) {
                LOGGER.warn("Input string exceeds maximum length of {} characters. Truncating to {} characters.", MAX_INPUT_LENGTH, MAX_INPUT_LENGTH);
            }
            input = input.substring(0, Math.min(input.length(), MAX_INPUT_LENGTH));
        }

        try {
            MessageDigest md = MessageDigest.getInstance(MD5_ALGORITHM);
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));

            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) {
                    hexString.append('0');
                }
                hexString.append(hex);
            }

            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new Exception("Error calculating MD5 hash: " + e.getMessage());
        }
    }
}
