function handleUserRequest() {
    $validate = new Validate();
    $save = new Save();

    if (!isset($_REQUEST['sub_action'])) {
        return json_encode(array('status' => 'error', 'message' => 'Invalid request: no sub-action specified'));
    }

    switch ($_REQUEST['sub_action']) {
        case 'create':
            if (!$validate->validateUserCreateData($_REQUEST)) {
                return json_encode(array('status' => 'error', 'message' => $validate->getError()));
            }
            break;
        case 'update':
            if (!isset($_REQUEST['id'])) {
                return json_encode(array('status' => 'error', 'message' => 'Invalid request: ID not specified'));
            }
            if (!$validate->validateUserUpdateData($_REQUEST)) {
                return json_encode(array('status' => 'error', 'message' => $validate->getError()));
            }
            break;
        case 'delete':
            if (!isset($_REQUEST['id'])) {
                return json_encode(array('status' => 'error', 'message' => 'Invalid request: ID not specified'));
            }
            break;
        default:
            return json_encode(array('status' => 'error', 'message' => 'Invalid sub-action'));
    }

    $result = array();
    if (isset($_REQUEST['id'])) {
        // Perform RBAC check and update user data
        $user = new User($_REQUEST['id']);
        if (!$user->hasPermission()) {
            return json_encode(array('status' => 'error', 'message' => 'Unauthorized access'));
        }
        $result = $save->updateUser($user);
    } elseif ($_REQUEST['sub_action'] == 'create') {
        // Perform RBAC check and create new user
        if (!$save->createUser($_REQUEST)) {
            return json_encode(array('status' => 'error', 'message' => $save->getError()));
        }
        $result = $_REQUEST;
    } elseif ($_REQUEST['sub_action'] == 'delete') {
        // Perform RBAC check and delete user
        if (!$save->deleteUser($_REQUEST['id'])) {
            return json_encode(array('status' => 'error', 'message' => $save->getError()));
        }
    }

    if (isset($result['errors'])) {
        return json_encode(array('status' => 'error', 'message' => $result['errors']));
    }

    return json_encode(array('status' => 'success', 'data' => $result));
}
