public class StateLoader {
    private static final String STATE_FILE = "state.ser";
    private static final int CHECKSUM_LENGTH = 4;
    private static Map<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static ObjectInputStream inputStream;

    public static MoSTState loadMoSTState(String stateName) throws Exception {
        MoSTState state = cache.get(stateName);
        if (state != null) {
            return state;
        }

        try {
            // Lazy loading
            if (inputStream == null) {
                inputStream = new ObjectInputStream(new FileInputStream(STATE_FILE));
            }
            Object obj = inputStream.readObject();
            int checksum = ((Byte[])obj)[0];
            byte[] bytes = ((byte[])obj).substring(1).getBytes();

            // Verify checksum
            int calculatedChecksum = calculateChecksum(bytes);
            if (checksum != calculatedChecksum) {
                logError("Invalid state file: " + STATE_FILE);
                return null;
            }

            // Deserialize and verify integrity
            state = (MoSTState) deserializeState(bytes);
            cache.put(stateName, state);
        } catch (EOFException e) {
            logError("End of File reached. This should not happen.");
            return null;
        } finally {
            try {
                if (inputStream != null) {
                    inputStream.close();
                }
            } catch (IOException e) {
                logError("Failed to close input stream: " + e.getMessage());
            }
        }

        return state;
    }

    private static int calculateChecksum(byte[] bytes) {
        // Your checksum algorithm implementation
        // For example:
        int checksum = 0;
        for (byte b : bytes) {
            checksum += b;
        }
        return checksum % Integer.MAX_VALUE;
    }

    private static MoSTState deserializeState(byte[] bytes) throws Exception {
        // Your deserialization logic
        // For example:
        ObjectInputStream tempInput = new ObjectInputStream(new ByteArrayInputStream(bytes));
        MoSTState state = (MoSTState)tempInput.readObject();
        tempInput.close();
        return state;
    }

    private static void logError(String message) {
        // Your logging mechanism implementation
        System.out.println("Error: " + message);
    }
}
