const fs = require('fs');
const path = require('path');

async function compileFiles(directory, maxConcurrentReads, prefix) {
  const files = await fs.readdir(directory);
  let totalFiles = files.length;
  let excludedFiles = 0;

  async function readFiles(files) {
    const promises = [];
    for (let file of files) {
      if (!file.startsWith(prefix)) {
        promises.push(fs.readFile(path.join(directory, file)));
      }
    }

    try {
      const results = await Promise.allSettled(promises);
      let content = '';
      for (const { status, value } of results) {
        if (status === 'fulfilled') {
          content += value.toString();
        }
      }
      return content;
    } catch (err) {
      throw err;
    }
  }

  async function readFilesConcurrently(files) {
    const promises = [];
    for (let i = 0; i < Math.min(maxConcurrentReads, files.length); i++) {
      const file = files[i];
      if (!file.startsWith(prefix)) {
        promises.push(fs.readFile(path.join(directory, file)));
      }
    }

    try {
      let results = await Promise.allSettled(promises);
      for (let i = 0; i < results.length; i++) {
        if (results[i].status === 'fulfilled') {
          const fileContent = results[i].value.toString();
          content += fileContent;
        } else {
          for (let retry = 1; retry <= 3; retry++) {
            try {
              await fs.readFile(path.join(directory, files[i]));
              break;
            } catch (err) {
              if (retry === 3) {
                console.error(`Failed to read file ${files[i]}: ${err}`);
              }
              await new Promise((resolve) => setTimeout(() => resolve(), 1000));
            }
          }
        }
      }

      return content;
    } catch (err) {
      throw err;
    }
  }

  let content = '';
  for (let i = 0; i < Math.ceil(totalFiles / maxConcurrentReads); i++) {
    const chunk = files.slice(i * maxConcurrentReads, (i + 1) * maxConcurrentReads);
    content += await readFilesConcurrently(chunk);
  }

  console.log(`Total files processed: ${totalFiles}`);
  console.log(`Files excluded due to prefix condition: ${excludedFiles}`);

  return content;
}
