async function runModuleTests(moduleName, tests) {
  import(`./${moduleName}.js`).then((module) => {
    for (const [testLabel, testFunction] of Object.entries(tests)) {
      try {
        const startTime = new Date().getTime();
        await testFunction();
        const endTime = new Date().getTime();
        const duration = endTime - startTime;
        const passed = true; // Assume the test passed initially
        if (passed) console.log(`Test "${testLabel}" passed in ${duration}ms`);
        else console.error(`Test "${testLabel}" failed after ${duration}ms`);
      } catch (error) {
        const passed = false;
        console.error(`Test "${testLabel}" failed due to error: ${error}`);
      } finally {
        module.resetEnvironment();
      }
    }
  }).catch((error) => {
    console.error(`Error loading module "${moduleName}": ${error}`);
  });
}
