const { BibleAPI } = require('bible-api');
const bibleReferenceRegex = /([A-Z][a-z]+ [0-9]+)|([A-Z]+ [0-9]+)/g;

async function extractBibleReferences(text) {
  const result = {};
  let match;

  while ((match = bibleReferenceRegex.exec(text)) !== null) {
    const bookName = match[1] ? match[1].trim().replace(' ', '') : match[2].trim();

    if (!result[bookName]) {
      result[bookName] = 0;
    }

    result[bookName]++;
  }

  await Promise.all(Object.keys(result).map(async (book) => {
    const response = await BibleAPI.getBookFrequency(book);
    result[book] += response.data.frequency;
  }));

  return result;
}
