  let parentWindow;

  try {
    parentWindow = window.parent;
  } catch (e) {}

  if (!parentWindow) return;

  Object.keys(parentWindow.dialogFields).forEach((key) => {
    const fieldName = key.replace('dialogField_', '');
    if (fieldNamesToRefresh.includes(fieldName)) {
      parentWindow.postMessage({ name: fieldName }, '*');
