function streamDataAndGraphify(inputStream) {
  let data = [];
  const pauseResume = { paused: false };

  function collectData(stream) {
    stream.on('data', (chunk) => {
      if (!pauseResume.paused) {
        data.push(chunk);
      }
    });
    stream.on('error', (err) => console.error(err));
  }

  function resume() {
    pauseResume.paused = false;
  }

  function pause() {
    pauseResume.paused = true;
  }

  function graphify() {
    const vertices = [];
    const edges = [];

    data.forEach((chunk) => {
      let jsonChunk;
      try {
        jsonChunk = JSON.parse(chunk);
      } catch (err) {
        console.error(err);
        return;
      }

      Object.keys(jsonChunk).forEach((key) => {
        if (!vertices.includes(key)) vertices.push(key);
      });

      jsonChunk.forEach((value, key) => {
        edges.push({ from: key, to: value });
      });
    });

    function addVertex(id) {
      vertices.push(id);
    }

    function addEdge(from, to) {
      edges.push({ from, to });
    }

    function addRandomPropertiesToVertices() {
      vertices.forEach((id) => {
        addProperty(id, Math.floor(Math.random() * 100));
      });
    }

    function addProperty(vertexId, propertyValue) {
      // Implement your own graph database library or use a standard one like neo4j
      console.log(`Added ${propertyValue} to vertex ${vertexId}`);
    }

    return { vertices, edges, addVertex, addEdge, addRandomPropertiesToVertices };
  }

  collectData(inputStream);
  const graphOperations = graphify();
}

