function copyBytes(dataChunks, byteCount) {
  const result = Buffer.alloc(0);
  let totalCopied = 0;

  dataChunks.forEach((chunk, i) => {
    if (!Buffer.isBuffer(chunk)) return;

    const chunkSize = chunk.length;
    const remainingByteCount = byteCount - totalCopied;

    if (remainingByteCount > chunkSize) {
      result = Buffer.concat([result, chunk.slice(0, chunkSize)]);
      totalCopied += chunkSize;
    } else {
      result = Buffer.concat([result, chunk.slice(0, remainingByteCount)]);
      totalCopied += remainingByteCount;
      break;
    }
  });

  if (totalCopied < byteCount) return null; // Not enough data

  const transformedData = transformData(result);
  reportProgress(totalCopied);

  return transformedData;
}

