["```
function filterElements(rootElement, selectorSet) {
  const cache = new Map();
  return Array.from(rootElement.querySelectorAll('*'), (element) => {
    let matches = [];
    for (const selector of selectorSet) {
      if (!selector || !element.matches(selector)) continue;
      matches.push(...getMatches(element, selector));
    }
    return matches.length > 0 ? element : null;
  });

  function getMatches(element, selector) {
    const cachedResult = cache.get(selector);
    if (cachedResult !== undefined) return cachedResult;

    let matches = [];
    if (selector.startsWith('#') || selector.startsWith('.')) {
      const id = selector.startsWith('#')
        ? selector.slice(1)
        : selector.slice(1);
      matches = Array.from(element.querySelectorAll(id));
    } else if (selector.includes(' ')) {
      for (const child of element.children) {
        matches.push(...getMatches(child, selector.replace(/^.*? /, '')));
      }
    } else {
      matches = element.matches(selector) ? [element] : [];
    }

    cache.set(selector, matches);
    return matches;
  }
