// Dynamic JavaScript file loader
class JSFileLoader {
  constructor() {
    this.files = [];
    this.dependencies = {};
    this.errorHandler = new ErrorHandler();
  }

  // Add a JavaScript file to the list for loading
  addFile(file) {
    this.files.push(file);
  }

  // Resolve dependencies between files
  resolveDependencies() {
    const deps = this.dependencies;
    let visited = [];

    function dfs(file, visited) {
      if (visited.includes(file)) return;

      visited.push(file);

      if (deps[file]) {
        deps[file].forEach((dep) => dfs(dep, visited));
      }
    }

    this.files.forEach((file) => dfs(file, visited));
  }

  // Load and execute files
  loadAndExecute() {
    const promises = [];

    this.files.forEach((file) => {
      const promise = new Promise((resolve, reject) => {
        const script = document.createElement('script');
        script.src = file;

        script.onload = () => resolve();
        script.onerror = (err) => reject(err);

        document.head.appendChild(script);
      });

      promises.push(promise);
    });

    return Promise.all(promises).then(() => this.errorHandler.handle()).catch((err) => this.errorHandler.handleError(err));
  }
}

// Error handling class
class ErrorHandler {
  handle() {
    // Handle successful execution (no errors)
  }

  handleError(err) {
    // Log or display error message
    console.error('Error loading and executing JavaScript files:', err);
  }
}

// Example usage:
const loader = new JSFileLoader();
loader.addFile('file1.js');
loader.addFile('file2.js', ['file1.js']);
loader.resolveDependencies();
loader.loadAndExecute();

