public Map<String, Integer> processFileList(List<String> filePaths) {
    Map<String, Integer> lineCounts = new HashMap<>();
    for (String filePath : filePaths) {
        try {
            File file = new File(filePath);
            if (!file.exists() || !file.isFile()) {
                continue;
            }
            int lineNumber = 0;
            long startTime = System.currentTimeMillis();
            try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    lineNumber++;
                }
            } catch (IOException e) {
                throw new CustomFileException(filePath, e);
            } finally {
                long endTime = System.currentTimeMillis();
                System.out.println("Processed file " + filePath + " in " + (endTime - startTime) + " ms");
            }
            lineCounts.put(filePath, lineNumber);
        } catch (FileNotFoundException e) {
            // Handle this case according to your requirements
        } catch (CustomFileException e) {
            System.err.println("Error processing file: " + e.getMessage());
        }
    }
    return lineCounts;
}

class CustomFileException extends IOException {
    public CustomFileException(String filePath, Throwable cause) {
        super(filePath + ": " + cause.getMessage(), cause);
    }
}
