import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Random;

public class ServiceController {
    public static void startAndStopService(String filePath) throws Exception {
        Random random = new Random();
        for (int i = 0; i < 5; i++) {
            Thread.sleep(random.nextInt(10000)); // delay in milliseconds
            System.out.println("Starting service...");
            String hashValue = generateMD5Hash(filePath);
            System.out.println("Service started. Hash value: " + hashValue);
            stopService();
            sendStopMessage(filePath);
        }
    }

    private static String generateMD5Hash(String filePath) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (FileInputStream fileInputStream = new FileInputStream(new File(filePath));
             BufferedInputStream bufferedInputStream = new BufferedInputStream(fileInputStream, 1024)) {
            byte[] chunk = new byte[4096];
            int bytesRead;
            while ((bytesRead = bufferedInputStream.read(chunk)) != -1) {
                md.update(chunk, 0, bytesRead);
            }
        } catch (IOException e) {
            throw new Exception("Error reading file: " + e.getMessage());
        }
        return String.format("%032x", new java.math.BigInteger(1, md.digest()));
    }

    private static void stopService() throws InterruptedException {
        System.out.println("Stopping service...");
        Thread.sleep(random.nextInt(10000)); // delay in milliseconds
        System.out.println("Service stopped.");
    }

    private static void sendStopMessage(String filePath) throws Exception {
        // send message to messaging system using your preferred library or API
        System.out.println("Sent stop message for file: " + filePath);
    }
}
