function getWeatherData($city) {
    // Define API endpoint URL and credentials
    $apiUrl = 'https://weather-api.com/latest';
    $apiKey = 'YOUR_API_KEY';

    // Initialize error log and cache arrays
    $errorLog = [];
    $cache = [];

    // Check if city is cached, if so return cached data
    if (isset($cache[$city])) {
        return array('status' => 'success', 'data' => $cache[$city]);
    }

    // Initialize API request headers and query string
    $headers = ['Authorization: Bearer ' . $apiKey];
    $query = http_build_query(['city' => $city, 'units' => 'metric']);

    try {
        // Make API request
        $response = json_decode(file_get_contents($apiUrl . '?' . $query), true);

        // Check if API returned an error
        if (!isset($response['data'])) {
            array_push($errorLog, 'Error fetching weather data: ' . json_encode($response));
            return array('status' => 'failure', 'message' => 'API error');
        }

        // Extract and cache relevant weather data
        $weatherData = [];
        foreach ($response['data'] as $key => $value) {
            if (in_array($key, ['temperature', 'humidity', 'wind_speed'])) {
                $weatherData[$key] = $value;
            }
        }

        // Cache city's weather data
        $cache[$city] = $weatherData;

        // Update local database with new weather data
        // (Assuming a function called updateLocalDatabase is defined elsewhere)
        $result = updateLocalDatabase($city, $weatherData);

        if ($result) {
            return array('status' => 'success', 'message' => 'Weather data updated successfully');
        } else {
            array_push($errorLog, 'Error updating local database: ' . json_encode($response));
            return array('status' => 'failure', 'message' => 'Database error');
        }
    } catch (Exception $e) {
        array_push($errorLog, 'An unexpected error occurred: ' . $e->getMessage());
        return array('status' => 'failure', 'message' => 'Unexpected error');
    }

    // Return error message if API rate limit is exceeded or other errors occur
    if (count($errorLog) > 0) {
        return array('status' => 'failure', 'message' => implode(', ', $errorLog));
    }
}
