using System;
using UnityEngine;

public class RandomValueGenerator
{
    private float minFloat = 0f;
    private float maxFloat = 1f;
    private int minInt = 0;
    private int maxInt = 100;

    public void SetFloatRange(float min, float max)
    {
        if (min > max) return;
        this.minFloat = min;
        this.maxFloat = max;
    }

    public void SetIntRange(int min, int max)
    {
        if (min > max) return;
        this.minInt = min;
        this.maxInt = max;
    }

    public float GenerateRandomFloat(bool exclusive = false)
    {
        return exclusive ? UnityEngine.Random.Range(minFloat + 1e-5f, maxFloat - 1e-5f) : UnityEngine.Random.Range(minFloat, maxFloat);
    }

    public int GenerateRandomInt(bool exclusive = false)
    {
        if (exclusive && minInt > maxInt) return minInt;
        return exclusive ? UnityEngine.Random.Range(minInt + 1, maxInt) : UnityEngine.Random.Range(minInt, maxInt + 1);
    }

    public Vector2 GenerateRandomVector2(float minX = default, float maxX = default, float minY = default, float maxY = default)
    {
        float x = GenerateRandomFloat();
        float y = GenerateRandomFloat();

        if (minX != default) x = Mathf.Clamp(x, minX, maxX);
        if (minY != default) y = Mathf.Clamp(y, minY, maxY);

        return new Vector2(x, y);
    }

    public Vector3 GenerateRandomVector3(float minX = default, float maxX = default, float minY = default, float maxY = default, float minZ = default, float maxZ = default)
    {
        float x = GenerateRandomFloat();
        float y = GenerateRandomFloat();
        float z = GenerateRandomFloat();

        if (minX != default) x = Mathf.Clamp(x, minX, maxX);
        if (minY != default) y = Mathf.Clamp(y, minY, maxY);
        if (minZ != default) z = Mathf.Clamp(z, minZ, maxZ);

        return new Vector3(x, y, z);
    }

    public override string ToString()
    {
        return $"Float Range: [{minFloat}, {maxFloat}], Int Range: [{minInt}, {maxInt}]";
    }
}
