["```javascript
const workerpool = require('worker-pool');

function asyncReduce(arr, initialValue, callback) {
  const pool = workerpool.pool();

  let result = initialValue;

  arr.forEach((num) => {
    pool.exec(() => {
      try {
        result = callback(result, num);
      } catch (err) {
        console.error('Error processing element:', err);
        result = initialValue; // reset to initial value on error
      }
    });
  });

  return new Promise((resolve, reject) => {
    pool.on('task-complete', () => {
      if (!pool.tasks.length) resolve(result);
    });

    pool.on('error', (err) => {
      reject(err);
    });
  });
}
