#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ITEMS 1000
#define BUFFER_SIZE 1024*1024 // 1 MB

typedef struct {
    char *key;
    char *value;
} ResourceBundleItem;

int loadResourceBundle(const char *filePath, ResourceBundleItem **bundleItems) {
    FILE *file = fopen(filePath, "rb");
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", filePath);
        return -1; // Error
    }

    size_t fileSize = ftell(file);
    rewind(file);

    *bundleItems = (ResourceBundleItem *)malloc((MAX_ITEMS + 1)*sizeof(ResourceBundleItem));
    if (!*bundleItems) {
        fclose(file);
        fprintf(stderr, "Error allocating memory\n");
        return -2; // Error
    }

    ResourceBundleItem *items = *bundleItems;
    size_t numItems = 0;

    char buffer[BUFFER_SIZE];

    while (fread(buffer, 1, BUFFER_SIZE, file) > 0) {
        for (size_t i = 0; i < BUFFER_SIZE; i++) {
            if (buffer[i] == '\n') {
                // Process the item
                items[numItems].key = malloc((i + 1)*sizeof(char));
                strcpy(items[numItems].key, buffer);
                items[numItems++].value = NULL;

                if (numItems >= MAX_ITEMS) {
                    fclose(file);
                    free(*bundleItems);
                    *bundleItems = NULL;
                    return -3; // Error
                }
            }
        }
    }

    rewind(file);
    fseek(file, 0, SEEK_END);

    items[numItems].key = malloc((size_t)fileSize + 1* sizeof(char));
    fread(items[numItems].key, 1, fileSize + 1, file);
    items[numItems--].value = NULL;

    fclose(file);

    if (numItems > MAX_ITEMS) {
        free(*bundleItems);
        *bundleItems = NULL;
        return -4; // Error
    }

    return numItems;
}

void freeBundle(ResourceBundleItem *items, size_t numItems) {
    for (size_t i = 0; i < numItems; i++) {
        free(items[i].key);
        items[i].key = NULL;
    }
    free(items);
}
