#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define CHUNK_SIZE 1000

typedef struct {
    char **lines;
    int size;
} chunk_t;

chunk_t *create_chunk() {
    chunk_t *chunk = (chunk_t *)malloc(sizeof(chunk_t));
    chunk->size = 0;
    chunk->lines = NULL;
    return chunk;
}

void free_chunk(chunk_t *chunk) {
    for(int i=0; i<chunk->size; i++) {
        free(chunk->lines[i]);
    }
    free(chunk->lines);
    free(chunk);
}

double calculate_average(char **line, int len) {
    double sum = 0.0;
    for(int i=len-2; i>=1; i--) {
        sum += atof(strtok(line[i], " "));
    }
    return sum / (len-1);
}

void process_chunk(FILE *file, chunk_t *chunk, FILE *log_file) {
    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while((read = getline(&line, &len, file)) != -1 && chunk->size < CHUNK_SIZE) {
        int count = 0;
        char *token = strtok(line, " ");
        printf("(");

        for(token; token; token = strtok(NULL, " ")) {
            if(count < chunk->size) {
                printf("%s,", token);
            } else {
                double average = calculate_average(chunk->lines, count+1);
                printf(" %.2f)", average);
                break;
            }
            count++;
        }

        free(line);
        line = NULL;
        len = 0;

        if(read == -1 || chunk->size == CHUNK_SIZE) {
            break;
        }

        int i = 0;
        while((read = getline(&line, &len, file)) != -1 && i < (count+1)) {
            free(chunk->lines[i]);
            chunk->lines[i] = line;
            i++;
        }
    }

    if(read == -1) {
        while(count > 1) {
            double average = calculate_average(chunk->lines, count);
            printf(" %.2f)", average);
            fwrite("\n", 1, 1, log_file);
            for(int i=0; i<count-1; i++) {
                free(chunk->lines[i]);
            }
            free(chunk->lines);
            chunk->size = 0;
            count--;
        }
    }

    if(ferror(file)) {
        perror("Error reading file");
    }

    fclose(file);
}

double total_average(char **lines, int len) {
    double sum = 0.0;
    for(int i=0; i<len; i++) {
        char *token = strtok(lines[i], " ");
        while(token) {
            if(i < len-1) {
                sum += atof(token);
                token = strtok(NULL, " ");
            } else {
                double average = (sum / ((i+1)*2)) + atof(token);
                return average;
            }
        }
    }
}

int main() {
    FILE *file = fopen("input.txt", "r");
    FILE *log_file = fopen("output.log", "w");

    if(file == NULL || log_file == NULL) {
        perror("Error opening files");
        return -1;
    }

    chunk_t *chunk = create_chunk();
    process_chunk(file, chunk, log_file);

    double total_avg = total_average(chunk->lines, chunk->size);
    fprintf(log_file, "Total Average: %.2f", total_avg);

    free_chunk(chunk);
    fclose(file);
    fclose(log_file);

    return 0;
}
