#include <string.h>
#include "tiff.h"
#include <openssl/aes.h>

typedef struct {
    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    uint16_t extraSamples;
} TiffInfo;

TiffInfo* parseTiff(char* filename) {
    TiffInfo* tiffInfo = (TiffInfo*)malloc(sizeof(TiffInfo));
    tiff_handle_t handle = TIFFOpen(filename, "r");
    if (!handle) {
        return NULL;
    }

    uint16_t bitsPerSample;
    uint16_t samplesPerPixel;
    TIFFGetFieldDefaulted(handle, TIFF_FIELD_BITSPERSAMPLE, &bitsPerSample);
    TIFFGetFieldDefaulted(handle, TIFF_FIELD_SAMPLESPERPIXEL, &samplesPerPixel);

    if (bitsPerSample != 1 && bitsPerSample != 2 && bitsPerSample != 4 && bitsPerSample != 8 && bitsPerSample != 16) {
        free(tiffInfo);
        TIFFClose(handle);
        return NULL;
    }

    tiffInfo->bitsPerSample = bitsPerSample;
    tiffInfo->samplesPerPixel = samplesPerPixel;
    uint16_t extraSamples = 0;
    TIFFGetFieldDefaulted(handle, TIFF_FIELD_EXTRASAMPLES, &extraSamples);
    tiffInfo->extraSamples = extraSamples;

    TIFFClose(handle);
    return tiffInfo;
}

void* processTiff(char* filename, char* operation) {
    TiffInfo* tiffInfo = parseTiff(filename);
    if (!tiffInfo) {
        return NULL;
    }

    if (strcmp(operation, "encrypt") == 0) {
        // Encrypt the file using AES
        AES_KEY key;
        AES_set_encrypt_key("your_secret_key", strlen("your_secret_key"), &key);
        FILE* file = fopen(filename, "rb");
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        fseek(file, 0, SEEK_SET);
        char* buffer = (char*)malloc(fileSize + 1);
        fread(buffer, 1, fileSize, file);
        fclose(file);

        AES_cbc_encrypt(buffer, buffer, fileSize, &key, "your Initialization Vector", AES_ENCRYPT);
        free(buffer);
    } else if (strcmp(operation, "decrypt") == 0) {
        // Decrypt the file using AES
        AES_KEY key;
        AES_set_decrypt_key("your_secret_key", strlen("your_secret_key"), &key);
        FILE* file = fopen(filename, "rb");
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        fseek(file, 0, SEEK_SET);
        char* buffer = (char*)malloc(fileSize + 1);
        fread(buffer, 1, fileSize, file);
        fclose(file);

        AES_cbc_decrypt(buffer, buffer, fileSize, &key, "your Initialization Vector", AES_DECRYPT);
        free(buffer);
    } else {
        // Handle unknown operation
    }

    return tiffInfo;
}']

