void rename_file(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        // handle error
        fprintf(stderr, "Error opening file: %s\n", filename);
        return;
    }

    char buffer[11]; // read up to 10 characters and null-terminate
    fseek(file, 0, SEEK_SET);
    fread(buffer, 1, 10, file); // read first 10 characters
    fclose(file);

    if (ferror(file)) {
        // handle error
        fprintf(stderr, "Error reading file: %s\n", filename);
        strcpy(filename + strlen(filename), "_empty");
        return;
    }

    struct stat sb;
    fstat(fileno(file), &sb); // get file size

    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, 32, "%Y-%m-%d_%H:%M:%S", localtime(&now));

    int sequence_number = (int) sb.st_size;
    char seq_str[8]; // convert sequence number to string
    sprintf(seq_str, "%06d", sequence_number);

    char random_string[6];
    for (int i = 0; i < 5; i++) {
        random_string[i] = (char) ('a' + rand() % 26); // generate random alphanumeric
        random_string[5] = '\0'; // null-terminate the string
    }

    char new_filename[64]; // buffer for new filename
    sprintf(new_filename, "%s_%s_%06d_%s", timestamp, seq_str, sequence_number, random_string);

    if (strlen(new_filename) > 50) {
        // truncate filename to 50 characters
        char truncated_filename[51];
        strncpy(truncated_filename, new_filename, 50);
        truncated_filename[50] = '\0';
        new_filename[50] = '\0'; // set the buffer to null-terminate
    }

    rename(filename, new_filename); // actually rename the file

    fclose(file); // close the original file
}
