void init_aes_cipher(unsigned char *password, int password_len, unsigned char *salt, int salt_len,
                     unsigned char **key, unsigned char **iv, int *key_len) {
    unsigned char *derived_key = NULL;
    unsigned char *temp_iv = NULL;

    if (!password || !salt || !key || !iv) {
        ERR_error_fp(stderr, "Invalid input");
        return;
    }

    // Derive key using PBKDF2
    int derived_key_len = PBKDF2(password, password_len, salt, salt_len, 1000, NULL, &derived_key);

    if (!derived_key) {
        ERR_error_fp(stderr, "Key derivation failed");
        return;
    }

    // Initialize AES cipher with derived key and generated IV
    unsigned char *aes_key = OPENSSL_malloc(derived_key_len + 1);
    memcpy(aes_key, derived_key, derived_key_len);
    aes_key[derived_key_len] = '\0';
    if (RAND_bytes(temp_iv, AES_BLOCK_SIZE) <= 0) {
        ERR_error_fp(stderr, "IV generation failed");
        OPENSSL_free(aes_key);
        return;
    }
    temp_iv[AES_BLOCK_SIZE] = '\0';

    // Set key and IV for the AES cipher
    int aes_key_len = strlen((char *)aes_key);
    *key = aes_key;
    *iv = (unsigned char *)temp_iv;

    *key_len = aes_key_len;
}

void clean_up_aes_cipher(void **cipher) {
    if (*cipher) {
        OPENSSL_free(*cipher);
        *cipher = NULL;
    }
}
