import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;

public class FileProcessor {

    private static final String LOG_FILE = "file_processor.log";
    private static final int FREE_SPACE_THRESHOLD_GB = 1;

    public static void main(String[] args) {
        try (java.io.FileWriter logWriter = new java.io.FileWriter(LOG_FILE)) {
            File directory = new File("path_to_directory");
            List<File> files = new ArrayList<>();
            for (File file : directory.listFiles()) {
                if (file.isFile() && !file.getName().equals("specific_file.txt")) {
                    files.add(file);
                }
            }

            Runtime runtime = Runtime.getRuntime();

            while (!files.isEmpty()) {
                File file = files.remove(0);

                // Check if specific file exists and delete it
                File specificFile = new File(directory, "specific_file.txt");
                if (specificFile.exists()) {
                    boolean deleted = specificFile.delete();
                    if (!deleted) {
                        System.out.println("Error deleting specific file: " + specificFile.getAbsolutePath());
                    }
                }

                // Execute command to generate temporary file
                String[] cmdArgs = {"your_custom_command", file.getName()};
                Process process = runtime.exec(cmdArgs, null, directory);
                int exitValue = process.waitFor();
                if (exitValue != 0) {
                    System.out.println("Error executing command: " + Arrays.toString(cmdArgs));
                }

                // Monitor available disk space and log
                long freeSpace = Files.size(Paths.get("/"));
                if (freeSpace < FREE_SPACE_THRESHOLD_GB * 1024 * 1024 * 1024L) {
                    System.out.println("Available disk space is low. Halting processing.");
                    break;
                }

                // Log command execution and temporary file creation
                logWriter.write(String.format("Processed file: %s, Temporary file created: output_%s.tmp%n", file.getName(), file.getName()));
            }
        } catch (IOException | InterruptedException e) {
            System.out.println("Error occurred: " + e.getMessage());
        }
    }
}
