#define MAX_TOKEN_LENGTH 1024
#define MAX_ERROR_MESSAGE_LENGTH 1024

int validate_oauth_token_json(char *json_data) {
    json_object *token_obj = json_object_from_string(json_data);
    if (!token_obj) {
        // Handle JSON parsing error
        printf("Error: Unable to parse JSON.\n");
        return 0;
    }

    char *access_token = json_object_get_string(token_obj, "access_token");
    if (!access_token || strlen(access_token) >= MAX_TOKEN_LENGTH) {
        printf("Error: Invalid access token - it must be a non-empty string.\n");
        return 0;
    }

    char *token_type = json_object_get_string(token_obj, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        printf("Error: Invalid token type - it must be 'Bearer' (case-sensitive).\n");
        return 0;
    }

    int expires_in = json_object_get_int(token_obj, "expires_in");
    if (expires_in <= 0 || expires_in > INT_MAX) {
        printf("Error: Invalid expiration time - it must be a positive integer.\n");
        return 0;
    }

    char *refresh_token = json_object_get_string(token_obj, "refresh_token");
    if (!refresh_token || strlen(refresh_token) >= MAX_TOKEN_LENGTH) {
        printf("Error: Invalid refresh token - it must be a non-empty string.\n");
        return 0;
    }

    // If we reach this point, the JSON is valid
    printf("OAuth2 access token is valid.\n");
    return 1;
}

int main() {
    char *json_data = "{\"access_token\": \"my_access_token\", \"token_type\": \"Bearer\", \"expires_in\": 3600}";
    validate_oauth_token_json(json_data);
    return 0;
}
