using System;
using System.IO;
using System.Security.Cryptography;

public byte[] DecryptCiphertext(byte[] ciphertext, byte[] key, byte[] iv)
{
    using (Aes aes = Aes.Create())
    {
        aes.Key = key;
        aes.IV = iv;

        using (MemoryStream ms = new MemoryStream())
        {
            using (CryptoStream cs = new CryptoStream(ms, aes.CreateDecryptor(), CryptoStreamMode.Write))
            {
                int chunkSize = 1024;
                byte[] buffer = new byte[chunkSize];

                for (int i = 0; i < ciphertext.Length; i += chunkSize)
                {
                    int bytesRead = Math.Min(chunkSize, ciphertext.Length - i);
                    cs.Write(ciphertext, i, bytesRead);

                    while ((readBytes := cs.Read(buffer, 0, buffer.Length)) > 0)
                    {
                        ms.Write(buffer, 0, readBytes);
                    }
                }
            }

            return ms.ToArray();
        }
    }
