const fs = require('fs');
const vm = require('vm');
const scriptManager = {};

class ScriptManager {
  constructor() {
    this.scripts = [];
    this.scriptOrder = [];
  }

  loadScript(url) {
    return new Promise((resolve, reject) => {
      fs.readFile(url, (err, data) => {
        if (err) {
          reject(new Error(`Failed to load script: ${url}`));
          return;
        }
        try {
          const script = vm.runInThisContext(data.toString());
          this.scripts.push(script);
          resolve();
        } catch (error) {
          reject(new Error(`Error executing script: ${url}`));
        }
      });
    });

    async executeScripts() {
      for await (const script of this.scripts) {
        try {
          await script();
        } catch (error) {
          console.error('Script execution failed:', error);
        }
      }
    }

    async loadAndExecuteScripts(urls) {
      this.scriptOrder = urls;
      await Promise.all(this.scriptOrder.map((url) => this.loadScript(url)));
      await this.executeScripts();
    }
  }

  // Usage example:
  const scriptManager = new ScriptManager();
  scriptManager.loadAndExecuteScripts(['script1.js', 'script2.js', 'script3.js']);
}
