function uploadFile(url) {
    const fileUploader = require('file-uploader');
    const { existsSync, readFileSync } = require('fs');
    let uploadedUrl;

    try {
        if (!existsSync(readFileSync(url, 'utf8'))) throw new Error(`File ${url} does not exist`);
        if (/\.(jpg|png|gif|mp3|mp4|wav)$/.test(path.extname(url))) {
            const chunkSize = 1024 * 1024;
            let buffer = Buffer.alloc(0);
            for (let i = 0; i < readFileSync(url, 'utf8').length; i += chunkSize) {
                if ((i + chunkSize) > readFileSync(url, 'utf8').length) {
                    buffer = Buffer.concat([buffer, readFileSync(url, 'utf8').slice(i)]);
                    break;
                }
                buffer = Buffer.concat([buffer, readFileSync(url, 'utf8').slice(i, i + chunkSize)]);
            }

            fileUploader
                .upload({
                    data: buffer,
                    contentType: 'application/octet-stream',
                    chunkSize: 1024 * 1024,
                    concurrent: true,
                    maxItemsInBundle: 1000
                })
                .then((response) => {
                    uploadedUrl = response.data.uploaded_url;
                })
                .catch((err) => {
                    console.error(`Error uploading file ${url}:`, err);
                });
        } else throw new Error(`Invalid file format for ${url}`);
    } catch (error) {
        console.log(`Warning: error processing ${url}: `, error);
    }

    return uploadedUrl;
}
