function execCmd(cmd) {
  const childProcess = require('child_process');
  const logger = console.log;
  const sanitizedCmd = cmd.replace(/[^\w\s]/gi, '');

  try {
    childProcess.exec(sanitizedCmd, (error, stdout, stderr) => {
      if (error) {
        logger(`exec error: ${error}`);
      }
      if (stderr) {
        logger(`exec stderr: ${stderr}`);
      } else {
        logger(stdout);
      }
    });
  } catch (err) {
    logger(err);
  }
}
