void addVerticesAndEdges(Map<String, Object> vertices, Map<String, Object> edges) {
    Session session = graphDB.createSession();
    try {
        session.beginTransaction();
        for (Map.Entry<String, Object> vertex : vertices.entrySet()) {
            Vertex v = session.find(Vertex.class, vertex.getKey());
            if (v == null) {
                v = new Vertex(vertex.getKey(), (Map<String, Object>) vertex.getValue());
                session.save(v);
            }
        }
        for (Map.Entry<String, Object> edge : edges.entrySet()) {
            String fromId = (String) edge.getKey().split(":")[0];
            String toId = (String) edge.getKey().split(":")[1];
            Vertex fromV = session.find(Vertex.class, fromId);
            Vertex toV = session.find(Vertex.class, toId);
            if (fromV != null && toV != null) {
                Edge e = new Edge(fromV, toV, (Map<String, Object>) edge.getValue());
                session.save(e);
            }
        }
        session.commitTransaction();
    } finally {
        session.close();
    }
}
