#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        eprintln!("Usage: {} <config_file> [task_1] [task_2] ...", &args[0]);
        return Ok(());
    }

    let config_path = &args[1];
    let tasks = &args[2..];

    let rt = Runtime::new().unwrap();
    let config = match load_config(config_path) {
        Ok(config) => config,
        Err(err) => {
            eprintln!("Error loading configuration: {}", err);
            return Ok(());
        }
    };

    let mut metrics = Metrics::default();

    for task in tasks {
        rt.block_on(async move {
            match execute_task(task, &config) {
                Ok(result) => {
                    metrics.completed_tasks += 1;
                    metrics.average_execution_time += result.execution_time as f64;
                }
                Err(err) => {
                    metrics.failed_tasks += 1;
                    eprintln!("Error executing task {}: {}", task, err);
                }
            }
        });
    }

    rt.block_on(metrics.report_to_server());

    Ok(())
}

struct Metrics {
    completed_tasks: u32,
    average_execution_time: f64,
    peak_memory_usage: usize,
    failed_tasks: u32,
}

impl Metrics {
    fn default() -> Self {
        Self {
            completed_tasks: 0,
            average_execution_time: 0.0,
            peak_memory_usage: 0,
            failed_tasks: 0,
        }
    }

    async fn report_to_server(&self) {
        // implement HTTP POST request to remote server
    }
}

