use std::sync::Once;

lazy_static! {
    static ref INIT: Once = Once::new();
}

fn setup_logs_dir() -> Result<PathBuf, Box<dyn std::error::Error>> {
    let log_dir_env_var = "LOG_DIR";
    let home_dir = dirs::home_dir().unwrap_or_else(|| Path::new("."));

    if !INIT.is_completed() {
        INIT.execute(move || {
            let log_dir = &format!("{}{}", home_dir.display(), "/logs");
            fs::create_dir_all(log_dir.as_path())?;
            env::set_var(log_dir_env_var, log_dir.display().to_string());
        });
    }

    let log_dir = PathBuf::from(env::var(log_dir_env_var));
    Ok(log_dir)
}
