#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    char status;
    struct record* child;
} record;

record* initRecords(int size) {
    record* records = (record*)malloc(size * sizeof(record));

    for (int i = 0; i < size; i++) {
        records[i].value = rand() % 100; // random value within the range [0, 100]

        if (i % 2 == 1) { // condition for setting status flag
            records[i].status = 'Y';
        } else {
            records[i].status = 'N';
        }

        if (i < size - 1) { // condition for child pointer
            records[i].child = &records[(i + 1) % size]; // wraparound to the beginning of the array when necessary
        } else {
            records[i].child = NULL;
        }
    }

    return records;
}

void freeRecords(record* records, int size) {
    for (int i = 0; i < size; i++) {
        if (records[i].child != NULL) {
            free(records[i].child);
        }
    }

    free(records);
}
