#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    int value;
    char status;
    struct record* child;
    int ref_count;
} record;

record* allocate_record(int value, int status, struct record* child, int ref_count) {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->value = value;
    new_record->status = status;
    new_record->child = child;
    new_record->ref_count = ref_count;
    return new_record;
}

void garbage_collect(record** records, int length) {
    for (int i = 0; i < length; i++) {
        if (records[i]->ref_count == 0) {
            free(records[i]);
            for (int j = i + 1; j < length; j++) {
                if (records[j]->child == records[i]) {
                    records[j]->child = NULL;
                    records[j]->ref_count--;
                }
            }
            records[i] = records[--length];
        }
    }
    record** new_records = (record**)malloc(sizeof(record*) * length);
    for (int i = 0; i < length; i++) {
        new_records[i] = records[i];
    }
    free(records);
    records = new_records;
}

record* generate_record(int key, long offset) {
    // Generate a random value within the given range
    int value = rand() % 100 + 1;

    // Set the status flag based on the condition involving the key and offset values
    char status = (key > offset) ? 'A' : 'B';

    // Check if the current record's index is even and its reference count is greater than 0
    int ref_count = (key % 2 == 0 && records[i]->ref_count > 0);
    record* child = (ref_count > 0) ? &records[(i + 1) % length] : NULL;

    return allocate_record(value, status, child, ref_count);
}

