void init_arrays(int* offset, int len_offset, int* key, int len_key, record** record_array, int len_record, char** transaction_id, int len_transaction) {
    // Initialize offset and key arrays
    for (int i = 0; i < len_offset; i++) {
        offset[i] = i;
    }
    for (int i = 0; i < len_key; i++) {
        key[i] = i;
    }

    // Initialize record array
    record_array[0] = create_record(rand() % 100, 'A', time(NULL));
    for (int i = 1; i < len_record; i++) {
        record_array[i] = create_record(rand() % 100, (key[i-1]%2 ? 'A' : 'B'), record_array[i-1]->timestamp + rand() % 10);
        if (i % 3 == 0) {
            record_array[i]->child = &record_array[(i+1)%len_record];
        }
    }

    // Initialize transaction ID array
    for (int i = 0; i < len_transaction; i++) {
        transaction_id[i] = (char*)malloc(10);
        sprintf(transaction_id[i], "TID-%d", i);
    }
}

void free_arrays(int* offset, int len_offset, int* key, int len_key, record** record_array, int len_record, char** transaction_id, int len_transaction) {
    // Free record array
    for (int i = 0; i < len_record; i++) {
        free(record_array[i]);
    }
