        records = (Record**)realloc(records, sizeof(Record*) * (record_length + 1));
        records[record_length] = fsa_malloc(sizeof(Record));
        record_length++;
    }

    // Initialize the 'record' array
    for(int i = 0; i < record_length; i++) {
        Record* current_record = &records[i];
        current_record->value = rand() % 100;
        if(current_record->value > 50) {
            current_record->status = 1;
        } else {
            current_record->status = 0;
        }
        current_record->child = NULL;
        current_record->reference_count = 0;
    }

    // Example of setting child pointers
    for(int i = 0; i < record_length - 1; i++) {
        Record* current_record = &records[i];
        if(current_record->value % 2 == 0) {
            current_record->child = &records[i + 1];
            current_record->reference_count++;
        }
    }

    // Example of garbage collection
    for(int i = 0; i < record_length; i++) {
        Record* current_record = &records[i];
        if(current_record->status == 0 && current_record->child == NULL) {
            free(current_record);
            record_length--;
            for(int j = i + 1; j < record_length; j++) {
                records[j - 1] = records[j];
            }
            i--;
        }
    }

