    std::string email;
    time_t registration_date;
    time_t last_active_date;
};

std::vector<float> floatsVector;
std::vector<std::string> stringsVector;
std::vector<UserProfile> profilesVector;
std::vector<int> enumsVector;

void createVectors() {
    srand(time(0));

    for (int i = 0; i < 100; ++i) {
        UserProfile profile;
        profile.username = "user" + std::to_string(i);
        profile.email = profile.username + "@example.com";
        profile.registration_date = time(0) - rand() % (60 * 60 * 24);
        profile.last_active_date = time(0) - rand() % (60 * 60 * 24);

        profilesVector.push_back(profile);

        float f = static_cast<float>(i);
        floatsVector.push_back(f);

        stringsVector.push_back(std::to_string(i));

        enumsVector.push_back(i % 3);
    }
}

void serializeToJson(const std::vector<UserProfile>& profiles, const std::string& filename) {
    Json::Value root;
    for (const auto& profile : profiles) {
        Json::Value profileJson;
        profileJson["username"] = profile.username;
        profileJson["email"] = profile.email;
        profileJson["registration_date"] = profile.registration_date;
        profileJson["last_active_date"] = profile.last_active_date;

        root.append(profileJson);
    }

    std::ofstream file(filename);
    file << root.toString(4) << std::endl;
}

int main() {
    createVectors();

    serializeToJson(profilesVector, "profiles.json");

    return 0;
}
