struct record {
    int feature;
    char status;
    record* child;
    unsigned long timestamp;
};

record* initializeOctree(int featureSize, int numLeafNodes) {
    std::random_device rd;  // obtain a random number from hardware
    std::mt19937 eng(rd()); // seed the generator 
    std::uniform_int_distribution<> distr(1, 100); // function to generate numbers

    record* root = new record();
    root->feature = distr(eng);
    root->status = (numLeafNodes > 0) ? 'L' : 'N';
    root->child = nullptr;
    root->timestamp = static_cast<unsigned long>(std::time(nullptr));

    std::vector<record*> children(8, nullptr);

    for (int i = 0; i < 8; ++i) {
        if (!children[i]) continue;
        children[i]->feature = distr(eng);
        children[i]->status = (numLeafNodes > 1) ? 'L' : 'N';
        children[i]->child = nullptr;
        children[i]->timestamp = static_cast<unsigned long>(std::time(nullptr));
    }

    return root;
}
