from tsdb import TSDB
from datetime import datetime, timedelta

def process_transactions(transactions):
    db = TSDB('localhost', 8080)

    daily_summaries = {}
    for transaction in transactions:
        transaction_id, amount, timestamp = transaction

        date = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')

        key = f"{date.strftime('%Y-%m-%d')}"

        if key not in daily_summaries:
            daily_summaries[key] = {'amount': 0, 'count': 0}

        daily_summaries[key]['amount'] += amount
        daily_summaries[key]['count'] += 1

    for date, summary in daily_summaries.items():
        db.insert(f"summary_{date}", {"amount": summary['amount'], "count": summary['count']})

    return daily_summaries

def main():
    # Example usage: process a stream of transactions
    transactions = [
        ('T1', 100.0, '2022-01-01 00:00:00'),
        ('T2', 200.0, '2022-01-02 01:00:00'),
        ...
    ]

    daily_summaries = process_transactions(transactions)

    # Example usage: retrieve and verify the stored summary
    for date, summary in daily_summaries.items():
        stored_summary = db.get(f"summary_{date}")

        if stored_summary != {'amount': summary['amount'], 'count': summary['count']]:
            raise ValueError("Data integrity error")

if __name__ == "__main__":
