#define MAX_FILENAME_LENGTH 50
#define BUFFER_SIZE 1024

void rename_file(char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        // Log error and append "_empty" to the filename
        char new_filename[MAX_FILENAME_LENGTH];
        sprintf(new_filename, "%s_empty_%ld", filename, time(NULL));
        rename(filename, new_filename);
        return;
    }

    char buffer[BUFFER_SIZE];
    fread(buffer, 1, 10, file);

    // Check if the content can be read
    if (ferror(file) || feof(file)) {
        fclose(file);
        // Log error and append "_empty" to the filename
        char new_filename[MAX_FILENAME_LENGTH];
        sprintf(new_filename, "%s_empty_%ld", filename, time(NULL));
        rename(filename, new_filename);
        return;
    }

    fclose(file);

    struct stat sb;
    stat(filename, &sb);
    off_t fileSize = sb.st_size;

    // Calculate the sequence number
    char seq_num[10];
    sprintf(seq_num, "%06lld", (long long)fileSize);

    // Generate a random alphanumeric string of length 5
    char* random_str = (char*)malloc(6);
    rand_s(random_str, 6);

    // Create the new filename with timestamp, sequence number, and random string
    time_t now = time(NULL);
    struct tm *tm = localtime(&now);
    char new_filename[MAX_FILENAME_LENGTH];
    sprintf(new_filename, "rename-%04d-%s-%s", tm->tm_year % 100, seq_num, random_str);

    // Check the filename length and truncate if necessary
    int len = strlen(new_filename);
    if (len > MAX_FILENAME_LENGTH) {
        new_filename[MAX_FILENAME_LENGTH - 1] = '\0';
    }

    rename(filename, new_filename);

    free(random_str);
}
