std::string modifyFileName(const std::string& fileName) {
    // Initialize result string
    std::string modifiedFileName = "";

    // Get original filename extension
    size_t dotIndex = fileName.find('.');
    if (dotIndex != std::string::npos) {
        modifiedFileName += fileName.substr(0, dotIndex);

        // Determine number of digits and file type from original filename
        int numDigits = 0;
        for (int i = dotIndex - 1; i >= 0 && isdigit(fileName[i]); --i) {
            ++numDigits;
        }
        std::string fileType = fileName.substr(dotIndex + 1);

        // Create new file name with modified extension
        sprintf(&modifiedFileName[dotIndex], "_%d.%s", numDigits, fileType.c_str());
    } else {
