using System;
using System.Collections.Generic;
using System.Linq;

public class ValueGenerator
{
    private Random _random;
    private int _minValue;
    private int _maxValue;
    private bool _isExclusive;
    private List<double> _generatedValues = new();
    private int _sequenceLength;

    public ValueGenerator(int minValue, int maxValue, bool isExclusive)
    {
        _minValue = minValue;
        _maxValue = maxValue;
        _isExclusive = isExclusive;
        _random = new Random();

        ResetSequence();
    }

    public void UpdateRange(int minValue, int maxValue, bool isExclusive)
    {
        if (_generatedValues.Count > 0)
        {
            RaiseEventsOnRangeChange();
        }

        _minValue = minValue;
        _maxValue = maxValue;
        _isExclusive = isExclusive;
    }

    public double Generate()
    {
        return _random.NextDouble() * (_isExclusive ? (double)(_maxValue - _minValue) : (double)(_maxValue + 1)) + _minValue;
    }

    public void GenerateSequence(int sequenceLength)
    {
        _sequenceLength = sequenceLength;

        for (int i = 0; i < sequenceLength; i++)
        {
            double value = Generate();
            _generatedValues.Add(value);
        }
    }

    public void ResetSequence()
    {
        _generatedValues.Clear();
        _sequenceLength = 0;
    }

    public double[] CalculateStatistics()
    {
        if (_generatedValues.Count == 0)
        {
            throw new InvalidOperationException("No values generated yet.");
        }

        double mean = _generatedValues.Average();
        double median = _generatedValues.OrderBy(x => x).ToArray()[_generatedValues.Count / 2];
        double standardDeviation = _generatedValues.StandardDeviation();

        return new[] { mean, median, standardDeviation };
    }

    public override string ToString()
    {
        if (_generatedValues.Count == 0)
        {
            return $"Range: [{_minValue}, {_maxValue}] Exclusive: {_isExclusive}";
        }
        else
        {
            double[] stats = CalculateStatistics();
            return $"Range: [{_minValue}, {_maxValue}] Exclusive: {_isExclusive}" +
                   $"\nGenerated Values: {_generatedValues.Count} Total" +
                   $"\nMean: {stats[0]:F2} Median: {stats[1]:F2}" +
                   $"\nStandard Deviation: {stats[2]:F2}";
        }
    }

    private void RaiseEventsOnRangeChange()
    {
        // Implement event handling here
    }
}
