#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ITEMS 1000
#define CHUNK_SIZE 1024

int loadResourceBundle(const char *path) {
    FILE *file = fopen(path, "rb");
    if (!file) return -1; // Error opening file

    ResourceBundle bundle;
    bundle.items = NULL;

    fseek(file, 0, SEEK_END);
    long fileSize = ftell(file);
    rewind(file);

    if (fseek(file, 0, SEEK_SET) || !fileSize) {
        fclose(file);
        return -2; // Error reading file size
    }

    long itemsCount = fileSize / sizeof(ResourceItem);
    if (itemsCount > MAX_ITEMS) {
        fclose(file);
        free(bundle.items);
        return -3; // File contains more than 1000 items
    }

    bundle.items = malloc(itemsCount * sizeof(ResourceItem));
    fread(bundle.items, sizeof(ResourceItem), itemsCount, file);

    fclose(file);
    return (int)itemsCount;
}

typedef struct {
    char key[16];
    char value[256];
} ResourceItem;

typedef struct {
    ResourceItem* items;
} ResourceBundle;
