#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1024 * 1024
#define REQUEST_RATE_LIMIT 1000

typedef struct {
    int key;
    char* value;
} cache_entry;

typedef struct {
    pthread_mutex_t lock;
    cache_entry** entries;
    int size;
} node_cache;

node_cache* create_node_cache(int size) {
    node_cache* cache = (node_cache*)malloc(sizeof(node_cache));
    cache->entries = (cache_entry**)malloc(size * sizeof(cache_entry*));
    for (int i = 0; i < size; i++) {
        cache->entries[i] = NULL;
    }
    cache->size = size;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void add_entry(node_cache* cache, int key, char* value) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (!cache->entries[i]) {
            cache->entries[i] = (cache_entry*)malloc(sizeof(cache_entry));
            cache->entries[i]->key = key;
            cache->entries[i]->value = value;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

void remove_entry(node_cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i] && cache->entries[i]->key == key) {
            free(cache->entries[i]);
            cache->entries[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);
}

char* get_value(node_cache* cache, int key) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i] && cache->entries[i]->key == key) {
            char* value = cache->entries[i]->value;
            pthread_mutex_unlock(&cache->lock);
            return value;
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void replicate_data(node_cache* cache, node_cache** nodes) {
    for (int i = 0; i < cache->size; i++) {
        for (int j = 0; j < cache->size; j++) {
            if (i != j && nodes[i] && nodes[j]) {
                for (int k = 0; k < MAX_CACHE_SIZE; k++) {
                    int key;
                    char* value;
                    pthread_mutex_lock(&nodes[i]->lock);
                    pthread_mutex_lock(&nodes[j]->lock);
                    if (!nodes[i]->entries[k] || !nodes[j]->entries[k]) {
                        break;
                    }
                    key = nodes[i]->entries[k]->key;
                    value = nodes[i]->entries[k]->value;
                    remove_entry(nodes[i], key);
                    remove_entry(nodes[j], key);
                }
            }
        }
    }
}

void* distributed_cache_thread(void* arg) {
    node_cache** nodes = (node_cache**)arg;
    while (1) {
        // Check for new requests and handle them accordingly
        if (!get_value(*nodes, 123)) {
            add_entry(*nodes, 123, "Hello World");
        }
    }
}

int main() {
    int num_nodes = 3;
    node_cache** nodes = (node_cache**)malloc(num_nodes * sizeof(node_cache*));
    for (int i = 0; i < num_nodes; i++) {
        nodes[i] = create_node_cache(MAX_CACHE_SIZE);
    }

    pthread_t threads[num_nodes];
    for (int i = 0; i < num_nodes; i++) {
        pthread_create(&threads[i], NULL, distributed_cache_thread, &nodes);
    }
    for (int i = 0; i < num_nodes; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
