    public void LoadBinaryData(string filePath, bool overwriteInMemoryData, bool useCacheDir)
    {
        if (string.IsNullOrEmpty(filePath))
            throw new ArgumentException("File path is required.");

        using (var fileStream = File.Open(filePath, FileMode.Open))
        {
            using (var binaryReader = new BinaryReader(fileStream))
            {
                var fileHeader = binaryReader.ReadInt32();
                if (fileHeader != ExpectedFileHeader)
                    LogWarning("Invalid file header. File may be corrupted or from a different version.");

                try
                {
                    using (var formatter = new BinaryFormatter())
                    {
                        var memoryStream = new MemoryStream();
                        fileStream.CopyTo(memoryStream);
                        memoryStream.Position = 0;

                        var data = formatter.Deserialize(memoryStream);
                        if (overwriteInMemoryData)
                            // todo: implement logic to overwrite in-memory data
                            ;

                        if (useCacheDir)
                        {
                            var cacheDir = GetTempDirectory();
                            if (!Directory.Exists(cacheDir))
                                Directory.CreateDirectory(cacheDir);

                            using (var fileStream = File.Create(Path.Combine(cacheDir, "temp.bin")))
                            {
                                formatter.Serialize(fileStream, data);
                            }
                        }
                    }
                }
                catch (Exception ex)
                {
                    LogError("Error deserializing binary data: {0}", ex.Message);
                }
            }
        }
    }

    private void LogWarning(string message) => Console.WriteLine($"[WARNING] {message}");

    private void LogError(string message, Exception ex) => Console.WriteLine($"[ERROR] {message}: {ex.Message}");

    private string GetTempDirectory() => Path.Combine(Path.GetTempPath(), "BinaryLoaderCache");
