char* modify_filename(char *filename) {
    time_t now = time(NULL);
    srand((unsigned int)now + (unsigned int)strlen(filename));

    // Initialize buffer to store modified filename
    char buf[256];

    // Check if the filename is shorter than 10 characters, if so, append current date and time
    if(strlen(filename) < 10) {
        sprintf(buf, "%s_%ld", filename, now);
        filename = strcpy((char*)malloc(sizeof(char)*(strlen(buf)+1)), buf);
    }

    // Replace spaces with underscores
    for(int i=0; i<strlen(filename); i++) {
        if(filename[i] == ' ') {
            filename[i] = '_';
        }
    }

    // Determine the file type based on last three characters of the original filename
    char* ext = strrchr(filename, '.');
    if(ext && strlen(ext) > 3) {
        int i;
        for(i=0; i<3; i++) {
            if(strncmp(ext+1, ".txt", 3) == 0 || strncmp(ext+1, ".jpg", 3) == 0 || strncmp(ext+1, ".png", 3) == 0)
                break;
            else
                ext++;
        }
        if(i<3) {
            // Generate random digit sequence
            for(int j=0; j<6; j++) {
                int num = rand() % 10;
                sprintf(buf, "%d", num);
                strcat(filename, buf);
            }
            // Append the determined file type
            strcat(filename, ext+1);
        } else {
            // Default to ".bin" if no recognized file type found
            strcat(filename, ".bin");
        }
    } else {
        // Generate random digit sequence and append default file type ".bin"
        for(int j=0; j<6; j++) {
            int num = rand() % 10;
            sprintf(buf, "%d", num);
            strcat(filename, buf);
        }
        strcat(filename, ".bin");
    }

    return filename;
}
