#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

char* modify_filename(char* filename) {
    static char result[256];
    int len = strlen(filename);

    // Check for null or invalid filename, return default if true
    if (!filename || !strchr("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_.-", *filename)) {
        return "unknown";
    }

    // Initialize random number generator with current time and hash of filename
    srand(time(NULL) + strlen(filename));

    // Append date and time to filename if it's too short
    if (len < 10) {
        sprintf(result, "%s_%lld", filename, (long long)time(NULL));
        len = strlen(result);
    } else {
        strcpy(result, filename);
    }

    // Replace spaces with underscores
    for (int i = 0; i < len; i++) {
        if (result[i] == ' ') {
            result[i] = '_';
        }
    }

    // Determine file type based on last three characters of original filename
    char* file_type;
    if (len > 3 && strcasecmp(&result[len-3], ".txt") == 0) {
        file_type = ".txt";
    } else if (len > 3 && strcasecmp(&result[len-3], ".jpg") == 0 || strcasecmp(&result[len-3], ".png") == 0) {
        file_type = &result[len-4];
    } else {
        file_type = ".bin";
    }

    // Generate random digit sequence and append to result
    sprintf(&result[len], "%%06d", (int)(rand() % (1000000 - 1 + 1)));

    // Ensure resulting filename does not exceed maximum length
    if (strlen(result) > 256) {
        return "unknown";
    }

    // Return modified filename with new extension
    return result;
}

// Function to implement logging mechanism
void log(const char* message, FILE* file) {
    fprintf(file, "%s\n", message);
    fclose(file);  // Close the file after writing
}

int main() {
    FILE *log_file = fopen("app.log", "a");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
    } else {
        // Rotate log file daily
        time_t current_time = time(NULL);
        struct tm* current_tm = localtime(&current_time);
        if ((current_tm->tm_mday - 1) % 7 == 0 && current_tm->tm_hour == 23 && current_tm->tm_min == 59) {
            log("Rotating log file.\n", log_file);
            fclose(log_file);  // Close the log file
            char command[256];
            sprintf(command, "gzip -9 %s &", "app.log");
            system(command);
            rename("app.log.gz", "app.log.gz.1");
            rename("log.txt", "log.txt.1");
        }
    }

    // Test the function
    printf("%s\n", modify_filename("example.jpg"));
    return 0;
}
