char* process_filename(char* filename) {
    // Check for null or invalid filenames
    if (filename == NULL || strlen(filename) > 128) {
        char* new_filename = malloc(256);
        sprintf(new_filename, "unknown_%s", filename);
        free(filename);
        return new_filename;
    }

    time_t current_time = time(NULL);

    // Derive the file type from the last three characters of the filename
    char* file_type = malloc(5);
    strncpy(file_type, filename + strlen(filename) - 3, 4);
    file_type[4] = '\0';

    if (strcmp(file_type, ".txt") == 0 || strcmp(file_type, ".jpg") == 0 || strcmp(file_type, ".png") == 0) {
        // Append a sequence of random digits generated from the current time and a hash of the filename
        char* hashed_filename = malloc(256);
        sprintf(hashed_filename, "%s_%ld", filename, (long int)current_time);

        // Replace any spaces with underscores
        char* processed_filename = malloc(256);
        sprintf(processed_filename, "%s_", hashed_filename);
        free(hashed_filename);

        // Ensure the resulting filename does not exceed 256 characters
        if (strlen(processed_filename) > 250) {
            int i;
            for (i = strlen(processed_filename); i > 0; i--) {
                if (processed_filename[i - 1] == '_') {
                    processed_filename[i - 1] = '\0';
                    break;
                }
            }
        }

        free(filename);
        return processed_filename;
    } else {
        // Default to ".bin"
        char* new_filename = malloc(256);
        sprintf(new_filename, "%s.bin", filename);
        free(filename);
        return new_filename;
    }
}
