#define MAX_PREF_LENGTH 1024
#define MAX_HASH_LENGTH 64

typedef struct {
    char* key;
    char* value;
} Pref;

void trim_whitespace(char* str) {
    size_t len = strlen(str);
    memmove(str, str + strspn(str, " "), len - strspn(str, " "));
}

int validate_input(const char* input, const char** allowed_values, int num_allowed) {
    for (int i = 0; i < num_allowed; i++) {
        if (!strcmp(input, allowed_values[i])) {
            return 1;
        }
    }
    return 0;
}

char* suggest_closest_match(const char* input, const char** allowed_values, int num_allowed) {
    int min_dist = INT_MAX;
    char* closest_match = NULL;

    for (int i = 0; i < num_allowed; i++) {
        int dist = levenshtein_distance(input, allowed_values[i]);
        if (dist < min_dist) {
            min_dist = dist;
            closest_match = allowed_values[i];
        }
    }

    return closest_match;
}

unsigned char* hash_string(const char* str) {
    // Implement your preferred hashing algorithm here
    // For example:
    unsigned char* hash = (unsigned char*)calloc(1, sizeof(char));
    for (size_t i = 0; i < strlen(str); i++) {
        *(hash + i) = (str[i] % 256);
    }
    return hash;
}

void truncate_and_hash(Pref* pref) {
    if (strlen(pref->value) > MAX_PREF_LENGTH) {
        char* truncated_value = malloc((MAX_PREF_LENGTH + 1) * sizeof(char));
        strncpy(truncated_value, pref->value, MAX_PREF_LENGTH);
        truncated_value[MAX_PREF_LENGTH] = '\0';
        pref->value = truncated_value;
        unsigned char* hash = hash_string(pref->value);
        // Store the hash alongside the preference
    }
}

Pref* manage_preferences(const char* key, const char* value) {
    Pref* pref = (Pref*)malloc(sizeof(Pref));
    trim_whitespace(key);
    trim_whitespace(value);

    if (!validate_input(value, /* allowed_values */, /* num_allowed */)) {
        // Suggest the closest match
        value = suggest_closest_match(value, /* allowed_values */, /* num_allowed */);
    }

    pref->key = strdup(key);
    pref->value = strdup(value);
    truncate_and_hash(pref);

    return pref;
}

void log_event(const char* event) {
    FILE* log_file = fopen("log.txt", "a");
    if (log_file == NULL) {
        // Handle log file error
    }
    fprintf(log_file, "%s\n", event);
    fclose(log_file);
}

// Example usage:
