    Pref* pref1 = manage_preferences("setting_1", "invalid_input");
    Pref* pref2 = manage_preferences("setting_2", "long_value_that_exceeds_max_length");

    // Log events
    log_event("User set setting_1 to 'new_value'.");
    log_event("Error handling long preference value for setting_2.");

    return 0;
}
