typedef enum {
    START,
    PROCESSING,
    FINISHED
} State;

void process_filenames(char **filenames, int num_files, int *num_digits, char **file_types, int reversible) {
    // Initialize the state machine
    State state = START;

    // Create a dynamic list of states
    int max_states = MAX_STATES + 1; // Include the initial state
    State *states = (State *)malloc(max_states * sizeof(State));
    states[0] = START; // Set the initial state

