        char filename[256];
        sprintf(filename, "file_%d", i);

        switch (state) {
            case START:
                // Process the first file
                if (reversible) {
                    states[1] = PROCESSING;
                    state = PROCESSING;
                } else {
                    states[1] = FINISHED;
                    state = FINISHED;
                }
                break;
            case PROCESSING:
                // Process subsequent files
                if (reversible) {
                    states[i + 2] = PROCESSING;
                    state = PROCESSING;
                } else {
                    states[i + 2] = FINISHED;
                    state = FINISHED;
                }
                break;
        }
    }

    free(states);
}
