#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

#define MAX_ENDPOINTS 100
#define BUFFER_SIZE 1024

typedef struct {
    char* endpoint;
    int port;
} Endpoint;

int readEndpoints(const char* filename, Endpoint** endpoints);
void validateEndpoint(int sockfd, const char* endpoint);
void* checkEndpoint(void* arg);
void updateActiveEndpoints(Endpoint** activeEndpoints);
void freeEndpoints(Endpoint** endpoints);

int main(const int argc, const char* argv[]) {
    if (argc != 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        return -1;
    }

    Endpoint* endpoints = NULL;
    readEndpoints(argv[1], &endpoints);

    // Periodically refresh the list of active endpoints
    pthread_t thread;
    pthread_create(&thread, NULL, checkEndpoint, (void*)endpoints);

    // Main program flow
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR | SO_KEEPALIVE, NULL, 0);

    // Perform health checks and update active endpoints
    while (1) {
        updateActiveEndpoints(&endpoints);
        sleep(5);  // Adjust the refresh interval as needed
    }

    close(sockfd);
    freeEndpoints(&endpoints);
    return 0;
}

int readEndpoints(const char* filename, Endpoint** endpoints) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("fopen");
        return -1;
    }

    int count = 0;
    char buffer[BUFFER_SIZE];
    while (fgets(buffer, BUFFER_SIZE, file)) {
        char* endpoint = strtok(buffer, ":");
        if (!endpoint) {
            fclose(file);
            free(*endpoints);
            *endpoints = NULL;
            return -1;
        }

        int port = atoi(strtok(NULL, " "));
        Endpoint newEndpoint = (Endpoint){.endpoint = strdup(endpoint), .port = port};
        (*endpoints)[++count] = newEndpoint;

        if (count >= MAX_ENDPOINTS) {
            fclose(file);
            free(*endpoints);
            *endpoints = NULL;
            return -1;
        }
    }

    fclose(file);
    return count;
}

void validateEndpoint(int sockfd, const char* endpoint) {
    struct sockaddr_in addr;
    socklen_t len = sizeof(addr);

    if (getaddrinfo(endpoint, "80", (const struct addrinfo*)NULL, &addr, &len)) {
        printf("Invalid endpoint: %s\n", endpoint);
        return;
    }

    int newsockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (newsockfd < 0) {
        perror("socket");
        return;
    }

    setsockopt(newsockfd, SOL_SOCKET, SO_REUSEADDR | SO_KEEPALIVE, NULL, 0);

    connect(newsockfd, (struct sockaddr*)&addr, len);
    close(newsockfd);
}

void* checkEndpoint(void* arg) {
    Endpoint* endpoints = (Endpoint*)arg;
    for (int i = 0; i < MAX_ENDPOINTS; i++) {
        if (!endpoints[i].endpoint || !endpoints[i].port) {
            continue;
        }

        validateEndpoint(socket(AF_INET, SOCK_STREAM, 0), endpoints[i].endpoint);
        free(endpoints[i].endpoint);
    }
}

void updateActiveEndpoints(Endpoint** activeEndpoints) {
    // Update the list of active endpoints based on health checks
    pthread_t thread;
    pthread_create(&thread, NULL, checkEndpoint, (void*)*activeEndpoints);

    // Ensure thread safety and memory management
    // ...

    close(thread);
}

void freeEndpoints(Endpoint** endpoints) {
    for (int i = 0; i < MAX_ENDPOINTS; i++) {
        if (!endpoints[i].endpoint || !endpoints[i].port) {
            continue;
        }

        free(endpoints[i].endpoint);
    }
}
