#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>

typedef struct node {
    char id[16];
    int status;
} Node;

void* readConfigFile(char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return NULL;

    Node** nodes = NULL;
    int numNodes = 0;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        Node* node = malloc(sizeof(Node));
        sscanf(line, "%s %d", node->id, &node->status);
        node->id[strcspn(node->id, "\n")] = '\0';

        if (!nodes) {
            nodes = malloc(sizeof(Node*) * 1);
            numNodes = 1;
        } else {
            Node** newNodeArray = realloc(nodes, sizeof(Node*) * (numNodes + 1));
            nodes = newNodeArray;
            numNodes++;
        }
        nodes[numNodes - 1] = node;
    }

    fclose(file);

    return nodes;
}

void validateNodeStatus(Node* node) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) return;

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(8080);

    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    connect(sock, (struct sockaddr*) &server_addr, sizeof(server_addr));

    // Send data and receive response
    char buffer[256];
    send(sock, node->id, strlen(node->id), 0);
    read(sock, buffer, 256);
    close(sock);
}

void updateActiveNodes(Node** nodes, int numNodes) {
    pthread_t threads[numNodes];

    for (int i = 0; i < numNodes; i++) {
        Node* node = nodes[i];
        pthread_create(&threads[i], NULL, &validateNodeStatus, node);
    }

    for (int i = 0; i < numNodes; i++) {
        pthread_join(threads[i], NULL);
    }
}

void printActiveNodes(Node** nodes, int numNodes) {
    printf("Active Nodes: ");
    for (int i = 0; i < numNodes; i++) {
        Node* node = nodes[i];
        if (node->status) {
            printf("%s ", node->id);
        }
    }
    printf("\n");
}

int main() {
    char* filename = "config.txt";
    Node** nodes = readConfigFile(filename);

    if (!nodes) return 1;

    int numNodes = 0;
    for (Node* node = *nodes; node; node = *(++nodes)) {
        numNodes++;
    }

    updateActiveNodes(nodes, numNodes);

    printActiveNodes(nodes, numNodes);

    return 0;
}
