void log_message(int log_level, const char* format, ...) {
    va_list args;
    va_start(args, format);

    LogEntry* entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return; // Handle allocation failure

    entry->timestamp = time(NULL);
    int id = ++log_entries;
    entry->log_id = id;
    entry->level = log_level;

    asprintf(&entry->message, format, args);
    va_end(args);

    pthread_mutex_lock(&lock);
    entries = realloc(entries, (log_entries + 1) * sizeof(LogEntry*));
    entries[log_entries] = entry;
    pthread_mutex_unlock(&lock);
}

