#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <pthread.h>

#define MEM_MAX 1024 // max memory size
#define BLOCK_MAX 256 // max block size
#define ID_SIZE 32 // unique id size

typedef struct {
    int id;
    time_t timestamp;
    size_t size;
    char* purpose;
} MemoryBlock;

MemoryBlock* mem_blocks = NULL; // array to hold memory blocks
int mem_count = 0; // count of allocated blocks
pthread_mutex_t mem_lock = PTHREAD_MUTEX_INITIALIZER; // lock for concurrent access

// allocate a new memory block with metadata and unique id
void* mem_alloc(size_t size, const char* purpose) {
    pthread_mutex_lock(&mem_lock);

    MemoryBlock* new_block = (MemoryBlock*)malloc(sizeof(MemoryBlock));
    new_block->id = mem_count++;
    new_block->timestamp = time(NULL);
    new_block->size = size;
    new_block->purpose = strdup(purpose);

    void* ptr = malloc(size);
    if (!ptr) {
        // memory allocation failed, release block and return
        free(new_block->purpose);
        free(new_block);
        pthread_mutex_unlock(&mem_lock);
        return NULL;
    }

    mem_blocks = realloc(mem_blocks, (mem_count + 1) * sizeof(MemoryBlock));
    mem_blocks[mem_count - 1] = *new_block;

    pthread_mutex_unlock(&mem_lock);

    return ptr;
}

// deallocate a memory block and release its metadata
void mem_free(void* ptr) {
    pthread_mutex_lock(&mem_lock);

    for (int i = 0; i < mem_count; i++) {
        if (mem_blocks[i].id == 0) continue; // skip unallocated blocks

        if (mem_blocks[i].size == strlen(mem_blocks[i].purpose)) {
            // found the block to deallocate
            free(ptr);
            ptr = NULL;

            for (int j = i + 1; j < mem_count; j++) {
                mem_blocks[j - 1] = mem_blocks[j];
            }
            mem_blocks[mem_count - 1].id = 0;
            mem_count--;
        } else if ((char*)ptr <= (char*)mem_allocs[i].ptr &&
                   (char*)mem_allocs[i].ptr + mem_allocs[i].size >= (char*)ptr) {
            // found the block to deallocate and update metadata
            free(ptr);
            ptr = NULL;

            for (int j = i; j < mem_count; j++) {
                mem_blocks[j] = mem_blocks[j + 1];
            }
            mem_allocs[i].id = 0;
        } else {
            continue; // not the correct block to deallocate
        }

        pthread_mutex_unlock(&mem_lock);
        return;
    }

    pthread_mutex_unlock(&mem_lock);

    return;
}

// release all memory blocks and reset counters
void mem_release() {
    for (int i = 0; i < mem_count; i++) {
        free(mem_blocks[i].purpose);
        free((void*)mem_blocks[i].ptr);
    }
    free(mem_blocks);
    mem_blocks = NULL;
    mem_count = 0;
}

// print current memory usage and statistics
void mem_stats() {
    printf("Memory Usage:\n");
    for (int i = 0; i < mem_count; i++) {
        printf("%u: %s, allocated at %lu, purpose: %s\n",
               mem_blocks[i].id,
               "unknown",
               mem_blocks[i].timestamp,
               mem_blocks[i].purpose);
    }
}

// release local buffers when resources become available
void mem_flush() {
    for (int i = 0; i < mem_count; i++) {
        free((char*)mem_blocks[i].ptr);
        mem_blocks[i].ptr = NULL;
    }
}

int main() {
    // initialize memory management service
    init_memory_service();

    // allocate and deallocate memory blocks concurrently
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, (void*)mem_alloc, (size_t)256, "test");
        pthread_join(threads[i]);
    }

    mem_stats();
    mem_flush();

    return 0;
}
