        // Print the processed filenames and array contents
        printf("Processed filename: %s\n", new_filename);
        for (int m = 0; m < max_states; m++) {
            printf("Offset value: %d, Key value: %s, Transaction ID: %ld\n",
                   offset_values[m], key_values[m], transaction_ids[m]);
            free(key_values[m]);
        }

        // Free memory allocated for states and arrays
        free(states);
    }
}

