    new_filename[content_len] = '\0';
    fclose(file);

    time_t timestamp = time(NULL);
    struct tm *tm = localtime(&timestamp);
    char timestamp_str[30];
    strftime(timestamp_str, 30, "%Y-%m-%d_%H:%M:%S", tm);
    int seq_num = (int)file_size(filename);
    char seq_num_str[10];
    sprintf(seq_num_str, "%06d", seq_num);
    char rand_str[5];
    for (int i = 0; i < 5; i++) {
        rand_str[i] = (char)(rand() % 26 + 'a');
    }
    rand_str[5] = '\0';

    sprintf(new_filename, "%s_%s_%s", new_filename, timestamp_str, seq_num_str);
    if (strlen(new_filename) > 50) {
        strcat(new_filename, "_empty");
    }

    // Log operation
    printf("Renamed file %s to %s.\n", filename, new_filename);

    free(new_filename);
}

int file_size(const char* filename) {
    struct stat stat;
    fstat(fileno fopen(filename, "r"), &stat);
    return (int)stat.st_size;
