char *rename_file(char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        return filename;
    }

    char buffer[101];
    fread(buffer, 1, 100, file);
    buffer[100] = '\0';

    unsigned int sequence_number = (unsigned int)(rand() % ((size_t)2 << 31));
    time_t timestamp = time(NULL);
    uint64_t hash = 0;
    for (int i = 0; i < 100 && buffer[i]; i++) {
        hash = (hash << 5) + buffer[i];
    }

    char random_string[9];
    for (int i = 0; i < 8; i++) {
        random_string[i] = (char)(rand() % ('z' - 'a' + 1)) + 'a';
    }
    random_string[8] = '\0';

    int name_len = sprintf(NULL, "rename_%u_%lu_%x_%s", sequence_number, timestamp, hash, random_string);

    char *new_filename = malloc(name_len + 1);
    if (new_filename == NULL) {
        return filename;
    }
    if (*buffer == '\0') {
        sprintf(new_filename, "rename_empty");
    } else {
        sprintf(new_filename, "%.*s", name_len, buffer);
    }

    fclose(file);

    FILE *meta_file = fopen(strcat(filename, ".meta"), "w+");
    if (meta_file == NULL) {
        return new_filename;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    rewind(file);

    uint64_t checksum = 0;
    for (size_t i = 0; i < file_size; i++) {
        char c = fgetc(file);
        if (c == EOF) break;
        checksum += c;
    }

    fprintf(meta_file, "%lu\n", timestamp);
    fprintf(meta_file, "%.*s\n", 50, buffer + 50);
    fprintf(meta_file, "%lu\n", checksum);

    fclose(meta_file);

    return new_filename;
}
