        mkdir(new_dir_path, S_IRWXU | S_IRWXG | S_IROTH | S_IXOTH);
    }

    // Initialize the checksum buffer
    char* checksum = (char*)malloc(128 * sizeof(char));
    if (!checksum) {
        return;
