            char mime_type[10];
            FILE *mime_file = fopen("mime_types.txt", "r");
            if (fseek(mime_file, ent->d_name, SEEK_SET) == -1 || !fgets(mime_type, 10, mime_file)) {
                // handle error
                printf("Error reading MIME type.\n");
                continue;
            }
            fclose(mime_file);

            sprintf(new_dir, "%s-%ld-%ld-%x", mime_type, time(NULL), modification_time, (unsigned)hash[0]);
        }

        if (rename(ent->d_name, new_dir) == -1) {
            // handle error
            printf("Error renaming directory.\n");
            continue;
        }
    }

    closedir(dir);

    FILE *checksum_file = fopen("checksums.txt", "w");
    dir = opendir(directory_path);
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        file = fopen(ent->d_name, "rb");
        if (!file) {
            // handle error
            printf("Error reading file.\n");
            continue;
        }

        fseek(file, 0, SEEK_END);
        off_t length = ftell(file);
        fseek(file, 0);

        buffer[500] = '\0';
        fread(buffer, 1, 500, file);
        fclose(file);

        unsigned char checksum[16];
        FILE *checksum_subfile = fopen("checksums.txt", "a");
        fprintf(checksum_subfile, "%ld %x ", time(NULL), (unsigned)hash[0]);
        fwrite(&buffer[0], 1, length - 500, checksum_subfile);
        fclose(checksum_subfile);

        // compute MD5 hash
        unsigned char md5_checksum[16];
        FILE *md5_file = fopen("md5.sum", "r");
        if (!fseek(md5_file, ent->d_name, SEEK_SET) || !fgets(mime_type, 10, md5_file)) {
            // handle error
            printf("Error reading MD5 checksum.\n");
            continue;
        }
        fclose(md5_file);

        sprintf(new_dir, "%s-%ld-%ld", mime_type, time(NULL), modification_time);
    }

    closedir(dir);

    FILE *error_log = fopen("error.log", "a");
    fprintf(error_log, "Error renaming directory: %s\n", strerror(errno));
    fclose(error_log);
}
