#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    int status;
    void* child;
    int ref_count;
} record_t;

record_t* new_record(int value) {
    record_t* r = (record_t*)malloc(sizeof(record_t));
    r->value = value;
    r->status = 0;
    r->child = NULL;
    r->ref_count = 1;
    return r;
}

void free_record(record_t* r) {
    if(r != NULL) {
        if(r->child != NULL) {
            free_record((record_t*)r->child);
        }
        free(r);
    }
}

int garbage_collect(record_t** records, int num_records) {
    for(int i = 0; i < num_records; i++) {
        record_t* r = records[i];
        if(r->ref_count == 0) {
            free_record(r);
            // shift array
            for(int j = i; j < num_records - 1; j++) {
                records[j] = records[j + 1];
            }
            i--; // decrement and re-check this record
            num_records--;
        }
    }
    return num_records;
}

void create_state_list(int* initial_states, int num_initial_states, int last_state, int max_states,
                        int** offset, int offset_len, int** key, int key_len, int** child_index, int child_index_len) {
    // initialize memory for 'offset', 'key', and 'child_index' arrays
    *offset = (int*)malloc(sizeof(int) * offset_len);
    *key = (int*)malloc(sizeof(int) * key_len);
    *child_index = (int*)malloc(sizeof(int) * child_index_len);

    // populate 'record' array
    record_t* records = NULL;
    int num_records = 0;

    for(int i = 0; i < num_initial_states; i++) {
        int value = rand() % 100;
        record_t* r = new_record(value);
        r->status = (r->value % 2 == 0) ? 1 : 0;
        if(r->value > last_state) {
            r->child = &records[r->value - last_state];
            r->ref_count++;
        }
        records = realloc(records, sizeof(record_t*) * (num_records + 1));
        records[num_records] = r;
        num_records++;
    }

    for(int i = 0; i < child_index_len; i++) {
        if(child_index[i] >= num_records) {
            printf("Invalid child index!\n");
            return;
        }
        record_t* r = &records[child_index[i]];
        if(r->child != NULL && r->ref_count > 1) {
            // decrement reference count and reset child pointer
            (record_t*)r->child->ref_count--;
            r->child = NULL;
        } else {
            r->ref_count++;
        }
    }

    // garbage collect records that are no longer referenced
    num_records = garbage_collect(records, num_records);

    free(*offset);
    free(*key);
    free(*child_index);

    for(int i = 0; i < num_records; i++) {
        free_record(&records[i]);
    }
    free(records);
}
