        printf("Memory allocation failed for offsets.\n");
        free(records);
        return NULL;
    }
    double* values = (double*)malloc(max_records * sizeof(double));
    if (!values) {
        printf("Memory allocation failed for values.\n");
        free(records);
        free(offsets);
        return NULL;
    }
    int* keys = (int*)malloc(max_records * sizeof(int));
    if (!keys) {
        printf("Memory allocation failed for keys.\n");
        free(records);
        free(offsets);
        free(values);
        return NULL;
