        if (sensors[i]->id == id) {
            free(sensors[i]);
            sensors[i] = create_sensor(id, new_location, new_status);
            return;
        }
    }
}

void add_sensor(sensor** sensors, int* num_sensors, sensor* s) {
    *num_sensors += 1;
    *sensors = (sensor*)realloc(*sensors, sizeof(sensor)*(*num_sensors));
    (*sensors)[*num_sensors - 1] = s;
}

void destroy_sensors(sensor** sensors, int num_sensors) {
    for (int i = 0; i < num_sensors; i++) {
        free(sensors[i]);
    }
    free(sensors);
}
