// Define structure for device data
typedef struct {
    int id;
    char serial_number[20];
    char location[50];
    int power_status;
    char firmware_version[10];
} Device;

// Function to add a new device record
void add_device(Device **devices, long *timestamp, float *humidity, int *num_devices) {
    (*num_devices)++;
    *devices = realloc(*devices, sizeof(Device) * (*num_devices));
    timestamp = realloc(timestamp, sizeof(long) * (*num_devices));
    humidity = realloc(humidity, sizeof(float) * (*num_devices));

    Device new_device;
    // Initialize device fields
    // ...
    strcpy(new_device.location, "New Location");
    new_device.power_status = 1; // Assume ON by default

    (*devices)[(*num_devices)-1] = new_device;
}

// Function to update an existing device record
void update_device(Device **devices, long *timestamp, float *humidity, int id, int power_status) {
    for (int i = 0; i < *num_devices; i++) {
        if ((*devices)[i].id == id) {
            (*devices)[i].power_status = power_status;
            return;
        }
    }
}

// Function to remove a device by ID
void remove_device(Device **devices, long *timestamp, float *humidity, int id) {
    for (int i = 0; i < *num_devices; i++) {
        if ((*devices)[i].id == id) {
            memmove(&(*devices)[i], &(*devices)[i+1], sizeof(Device) * (*num_devices - i - 1));
            timestamp = realloc(timestamp, sizeof(long) * (--*num_devices));
            humidity = realloc(humidity, sizeof(float) * (*num_devices));
        }
    }
}

// Function to query the total number of devices meeting specific criteria
int query_devices(Device **devices, int power_status_threshold, char *firmware_version_threshold) {
    int count = 0;
    for (int i = 0; i < *num_devices; i++) {
        if ((*devices)[i].power_status == power_status_threshold && 
            strcmp((*devices)[i].firmware_version, firmware_version_threshold) > 0) {
            count++;
        }
    }
    return count;
}

int main() {
    // Initialize arrays and variables
    Device *devices = NULL;
    long *timestamp = NULL;
    float *humidity = NULL;
    int num_devices = 0;

    // Add new devices, update existing ones, remove devices
    add_device(&devices, &timestamp, &humidity, &num_devices);
    update_device(&devices, &timestamp, &humidity, 1, 0); // Update power status to OFF for device with ID 1
    remove_device(&devices, &timestamp, &humidity, 2); // Remove device with ID 2

