    FILE *fp = fopen(input_file, "rb");
    if (!fp) {
        printf("Error opening input file.\n");
        return;
    }

    Device *devices = NULL;
    long *timestamps = NULL;
    float *humidity_readings = NULL;

    int device_count = 0;
    int timestamp_count = 0;
    int humidity_reading_count = 0;

