        Device temp_device;
        if (fread(&temp_device, sizeof(Device), 1, fp) != 1) break;

        devices = realloc(devices, (device_count + 1) * sizeof(Device));
        timestamps = realloc(timestamps, (timestamp_count + 1) * sizeof(long));
        humidity_readings = realloc(humidity_readings, (humidity_reading_count + 1) * sizeof(float));

        devices[device_count] = temp_device;
        timestamps[timestamp_count] = temp_device.timestamp;
        humidity_readings[humidity_reading_count] = temp_device.humidity;

        device_count++;
        timestamp_count++;
        humidity_reading_count++;
    }

    fclose(fp);

    fp = fopen(output_file, "wb");
    if (!fp) {
        printf("Error opening output file.\n");
        return;
    }

    fwrite(&device_count, sizeof(int), 1, fp);
    fwrite(devices, sizeof(Device), device_count, fp);
    fwrite(timestamps, sizeof(long), timestamp_count, fp);
    fwrite(humidity_readings, sizeof(float), humidity_reading_count, fp);

    free(devices);
    free(timestamps);
    free(humidity_readings);

