    if (!entries) return NULL;

    const char* substrStart = str;
    for (size_t i = 0; i < n; ++i) {
        size_t len = strlen(substrStart);
        entries[i].buffer = (char*)malloc(len + 1);
        if (!entries[i].buffer) return NULL;

        memcpy(entries[i].buffer, substrStart, len);
        entries[i].buffer[len] = '\0';

        entries[i].key = len;
        substrStart += len + 1;
    }

    return entries;
