#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* buffer;
    int key;
} dataEntry;

dataEntry* manageMemory(char* str, size_t limit) {
    dataEntry* entries = NULL;
    size_t totalSize = 0;
    size_t count = 0;

    for (char* p = str; *p != '\0'; p++) {
        if (*p == ' ') {
            *p = '\0';
            p++;
        }
    }

    char substr[10];
    for (char* p = strtok(str, " "); p; p = strtok(NULL, " ")) {
        dataEntry* entry = malloc(sizeof(dataEntry));
        if (!entry) return NULL;

        entry->buffer = malloc(strlen(p) + 1);
        if (!(entry->buffer)) {
            free(entry);
            return NULL;
        }

        strcpy(entry->buffer, p);

        entries = realloc(entries, (count + 1) * sizeof(dataEntry));
        if (!entries) {
            for (size_t i = 0; i < count; i++) {
                free(entries[i].buffer);
            }
            free(entries);
            return NULL;
        }

        entries[count] = *entry;

        totalSize += strlen(p) + 1;
        count++;

        if (totalSize > limit) {
            while (count-- > 0 && totalSize - (strlen(entries[count].buffer) + 1) >= limit) {
                free(entries[count].buffer);
            }
            reallocateEntries(&entries, &count, limit);
        }
    }

    for (size_t i = 0; i < count; i++) {
        entries[i].key = strlen(entries[i].buffer);
    }

    return entries;
}

void reallocEntries(dataEntry** entries, size_t* count, size_t limit) {
    while (*count > 0 && totalSize - (strlen(entries[*count-1].buffer) + 1) >= limit) {
        free(entries[--*count].buffer);
    }
}
