void manageFileEntries(int numEntries, char* directoryPath, size_t limit) {
    fileEntry* entries = malloc(numEntries * sizeof(fileEntry));
    if (!entries) {
        perror("malloc");
        return;
    }
    time_t currenttime = time(NULL);
    for (int i = 0; i < numEntries; i++) {
        fileEntry* entry = &entries[i];
        int fd = open_temp_file(directoryPath, i);
        if (-1 == fd) {
            perror("open");
            close_file_entry(entry);
            free(entry);
            continue;
        }
        entry->fd = fd;
        entry->timestamp = currenttime - i;
    }

    while (check_disk_usage() > limit) {
        fileEntry* minEntry = find_least_recently_used_entry();
        if (!minEntry) {
            break;
        }
        close_file_entry(minEntry);
        free(minEntry);
    }

    pthread_create(&timer_thread, NULL, timer_func, entries);
}

int open_temp_file(char* directoryPath, int id) {
    char filename[256];
    sprintf(filename, "%s/temp_%d.txt", directoryPath, id);
    int fd = creat(filename, 0644);
    if (-1 == fd) {
        return -1;
    }
    ftruncate(fd, 0);
    close(fd);
    return open(filename, O_RDWR | O_CREAT | O_TRUNC, 0666);
}

void close_file_entry(fileEntry* entry) {
    close(entry->fd);
    unlink((char*)entry->filename);
}
