    // Check if allocation fails
    if ((size <= 0) || (size > (1 << 30))) {
        return NULL;
    }

    // Dynamically allocate memory for the Item array
    Item* items = (Item*)malloc(size * sizeof(Item));

    if (items == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed!\n");
        return NULL;
    }

    // Initialize each Item with a unique ID and random value
    srand(time(NULL));  // Seed the random number generator

    for (int i = 0; i < size; i++) {
        items[i].id = i + 1;
        items[i].value = (double)rand() / RAND_MAX * 100.0;
    }

    return items;
}

// Function to deallocate memory for the Item array
void freeItems(Item* items, int size) {
    if (items != NULL && size > 0) {
        free(items);
    }
