#define MINUTE 60

typedef struct {
    int fd;
    time_t timestamp;
} fileEntry;

fileEntry* files[MAX_FILE_DESCR];
int numFiles = 0;
int totalSpaceUsage = 0;
char* defaultDir = DEFAULT_DIR;

void closeFile(int fd) {
    // implementation to close the file descriptor
}

void removeFile(int fd) {
    // implementation to remove the file associated with the file descriptor
}

void updateTimestamp(fileEntry* entry) {
    entry->timestamp = time(NULL) - (entry->timestamp % MINUTE);
}

void manageFiles(int dirSpaceLimit, int checkInterval) {
    while (1) {
        sleep(checkInterval);
        for (int i = 0; i < numFiles; i++) {
            fileEntry* entry = files[i];
            if (!entry) continue;
            updateTimestamp(entry);
            if (totalSpaceUsage + lseek(entry->fd, 0, SEEK_END) > dirSpaceLimit) {
                int leastUsedIndex = -1;
                int minAge = INT_MAX;
                for (int j = 0; j < numFiles; j++) {
                    fileEntry* curEntry = files[j];
                    if (!curEntry) continue;
                    int age = difftime(time(NULL), curEntry->timestamp);
                    if (age < minAge) {
                        leastUsedIndex = j;
                        minAge = age;
                    }
                }
                if (leastUsedIndex != -1) {
                    closeFile(files[leastUsedIndex]->fd);
                    removeFile(files[leastUsedIndex]->fd);
                    files[leastUsedIndex] = NULL;
                    totalSpaceUsage -= lseek(files[leastUsedIndex]->fd, 0, SEEK_END);
                    numFiles--;
                }
            }
        }
    }
}

int initFiles(const char* dirPath) {
    defaultDir = dirPath;
    for (int i = 0; i < MAX_FILE_DESCR; i++) files[i] = NULL;
    return 0;
}
