        (*records)[i]->value = i + 1;
        strcpy((*records)[i]->string, "Item ");
        strcat((*records)[i]->string, itoa(item.id));
        (*records)[i]->weight = item.value;

        // Initialize the offsets and keys arrays
        (*offsets)[i] = (long)i;
        (*keys)[i] = i % 1000;
    }
}

// Compute the weighted average of the weights for each batch
Result computeWeightedAverage(int numItems, double* weights) {
    Result result;
    double sum_weights = 0.0;
    for (int i = 0; i < numItems; i++) {
        sum_weights += (*weights)[i];
    }
    result.average_weight = sum_weights / numItems;
    return result;
}

// Main function
int main() {
    int numItems;
    long* offsets;
    int* keys;
    double* weights;
    Record** records;

    pthread_t thread;
    pthread_create(&thread, NULL, initializeItems, &numItems, &offsets, &keys, &weights, &records);
    pthread_join(thread, NULL);

    Result result = computeWeightedAverage(numItems, weights);

    // Print the result
    printf("Weighted average: %f\n", result.average_weight);

    return 0;
}

