        items[i].id = i + 1;
        items[i].value = (double)rand() / RAND_MAX * 100.0;
    }

    return items;
}

// Function to serialize the Item array into a binary format
void item_array_serialize(const Item* items, int size, char* buffer) {
    // Serialize the data in binary format
    for (int i = 0; i < size; i++) {
        *(char*)buffer += (items[i].id << 31) | (items[i].value * 100.0);  // Use bit shifting to encode id and value
        buffer += sizeof(char);
    }
}

// Function to deserialize the Item array from a binary format
Item* item_array_deserialize(const char* buffer, int size) {
    // Deserialize the data in binary format
    Item* items = (Item*)malloc(size * sizeof(Item));

    for (int i = 0; i < size; i++) {
        items[i].id = *(buffer + i * sizeof(char)) >> 31;
        items[i].value = (*(buffer + i * sizeof(char))) / 100.0;  // Use bit shifting to decode id and value
    }

    return items;
}

// Function to deallocate memory for the Item array
void item_array_free(Item* items, int size) {
    free(items);
}

int main() {
    // Example usage
    int size = 10;
    Item* items = item_array(size);

    // Use the Item array

    // Serialize and store the data
    char buffer[size * sizeof(char)];
    item_array_serialize(items, size, buffer);

