void config_settings_manager(size_t max_settings) {
    // Allocate arrays for key, type, and value
    char** keys = (char**)malloc(max_settings * sizeof(char*));
    if (!keys) {
        fprintf(stderr, "Error: Memory allocation failed for keys.\n");
        return;
    }

    ValueType* types = (ValueType*)malloc(max_settings * sizeof(ValueType));
    if (!types) {
        free(keys);
        fprintf(stderr, "Error: Memory allocation failed for types.\n");
        return;
    }

    void** values = (void**)malloc(max_settings * sizeof(void*));
    if (!values) {
        free(keys);
        free(types);
        fprintf(stderr, "Error: Memory allocation failed for values.\n");
        return;
    }

    // Populate arrays with default values
    for (size_t i = 0; i < max_settings; ++i) {
        keys[i] = (char*)malloc(16 * sizeof(char)); // assume max key length is 15
        sprintf(keys[i], "setting_%zu", i);

        types[i] = INTEGER;
        if (i % 3 == 1) {
            types[i] = FLOAT;
        } else if (i % 3 == 2) {
            types[i] = BOOLEAN;
        }

        switch (types[i]) {
            case INTEGER:
                values[i] = malloc(sizeof(int));
                *(int*)values[i] = i;
                break;
            case FLOAT:
                values[i] = malloc(sizeof(float));
                *(float*)values[i] = i / 3.0f;
                break;
            case BOOLEAN:
                values[i] = malloc(sizeof(bool));
                *(bool*)values[i] = i % 2 == 0;
                break;
        }
    }

    // Free allocated memory
    for (size_t i = 0; i < max_settings; ++i) {
        free(keys[i]);
        if (types[i] == INTEGER || types[i] == FLOAT) {
            free(values[i]);
        } else {
            free((void*)values[i]);
        }
    }

    free(keys);
    free(types);
    free(values);
}
