// Function to manage memory allocation and initialization for a collection of records
void* recordManager(int maxRecords) {
    // Allocate memory for three arrays: one for `long` offset values, one for `int` keys, and one for `struct record` objects
    void** arrays = malloc(3 * sizeof(void*));
    if (!arrays) return NULL;

