        rec->offset = rand() % 100000;
        rec->key = rand() % 10000;
        rec->timestamp = time(NULL);
        rec->status = INIT;
    }

    return arrays;
}

// Function to free all allocated memory
void recordManagerFree(void** arrays) {
    if (!arrays) return;

    free((long*)arrays[0]);
    free((int*)arrays[1]);
    free((record*)arrays[2]);

    free(arrays);
}
