    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    new_node->record = record;
    new_node->next = NULL;
    return new_node;
}

void free_nodes(Node** head_ref) {
    Node* current = *head_ref;
    Node* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    *head_ref = NULL;
}

int main() {
    srand(time(NULL));  // seed the random number generator

    int num_records = 10; // specify the number of records
    Node* head = NULL;

    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) {
        printf("Memory allocation failed\n");
        return -1;
    }

    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        printf("Memory allocation failed\n");
        return -1;
    }

    struct record** records = (struct record**)malloc(num_records * sizeof(struct record*));
    for (int i = 0; i < num_records; i++) {
        records[i] = (struct record*)malloc(sizeof(struct record));
        if (!records[i]) {
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++)
                free(records[j]);
            printf("Memory allocation failed\n");
            return -1;
        }
        records[i]->value = rand() % 100; // generate a random value
        records[i]->field = 'A' + rand() % 26; // generate a random character field
    }

    for (int i = 0; i < num_records; i++) {
        offsets[i] = i;
        keys[i] = i;
        Node* new_node = create_node(records[i]);
        if (!new_node) {
            free_nodes(&head);
            free(offsets);
            free(keys);
            for (int j = 0; j < i; j++)
                free(records[j]);
            printf("Memory allocation failed\n");
            return -1;
        }
        new_node->next = head;
        head = new_node;
    }

    // ... use the records and linked list here ...

    free_nodes(&head);
    free(offsets);
    free(keys);
    for (int i = 0; i < num_records; i++)
        free(records[i]);

    return 0;
}
