#include <string.h>
#include <stdbool.h>

// Define structure for user preference
typedef struct {
    char* key;
    char* value;
} Preference;

// Define hash table structure
typedef struct {
    size_t capacity;
    size_t size;
    Preference** buckets;
} HashTable;

// Function to manage dynamic list of user preferences
Preference* manage_preferences(char* input, HashTable* ht) {
    // Normalize input by converting to lowercase and trimming whitespace
    char normalized[128];
    snprintf(normalized, 127, "%s", strcasecmp(input, "") == 0 ? "" : strdup(strtok(strlwr(input), " \t")));

    // Validate input against allowed values
    if (strlen(normalized) > 1024 || !strpbrk(normalized, "abcdefghijklmnopqrstuvwxyz0123456789_-,./:;()[]{}'|\"-+*~!@#$%^&=<>.? ")) {
        return manage_preferences("default_preference", ht);
    }

    // Check for preference exceeding 128 characters
    if (strlen(normalized) > 128) {
        // Truncate and append hash of truncated version
        char truncated[129];
        snprintf(truncated, 128, "%s", strlwr(strtok(normalized, "")));
        char hash[33];
        sprintf(hash, "%x", crc32(truncated));
        normalized[127] = '\0';
        strcat(normalized, "#");
        strcat(normalized, hash);
    }

    // Store preference in hash table
    size_t index = crc32(normalized) % ht->capacity;
    Preference* preference = malloc(sizeof(Preference));
    preference->key = strdup(normalized);
    preference->value = "";
    if (ht->buckets[index] == NULL || strcmp(preference->key, ht->buckets[index]->key) < 0) {
        for (int i = ht->size; i > 0; --i) {
            if (strcmp(preference->key, ht->buckets[(index + i - 1) % ht->capacity]->key) <= 0) {
                memmove(&ht->buckets[index], &ht->buckets[(index + i - 1) % ht->capacity], sizeof(Preference*) * i);
                break;
            }
        }
        ht->size++;
    } else {
        Preference* temp = ht->buckets[index];
        free(preference);
        preference = temp;
    }

    return preference;
}

// Function to initialize hash table
HashTable* init_hash_table(size_t capacity) {
    HashTable* ht = malloc(sizeof(HashTable));
    ht->capacity = capacity;
    ht->size = 0;
    ht->buckets = calloc(capacity, sizeof(Preference*));
    return ht;
}

// Function to free resources
void free_resources(Preference* preference) {
    if (preference != NULL) {
        free(preference->key);
        free(preference);
    }
}
