typedef struct {
    char* buffer;
    int size;
} NFAPI_UL_CCCH_pdu_t;

NFAPI_RRC_UECONTEXT_T* create_ue_context() {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    ue_ctx->pdus = NULL;
    return ue_ctx;
}

void add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T* ue_ctx, NFAPI_UL_CCCH_pdu_t* pdu) {
    // Validate the integrity of the PDU list
    if (!ue_ctx->pdus) {
        ue_ctx->pdus = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        ue_ctx->pdus->buffer = NULL;
        ue_ctx->pdus->size = 0;
    }
    // Add the PDU to the list
    pdu->buffer = (char*)malloc(strlen(pdu->buffer) + 1);
    strcpy(pdu->buffer, pdu->buffer);
    ue_ctx->pdus->size++;
}

void free_ue_context(NFAPI_RRC_UECONTEXT_T* ue_ctx) {
    if (!ue_ctx) return;
    // Free the PDU list
    NFAPI_UL_CCCH_pdu_t* pdus = ue_ctx->pdus;
    while (pdus) {
        NFAPI_UL_CCCH_pdu_t* next = pdus->next;
        free(pdus->buffer);
        free(pdus);
        pdus = next;
    }
    free(ue_ctx);
}

NFAPI_RRC_UECONTEXT_T* ue_context_init() {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = create_ue_context();
    return ue_ctx;
}
