void rename_file(char *filename, FILE *file) {
    char buffer[1024];
    fseek(file, 0, SEEK_SET);
    fread(buffer, sizeof(char), 10, file);

    if (ferror(file) || feof(file)) {
        sprintf(filename, "%s_empty", get_original_extension(filename));
    } else {
        char new_filename[MAX_FILENAME_LENGTH + 1];
        sprintf(new_filename, "timestamp-%s-sequence-%05ld-random-%c%c%c%c%c.txt",
                strftime(buffer, sizeof(buffer), TIMESTAMP_FORMAT, localtime(NULL)),
                ftell(file) / (1024 * 1024),
                rand() % 26 + 'a',
                rand() % 26 + 'a',
                rand() % 26 + 'a',
                rand() % 26 + 'a',
                rand() % 26 + 'a');

        if (strlen(new_filename) > MAX_FILENAME_LENGTH) {
            sprintf(new_filename, "%.*s", (int)(MAX_FILENAME_LENGTH - 1), new_filename);
            strcat(new_filename, ".");
            strcat(new_filename, get_original_extension(filename));
        }
    }
}

char *get_original_extension(const char *filename) {
    int i = strlen(filename) - 1;
    while (i >= 0 && filename[i] != '.') {
        i--;
    }
    return strdup(&filename[i + 1]);
}
