// Function to modify filename extension
void modify_filename(char* filename) {
    // Open file and read first 10 characters of content
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        strcpy(filename, "_empty");
        return;
    }
    fseek(file, 0, SEEK_SET);
    char buffer[11];
    fread(buffer, 1, 10, file);
    fclose(file);

    // Generate random alphanumeric string
    srand(time(NULL));
    int len = 5;
    char* random_string = (char*)malloc(len + 1);
    for (int i = 0; i < len; i++) {
        if (rand() % 2) {
            random_string[i] = 'a' + rand() % 26;
        } else {
            random_string[i] = 'A' + rand() % 26;
        }
    }
    random_string[len] = '\0';

    // Create new filename with sequence number, file type, and timestamp
    time_t current_time = time(NULL);
    char* new_filename = (char*)malloc(strlen(filename) + len + 20);
    strcpy(new_filename, filename);
    strcat(new_filename, "_");
    sprintf(new_filename + strlen(new_filename), "%05d_%s_", rand() % 100000);
    struct tm* time_info = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, 20, "%Y-%m-%dT%H:%M:%S", time_info);
    strcat(new_filename, timestamp);

    // Replace original filename with new one
    free(filename);
    filename = new_filename;

    // Free dynamically allocated memory
    free(random_string);
}

int main() {
    char* filename = "example.txt";
    modify_filename(filename);
    printf("%s\n", filename);
    return 0;
}
