#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <cmath>

class DataProcessor {
private:
    std::vector<double> dataset;
    double mean_, variance_;
    mutable std::mutex mtx;

public:
    DataProcessor() : mean_(0.0), variance_(0.0) {}

    void insert(double value) {
        std::lock_guard<std::mutex> lock(mtx);
        dataset.push_back(value);
        if (dataset.size() > 1) {
            double sum = 0.0;
            for (double val : dataset) {
                sum += val - mean_;
            }
            variance_ = sum / (dataset.size() - 1);
            mean_ = std::accumulate(dataset.begin(), dataset.end(), 0.0) / dataset.size();
        } else {
            mean_ = value;
        }
    }

    void remove(size_t index) {
        if (index >= dataset.size()) return;

        std::lock_guard<std::mutex> lock(mtx);
        double sum = 0.0, new_mean = 0.0;
        for (size_t i = 0; i < dataset.size(); ++i) {
            if (i != index) {
                sum += dataset[i] - mean_;
            }
        }
        if (dataset.size() > 1) {
            variance_ = sum / (dataset.size() - 2);
            new_mean = (std::accumulate(dataset.begin(), dataset.end(), 0.0) - dataset[index]) / (dataset.size() - 1);
        } else {
            mean_ = 0.0;
        }
        dataset.erase(dataset.begin() + index);
        mean_ = new_mean;
    }

    double getMean() const {
        return mean_;
    }

    double getVariance() const {
        return variance_;
    }

    void exportToCSV(const std::string& filename) const {
        std::ofstream file(filename);
        for (double val : dataset) {
            file << val << ", ";
        }
        file << "\nMean: " << mean_ << ", Variance: " << variance_;
    }

    static DataProcessor loadFromCSV(const std::string& filename) {
        DataProcessor processor;
        std::ifstream file(filename);
        if (!file.is_open()) return processor;

        double val;
        while (file >> val) {
            processor.insert(val);
        }
        return processor;
    }

    friend std::ostream& operator<<(std::ostream& os, const DataProcessor& processor) {
        os << "Dataset size: " << processor.dataset.size() << "\nMean: " << processor.mean_ << ", Variance: " << processor.variance_;
        return os;
    }
};
