#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_TOKEN_LENGTH 128
#define CACHE_SIZE 1000

typedef struct {
    char token[MAX_TOKEN_LENGTH + 1];
    bool isValid;
} Token;

Token* session_tokens = NULL;
int num_tokens = 0;

void tokenize_session(char* token) {
    int len = strlen(token);
    for (int i = 0; i < len; i++) {
        if (!isalnum((unsigned char)token[i]) && token[i] != '_') {
            sprintf(token, "_%.*s", i, token);
            return;
        }
    }
}

bool validate_token(char* token) {
    // Validate against predefined allowed formats
    if (strlen(token) > MAX_TOKEN_LENGTH)
        return false;
    for (int i = 0; i < strlen(token); i++) {
        if (!isalnum((unsigned char)token[i]) && token[i] != '_') {
            tokenize_session(token);
            return true;
        }
    }
    return true;
}

void normalize_token(char* token) {
    int len = strlen(token);
    for (int i = 0; i < len; i++) {
        if (!isalpha((unsigned char)token[i])) {
            sprintf(token, "%.*s", i, token);
            return;
        }
    }
}

bool check_token(char* token) {
    // Check if the token is valid and normalized
    if (validate_token(token) && normalize_token(token))
        return true;
    else
        return false;
}

void add_session_token(char* token) {
    int len = strlen(token);
    char new_token[MAX_TOKEN_LENGTH + 1];
    if (len > MAX_TOKEN_LENGTH) {
        strncpy(new_token, token, MAX_TOKEN_LENGTH);
        new_token[MAX_TOKEN_LENGTH] = '\0';
    } else
        strcpy(new_token, token);

    // Check for uniqueness and truncate to 64 characters if necessary
    if (!check_token(token)) {
        char* valid_token = NULL;
        int j = 0;
        while (j < strlen(new_token) && !isalnum((unsigned char)new_token[j])) {
            j++;
        }
        strncpy(valid_token, new_token + j, MAX_TOKEN_LENGTH - j);
        valid_token[MAX_TOKEN_LENGTH] = '\0';
        if (!check_token(valid_token)) {
            int hash_len = 4;
            char hash[hash_len + 1];
            sprintf(hash, "%x", (unsigned)valid_token[0]);
            strcat(valid_token, hash);
        }
    }

    // Store token in the session tokens array
    Token* new_token_obj = (Token*)malloc(sizeof(Token));
    strcpy(new_token_obj->token, valid_token ? valid_token : "default_token");
    new_token_obj->isValid = true;
    if (!session_tokens) {
        session_tokens = (Token*)malloc(sizeof(Token) * 1);
        num_tokens = 1;
    } else {
        session_tokens = (Token*)realloc(session_tokens,
                                          sizeof(Token) * (num_tokens + 1));
        num_tokens++;
    }
    session_tokens[num_tokens - 1] = *new_token_obj;
}

void get_session_token(char* token) {
    // Retrieve and return the corresponding token from the session tokens array
    for (int i = 0; i < num_tokens; i++) {
        if (strcmp(session_tokens[i].token, token) == 0)
            strcpy(token, session_tokens[i].token);
    }
}

void update_session_token(char* old_token, char* new_token) {
    // Update the corresponding token in the session tokens array
    for (int i = 0; i < num_tokens; i++) {
        if (strcmp(session_tokens[i].token, old_token) == 0) {
            strcpy(session_tokens[i].token, new_token);
            return;
        }
    }
}

void clear_session_tokens() {
    // Clear the session tokens array
    for (int i = 0; i < num_tokens; i++)
        free(&session_tokens[i]);
    free(session_tokens);
    session_tokens = NULL;
    num_tokens = 0;
}
