#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct LTE_RRC_MSG_T {
    int UE_ID;
    int CELL_ID;
    char RRC_MESSAGE_TAG[10];
    int SEQUENCE_NUMBER;
} LTE_RRC_MSG_T;

typedef struct node {
    LTE_RRC_MSG_T data;
    struct node* next;
} node_t;

node_t* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

node_t* create_node(LTE_RRC_MSG_T data) {
    node_t* new_node = (node_t*)malloc(sizeof(node_t));
    if(new_node == NULL) {
        return NULL;
    }
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_at_end(LTE_RRC_MSG_T data) {
    node_t* new_node = create_node(data);
    pthread_mutex_lock(&lock);
    if(head == NULL) {
        head = new_node;
    } else {
        node_t* temp = head;
        while(temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

void delete_node(int UE_ID) {
    node_t* prev = NULL;
    node_t* current = head;
    pthread_mutex_lock(&lock);
    while(current != NULL && current->data.UE_ID != UE_ID) {
        prev = current;
        current = current->next;
    }
    if(current == NULL) {
        printf("Node not found\n");
        return;
    }
    if(prev == NULL) {
        head = current->next;
    } else {
        prev->next = current->next;
    }
    free(current);
    pthread_mutex_unlock(&lock);
}

void* iterate_list(void* arg) {
    node_t* temp = head;
    while(temp != NULL) {
        printf("UE_ID: %d, CELL_ID: %d, RRC_MESSAGE_TAG: %s, SEQUENCE_NUMBER: %d\n", 
               temp->data.UE_ID, temp->data.CELL_ID, temp->data.RRC_MESSAGE_TAG, temp->data.SEQUENCE_NUMBER);
        temp = temp->next;
    }
    return NULL;
}

void print_list() {
    pthread_create(NULL, NULL, iterate_list, NULL);
}

int main() {
    // Example usage:
    LTE_RRC_MSG_T data1 = {1234, 5678, "MSG_1", 1};
    LTE_RRC_MSG_T data2 = {9012, 3456, "MSG_2", 2};
    LTE_RRC_MSG_T data3 = {7890, 6789, "MSG_3", 3};

    insert_at_end(data1);
    insert_at_end(data2);
    insert_at_end(data3);

    print_list();

    // Example deletion:
    delete_node(1234);

    return 0;
}
