    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        return -1;  // Directory not found or access denied
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        char file_path[256];
        sprintf(file_path, "%s/%s", dir_path, entry->d_name);

        FILE* file = fopen(file_path, "rb");
        if (file == NULL) {
            return -1;  // File not found or access denied
        }

        fseek(file, 0, SEEK_END);
        int file_size = ftell(file);
        rewind(file);

        char content[file_size];
        fread(content, 1, 500, file);
        fclose(file);

        if (file_size == 0) {
            // File is empty or cannot be read
            strcat(dir_path, "_empty");
        } else {
            time_t timestamp = time(NULL);
            char classification_tag[12];
            sprintf(classification_tag, "%s-%d-%d-", mime_type(entry->d_name), timestamp, rand());
            hash_t file_hash;
            md5(content, 500, &file_hash);

            char new_dir_path[128];
            sprintf(new_dir_path, "%s/%s-%ld-%x-", dir_path, classification_tag, timestamp, (long)file_hash);
            mkdir(new_dir_path, 0755);

            // Write checksum to "checksums.txt"
            FILE* checksum_file = fopen("checksums.txt", "a");
            if (checksum_file == NULL) {
                return -1;  // Error writing checksum file
            }

            fprintf(checksum_file, "%d %d %x\n", timestamp, file_hash, (long)file_hash);
            fclose(checksum_file);
        }
    }

    closedir(dir);
}

int main() {
    manage_ue_contexts(ue_contexts, num_ue_contexts);
    rename_directory("/path/to/directory");
    return 0;
}
