                                // Create a new connection structure if it doesn't exist
                                if (num_conns == 0) {
                                    conn_list = malloc(sizeof(Connection));
                                    conn_list->session_id = num_conns;
                                    conn_list->status = 1; // assume the connection is connected initially
                                    conn_list->requests = NULL;
                                    conn_list->num_requests = 0;
                                    num_conns++;
                                }

                                // Allocate memory for the new request and add it to the list
                                char* req = malloc(strlen(category_name) + 1);
                                strcpy(req, category_name);

                                // Add the request to the connection's request list
                                if (conn_list->requests == NULL) {
                                    conn_list->requests = malloc(sizeof(char*) * 2);
                                    conn_list->requests[0] = req;
                                    conn_list->num_requests = 1;
                                } else {
                                    char** new_reqs = realloc(conn_list->requests, sizeof(char*) * (conn_list->num_requests + 2));
                                    new_reqs[conn_list->num_requests] = req;
                                    new_reqs[conn_list->num_requests + 1] = NULL;
                                    conn_list->requests = new_reqs;
                                    conn_list->num_requests++;
