                    method_counts[0]++;
                } else if (strcmp(req_method, "POST") == 0) {
                    method_counts[1]++;
                } // ... handle other request methods ...
            }
        }

        for (int i = 0; i < 10 && i < num_conns; i++) {
            int max_count = 0;
            char* top_method = NULL;

            for (int j = 0; j < num_conns; j++) {
                // Find the most frequent request method
                Connection* conn = &conn_list[j];
                for (int k = 0; k < conn->num_requests; k++) {
                    char* req_method = conn->requests[k];
                    if (strcmp(req_method, "GET") == 0) {
                        max_count++;
                        top_method = "GET";
                    } else if (strcmp(req_method, "POST") == 0) {
                        max_count++;
                        top_method = "POST";
                    } // ... handle other request methods ...
                }
            }

            fprintf(meta_file, "%s - %d\n", top_method, method_counts[i]);
        }

        fclose(meta_file);
    }

    // Handle errors and log them to a specified error log file
    // ... implement error handling logic ...

    // Free memory resources
    for (int i = 0; i < num_conns; i++) {
        Connection* conn = &conn_list[i];
        for (int j = 0; j < conn->num_requests; j++) {
            free(conn->requests[j]);
        }
        free(conn->requests);
    }

    free(dir_str);

    // Close the log directory
    closedir(dp);
}
