    while ((ent = readdir(dir))) {
        char file_path[1024];
        sprintf(file_path, "%s/%s", dir_path, ent->d_name);

        FILE* file = fopen(file_path, "rb");
        if (!file) {
            // handle error
            continue;
        }

        fseek(file, 0, SEEK_END);
        long file_size = ftell(file);
        rewind(file);

