        char hash_string[33];
        for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
            sprintf(&hash_string[i*2], "%02x", (unsigned int) hash[i]);
        }
        hash_string[32] = '\0';

        strcat(category, "_");
        strcat(category, timestamp);
        strcat(category, "_");
        sprintf(category + strlen(category), "%d", sequence_number);
        strcat(category, "_");
        strcat(category, hash_string);
        strcat(category, "_");
        strcat(category, random_string);

        *resources = realloc(*resources, (++num_resources) * sizeof(Resource*));
        new_resource->id = num_resources;
        new_resource->value = (double)rand() / RAND_MAX;

        // handle potential allocation failures
    }

    closedir(dir);
}
