typedef struct {
    char session_id[16];
    int status;
    struct {
        char* request_list;
        int size;
    } http_requests;
} TCP_connection;

TCP_connection* new_tcp_connection(char* session_id) {
    TCP_connection* conn = (TCP_connection*)malloc(sizeof(TCP_connection));
    strcpy(conn->session_id, session_id);
    conn->status = 0;
    conn->http_requests.request_list = NULL;
    conn->http_requests.size = 0;
    return conn;
}

void add_request_to_session(TCP_connection* conn, char* request) {
    // validate integrity of the request list
    if (!conn || !request) return;

    int new_size = conn->http_requests.size + strlen(request);
    char* new_list = (char*)realloc(conn->http_requests.request_list, new_size+1);
    strcpy(new_list, conn->http_requests.request_list);
    strcat(new_list, request);
    free(conn->http_requests.request_list);
    conn->http_requests.request_list = new_list;
    conn->http_requests.size = new_size;
}

void category_web_traffic(char* log_dir_path) {
    // scan all log files within the directory
    DIR* dir;
