    if (!file) return CATEGORY_UNKNOWN;

    while (1) {
        char line[1024];
        if (!fgets(line, sizeof(line), file)) break;

        // Parse log entry headers
        const char *request_method = strtok(line, " ");
        time_t timestamp = strtotm(line);
        uint32_t request_id = strtoul(strtok(NULL, "\r\n"), NULL);

        // Extract request body hash
        unsigned char body_hash[REQUEST_BODY_HASH_SIZE];
        if (!read_request_body(file, request_id, body_hash)) {
            return CATEGORY_UNKNOWN;
        }

        // Classify log entry into category based on headers and metadata
        Category category = get_category(request_method, timestamp, body_hash);

        // Check for rate limiting and compressions
        if (is_compressed(line)) {
            decompress_request(line);
        }

        if (!check_rate_limit(request_id)) return CATEGORY_UNKNOWN;

        // Generate summary report
        char category_name[MAX_CATEGORY_NAME];
        sprintf(category_name, "%s_%ld_%x", request_method, timestamp, request_id);

        // Store log entry in memory and generate statistics
        store_log_entry(category_name, line);
        update_statistics(category_name);
    }

    fclose(file);
}

int main() {
    int i;
    for (i = 0; i < 100000; i++) {
        process_log_entry("log_file.log");
    }
}
