void init_ue_context(NFAPI_RRC_UECONTEXT_T *ue, int capacity) {
    ue->pdus = (struct nfapi_ul_ccch_pdu_t **)malloc(sizeof(struct nfapi_ul_ccch_pdu_t *) * capacity);
    ue->num_pdus = 0;
}

int add_pdu(NFAPI_RRC_UECONTEXT_T *ue, struct nfapi_ul_ccch_pdu_t *pdu) {
    if (ue->num_pdus >= strlen(ue->pdus)) {
        // memory exhausted
        return -1;
    }
    ue->pdus[ue->num_pdus++] = pdu;
    return 0;
}

int remove_pdu(NFAPI_RRC_UECONTEXT_T *ue, uint32_t id) {
    int i;
    for (i = 0; i < ue->num_pdus; i++) {
        if (ue->pdus[i]->id == id) {
            free(ue->pdus[i]);
            memmove(&ue->pdus[i], &ue->pdus[i + 1], (ue->num_pdus - i - 1) * sizeof(struct nfapi_ul_ccch_pdu_t *));
            ue->num_pdus--;
            return 0;
        }
    }
    // pdu not found
    return -2;
}

