NFAPI_RRC_UECONTEXT_T* nfaapi_uecontext_init(int num_elements) {
    NFAPI_RRC_UECONTEXT_T* uecontexts = (NFAPI_RRC_UECONTEXT_T*)malloc(num_elements * sizeof(NFAPI_RRC_UECONTEXT_T));
    for (int i = 0; i < num_elements; i++) {
        uecontexts[i].ue_id = -1;
        uecontexts[i].rrc_state = -1;
        uecontexts[i].list_size = 0;
        uecontexts[i].pdu_list = NULL;
    }
    return uecontexts;
}

// Function to add a new PDU to the list
void nfaapi_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t* pdu) {
    // Allocate memory for the new PDU
    NFAPI_UL_CCCH_pdu_t* new_pdu = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
    new_pdu->data[0] = '\0';
    new_pdu->size = 0;

    // Add the new PDU to the list
    if (uecontext->list_size == 0) {
        uecontext->pdu_list = (NFAPI_UL_CCCH_pdu_t**)malloc(sizeof(NFAPI_UL_CCCH_pdu_t*));
        uecontext->pdu_list[0] = new_pdu;
        uecontext->list_size = 1;
    } else {
        NFAPI_UL_CCCH_pdu_t** temp_pdu_list = (NFAPI_UL_CCCH_pdu_t**)malloc((uecontext->list_size + 1) * sizeof(NFAPI_UL_CCCH_pdu_t*));
        memcpy(temp_pdu_list, uecontext->pdu_list, uecontext->list_size * sizeof(NFAPI_UL_CCCH_pdu_t*));
        temp_pdu_list[uecontext->list_size] = new_pdu;
        free(uecontext->pdu_list);
        uecontext->pdu_list = temp_pdu_list;
        uecontext->list_size++;
    }
}

// Function to delete a PDU from the list
void nfaapi_uecontext_delete_pdu(NFAPI_RRC_UE_CONTEXT_T* uecontext, int index) {
    if (uecontext->list_size > 0 && index >= 0 && index < uecontext->list_size) {
        free(uecontext->pdu_list[index]);
        for (int i = index; i < uecontext->list_size - 1; i++) {
            uecontext->pdu_list[i] = uecontext->pdu_list[i + 1];
        }
        free(uecontext->pdu_list);
        uecontext->list_size--;
    }
}

// Function to serialize the NFAPI_RRC_UECONTEXT_T structures
int nfaapi_uecontext_serialize(NFAPI_RRC_UE_CONTEXT_T* uecontext, char* buffer) {
    int size = sizeof(NFAPI_RRC_UE_CONTEXT_T);
    for (int i = 0; i < uecontext->list_size; i++) {
        NFAPI_UL_CCCH_pdu_t* pdu = uecontext->pdu_list[i];
        // Serialize the PDU
        int pdu_size = sizeof(NFAPI_UL_CCCH_pdu_t);
        memcpy(buffer, &pdu, pdu_size);
        buffer += pdu_size;
    }
    return size + (uecontext->list_size * pdu_size);
}

// Function to deserialize the NFAPI_RRC_UECONTEXT_T structures
int nfaapi_uecontext_deserialize(char* buffer, NFAPI_RRC_UE_CONTEXT_T* uecontext) {
    int size = sizeof(NFAPI_RRC_UE_CONTEXT_T);
    while (size > 0 && uecontext->list_size < MAX_PDU_SIZE) {
        // Deserialize the PDU
        NFAPI_UL_CCCH_pdu_t pdu;
        memcpy(&pdu, buffer, sizeof(NFAPI_UL_CCCH_pdu_t));
        buffer += sizeof(NFAPI_UL_CCCH_pdu_t);
        // Add the PDU to the list
        if (uecontext->list_size == 0) {
            uecontext->pdu_list = (NFAPI_UL_CCCH_pdu_t**)malloc(sizeof(NFAPI_UL_CCCH_pdu_t*));
            uecontext->pdu_list[0] = &pdu;
            uecontext->list_size = 1;
        } else {
            NFAPI_UL_CCCH_pdu_t** temp_pdu_list = (NFAPI_UL_CCCH_pdu_t**)malloc((uecontext->list_size + 1) * sizeof(NFAPI_UL_CCCH_pdu_t*));
            memcpy(temp_pdu_list, uecontext->pdu_list, uecontext->list_size * sizeof(NFAPI_UL_CCCH_pdu_t*));
            temp_pdu_list[uecontext->list_size] = &pdu;
            free(uecontext->pdu_list);
            uecontext->pdu_list = temp_pdu_list;
            uecontext->list_size++;
        }
    }
    return size;
}

int main() {
    // Example usage
    NFAPI_RRC_UE_CONTEXT_T* uecontext = nfaapi_uecontext_init(5);
    for (int i = 0; i < 3; i++) {
        NFAPI_UL_CCCH_pdu_t pdu;
        // Initialize the PDU
        pdu.data[0] = 'A';
        pdu.size = 1;
        nfaapi_uecontext_add_pdu(uecontext, &pdu);
    }
    for (int i = 2; i >= 0; i--) {
        NFAPI_UL_CCCH_pdu_t* pdu = uecontext->pdu_list[i];
        if (pdu != NULL) {
            free(pdu);
        }
    }
    free(uecontext);
    return 0;
}
