void add_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, char* pdu_data, size_t pdu_len) {
    // Allocate memory for the new PDU
    NFAPI_UL_CCCH_pdu_t* new_pdu = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
    new_pdu->data = (char*)malloc(pdu_len + 1);
    memcpy(new_pdu->data, pdu_data, pdu_len);
    new_pdu->data[pdu_len] = '\0';
    new_pdu->len = pdu_len;

    // Add the new PDU to the list
    uecontext->pdus = (NFAPI_UL_CCCH_pdu_t**)realloc(uecontext->pdus, sizeof(NFAPI_UL_CCCH_pdu_t*) * (uecontext->pdus_len + 1));
    uecontext->pdus[uecontext->pdus_len] = new_pdu;
    uecontext->pdus_len++;

    // Validate the integrity of the PDU list
    for(int i = 0; i < uecontext->pdus_len; i++) {
        NFAPI_UL_CCCH_pdu_t* pdu = uecontext->pdus[i];
        regmatch_t match[1];

        for(size_t j = 0; j < sizeof(book_regexes) / sizeof(regex_t); j++) {
            if(regexec(&book_regexes[j], pdu->data, 1, &match, 0) == 0) {
                char* book_name = malloc(match.rm_so + match.rm_eo - match.rm_so);
                strncpy(book_name, pdu->data + match.rm_so, match.rm_eo - match.rm_so);
                // Update the PDU count for this book
                if(i == uecontext->pdus_len) {
                    // This is a new book, add it to the dictionary
                    printf("%s: 1\n", book_name);
                    free(book_name);
                } else {
                    // This book has been seen before, increment its count
                    printf("%s: %d\n", book_name, uecontext->pdus_len - i);
                    free(book_name);
                }
            }
        }
    }
}

void remove_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, char* pdu_data, size_t pdu_len) {
    // Find the PDU in the list
    for(int i = 0; i < uecontext->pdus_len; i++) {
        if(memcmp(uecontext->pdus[i]->data, pdu_data, pdu_len) == 0) {
            // Remove the PDU from the list
            free(uecontext->pdus[i]->data);
            free(uecontext->pdus[i]);
            for(int j = i; j < uecontext->pdus_len - 1; j++) {
                uecontext->pdus[j] = uecontext->pdus[j + 1];
            }
            uecontext->pdus_len--;
            return;
        }
    }
}

void free_uecontext(NFAPI_RRC_UECONTEXT_T* uecontext) {
    for(int i = 0; i < uecontext->pdus_len; i++) {
        free(uecontext->pdus[i]->data);
        free(uecontext->pdus[i]);
    }
    free(uecontext->pdus);
    free(uecontext->ue_id);
    free(uecontext);
}
