#include <string.h>

typedef struct {
    int id;
    char status[16];
    struct Task* tasks;
    int task_count;
} Node;

typedef struct {
    char name[32];
    void (*func)(void*);
    void* data;
} Task;

Node* node_init(int id) {
    Node* node = (Node*) malloc(sizeof(Node));
    if (!node) return NULL;
    node->id = id;
    strcpy(node->status, "Idle");
    node->tasks = NULL;
    node->task_count = 0;
    return node;
}

void node_free(Node* node) {
    if (!node) return;
    while (node->tasks && node->task_count > 0) {
        Task* task = node->tasks;
        node->tasks = task->next;
        free(task);
    }
    free(node);
}

int node_validate(Node* node) {
    if (!node) return -1;
    if (!node->status[0]) return -2;
    return 0;
}

void node_add_task(Node* node, char* name, void (*func)(void*), void* data) {
    Task* task = (Task*) malloc(sizeof(Task));
    if (!task) return;
    strcpy(task->name, name);
    task->func = func;
    task->data = data;
    task->next = node->tasks;
    node->tasks = task;
    node->task_count++;
}

void node_run_tasks(Node* node) {
    Task* task = node->tasks;
    while (task) {
        task->func(task->data);
        task = task->next;
    }
}
