int ue_context_add_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (context->pdu_count >= MAX_PDU) return -1;
    context->pdu_list = realloc(context->pdu_list, sizeof(NFAPI_UL_CCCH_pdu_t*) * (context->pdu_count + 2));
    if (!context->pdu_list) return -1;
    context->pdu_list[context->pdu_count] = pdu;
