    pthread_mutex_unlock(&log_mutex);
    return 0;
}

int ue_context_del_pdu(NFAPI_RRC_UECONTEXT_T* context, uint32_t pdu_id) {
    for (int i = 0; i < context->pdu_count; i++) {
        if (context->pdu_list[i]->id == pdu_id) {
            free(context->pdu_list[i]);
            memmove(&context->pdu_list[i], &context->pdu_list[i+1], sizeof(NFAPI_UL_CCCH_pdu_t*) * (context->pdu_count - i - 1));
            context->pdu_count--;
            pthread_mutex_lock(&log_mutex);
            log_info("PDU deleted from UE context");
            pthread_mutex_unlock(&log_mutex);
            return 0;
        }
    }
    return -1;
}

int ue_context_serialize(NFAPI_RRC_UECONTEXT_T* context, char** buffer) {
    *buffer = (char*)malloc(sizeof(char) * (context->pdu_count * sizeof(NFAPI_UL_CCCH_pdu_t) + 1));
    if (!*buffer) return -1;
    for (int i = 0; i < context->pdu_count; i++) {
        memcpy(*buffer, &context->pdu_list[i], sizeof(NFAPI_UL_CCCH_pdu_t));
        *buffer += sizeof(NFAPI_UL_CCCH_pdu_t);
    }
    **buffer = '\0';
    return 0;
}

int ue_context_deserialize(char* buffer, NFAPI_RRC_UECONTEXT_T** context) {
    *context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!*context) return -1;
    (*context)->pdu_list = NULL;
    (*context)->pdu_count = 0;
    char* p = buffer;
    while (*p) {
        NFAPI_UL_CCCH_pdu_t pdu;
        memcpy(&pdu, p, sizeof(NFAPI_UL_CCCH_pdu_t));
        p += sizeof(NFAPI_UL_CCCH_pdu_t);
        if (!(*context)->pdu_list) (*context)->pdu_list = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t*));
        (*context)->pdu_list = realloc((*context)->pdu_list, sizeof(NFAPI_UL_CCCH_pdu_t*) * ((*context)->pdu_count + 2));
        (*context)->pdu_list[(*context)->pdu_count] = &pdu;
        (*context)->pdu_count++;
    }
    return 0;
}

void* ue_context_garbage_collect(void* arg) {
    NFAPI_RRC_UECONTEXT_T* context = (NFAPI_RRC_UECONTEXT_T*)arg;
    if (context->pdu_list) {
        for (int i = 0; i < context->pdu_count; i++) {
            free(context->pdu_list[i]);
        }
        free(context->pdu_list);
    }
    return NULL;
}

void ue_context_periodic_gc() {
