// Function to initialize and manage the dynamic array
ResourcePool* initResourcePool(int capacity) {
    ResourcePool* pool = (ResourcePool*)malloc(sizeof(ResourcePool));
    if (!pool) return NULL;

    pool->nodeId = 0; // assume default node ID for simplicity
    pool->status = IDLE;
    pool->tasks = (void**)calloc(capacity, sizeof(void*)); // allocate memory for tasks
    pool->taskCount = 0;
    pthread_mutex_init(&pool->lock, NULL); // initialize lock for thread safety

    return pool;
}

// Function to add a new task to the resource pool
int addTask(ResourcePool* pool, void* task) {
    if (!pool || !task) return -1; // check for invalid arguments

    pthread_mutex_lock(&pool->lock); // acquire lock for thread safety
    int index = pool->taskCount++;
    pool->tasks[index] = task;
    pthread_mutex_unlock(&pool->lock);

    return 0; // operation successful
}

// Function to remove tasks based on specific criteria
int removeTasks(ResourcePool* pool, void* criterion) {
    if (!pool || !criterion) return -1; // check for invalid arguments

    pthread_mutex_lock(&pool->lock); // acquire lock for thread safety
    int i = 0;
    while (i < pool->taskCount) {
        if (!checkTask(criterion, pool->tasks[i])) { // check task against criterion
            free(pool->tasks[i]); // remove task and reassign memory
            pool->tasks[i] = pool->tasks[--pool->taskCount];
        }
        i++;
    }
    pthread_mutex_unlock(&pool->lock);

    return 0; // operation successful
}

