#include <stdlib.h>
#include <string.h>

void dynamic_array_init(int num_records, int* offset_values, int* keys, double* weights, record_t*** records) {
    // initialize arrays with memory allocations
    *offset_values = (long*)malloc(num_records * sizeof(long));
    *keys = (int*)malloc(num_records * sizeof(int));
    *weights = (double*)malloc(num_records * sizeof(double));
    *records = (record_t***)malloc(num_records * sizeof(record_t*));

    for (int i = 0; i < num_records; i++) {
        (*records)[i] = (record_t*)malloc(sizeof(record_t));
        (*records)[i]->key = (*keys)[i];
        (*records)[i]->weight = (*weights)[i];
    }
}

void dynamic_array_adjust_size(int num_records, int* offset_values, int* keys, double* weights, record_t*** records) {
    // adjust array sizes based on number of processed records
    if (num_records > *offset_values) {
        *offset_values = (long*)realloc(*offset_values, num_records * sizeof(long));
        *keys = (int*)realloc(*keys, num_records * sizeof(int));
        *weights = (double*)realloc(*weights, num_records * sizeof(double));
        *records = (record_t***)realloc(*records, num_records * sizeof(record_t*));
    }
}

void dynamic_array_cleanup(int num_records, int* offset_values, int* keys, double* weights, record_t*** records) {
    // free memory during cleanup
    for (int i = 0; i < num_records; i++) {
        free((*records)[i]);
    }
    free(*offset_values);
    free(*keys);
    free(*weights);
    free(*records);
}
