#define MAX_UE_CONTEXTS 1000
#define MAX_PDUS_PER_CONTEXT 1000
#define AGE_THRESHOLD 60 // in seconds

typedef struct {
    int ue_id;
    enum RRC_STATE state;
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    int pdu_id;
    char data[256];
} NFAPI_UL_CCCH_pdu_t;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file;

NFAPI_RRC_UECONTEXT_T *ue_contexts[MAX_UE_CONTEXTS];
int ue_context_count = 0;

void init_ue_contexts() {
    pthread_mutex_init(&lock, NULL);
    log_file = fopen("pdu_list.log", "w");
}

void add_pdu(int ue_id, NFAPI_UL_CCCH_pdu_t *pdu) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            // Check if the PDU list is not full
            if (ue_contexts[i]->pdus != NULL && 
                ue_contexts[i]->pdu_count < MAX_PDUS_PER_CONTEXT) {
                // Add the new PDU to the existing list
                ue_contexts[i]->pdus = realloc(ue_contexts[i]->pdus, 
                    sizeof(NFAPI_UL_CCCH_pdu_t *) * (ue_contexts[i]->pdu_count + 1));
                ue_contexts[i]->pdus[ue_contexts[i]->pdu_count++] = pdu;
            } else {
                // Create a new PDU list if the existing one is full
                pdu_list_t *new_pdu_list = malloc(sizeof(pdu_list_t));
                new_pdu_list->pdu_id = ue_id;
                new_pdu_list->pdus = calloc(MAX_PDUS_PER_CONTEXT, sizeof(NFAPI_UL_CCCH_pdu_t *));
                new_pdu_list->pdu_count = 1;
                new_pdu_list->pdus[0] = pdu;
                // Add the new PDU list to the UE context
                ue_contexts[i]->pdus = new_pdu_list;
            }
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void remove_pdu(int ue_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            // Remove the PDU list
            free(ue_contexts[i]->pdus);
            ue_contexts[i]->pdu_count = 0;
            ue_contexts[i]->pdus = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void validate_pdu_list() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->pdu_count > 0) {
            // Check if the PDU list is not empty
            for (int j = 0; j < ue_contexts[i]->pdu_count; j++) {
                // Check if each PDU has a valid PDU ID and data
                if (ue_contexts[i]->pdus[j]->pdu_id <= 0 || 
                    strlen(ue_contexts[i]->pdus[j]->data) > 256) {
                    printf("Invalid PDU detected: ue_id=%d, pdu_id=%d, data=\"%s\"\n", 
                        ue_id, ue_contexts[i]->pdus[j]->pdu_id, ue_contexts[i]->pdus[j]->data);
                }
            }
        }
    }
    pthread_mutex_unlock(&lock);
}

void log_pdu_operation(int operation) {
    fprintf(log_file, "%d: %s\n", operation, (operation == 1 ? "Added" : "Removed"));
    fflush(log_file);
}
