void *malloc_aligned(size_t size, size_t alignment) {
    size_t aligned_size = (size + alignment - 1) & ~(alignment - 1);
    void *ptr = valloc(aligned_size);
    if (!ptr) {
        ptr = malloc(aligned_size);
    }
    return ptr;
}

int init_ue_context_array(NFAPI_RRC_UECONTEXT_T **ue_contexts, int num_ue_contexts) {
    *ue_contexts = (NFAPI_RRC_UECONTEXT_T *)malloc_aligned(num_ue_contexts * sizeof(NFAPI_RRC_UECONTEXT_T), 16);
    if (!*ue_contexts) return -1;
    for (int i = 0; i < num_ue_contexts; i++) {
        (*ue_contexts)[i].pdu_list.next = &((*ue_contexts)[i].pdu_list);
        (*ue_contexts)[i].pdu_list.prev = &((*ue_contexts)[i].pdu_list);
    }
    return 0;
}

int update_ue_context_array(NFAPI_RRC_UECONTEXT_T **ue_contexts, int num_ue_contexts) {
    for (int i = 0; i < num_ue_contexts; i++) {
        NFAPI_UL_CCCH_pdu_t *pdu = (*ue_contexts)[i].pdu_list.next;
        while (pdu != &((*ue_contexts)[i].pdu_list)) {
            NFAPI_UL_CCCH_pdu_t *next_pdu = pdu->list.next;
            free(pdu);
            pdu = next_pdu;
        }
    }
    return 0;
}

