#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int id;
    int timestamps[100]; // Assuming max 100 timestamps per connection
    int status;
} TCP_CONNECTION_RECORD;

void* new_connection_record() {
    return malloc(sizeof(TCP_CONNECTION_RECORD));
}

int connection_record_free(void* record) {
    free(record);
    return 0;
}

// Hash table to manage connections efficiently
typedef struct {
    TCP_CONNECTION_RECORD** records;
    int size;
} CONNECTION_TABLE;

CONNECTION_TABLE new_connection_table(int initial_size) {
    CONNECTION_TABLE table = (CONNECTION_TABLE)malloc(sizeof(struct CONNECTION_TABLE));
    table->records = (TCP_CONNECTION_RECORD**)malloc(initial_size * sizeof(TCP_CONNECTION_RECORD*));
    table->size = initial_size;
    return table;
}

int connection_table_free(CONNECTION_TABLE table) {
    for(int i = 0; i < table->size; i++) {
        if(table->records[i]) connection_record_free(table->records[i]);
    }
    free(table->records);
    free(table);
    return 0;
}

// Connection management function
int manage_connections(CONNECTION_TABLE* table, int new_id, int timestamp) {
    // Find the record with matching ID (O(1))
    TCP_CONNECTION_RECORD** records = table->records;
    for(int i = 0; i < table->size; i++) {
        if(records[i] && records[i]->id == new_id) {
            // Update existing record
            int* timestamps = records[i]->timestamps;
            int status = records[i]->status;
            // Add the new timestamp and update status if necessary
            for(int j = 0; j < 100; j++) {
                if(timestamps[j] == 0) {
                    timestamps[j] = timestamp;
                    break;
                }
            }
            return 0;
        }
    }

    // Create a new record (O(1))
    TCP_CONNECTION_RECORD* new_record = new_connection_record();
    new_record->id = new_id;
    int* timestamps = new_record->timestamps;
    for(int i = 0; i < 100; i++) {
        timestamps[i] = 0;
    }
    timestamps[0] = timestamp; // Set the initial timestamp
    new_record->status = 1; // Assume connection is active initially

    // Resize the table if necessary (O(n))
    int size = table->size;
    if(size * 2 > 100) { // Assume maximum connections limit of 100
        table->records = (TCP_CONNECTION_RECORD**)realloc(table->records, size * 2 * sizeof(TCP_CONNECTION_RECORD*));
        table->size *= 2;
    }

    // Insert the new record into the table
    for(int i = 0; i < size; i++) {
        if(!records[i]) {
            records[i] = new_record;
            break;
        }
    }

    return 0;
}

// Periodic cleanup function to free up resources
void clean_up_connections(CONNECTION_TABLE* table) {
    TCP_CONNECTION_RECORD** records = table->records;
    for(int i = 0; i < table->size; i++) {
        if(records[i]) {
            int status = records[i]->status;
            // Check for inactive connections (timestamp array is full)
            if(status && !records[i]->timestamps[99]) { 
                connection_record_free(records[i]);
                records[i] = NULL;
            }
        }
    }
}

int main() {
    CONNECTION_TABLE table = new_connection_table(10);
    manage_connections(&table, 1, 1643723400); // Initial connection
    manage_connections(&table, 2, 1643723410); 
    clean_up_connections(&table); // Cleanup inactive connections
    return 0;
}
