// Structure representing a user session
typedef struct {
    int id;
    char* actions[10]; // list of associated user actions (max 10)
    time_t expiration;
} USER_SESSION;

// Dynamic array to store user sessions
USER_SESSION** sessions = NULL;
int session_count = 0;
time_t last_expired_session_check = 0;

// Function to add a new user session
void add_session(int id, const char* action) {
    USER_SESSION* new_session = (USER_SESSION*)malloc(sizeof(USER_SESSION));
    new_session->id = id;
    new_session->actions[0] = (char*)malloc(strlen(action) + 1);
    strcpy(new_session->actions[0], action);
    new_session->expiration = time(NULL) + 3600; // expire after 1 hour

    // Insert the new session at the end of the dynamic array
    sessions = realloc(sessions, (session_count + 2) * sizeof(USER_SESSION*));
    sessions[session_count] = new_session;
    session_count++;

    // Sort the session IDs for efficient lookup
    qsort(sessions, session_count, sizeof(USER_SESSION*), compare_sessions);
}

// Function to remove a user session by its ID
void remove_session(int id) {
    int i;
    for (i = 0; i < session_count; i++) {
        if (sessions[i]->id == id) {
            free(sessions[i]->actions[0]);
            free(sessions[i]);
            memmove(&sessions[i], &sessions[i + 1], (session_count - i - 1) * sizeof(USER_SESSION*));
            session_count--;
            return;
        }
    }
}

// Function to lookup a user session by its ID
USER_SESSION* get_session(int id) {
    int i;
    for (i = 0; i < session_count; i++) {
        if (sessions[i]->id == id) {
            return sessions[i];
        }
    }
    return NULL;
}

// Function to check and expire sessions that have reached their expiration timestamp
void check_expired_sessions() {
    time_t current_time = time(NULL);
    int i, j;
    for (i = 0; i < session_count; i++) {
        if (current_time > sessions[i]->expiration) {
            // Expired session found - remove it
            free(sessions[i]->actions[0]);
            free(sessions[i]);
            memmove(&sessions[i], &sessions[i + 1], (session_count - i - 1) * sizeof(USER_SESSION*));
            session_count--;
        } else if (current_time > last_expired_session_check + 60) { // 1 minute
            // Check for expired sessions again after 1 minute
            last_expired_session_check = current_time;
        }
    }
}

// Function to compare two user sessions by their IDs
int compare_sessions(const void* a, const void* b) {
    USER_SESSION** session_a = *(USER_SESSION**)a;
    USER_SESSION** session_b = *(USER_SESSION**)b;

    return (session_a->id - session_b->id);
}

// Function to periodically check and expire sessions that have reached their expiration timestamp
void periodic_session_check() {
    while (1) {
        sleep(60); // wait 1 minute
        check_expired_sessions();
    }
}
