    // Dynamically allocated list of PDU structures
    struct {
        NFAPI_UL_CCCH_pdu_t* pdu_list;
        size_t list_size;
        pthread_mutex_t lock;
    } pdus;
} NFAPI_RRC_UECONTEXT_T;

// Define the logging framework function to record operations
void log_operation(const char*, const NFAPI_RRC_UECONTEXT_T*);

// Function to create a new UE context structure and initialize it
NFAPI_RRC_UECONTEXT_T* ue_context_new() {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    pthread_mutex_init(&ue_ctx->lock, NULL);
    pthread_mutex_init(&ue_ctx->pdus.lock, NULL);
    return ue_ctx;
}

// Function to add a new PDU to the UE context
void ue_context_add_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, NFAPI_UL_CCCH_pdu_t pdu) {
    pthread_mutex_lock(&ue_ctx->lock);
    // Allocate memory for the new PDU if necessary
    if (ue_ctx->pdus.list_size == 0 || ue_ctx->pdus.pdu_list[ue_ctx->pdus.list_size-1] != pdu) {
        // Reallocate memory to accommodate the new PDU
        NFAPI_UL_CCCH_pdu_t* new_pdu_list = (NFAPI_UL_CCCH_pdu_t*)realloc(ue_ctx->pdus.pdu_list, sizeof(NFAPI_UL_CCCH_pdu_t)*(ue_ctx->pdus.list_size + 1));
        ue_ctx->pdus.pdu_list = new_pdu_list;
        ue_ctx->pdus.list_size++;
    }
    // Add the new PDU to the list
    ue_ctx->pdus.pdu_list[ue_ctx->pdus.list_size-1] = pdu;
    pthread_mutex_unlock(&ue_ctx->lock);
}

// Function to remove a PDU from the UE context
void ue_context_remove_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, NFAPI_UL_CCCH_pdu_t pdu) {
    pthread_mutex_lock(&ue_ctx->lock);
    // Find and remove the specified PDU from the list
    for (size_t i = 0; i < ue_ctx->pdus.list_size; i++) {
        if (ue_ctx->pdus.pdu_list[i] == pdu) {
            // Move all subsequent PDUs to fill the gap
            memmove(&ue_ctx->pdus.pdu_list[i], &ue_ctx->pdus.pdu_list[i+1], sizeof(NFAPI_UL_CCCH_pdu_t)*(ue_ctx->pdus.list_size-i-1));
            ue_ctx->pdus.list_size--;
            break;
