    }
    pthread_mutex_unlock(&ue_ctx->lock);
}

// Function to check the integrity of the UE context
void ue_context_check_integrity(NFAPI_RRC_UECONTEXT_T* ue_ctx) {
    pthread_mutex_lock(&ue_ctx->lock);
    // Check for memory leaks by freeing any dangling pointers
    for (size_t i = 0; i < ue_ctx->pdus.list_size; i++) {
        if (!ue_ctx->pdus.pdu_list[i]) {
            free(ue_ctx->pdus.pdu_list);
