// Function to create a new TCP connection structure
TCP_CONNECTION* tcp_connection_create() {
    // Allocate memory for the connection structure
    TCP_CONNECTION* conn = (TCP_CONNECTION*)malloc(sizeof(TCP_CONNECTION));

    if (!conn) {
        return NULL;  // Error handling: cannot allocate memory
    }

    // Initialize connection fields
    conn->id = -1;
    conn->state = DISCONNECTED;

    conn->message_count = 0;
    conn->messages = (void**)malloc(sizeof(void*) * 10);  // Initial capacity

    return conn;
}

// Function to add a TCP message to the connection's list
void tcp_connection_add_message(TCP_CONNECTION* conn, void* message, size_t len) {
    // Check if the message is too large to store
    if (len > 1024) {
        fprintf(stderr, "Error: message exceeds maximum length\n");
        return;
    }

    // Allocate space for the new message and append it to the list
    conn->messages = realloc(conn->messages, sizeof(void*) * (conn->message_count + 1));
    conn->messages[conn->message_count] = malloc(len);
    memcpy(conn->messages[conn->message_count], message, len);

    // Update message count
    conn->message_count++;
}

// Function to remove the TCP message at the specified index from the connection's list
void tcp_connection_remove_message(TCP_CONNECTION* conn, int idx) {
    if (idx >= 0 && idx < conn->message_count) {
        free(conn->messages[idx]);
        memmove(&conn->messages[idx], &conn->messages[idx + 1],
                sizeof(void*) * (conn->message_count - idx));
        conn->message_count--;
        // Reallocate memory for the updated list
        conn->messages = realloc(conn->messages, sizeof(void*) * conn->message_count);
    }
}

