#define MAX_LINE_LENGTH 1024
#define MAX_FILE_NAME_LENGTH 256
#define DEFAULT_DELIMITER "\n"
#define DEFAULT_OUTPUT_FILE "output.txt"

// Struct to hold the program's configuration
typedef struct {
    bool verbose;
    int logLevel;
    char* delimiter;
    char* outputFilePath;
} Config;

// Function to parse command line arguments and set up configuration
void setupConfig(int argc, char** argv) {
    // Initialize default values for configuration
    Config config = {false, 0, DEFAULT_DELIMITER, DEFAULT_OUTPUT_FILE};

    // Parse command line arguments
    int i;
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-v") == 0) {
            config.verbose = true;
        } else if (strcmp(argv[i], "-d") == 0) {
            i++;
            config.delimiter = argv[i];
        } else if (strcmp(argv[i], "-o") == 0) {
            i++;
            config.outputFilePath = argv[i];
        }
    }

    // Set log level based on configuration
    if (!config.verbose && config.logLevel == 0) {
        config.logLevel = 1; // Default to warning log level
    }
}

// Function to read and count lines from a file
void processFile(char* filePath, char* delimiter, bool verbose, int logLevel, FILE* output) {
    int lineCount = 0;
    FILE* file = fopen(filePath, "r");
    if (file == NULL) {
        // Handle error: file not found or permission denied
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    char buffer[MAX_LINE_LENGTH];
    while (fgets(buffer, MAX_LINE_LENGTH, file)) {
        lineCount++;
    }
    fclose(file);

    if (verbose) {
        printf("Processed file %s with %d lines.\n", filePath, lineCount);
    }

    // Write line count to output file
    fprintf(output, "%d\n", lineCount);
}

// Function to process files recursively and update the total line count
void processFiles(char* directoryPath, char* delimiter, bool verbose, int logLevel, FILE* output) {
    DIR* dir = opendir(directoryPath);
    if (dir == NULL) {
        // Handle error: unable to open directory
        printf("Error: unable to open directory %s\n", directoryPath);
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        char filePath[MAX_FILE_NAME_LENGTH];
        sprintf(filePath, "%s/%s", directoryPath, entry->d_name);

        if (strcmp(entry->d_type, "directory") == 0) {
            // Recursively process subdirectories
            processFiles(filePath, delimiter, verbose, logLevel, output);
        } else {
            // Process files
            int lineCount = 0;
            FILE* file = fopen(filePath, "r");
            if (file != NULL) {
                char buffer[MAX_LINE_LENGTH];
                while (fgets(buffer, MAX_LINE_LENGTH, file)) {
                    lineCount++;
                }
                fclose(file);

                if (verbose) {
                    printf("Processed file %s with %d lines.\n", filePath, lineCount);
                }

                // Write line count to output file
                fprintf(output, "%d\n", lineCount);
            } else {
                // Handle error: file not found or permission denied
                printf("Error: unable to open file %s\n", filePath);
            }
        }
    }
    closedir(dir);
}

// Function to compress a file using zlib
void compressFile(char* filePath, char* outputFilePath) {
    int compressionLevel = 6; // Default compression level

    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        // Handle error: unable to open file
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    unsigned char buffer[1024];
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, 1024, file)) > 0) {
        // Compress data using zlib
        unsigned char compressedBuffer[1024];
        int compressionResult = compress(compressedBuffer, 1024, buffer, bytesRead);
        if (compressionResult != Z_OK) {
            // Handle error: unable to compress data
            printf("Error: unable to compress file %s\n", filePath);
            return;
        }

        // Write compressed data to output file
        FILE* outputFile = fopen(outputFilePath, "wb");
        if (outputFile == NULL) {
            // Handle error: unable to open output file
            printf("Error: unable to open output file %s\n", outputFilePath);
            return;
        }
        fwrite(compressedBuffer, 1, compressionResult, outputFile);
        fclose(outputFile);
    }
    fclose(file);
}

// Function to decompress a compressed file using zlib
void decompressFile(char* filePath, char* outputFilePath) {
    int compressionLevel = 6; // Default compression level

    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        // Handle error: unable to open file
        printf("Error: unable to open file %s\n", filePath);
        return;
    }

    unsigned char buffer[1024];
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, 1024, file)) > 0) {
        // Decompress data using zlib
        unsigned char decompressedBuffer[1024];
        int decompressionResult = uncompress(decompressedBuffer, 1024, buffer, bytesRead);
        if (decompressionResult != Z_OK) {
            // Handle error: unable to decompress data
            printf("Error: unable to decompress file %s\n", filePath);
            return;
        }

        // Write decompressed data to output file
        FILE* outputFile = fopen(outputFilePath, "wb");
        if (outputFile == NULL) {
            // Handle error: unable to open output file
            printf("Error: unable to open output file %s\n", outputFilePath);
            return;
        }
        fwrite(decompressedBuffer, 1, decompressionResult, outputFile);
        fclose(outputFile);
    }
    fclose(file);
}

int main(int argc, char** argv) {
    setupConfig(argc, argv);

    int lineCount = 0;
    FILE* output = fopen(DEFAULT_OUTPUT_FILE, "w");
    if (output == NULL) {
        // Handle error: unable to open output file
        printf("Error: unable to open output file %s\n", DEFAULT_OUTPUT_FILE);
        return 1;
    }

    int i;
    for (i = 1; i < argc; i++) {
        char* filePath = argv[i];
        processFile(filePath, config.delimiter, config.verbose, config.logLevel, output);
    }

    fclose(output);

    return 0;
}
