#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <md5.h>

typedef struct {
    char client_ip[16];
    int port;
    void* buffer;
} Connection;

void manage_connections() {
    // Initialize connections
    Connection* connections = NULL;
    size_t connection_count = 0;

    // Process directory of configuration files
    DIR* dir = opendir(".");
    if (dir == NULL) {
        printf("Error: Unable to open directory.\n");
        return;
    }

    while ((struct dirent* entry = readdir(dir))) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;

        // Open file
        int fd = open(entry->d_name, O_RDONLY);
        if (fd < 0) {
            printf("Error: Unable to open file '%s'.\n", entry->d_name);
            continue;
        }

        // Read first 100 bytes of file content
        char buffer[100];
        read(fd, buffer, 100);

        // Generate new directory path
        time_t timestamp = time(NULL);
        struct tm* tm = localtime(&timestamp);
        size_t sequence_number = (size_t)tm->tm_mtime;
        unsigned char hash[16];
        MD5_CTX md5ctx;
        MD5Init(&md5ctx);
        MD5Update(&md5ctx, buffer, 100);
        MD5Final(hash, &md5ctx);

        char directory_path[128];
        sprintf(directory_path, "/%s-%ld-%d-%x-", getcwd(NULL, 0), timestamp, sequence_number, hash[10]);
        if (strlen(entry->d_name) == 0 || buffer[100] == '\0') {
            strcat(directory_path, "_empty");
        }

        // Process connection
        Connection* new_connection = malloc(sizeof(Connection));
        strcpy(new_connection->client_ip, "127.0.0.1");  // Default IP address
        new_connection->port = 12345;                      // Default port

        // Add to connections list
        connections = realloc(connections, (connection_count + 1) * sizeof(Connection));
        connections[connection_count].buffer = malloc(1024);  // Initialize buffer
        connection_count++;

        // Close file and directory
        close(fd);
        closedir(dir);
    }

    // Generate checksum of entire directory
    FILE* checksums_file = fopen("checksums.txt", "w");
    if (checksums_file == NULL) {
        printf("Error: Unable to open 'checksums.txt' for writing.\n");
        return;
    }

    for (size_t i = 0; i < connection_count; i++) {
        MD5_CTX md5ctx;
        MD5Init(&md5ctx);
        MD5Update(&md5ctx, connections[i].buffer, 1024);
        unsigned char hash[16];
        MD5Final(hash, &md5ctx);

        // Write checksum and file content to 'checksums.txt'
        fprintf(checksums_file, "%x\n", hash[10]);
        fwrite(connections[i].buffer, sizeof(char), 100, checksums_file);
    }

    fclose(checksums_file);

    // Log errors
    FILE* error_log = fopen("error.log", "a");
    if (error_log == NULL) {
        printf("Error: Unable to open 'error.log' for writing.\n");
        return;
    }

    // Release connections and buffer memory
    for (size_t i = 0; i < connection_count; i++) {
        free(connections[i].buffer);
    }
    free(connections);

    fclose(error_log);
}

int main() {
    manage_connections();
    return 0;
}
