                sprintf(&random_string[i], "%c", 'a' + rand_val);
            } else {
                sprintf(&random_string[i], "%d", rand_val);
            }
        }
        random_string[12] = '\0';

        // Construct new directory path
        char* new_dir_path = (char*)malloc(MAX_DIR_NAME_LENGTH * sizeof(char));
        sprintf(new_dir_path, "/%s_%ld_%llu_%s",
                classification_tag,
                timestamp,
                sequence_number,
                random_string);

        if (file_size(file_path) == 0 || buffer[0] == '\0') {
            strcat(new_dir_path, "_empty");
        }
    }

    // Compute checksum of the entire directory
    FILE* checksum_file = fopen("checksums.txt", "w");
    for (int i = 0; i < num_ue_contexts; i++) {
        NFAPI_RRC_UECONTEXT_T ue_context = ue_contexts[i];

        // Compute MD5 checksum using a standard library function
        uint8_t* md5_checksum = compute_md5(file_path);

        // Write checksum to file along with timestamp and last 50 bytes of each file's content
        fwrite(&timestamp, sizeof(time_t), 1, checksum_file);
        fwrite(md5_checksum, sizeof(uint8_t), MAX_CHECKSUM_LENGTH, checksum_file);
        fclose(checksum_file);
    }

    // Free dynamically allocated memory
    free(ue_contexts);
    free(new_dir_path);
}

void compute_md5(char* file_path) {
    FILE* file = fopen(file_path, "r");
    char buffer[MAX_FILE_CONTENT];
    fread(buffer, sizeof(char), MAX_FILE_CONTENT, file);
    fclose(file);

    // Compute MD5 checksum using a standard library function
    uint8_t md5_checksum[MAX_CHECKSUM_LENGTH];
    MD5_CTX ctx;
    uint32_t len = (uint32_t)strlen(buffer);
    char* data = buffer;

    MD5_Init(&ctx);
    while (len > 0) {
        uint32_t blockLen = MIN(len, sizeof(ctx.input));
        memcpy(ctx.input, data, blockLen);
        data += blockLen;
        len -= blockLen;
        MD5_Update(&ctx, ctx.input, blockLen);
    }

    MD5_Final(md5_checksum, &ctx);
}

int main() {
    manage_ue_contexts(10);
    categorize_directories("/path/to/directory");

    return 0;
}
