file_descriptor* manage_file_descriptors(const char* dir_path) {
    // Initialize file descriptor structures
    file_descriptor* files = (file_descriptor*)malloc(1 * sizeof(file_descriptor));
    int num_files = 0;

    // Scan all files within the directory
    struct dirent* dent;
    DIR* dir = opendir(dir_path);
    while ((dent = readdir(dir)) != NULL) {
        if (strcmp(dent->d_name, ".") == 0 || strcmp(dent->d_name, "..") == 0)
            continue;

        // Extract file metadata
        struct stat file_stat;
        char* file_path = malloc(strlen(dir_path) + strlen(dent->d_name) + 2);
        sprintf(file_path, "%s/%s", dir_path, dent->d_name);
        fstatat(AT_FDCWD, file_path, &file_stat, AT_SYMLINK_NOFOLLOW);
        free(file_path);

        // Determine new traffic category and naming convention
        char* category = malloc(65 * sizeof(char));
        sprintf(category, "%s_%ld_%ld_%x", dent->d_name, (long)time(NULL), (long)file_stat.st_mtime,
                (unsigned int)hash_file_content(file_path));

        // Allocate memory for buffer and initialize file descriptor structure
        files = realloc(files, (num_files + 1) * sizeof(file_descriptor));
        files[num_files].file_id = num_files;
        files[num_files].current_pos = 0;
        files[num_files].buffer = malloc(1024 * sizeof(char)); // Initialize with a fixed size buffer

        num_files++;
    }
    closedir(dir);
    free(files);

    return NULL; // Handle errors and logging
}

void generate_summary_report(const char* dir_path) {
    // Open the metadata file for writing
    FILE* summary_file = fopen("file_summary.txt", "w");
    if (summary_file == NULL)
        return;

    // Scan all files within the directory again to extract statistics
    int num_files_per_category[10] = {0};
    long total_bytes_per_category[10] = {0};

    for (int i = 0; i < num_files; i++) {
        file_descriptor* file = &files[i];
        // Read file content and calculate statistics
        off_t pos = file->current_pos;
        fseek(file->buffer, pos, SEEK_SET);
        int bytes_read = fread(file->buffer, 1, 1024, file->buffer);
        if (bytes_read == 0)
            continue;

        // Update statistics for the category
        num_files_per_category[file->file_id]++;
        total_bytes_per_category[file->file_id] += bytes_read;
    }

    // Write summary report to file
    for (int i = 0; i < 10; i++) {
        fprintf(summary_file, "%d: %d files, %ld bytes\n",
                i, num_files_per_category[i], total_bytes_per_category[i]);
    }
    fclose(summary_file);
}
