import socket

def process_connections(addresses):
    # Initialize dictionary to store request counts per server
    requests_per_server = {}

    # Process each network address and yield processed data in batches
    for address in addresses:
        # Establish a connection with the remote server
        conn = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        conn.connect((address, 80))  # adjust port number as needed

        try:
            # Process the connection using a generator-based approach
            requests = []
            while True:
                response = conn.recv(1024)  # adjust buffer size as needed
                if not response:
                    break
                requests.append(response.decode())
            yield requests[:100]  # process data in batches of 100

            # Store request counts per server and total requests
            requests_per_server[address] = len(requests)
        except Exception as e:
            print(f"Error processing connection: {e}")
        finally:
            conn.close()

    return requests_per_server
