        strcat(category_name, buffer);

        // Add the new category name to the list of categories
        category_names[categories] = category_name;
        file_sizes[categories] = file_size;

        free(buffer);

        // Clean up and release resources
        fclose(file);
        free(entry->d_name);
        free(file_name);
    }

    return (void*)malloc(max_files * sizeof(char*));
