    int new_count = ++session->request_count;
    void** new_requests = (void**)realloc(session->requests, new_count * sizeof(void*));
    new_requests[new_count - 1] = malloc(strlen(request) + 1);
    strcpy((char*)new_requests[new_count - 1], request);
