struct SensorMetric {
    int temperatureThreshold;
    int humidityThreshold;
    int airQualityThreshold;
};

// Function to process sensor readings from CSV files
void processSensorReadings(const std::string& directoryPath, const SensorMetric& sensorMetrics) {
    // Initialize summary report JSON file
    Json::Value summaryReport;
    summaryReport["trend"] = Json::Value(Json::objectValue);

    // Create a mutex for thread safety
    std::mutex mutex;

    // Create a vector to store categorized data
    std::vector<EnvironmentalZone> categorizedData;

    // Define threads for concurrent processing of CSV files
    const int numThreads = 10;
    std::vector<std::thread> threads;
    for (int i = 0; i < numThreads; i++) {
        threads.emplace_back([&, directoryPath, sensorMetrics, &mutex, &categorizedData]() {
            // Process CSV file in this thread
            for (const auto& filePath : getCSVFiles(directoryPath)) {
                processCSVFile(filePath, sensorMetrics, mutex, categorizedData);
            }
        });
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    // Calculate environmental trends and generate summary report
    calculateTrends(categorizedData, summaryReport);

    // Write summary report to JSON file
    std::ofstream jsonFile("environmental_summary.json");
    jsonFile << summaryReport.toString(4);
}

// Helper function to process a single CSV file
void processCSVFile(const std::string& filePath, const SensorMetric& sensorMetrics, std::mutex& mutex, std::vector<EnvironmentalZone>& categorizedData) {
    // Read CSV file and validate sensor readings for accuracy and completeness
    Json::Value sensorReadings;
    if (readCSVFile(filePath, sensorReadings)) {
        // Categorize each reading based on predefined environmental criteria
