            EnvironmentalZone zone = categorizeReading(reading.asInt(), reading["humidity"].asInt(), reading["airQuality"].asInt(), sensorMetrics);
            {
                std::lock_guard<std::mutex> lock(mutex);
                categorizedData.push_back(zone);
