    for (const auto& zone : categorizedData) {
        switch (zone) {
            case EnvironmentalZone::Optimal:
                optimalReadings++;
                optimalTemperature += sensorMetrics.temperatureThreshold;
                optimalHumidity += sensorMetrics.humidityThreshold;
                optimalAirQuality += sensorMetrics.airQualityThreshold;
                break;
            case EnvironmentalZone::Caution:
