#include <stdlib.h>
#include <stdio.h>

// Custom allocator and deallocator
void* custom_malloc(size_t size);
void custom_free(void* ptr);

// Structure to be dynamically allocated
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_ind_rel8;
    CRC_INDICATION_REL16_TAG crc_ind_rel16;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and manage the linked list
int create_and_manage_linked_list(int n) {
    // Initialize the head of the linked list
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        // Allocate a new structure
        NFAPI_CRC_INDICATION_PDU_T* new_structure = custom_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_structure) {
            return -1;
        }

        // Set the CRCFLAG in the CRC_INDICATION_REL8_TAG based on the parity of the RNTI value
        new_structure->crc_ind_rel8.crcflag = (new_structure->rnti & 1) ? CRCFLAG_SET : CRCFLAG_CLEAR;

        // Set the CRCFLAG in the CRC_INDICATION_REL16_TAG as the inverse of the parity of the RNTI value
        new_structure->crc_ind_rel16.crcflag = (new_structure->rnti & 1) ? CRCFLAG_CLEAR : CRCFLAG_SET;

        // Add the new structure to the linked list, ensuring no two consecutive structures have the same RNTI value
        NFAPI_CRC_INDICATION_PDU_T* current = head;
        while (current && current->rnti == i) {
            current = current->next;
        }

        if (!current) {
            new_structure->next = NULL;
