    for file in file_list:
        with open(file, 'r') as f:
            for line in f:
                # Extract client IP and message count from the line
                client_ip = ...;
                msg_count = ...;

                # Update the dictionary with the new count
                if client_ip not in client_ip_counts:
                    client_ip_counts[client_ip] = 0
                client_ip_counts[client_ip] += msg_count

    # Yield processed data in batches
    batch_size = 10
    for i in range(0, len(client_ip_counts), batch_size):
        yield {k: v for k, v in list(client_ip_counts.items())[i:i+batch_size]}

    # Return a dictionary containing the count of messages per client IP
    return client_ip_counts

