NFAPI_RRC_UECONTEXT_T* create_ue_context() {
    NFAPI_RRC_UECONTEXT_T* context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!context) {
        printf("Memory allocation failed!\n");
        return NULL;
    }
    context->ue_id = 0;
    context->rrc_state = NFAPI_RRC_STATE_DISCONNECTED;
    context->pdu_list = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t) * MAX_PDU_PER_CONTEXT);
    if (!context->pdu_list) {
        printf("Memory allocation failed!\n");
        free(context);
        return NULL;
    }
    context->list_size = 0;
    return context;
}

void destroy_ue_context(NFAPI_RRC_UECONTEXT_T* context) {
    for (int i = 0; i < context->list_size; i++) {
        if (context->pdu_list[i]) {
            free(context->pdu_list[i]);
        }
    }
    free(context->pdu_list);
    free(context);
}

void validate_ue_context(NFAPI_RRC_UECONTEXT_T* context) {
    // PDU list validation logic
    for (int i = 0; i < context->list_size; i++) {
