    if (context->list_size >= MAX_PDU_PER_CONTEXT) {
        printf("PDU list is full!\n");
        return;
    }
    context->pdu_list[context->list_size++] = pdu;
}

void remove_pdu_from_ue_context(NFAPI_RRC_UECONTEXT_T* context, int index) {
    if (index < 0 || index >= context->list_size) {
        printf("Invalid PDU index!\n");
        return;
    }
    free(context->pdu_list[index]);
    for (int i = index; i < context->list_size - 1; i++) {
        context->pdu_list[i] = context->pdu_list[i + 1];
    }
    context->list_size--;
}

void resize_ue_context(NFAPI_RRC_UECONTEXT_T** contexts, int new_capacity) {
    NFAPI_RRC_UECONTEXT_T* new_contexts = (NFAPI_RRC_UECONTEXT_T*)realloc(*contexts, sizeof(NFAPI_RRC_UECONTEXT_T) * new_capacity);
    if (!new_contexts) {
        printf("Memory reallocation failed!\n");
        return;
    }
    *contexts = new_contexts;
}

void log_ue_context_operation(const char* operation, NFAPI_RRC_UECONTEXT_T* context) {
