} NFAPI_CRC_INDICATION_PDU_T;

int create_and_populate_list(int N, NFAPI_CRC_INDICATION_PDU_T ***list) {
    *list = (NFAPI_CRC_INDICATION_PDU_T ***)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if (*list == NULL) return -1;  // memory allocation failed

    for(int i=0; i<N; i++) {
        (*list)[i] = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if((*list)[i] == NULL) return -1;  // memory allocation failed

        (*list)[i]->RX_UE_INFORMATION_TAG = rand() % 1000;
        (*list)[i]->RNTI = rand() % 500;
        (*list)[i]->CRC_INDICATION_REL8_TAG = i;
        (*list)[i]->CRCFLAG = rand() % 2; // randomly set for each entry

    }
    return 0; // success
}

int insert_entry(NFAPI_CRC_INDICATION_PDU_T ***list, int N, int index, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if(index < 0 || index > N) return -1;  // invalid index

    NFAPI_CRC_INDICATION_PDU_T **temp = (NFAPI_CRC_INDICATION_PDU_T **)malloc((N+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T *));
    if(temp == NULL) return -1;  // memory allocation failed

    for(int i=0; i<index; i++) {
        temp[i] = (*list)[i];
    }
    temp[index] = entry;
    for(int i=index+1; i<=N; i++) {
        temp[i] = (*list)[i-1];
    }

    free(*list);
    *list = temp;

    return 0; // success
}

int update_entry(NFAPI_CRC_INDICATION_PDU_T ***list, int N, int index, NFAPI_CRC_INDICATION_PDU_T *entry) {
    if(index < 0 || index > N) return -1;  // invalid index

    (*list)[index]->RX_UE_INFORMATION_TAG = entry->RX_UE_INFORMATION_TAG;
    (*list)[index]->RNTI = entry->RNTI;
    (*list)[index]->CRC_INDICATION_REL8_TAG = entry->CRC_INDICATION_REL8_TAG;
    (*list)[index]->CRCFLAG = entry->CRCFLAG;

    return 0; // success
}

int remove_entry(NFAPI_CRC_INDICATION_PDU_T ***list, int N, int index) {
    if(index < 0 || index > N-1) return -1;  // invalid index

    for(int i=index; i<N-1; i++) {
        (*list)[i] = (*list)[i+1];
    }

    free((*list)[N-1]);
    (*list)[N-1] = NULL;

    N--;  // decrement size of list

    return 0; // success
}
