// Function to initialize a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu_init(int capacity) {
    // Calculate the memory needed for the given capacity
    size_t total_memory = sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (capacity + 1);

    // Allocate the necessary memory for the dynamic list
    NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T**)malloc(total_memory);

    if (!nfaPi_crc_indication_pdu) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the dynamic list
    for (int i = 0; i <= capacity; i++) {
        nfaPi_crc_indication_pdu[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!nfaPi_crc_indication_pdu[i]) {
            printf("Memory allocation failed\n");
            for (int j = 0; j < i; j++) {
                free(nfaPi_crc_indication_pdu[j]);
            }
            free(nfaPi_crc_indication_pdu);
            return NULL;
        }
    }

    // Initialize the list by setting CRCFLAG to a random value
    srand(time(NULL));
    for (int i = 0; i <= capacity; i++) {
        nfaPi_crc_indication_pdu[i]->CRCFLAG = rand() % 2;
    }

    return nfaPi_crc_indication_pdu;
}

// Function to insert an entry at a specific position in the dynamic list
void nfaPi_crc_indication_pdu_insert(NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu, int capacity, int index, NFAPI_CRC_INDICATION_PDU_T* new_entry) {
    // Check if the given index is valid for the current capacity
    if (index > capacity || index < 0) {
        printf("Invalid index\n");
        return;
    }

    // Allocate memory for the new entry
    nfaPi_crc_indication_pdu = realloc(nfaPi_crc_indication_pdu, (capacity + 2) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!nfaPi_crc_indication_pdu) {
        printf("Memory allocation failed\n");
        return;
    }

    // Shift the existing entries to make room for the new entry
    memmove(&nfaPi_crc_indication_pdu[index + 1], &nfaPi_crc_indication_pdu[index], (capacity - index) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    // Insert the new entry at the given index
    nfaPi_crc_indication_pdu[index] = new_entry;

    capacity++;

    return;
}

// Function to update an existing entry in the dynamic list
void nfaPi_crc_indication_pdu_update(NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu, int capacity, int index, NFAPI_CRC_INDICATION_PDU_T* updated_entry) {
    // Check if the given index is valid for the current capacity
    if (index > capacity - 1 || index < 0) {
        printf("Invalid index\n");
        return;
    }

    // Update the existing entry at the given index
    nfaPi_crc_indication_pdu[index] = updated_entry;

    return;
}

// Function to remove an entry by its index from the dynamic list
void nfaPi_crc_indication_pdu_remove(NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu, int capacity, int index) {
    // Check if the given index is valid for the current capacity
    if (index > capacity - 1 || index < 0) {
        printf("Invalid index\n");
        return;
    }

    // Shift the existing entries to fill the gap left by removal
    memmove(&nfaPi_crc_indication_pdu[index], &nfaPi_crc_indication_pdu[index + 1], (capacity - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    capacity--;

    return;
}

// Function to free the memory allocated for the dynamic list
void nfaPi_crc_indication_pdu_free(NFAPI_CRC_INDICATION_PDU_T** nfaPi_crc_indication_pdu, int capacity) {
    // Free each entry in the dynamic list
    for (int i = 0; i <= capacity; i++) {
        free(nfaPi_crc_indication_pdu[i]);
    }

    // Free the dynamic list itself
    free(nfaPi_crc_indication_pdu);

