void* nfpa_i_rrc_cell_context_init() {
    return malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T));
}

void nfpa_i_rrc_cell_context_free(void* cell_context) {
    NFPAI_RRC_CELL_CONTEXT_T* context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context;
    free(context->connection_info_map);
    free(cell_context);
}

int nfpa_i_rrc_cell_context_validate(void* cell_context) {
    NFPAI_RRC_CELL_CONTEXT_T* context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context;
    if (!context || !context->connection_info_map || context->connection_info_map_size <= 0) {
        return -1; // invalid state
    }
    for (int i = 0; i < context->connection_info_map_size; i++) {
        RRC_CONNECTION_INFO_T* info = *(RRC_CONNECTION_INFO_T**)context->connection_info_map[i];
        if (!info || !info->valid) {
            return -1; // invalid connection information
        }
    }
    return 0; // valid state
}

int nfpa_i_rrc_cell_context_add_connection_info(void* cell_context, uint16_t cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    NFPAI_RRC_CELL_CONTEXT_T* context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context;
    if (!context || !connection_info || !nfpa_i_rrc_cell_context_validate(cell_context)) {
        return -1; // invalid state
    }
    for (int i = 0; i < context->connection_info_map_size; i++) {
        if (context->connection_info_map[i] == &connection_info) {
            return 0; // connection info already exists
        }
    }
    void** new_connection_info_map = realloc(context->connection_info_map, sizeof(void*) * (context->connection_info_map_size + 1));
    if (!new_connection_info_map) {
        return -1; // memory allocation failed
    }
    context->connection_info_map = new_connection_info_map;
    *(void**)context->connection_info_map[context->connection_info_map_size] = connection_info;
    context->connection_info_map_size++;
    return 0; // added successfully
}

int nfpa_i_rrc_cell_context_update_connection_info(void* cell_context, uint16_t cell_id, RRC_CONNECTION_INFO_T* new_connection_info) {
    NFPAI_RRC_CELL_CONTEXT_T* context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context;
    if (!context || !new_connection_info || !nfpa_i_rrc_cell_context_validate(cell_context)) {
        return -1; // invalid state
    }
    for (int i = 0; i < context->connection_info_map_size; i++) {
        RRC_CONNECTION_INFO_T* info = *(RRC_CONNECTION_INFO_T**)context->connection_info_map[i];
        if (info && info == new_connection_info) {
            return 0; // connection info already exists and needs updating
        }
    }
    return -1; // no matching connection info found
}

int nfpa_i_rrc_cell_context_remove_connection_info(void* cell_context, uint16_t cell_id) {
    NFPAI_RRC_CELL_CONTEXT_T* context = (NFPAI_RRC CELL_CONTEXT_T*)cell_context;
    if (!context || !nfpa_i_rrc_cell_context_validate(cell_context)) {
        return -1; // invalid state
    }
    for (int i = 0; i < context->connection_info_map_size; i++) {
        void** connection_info = &context->connection_info_map[i];
        if (*connection_info && (*connection_info)->cell_id == cell_id) {
            free(*connection_info);
            *connection_info = NULL;
            return 0; // removed successfully
        }
    }
    return -1; // no matching connection info found
