typedef struct {
    uint16_t cell_id;
    RRC_STATE state;
    void** rrc_info_map;
} NFPAI_RRC_CELL_CONTEXT_T;

void* nfpa_i_rrc_cell_context_create() {
    return malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T));
}

void nfpa_i_rrc_cell_context_destroy(void* cell_ctx) {
    free(cell_ctx);
}

int nfpa_i_rrc_cell_context_add_rrc_info(void* cell_ctx, uint16_t rrc_id, RRC_CONNECTION_INFO_T* rrc_info) {
    NFPAI_RRC_CELL_CONTEXT_T* ctx = (NFPAI_RRC_CELL_CONTEXT_T*)cell_ctx;
    ctx->rrc_info_map = realloc(ctx->rrc_info_map, sizeof(void*) * (ctx->state + 1));
    ctx->rrc_info_map[ctx->state] = rrc_info;
    return 0;
}

int nfpa_i_rrc_cell_context_remove_rrc_info(void* cell_ctx, uint16_t rrc_id) {
    NFPAI_RRC_CELL_CONTEXT_T* ctx = (NFPAI_RRC_CELL_CONTEXT_T*)cell_ctx;
    for(int i = 0; i <= ctx->state; i++) {
        if(ctx->rrc_info_map[i] && ((RRC_CONNECTION_INFO_T*)ctx->rrc_info_map[i])->id == rrc_id) {
            free(ctx->rrc_info_map[i]);
            memmove(&ctx->rrc_info_map[i], &ctx->rrc_info_map[i+1], sizeof(void*) * (ctx->state - i));
            ctx->state--;
            return 0;
        }
    }
    return -1;
}

int nfpa_i_rrc_cell_context_update_state(void* cell_ctx, uint16_t new_state) {
    NFPAI_RRC_CELL_CONTEXT_T* ctx = (NFPAI_RRC_CELL_CONTEXT_T*)cell_ctx;
    if(new_state > ctx->state) {
        void** new_map = malloc(sizeof(void*) * (new_state + 1));
        memcpy(new_map, ctx->rrc_info_map, sizeof(void*) * (ctx->state + 1));
        free(ctx->rrc_info_map);
        ctx->rrc_info_map = new_map;
    }
    ctx->state = new_state;
    return 0;
}

int main() {
    // Example usage
    void* cell_ctx = nfpa_i_rrc_cell_context_create();
    NFPAI_RRC_CELL_CONTEXT_T* ctx = (NFPAI_RRC_CELL_CONTEXT_T*)cell_ctx;
    for(int i = 0; i < 5; i++) {
        RRC_CONNECTION_INFO_T* rrc_info = malloc(sizeof(RRC_CONNECTION_INFO_T));
        // Initialize rrc_info
        nfpa_i_rrc_cell_context_add_rrc_info(cell_ctx, i, rrc_info);
    }
    nfpa_i_rrc_cell_context_update_state(cell_ctx, 10);
    for(int i = 0; i < 5; i++) {
        RRC_CONNECTION_INFO_T* rrc_info = (RRC_CONNECTION_INFO_T*)ctx->rrc_info_map[i];
        // Use rrc_info
    }
    for(int i = 0; i <= ctx->state; i++) {
        free(ctx->rrc_info_map[i]);
    }
    nfpa_i_rrc_cell_context_destroy(cell_ctx);
}
