LTE_CELLINFO_T* cells[MAX_CELLS];
int num_cells = 0;
pthread_mutex_t lock;

void add_cell(LTE_CELLINFO_T* new_cell) {
    pthread_mutex_lock(&lock);
    if (num_cells >= MAX_CELLS) {
        // resize the array
        LTE_CELLINFO_T** new_array = realloc(cells, sizeof(LTE_CELLINFO_T*) * (MAX_CELLS * 2));
        if (!new_array) {
            printf("Failed to allocate memory for cell array\n");
            exit(1);
        }
        cells = new_array;
        MAX_CELLS *= 2;
    }
    cells[num_cells] = new_cell;
    num_cells++;
    pthread_mutex_unlock(&lock);
}

void remove_cell(uint32_t cell_id) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_cells; i++) {
        if (cells[i]->cell_id == cell_id) {
            free(cells[i]->pdu_list);
            free(cells[i]);
            for (int j = i; j < num_cells - 1; j++) {
                cells[j] = cells[j + 1];
            }
            num_cells--;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

