    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_cells; i++) {
        // send network probes to ensure cells are active and reachable
        if (!cell_is_active(cells[i])) {
            remove_cell(cells[i]->cell_id);
        }
    }
    pthread_mutex_unlock(&lock);
}

