#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 1000
#define GC_INTERVAL 60 // seconds
#define EXPIRY_THRESHOLD 2592000 // milliseconds (30 days)

typedef struct {
    uint32_t cell_id;
    RRC_STATE rrc_state;
    void* map;
} NFPAI_RRC_CELL_CONTEXT_T;

typedef struct {
    time_t last_update_time;
    void* data;
} RRC_CONNECTION_INFO_T;

void* gc_timer = NULL;

int nfpa_i_rrc_cell_context_init() {
    // Initialize dynamic array
    NFPAI_RRC_CELL_CONTEXT_T* arr = (NFPAI_RRC_CELL_CONTEXT_T*)malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T) * MAX_SIZE);
    if (!arr) return -1; // Handle memory allocation failure

    int size = 0;
    // Initialize map for cell IDs
    void** cell_id_map = (void**)calloc(MAX_SIZE, sizeof(void*));
    if (!cell_id_map) {
        free(arr);
        return -2; // Handle memory allocation failure
    }

    // Set gc timer for initial garbage collection
    gc_timer = malloc(sizeof(time_t));
    *gc_timer = time(NULL);

    return 1;
}

int nfpa_i_rrc_cell_context_add_connection(uint32_t cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    int i;
    for (i = 0; i < size; i++) {
        if (arr[i].cell_id == cell_id) {
            // Update existing entry
            arr[i].rrc_state = connection_info->last_update_time;
            return 1;
        }
    }

    // Add new connection info
    if (size >= MAX_SIZE) {
        // Resize array
        NFPAI_RRC_CELL_CONTEXT_T* new_arr = (NFPAI_RRC_CELL_CONTEXT_T*)realloc(arr, sizeof(NFPAI_RRC_CELL_CONTEXT_T) * (MAX_SIZE * 2));
        if (!new_arr) return -1; // Handle memory allocation failure

        arr = new_arr;
    }

    arr[size].cell_id = cell_id;
    arr[size].rrc_state = connection_info->last_update_time;
    cell_id_map[cell_id] = connection_info;

    size++;

    return 1;
}

int nfpa_i_rrc_cell_context_remove_connection(uint32_t cell_id) {
    int i, j;
    for (i = 0; i < size; i++) {
        if (arr[i].cell_id == cell_id) {
            // Remove connection info
            free(cell_id_map[cell_id]);
            for (j = i + 1; j < size; j++) {
                arr[j - 1] = arr[j];
            }
            size--;
            return 1;
        }
    }

    return -1; // Connection not found
}

int nfpa_i_rrc_cell_context_gc() {
    time_t current_time = time(NULL);
    int i;
    for (i = 0; i < size; i++) {
        if (*gc_timer + GC_INTERVAL <= current_time) {
            RRC_CONNECTION_INFO_T* connection_info = (RRC_CONNECTION_INFO_T*)cell_id_map[arr[i].cell_id];
            if ((current_time - connection_info->last_update_time) > EXPIRY_THRESHOLD) {
                // Remove expired connection entry
                free(cell_id_map[arr[i].cell_id]);
                for (j = i + 1; j < size; j++) {
                    arr[j - 1] = arr[j];
                }
                size--;
            }
        }
    }

    *gc_timer = current_time;

    return 1;
}

void nfpa_i_rrc_cell_context_deinit() {
    int i;
    for (i = 0; i < size; i++) {
        free(cell_id_map[arr[i].cell_id]);
    }

    free(arr);
    free(cell_id_map);
    free(gc_timer);
}
