#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int num_ue, int* crc_lengths) {
    srand(time(NULL));
    pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;

    // Dynamically allocate memory for UE structures
    NFAPI_CRC_INDICATION_PDU_T** ue_structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(num_ue * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!ue_structures) {
        return NULL;
    }

    int* crc_indication_stats = (int*)malloc(sizeof(int) * 3);
    FILE* stats_file = fopen("crc_indication_stats.log", "w");

    for (int i = 0; i < num_ue; i++) {
        pthread_mutex_lock(&mtx);

        // Generate random RX_UE_INFORMATION_TAG and RNTI
        int rx_tag = rand() % 10000;
        int rnti = rand() % 10000;

        // Dynamically allocate memory for CRC_INDICATION_REL8_TAG with random length
        int crc_length = crc_lengths[i] % 4 + 1; // Ensure a minimum of 4 bytes and maximum of 16 bytes
        NFAPI_CRC_INDICATION_PDU_T* ue_structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(crc_length * sizeof(int));

        if (!ue_structure) {
            pthread_mutex_unlock(&mtx);
            return NULL;
        }

        // Generate random CRC_INDICATION_REL8_TAG
        for (int j = 0; j < crc_length; j++) {
            ue_structure[j] = rand() % 10000;
        }

        // Store UE structure in the list and update statistics
        ue_structures[i] = ue_structure;
        crc_indication_stats[0]++;
        crc_indication_stats[1]++;
        pthread_mutex_unlock(&mtx);
    }

    // Periodically generate CRC indication statistics
    for (int i = 0; i < num_ue; i++) {
        int stats_index = i % 3;
        fprintf(stats_file, "CRC Indication Statistics: Average CRC Length = %.2f bytes, Successful Processings = %d, Errors = %d\n", crc_lengths[i] / 4.0, crc_indication_stats[stats_index * 3], crc_indication_stats[(stats_index + 1) * 3]);
    }

    // Update statistics and free memory
    for (int i = 0; i < num_ue; i++) {
        pthread_mutex_lock(&mtx);

        if (!ue_structures[i]) {
            pthread_mutex_unlock(&mtx);
            continue;
        }

        free(ue_structures[i]);
        pthread_mutex_unlock(&mtx);
    }

    free(crc_indication_stats);
    fclose(stats_file);
    free(ue_structures);

    return NULL;
}

int main() {
    int num_ue = 10000;
    int* crc_lengths = (int*)malloc(num_ue * sizeof(int));

    // Initialize CRC lengths
    for (int i = 0; i < num_ue; i++) {
        crc_lengths[i] = rand() % 16 + 4; // Random CRC length between 4 and 20 bytes
    }

    generate_crc_indications(num_ue, crc_lengths);

    return 0;
}
