NFPAI_RRC_CELL_CONTEXT_T** cell_contexts = NULL;
int num_cell_contexts = 0;
int max_cell_contexts = 1000; // Initial capacity

void init_cell_contexts() {
    cell_contexts = (NFPAI_RRC_CELL_CONTEXT_T**)malloc(max_cell_contexts * sizeof(NFPAI_RRC_CELL_CONTEXT_T*));
    for (int i = 0; i < max_cell_contexts; i++) {
        cell_contexts[i] = NULL;
    }
}

void add_connection(int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    // Check if the cell ID already exists
    int idx = find_cell_context(cell_id);
    if (idx != -1) {
        // Update existing entry
        cell_contexts[idx]->state = RRC_STATE_CONNECTED;
    } else {
        // Add new cell context
        NFPAI_RRC_CELL_CONTEXT_T* new_cell_ctx = (NFPAI_RRC_CELL_CONTEXT_T*)malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T));
        new_cell_ctx->cell_id = cell_id;
        new_cell_ctx->state = RRC_STATE_CONNECTED;
        new_cell_ctx->connection_info = connection_info;
        cell_contexts[num_cell_contexts] = new_cell_ctx;
        num_cell_contexts++;
    }
}

void update_connection(int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    int idx = find_cell_context(cell_id);
    if (idx != -1) {
        // Update existing entry
        cell_contexts[idx]->state = RRC_STATE_CONNECTED;
        cell_contexts[idx]->connection_info = connection_info;
    }
}

void remove_connection(int cell_id) {
    int idx = find_cell_context(cell_id);
    if (idx != -1) {
        free(cell_contexts[idx]->connection_info); // Free dynamically allocated map
        free(cell_contexts[idx]);
        for (int i = idx; i < num_cell_contexts - 1; i++) {
            cell_contexts[i] = cell_contexts[i + 1];
        }
        num_cell_contexts--;
    }
}

int find_cell_context(int cell_id) {
    for (int i = 0; i < num_cell_contexts; i++) {
        if (cell_contexts[i]->cell_id == cell_id) {
            return i;
        }
    }
    return -1; // Cell ID not found
}
