// Function to perform CRUD operations using SQLite database
void performCRUD(sqlite3 *db) {
    sqlite3_stmt *stmt;
    const char *tail;

    // Execute SQL query
    char *query = "SELECT * FROM users WHERE username = ? AND email = ?";
    sqlite3_prepare_v2(db, query, strlen(query), &stmt, &tail);

    // Bind parameters
    sqlite3_bind_text(stmt, 1, "username", -1, SQLITE_TRANSIENT);
    sqlite3_bind_text(stmt, 2, "email@example.com", -1, SQLITE_TRANSIENT);

