                new_cell_context->connection_info_map_size = 0;

                // Add new cell context to the dynamic array
                for (size_t i = 0; i < 10; i++) {
                    if (!cell_context_array[i]) {
                        cell_context_array[i] = new_cell_context;
                        break;
                    }
                }

                // Update memory usage tracking variables
                total_memory_usage += sizeof(NFPAI_RRC_CELL_CONTEXT_T);
                max_memory_usage = total_memory_usage > max_memory_usage ? total_memory_usage : max_memory_usage;

                break;
            case 2:
                // Update an existing cell context
                int cell_id_to_update;
                printf("Enter the cell ID to update: ");
