    private struct NFPAI_RRC_CELL_CONTEXT_T
    {
        public int CellId;
        public RRC_STATE State;
        public Dictionary<int, RRC_CONNECTION_INFO_T> ConnectionInfoMap;
    }

    private enum RRC_STATE { Connected, Disconnected };

    private struct RRC_CONNECTION_INFO_T
    {
        public DateTime Timestamp;
        public int PacketLossCount;
    }

    private Dictionary<int, NFPAI_RRC_CELL_CONTEXT_T> cellContexts;

    public NetworkConnectionManager()
    {
        cellContexts = new Dictionary<int, NFPAI_RRC_CELL_CONTEXT_T>();
    }

    public void AddRRCConnectionInfo(int cellId, DateTime timestamp, int packetLossCount)
    {
        if (!cellContexts.ContainsKey(cellId))
        {
            NFPAI_RRC_CELL_CONTEXT_T context = new NFPAI_RRC_CELL_CONTEXT_T
            {
                CellId = cellId,
                State = RRC_STATE.Connected,
                ConnectionInfoMap = new Dictionary<int, RRC_CONNECTION_INFO_T>()
            };
            cellContexts.Add(cellId, context);
        }

        if (cellContexts[cellId].ConnectionInfoMap.ContainsKey(packetLossCount))
        {
            cellContexts[cellId].ConnectionInfoMap[packetLossCount] = new RRC_CONNECTION_INFO_T
            {
                Timestamp = timestamp,
                PacketLossCount = packetLossCount
            };
        }
        else
        {
            cellContexts[cellId].ConnectionInfoMap.Add(packetLossCount, new RRC_CONNECTION_INFO_T
            {
                Timestamp = timestamp,
                PacketLossCount = packetLossCount
            });
        }
    }

    public void UpdateRRCConnectionInfo(int cellId, int packetLossCount)
    {
        if (cellContexts.ContainsKey(cellId))
        {
            NFPAI_RRC_CELL_CONTEXT_T context = cellContexts[cellId];
            RRC_CONNECTION_INFO_T info;
            if (context.ConnectionInfoMap.TryGetValue(packetLossCount, out info))
            {
                // Update the timestamp
                info.Timestamp = DateTime.Now;
            }
            else
            {
                throw new ArgumentException("Invalid packet loss count");
            }
        }
    }

    public void RemoveRRCConnection(int cellId)
    {
        if (cellContexts.ContainsKey(cellId))
        {
            cellContexts.Remove(cellId);
        }
    }

