} NFPAI_RRC_CELL_CONTEXT_T;

typedef struct RRC_CONNECTION_INFO_T {
    // Define structure fields
} RRC_CONNECTION_INFO_T;

void initialize_cell_context_array(NFPAI_RRC_CELL_CONTEXT_T** cell_context_array, int* size) {
    *cell_context_array = (NFPAI_RRC_CELL_CONTEXT_T*)malloc(*size * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
}

int add_connection_info(NFPAI_RRC_CELL_CONTEXT_T** cell_context_array, int size, int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    for (int i = 0; i < size; i++) {
        if ((*cell_context_array)[i].cell_id == cell_id) {
            (*cell_context_array)[i].connection_info_map = realloc((*cell_context_array)[i].connection_info_map, sizeof(RRC_CONNECTION_INFO_T) * (strlen(connection_info->map) + 1));
            strcat((*cell_context_array)[i].connection_info_map, connection_info->map);
            return i;
        }
    }
    // Add new cell context
    (*cell_context_array) = realloc(*cell_context_array, (++*size) * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
    (*cell_context_array)[*size - 1].cell_id = cell_id;
    (*cell_context_array)[*size - 1].rrc_state = RRC_STATE_INITIALIZE;
    (*cell_context_array)[*size - 1].connection_info_map = malloc(sizeof(RRC_CONNECTION_INFO_T) * 1);
    strcpy((*cell_context_array)[*size - 1].connection_info_map, connection_info->map);
    return *size - 1;
}

void update_connection_info(NFPAI_RRC_CELL_CONTEXT_T** cell_context_array, int size, int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
    for (int i = 0; i < size; i++) {
        if ((*cell_context_array)[i].cell_id == cell_id) {
            strcpy((*cell_context_array)[i].connection_info_map, connection_info->map);
            return;
        }
    }
}

void remove_connection_info(NFPAI_RRC_CELL_CONTEXT_T** cell_context_array, int size, int cell_id) {
    for (int i = 0; i < size; i++) {
        if ((*cell_context_array)[i].cell_id == cell_id) {
            free((*cell_context_array)[i].connection_info_map);
            memset(&(*cell_context_array)[i], 0, sizeof(NFPAI_RRC_CELL_CONTEXT_T));
            for (int j = i + 1; j < size; j++) {
                (*cell_context_array)[j - 1] = (*cell_context_array)[j];
            }
            *size--;
            return;
        }
    }
}

void validate_cell_context(NFPAI_RRC_CELL_CONTEXT_T* cell_context) {
    if (cell_context->rrc_state != RRC_STATE_INITIALIZE && cell_context->connection_info_map == NULL)
        printf("Error: Cell context integrity not valid.\n");
}
