void* nfpa_i_rrc_cell_context_manager(void) {
    // Initialize an empty dynamic array
    NFPAI_RRC_CELL_CONTEXT_T** cell_contexts = NULL;
    int num_cell_contexts = 0, max_num_cell_contexts = 100; // Start with a small initial size

    // Allocate memory for the first batch of cell contexts
    cell_contexts = (NFPAI_RRC_CELL_CONTEXT_T**)malloc(max_num_cell_contexts * sizeof(NFPAI_RRC_CELL_CONTEXT_T*));
    if (!cell_contexts) {
        return NULL; // Handle allocation error
    }

    // Initialize and manage the dynamic array
    for (int i = 0; i < max_num_cell_contexts; i++) {
        cell_contexts[i] = malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T));
        if (!cell_contexts[i]) {
            return NULL; // Handle allocation error
        }
        cell_contexts[i]->connection_info_map = NULL;
    }

    // Define function to add a new connection for a given cell ID
    void add_connection(int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
        // Find the corresponding cell context in the dynamic array
        NFPAI_RRC_CELL_CONTEXT_T* cell_context = get_cell_context(cell_id, cell_contexts);
        if (cell_context) {
            // Check for existing connections with the same ID
            for (int i = 0; i < num_cell_contexts; i++) {
                if (cell_contexts[i]->cell_id == cell_id && cell_contexts[i]->connection_info_map) {
                    return; // Connection already exists, skip duplicate addition
                }
            }

            // Update the connection information map for the given cell ID
            NFPAI_RRC_CELL_CONTEXT_T* new_cell_context = realloc(cell_context->connection_info_map,
                                                                    (num_cell_contexts + 1) * sizeof(RRC_CONNECTION_INFO_T*));
            if (!new_cell_context) {
                return; // Handle allocation error
            }
            cell_context->connection_info_map = new_cell_context;
            cell_context->connection_info_map[num_cell_contexts++] = connection_info;
        }
    }

    // Define function to update an existing connection for a given cell ID
    void update_connection(int cell_id, RRC_CONNECTION_INFO_T* connection_info) {
        // Find the corresponding cell context in the dynamic array
        NFPAI_RRC_CELL_CONTEXT_T* cell_context = get_cell_context(cell_id, cell_contexts);
        if (cell_context && cell_context->connection_info_map) {
            for (int i = 0; i < num_cell_contexts; i++) {
                if (cell_contexts[i]->cell_id == cell_id) {
                    // Update the connection information map
                    cell_contexts[i]->connection_info_map[i] = connection_info;
                    return;
                }
            }
        }
    }

    // Define function to remove a connection for a given cell ID
    void remove_connection(int cell_id) {
        // Find the corresponding cell context in the dynamic array
        NFPAI_RRC_CELL_CONTEXT_T* cell_context = get_cell_context(cell_id, cell_contexts);
        if (cell_context && cell_context->connection_info_map) {
            for (int i = 0; i < num_cell_contexts; i++) {
                if (cell_contexts[i]->cell_id == cell_id) {
                    // Remove the connection and update the map
                    free(cell_contexts[i]->connection_info_map[i]);
                    cell_context->connection_info_map[i] = NULL;
                    break;
                }
            }
        }
    }

    // Define function to get a cell context by ID
    NFPAI_RRC_CELL_CONTEXT_T* get_cell_context(int cell_id, NFPAI_RRC_CELL_CONTEXT_T** cell_contexts) {
        for (int i = 0; i < num_cell_contexts; i++) {
            if (cell_contexts[i]->cell_id == cell_id) {
                return cell_contexts[i];
            }
        }
        return NULL;
    }

    // Define function to free the dynamic array
    void free_cell_contexts(NFPAI_RRC_CELL_CONTEXT_T** cell_contexts, int num_cell_contexts) {
        for (int i = 0; i < num_cell_contexts; i++) {
            if (cell_contexts[i]->connection_info_map) {
                // Clean up the connection information map
                for (int j = 0; j < num_cell_contexts; j++) {
                    free(cell_contexts[i]->connection_info_map[j]);
                }
                free(cell_contexts[i]->connection_info_map);
            }
            free(cell_contexts[i]);
        }
        free(cell_contexts);
    }

    return cell_contexts;
}
