void init_ue_context(NFAPI_RRC_UECONTEXT_T **ue_context, uint32_t ue_id) {
    *ue_context = (NFAPI_RRC_UECONTEXT_T *)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (*ue_context == NULL) {
        printf("Memory allocation failed\n");
        return;
    }
    (*ue_context)->ue_id = ue_id;
    (*ue_context)->rrc_state = RRC_IDLE;
    (*ue_context)->pdu_list = NULL;
    (*ue_context)->pdu_list_len = 0;
}

int add_pdu_to_ue(NFAPI_RRC_UECONTEXT_T *ue_context, NFAPI_UL_CCCH_pdu_t *pdu) {
    // Check if the PDU is valid
    if (pdu == NULL) return -1;

    // Allocate memory for a new entry in the list
    struct nfaPI_UL_CCCH_pdu_t *new_entry = (struct nfaPI_UL_CCCH_pdu_t *)malloc(sizeof(struct nfaPI_UL_CCCH_pdu_t));
    if (new_entry == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Add the new PDU to the list
    if (ue_context->pdu_list == NULL) {
        ue_context->pdu_list = new_entry;
    } else {
        struct nfaPI_UL_CCCH_pdu_t *curr = ue_context->pdu_list;
        while (curr->next != NULL) curr = curr->next;
        curr->next = new_entry;
    }
    ue_context->pdu_list_len++;

    return 0;
}

void update_ue_context(NFAPI_RRC_UECONTEXT_T **ue_context, uint32_t ue_id, enum rrc_state state) {
    // Check if the UE context is valid
    if (*ue_context == NULL || (*ue_context)->ue_id != ue_id) return;

    (*ue_context)->rrc_state = state;
}

void free_ue_context(NFAPI_RRC_UECONTEXT_T *ue_context) {
    // Free each PDU in the list
    struct nfaPI_UL_CCCH_pdu_t *curr = ue_context->pdu_list;
    while (curr != NULL) {
        struct nfaPI_UL_CCCH_pdu_t *next = curr->next;
        free(curr);
        curr = next;
    }
    // Free the UE context itself
    free(ue_context);
}

int main() {
    NFAPI_RRC_UECONTEXT_T *ue_context1, *ue_context2;

    init_ue_context(&ue_context1, 1);
    init_ue_context(&ue_context2, 2);

    add_pdu_to_ue(ue_context1, NULL); // Add a PDU to ue_context1
    update_ue_context(&ue_context1, 1, RRC_CONNECTED);

    free_ue_context(ue_context1);
    free_ue_context(ue_context2);

    return 0;
}
