#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UERCC 10
#define MAX_PDU_PER_UERCC 100
#define CLEANUP_GRACE_PERIOD 60 // in seconds

typedef struct {
    int ue_id;
    NFAPI_RRC_UECONTEXT_T rrc_state;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    void** pdus;
} NFAPI_UL_CCCH_CTX;

typedef struct {
    timestamp ts;
    char data[256];
} NFAPI_UL_CCCH_pdu_t;

void* nfa_api_ul_ccch_ctx_create() {
    return malloc(sizeof(NFAPI_UL_CCCH_CTX));
}

void nfa_api_ul_ccch_ctx_destroy(void* ctx) {
    free(ctx);
}

void nfa_api_ul_ccch_ctx_init(NFAPI_UL_CCCH_CTX* ctx, int ue_id, NFAPI_RRC_UECONTEXT_T rrc_state) {
    ctx->ue_id = ue_id;
    ctx->rrc_state = rrc_state;
    ctx->size = 0;
}

int nfa_api_ul_ccch_ctx_add_pdu(NFAPI_UL_CCCH_CTX* ctx, void* pdu) {
    pthread_mutex_lock(&ctx->mutex);
    if (ctx->size >= MAX_PDU_PER_UERCC) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    void** new_pdus = realloc(ctx->pdus, (ctx->size + 2) * sizeof(void*));
    if (!new_pdus) {
        pthread_mutex_unlock(&ctx->mutex);
        return -1;
    }
    ctx->pdus = new_pdus;
    ctx->pdus[ctx->size] = pdu;
    ctx->size++;
    pthread_cond_signal(&ctx->cond);
    pthread_mutex_unlock(&ctx->mutex);
    return 0;
}

void* nfa_api_ul_ccch_ctx_get_pdu(NFAPI_UL_CCCH_CTX* ctx, int index) {
    if (index >= ctx->size || !ctx->pdus[index]) {
        return NULL;
    }
    return ctx->pdus[index];
}

int nfa_api_ul_ccch_ctx_cleanup(NFAPI_UL_CCCH_CTX* ctx, int grace_period) {
    pthread_mutex_lock(&ctx->mutex);
    for (int i = 0; i < ctx->size; i++) {
        if (!ctx->pdus[i] || timestamp_diff(ctx->pdus[i]->ts, timestampGetCurrent()) > grace_period * 1000) {
            free(ctx->pdus[i]);
            memmove(&ctx->pdus[i], &ctx->pdus[i + 1], (ctx->size - i - 1) * sizeof(void*));
            ctx->size--;
        }
    }
    pthread_mutex_unlock(&ctx->mutex);
    return 0;
}

int main() {
    // usage example
    NFAPI_UL_CCCH_CTX* ctx = nfa_api_ul_ccch_ctx_create();
    nfa_api_ul_ccch_ctx_init(ctx, 1, RRC_STATE_CONNECTED);
    for (int i = 0; i < MAX_PDU_PER_UERCC; i++) {
