// Define the Task structure
typedef struct {
    int id;
    char* description;
    int priority;
    time_t deadline;
} Task;

// Define the TaskStatus structure
typedef struct {
    int taskId;
    int status;
    time_t lastUpdate;
} TaskStatus;

// Function to initialize and manage memory for Task structures
Task* taskManager(int numTasks) {
    Task* tasks = (Task*)malloc(numTasks * sizeof(Task));

    if (!tasks) {
        printf("Memory allocation failed!\n");
        return NULL;
    }

    for (int i = 0; i < numTasks; i++) {
        tasks[i].id = i;
        tasks[i].description = malloc(strlen("Task ") + 1);
        strcpy(tasks[i].description, "Task ");
        tasks[i].priority = rand() % 5 + 1;
        tasks[i].deadline = time(NULL) + rand() % 10000;
    }

    return tasks;
}

// Function to initialize and manage memory for TaskStatus structures
void taskStatusManager(Task* tasks, int numTasks) {
    TaskStatus* statuses = (TaskStatus*)malloc(numTasks * sizeof(TaskStatus));

    if (!statuses) {
        printf("Memory allocation failed!\n");
        return;
    }

    for (int i = 0; i < numTasks; i++) {
        statuses[i].taskId = tasks[i].id;
        statuses[i].status = 0; // Initialize status as not completed
        statuses[i].lastUpdate = time(NULL);
    }
}

// Function to update task status and timestamp
void updateTaskStatus(Task* tasks, TaskStatus* statuses, int taskId) {
    for (int i = 0; i < numTasks; i++) {
        if (tasks[i].id == taskId) {
            statuses[i].status = 1; // Mark as completed
            statuses[i].lastUpdate = time(NULL);
            return;
        }
    }
}

// Function to garbage collect un-referenced tasks
void garbageCollect(Task* tasks, TaskStatus* statuses) {
    for (int i = 0; i < numTasks; i++) {
        if (statuses[i].status == 1) { // Check if task is completed
            free(tasks[i].description);
            tasks[i].id = -1;
            tasks[i].priority = -1;
            tasks[i].deadline = -1;
        }
    }
}
