    // integrate with external logging system
    printf("Total entries processed: %u, Skipped entries: %u\n", num_entries, skipped);
}

uint32_t populate_nfapi_crc_indication_pdu_t_array(size_t num_entries, size_t timeout_ms) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    uint32_t allocated = 0;
    uint32_t skipped = 0;

    clock_t start_time = clock();

    while (allocated < num_entries && (array == NULL || (clock() - start_time) * 1000 / CLOCKS_PER_SEC <= timeout_ms)) {
        if (array == NULL || array + allocated >= &array[num_entries]) {
            size_t new_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (num_entries - allocated);
            array = realloc(array, new_size);
            if (array == NULL) {
                // handle memory allocation failure
                break;
            }
        }

        NFAPI_CRC_INDICATION_PDU_T* entry = &array[allocated];

        // generate random RNTI within the specified range
        uint16_t rnti = rand() % 65536;

        if (rnti < 0 || rnti > 65535) {
            skipped++;
            continue;
        }

        entry->RX_UE_INFORMATION_TAG = ...;  // set valid RX_UE_INFORMATION_TAG
        entry->RNTI = rnti;
        entry->CRC_INDICATION_REL8_TAG = ...;  // set CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG

        allocated++;
    }

    if (array != NULL) {
        free(array);
    }

    log_entry(num_entries, skipped);

    return allocated;
}
