    size_t size;
} file_chunk;

SSL_CTX* context = NULL;
FILE* file = NULL;
file_chunk* chunk = NULL;
size_t total_size = 0;
MD5_CTX md5_ctx;

void process_file(const char* file_path) {
    if (NULL == (file = fopen(file_path, "rb"))) {
        printf("Error opening file: %s\n", file_path);
        return;
    }

    SSL_library_init();
    SSL_load_error_strings();
    context = SSL_CTX_new(TLS_client_method());
    MD5_Init(&md5_ctx);

    while (1) {
        if (-1 == (int)fread(chunk->data, 1, chunk->size, file)) {
            break;
        }
        total_size += chunk->size;

        MD5_Update(&md5_ctx, chunk->data, chunk->size);
    }

    fclose(file);

    unsigned char* md5_hash = MD5_Final(NULL, &md5_ctx);
    // Process the hash here...

    SSL_CTX_free(context);
}

int main(int argc, char** argv) {
    if (argc != 2) {
        printf("Usage: %s <file_path>\n", argv[0]);
        return 1;
    }

    const char* file_path = argv[1];
    process_file(file_path);

    return 0;
}
