pthread_mutex_t filename_lock = PTHREAD_MUTEX_INITIALIZER;

void generate_random_digits(char *random_string, int length) {
    static int seed = time(NULL);
    srand(seed);

    for (int i = 0; i < length; i++) {
        random_string[i] = '0' + rand() % 10;
    }
    random_string[length] = '\0';
}

char *transform_filename(char *filename) {
    char transformed_filename[MAX_FILENAME_LENGTH];
    char file_type[FILE_TYPE_PREFIX_LENGTH + 1];

    // Replace spaces with underscores
    int i, j = 0;
    for (i = 0; i < strlen(filename); i++) {
        if (filename[i] == ' ') {
            continue;
        }
        transformed_filename[j++] = filename[i];
    }
    transformed_filename[j] = '\0';

    // Append random digits
    char random_digits[10];
    generate_random_digits(random_digits, 8);
    strcat(transformed_filename, random_digits);

    // Derive file type from the last three characters
    for (i = strlen(filename) - FILE_TYPE_PREFIX_LENGTH; i < strlen(filename); i++) {
        file_type[i - FILE_TYPE_PREFIX_LENGTH] = filename[i];
    }
    file_type[FILE_TYPE_PREFIX_LENGTH] = '\0';

    char *file_extension;
    if (strchr(file_type, '.') != NULL) {
        file_extension = strchr(file_type, '.');
        *file_extension = '\0';
    } else {
        file_extension = "bin";
    }

    // Ensure no result exceeds 256 characters
    int length = strlen(transformed_filename);
    if (length < MAX_FILENAME_LENGTH - FILE_TYPE_PREFIX_LENGTH) {
        strcat(transformed_filename, file_extension);
    } else {
        transformed_filename[MAX_FILENAME_LENGTH - FILE_TYPE_PREFIX_LENGTH] = '\0';
    }

    return transformed_filename;
}

void *filename_thread_func(void *arg) {
