void transform_filename(char *original, filename_t *result) {
    // Replace spaces with underscores
    char *new_name = (char *)malloc(MAX_FILENAME_LENGTH);
    strcpy(new_name, original);
    new_name[strcspn(new_name, " ")] = '_';

    // Append random digits based on current time and filename hash
    char rand_str[MAX_RANDOM_DIGITS + 1];
    sprintf(rand_str, "%x", time(NULL) ^ (uintptr_t)original);
    strcat(new_name, rand_str);

    // Derive file type from last three characters
    char *file_type = NULL;
    if ((file_type = strrchr(new_name, '.')) != NULL) {
        *file_type = '\0';
    } else {
        *new_name = '\0';
    }
    result->file_type = 1; // default to ".bin"

    // Ensure no result exceeds MAX_FILENAME_LENGTH
    int len = strlen(new_name);
    if (len > MAX_FILENAME_LENGTH) {
        new_name[MAX_FILENAME_LENGTH - 3] = '_';
        new_name[MAX_FILENAME_LENGTH - 2] = 't';
        new_name[MAX_FILENAME_LENGTH - 1] = 'o';
    }

    // Short filenames: prepend current date and time
    char short_name[32];
    strftime(short_name, sizeof(short_name), "%Y-%m-%d_%H:%M:%S_");
    strcat(short_name, new_name);
    free(new_name);
    result->filename = short_name;
}

int main() {
