    FILE *log_file = fopen("credentials.log", "a+");
    time_t current_time = time(NULL);
    if(current_time % (60*60*24*30) == 0) {
        fclose(log_file);
        log_file = fopen("credentials.log", "w");
    }
    fprintf(log_file, "%s\n", (char*) arg);

    return NULL;
}

// Define a function to handle errors and recover gracefully
