// Function to create a new credential manager
CredentialManager *credential_manager_create() {
    CredentialManager *manager = (CredentialManager *)malloc(sizeof(CredentialManager));
    manager->size = 0;
    manager->capacity = 10; // Initialize with a default capacity
    manager->credentials = (Credential **)calloc(manager->capacity, sizeof(Credential *));
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new credential to the collection
void credential_manager_add(CredentialManager *manager, Credential *credential) {
    if (manager->size == manager->capacity) {
        // If the collection is full, double its capacity and realloc memory
        manager->capacity *= 2;
        manager->credentials = (Credential **)realloc(manager->credentials, manager->capacity * sizeof(Credential *));
    }
    manager->credentials[manager->size] = credential;
    manager->size++;
}

