} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* init_ue_context(int num_pdu) {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!ue_ctx) return NULL;

    ue_ctx->ue_id = 0;
    ue_ctx->rrc_state = RRC_STATE_UNDEFINED;

    ue_ctx->pdu_list = malloc(num_pdu * sizeof(struct NFAPI_UL_CCCH_pdu_t*));
    if (!ue_ctx->pdu_list) {
        free(ue_ctx);
        return NULL;
    }

    for (int i = 0; i < num_pdu; i++) {
        ue_ctx->pdu_list[i] = malloc(sizeof(struct NFAPI_UL_CCCH_pdu_t));
        if (!ue_ctx->pdu_list[i]) {
            for (int j = 0; j <= i; j++) {
                free(ue_ctx->pdu_list[j]);
            }
            free(ue_ctx->pdu_list);
            free(ue_ctx);
            return NULL;
        }
    }

    ue_ctx->pdu_list_len = num_pdu;

    return ue_ctx;
}

void add_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, struct NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!ue_ctx || !pdu) return;

    int new_len = ue_ctx->pdu_list_len + 1;
    struct NFAPI_UL_CCCH_pdu_t** new_pdu_list = realloc(ue_ctx->pdu_list, new_len * sizeof(struct NFAPI_UL_CCCH_pdu_t*));
    if (!new_pdu_list) return;

    for (int i = ue_ctx->pdu_list_len; i < new_len - 1; i++) {
        new_pdu_list[i] = new_pdu_list[i + 1];
    }
    new_pdu_list[new_len - 1] = pdu;

    free(ue_ctx->pdu_list);
    ue_ctx->pdu_list = new_pdu_list;
    ue_ctx->pdu_list_len = new_len;
}

void remove_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, struct NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!ue_ctx || !pdu) return;

    int i;
    for (i = 0; i < ue_ctx->pdu_list_len; i++) {
        if (ue_ctx->pdu_list[i] == pdu) break;
    }

    if (i >= ue_ctx->pdu_list_len) return;

    for (; i < ue_ctx->pdu_list_len - 1; i++) {
        ue_ctx->pdu_list[i] = ue_ctx->pdu_list[i + 1];
    }

    free(ue_ctx->pdu_list[ue_ctx->pdu_list_len - 1]);
    ue_ctx->pdu_list = realloc(ue_ctx->pdu_list, (ue_ctx->pdu_list_len - 1) * sizeof(struct NFAPI_UL_CCCH_pdu_t*));
    ue_ctx->pdu_list_len--;
}

