        struct NFAPI_UL_CCCH_pdu_t* pdu = ue_ctx->pdu_list[i];

        *(uint32_t*)(&buffer[pos]) = pdu->header;
        pos += sizeof(uint32_t);
        *(char*)(&buffer[pos]) = pdu->data[0];
        pos++;

        free(pdu);
    }

    return pos;
}

int deserialize_ue_context(NFAPI_RRC_UECONTEXT_T** ue_ctx, char* buffer) {
    if (!ue_ctx || !buffer) return -1;

    *ue_ctx = malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!*ue_ctx) return -1;

    (*ue_ctx)->ue_id = *(uint32_t*)(&buffer[0]);
    buffer += sizeof(uint32_t);
    (*ue_ctx)->rrc_state = *(RRC_STATE*)(&buffer[0]);
    buffer += sizeof(RRC_STATE);

    int pdu_list_len = (int)(buffer - &buffer[0]) / sizeof(struct NFAPI_UL_CCCH_pdu_t);
    (*ue_ctx)->pdu_list_len = pdu_list_len;

    (*ue_ctx)->pdu_list = malloc(pdu_list_len * sizeof(struct NFAPI_UL_CCCH_pdu_t*));
    if (!(*ue_ctx)->pdu_list) return -1;

    for (int i = 0; i < pdu_list_len; i++) {
        struct NFAPI_UL_CCCH_pdu_t* pdu = malloc(sizeof(struct NFAPI_UL_CCCH_pdu_t));
        if (!pdu) return -1;

        *(uint32_t*)(&buffer[0]) = pdu->header;
        buffer += sizeof(uint32_t);
        pdu->data[0] = *buffer++;

        (*ue_ctx)->pdu_list[i] = pdu;
    }

    return 0;
}

void handle_ue_context_change(NFAPI_RRC_UECONTEXT_T* ue_ctx, int event_type) {
    if (!ue_ctx) return;

    switch (event_type) {
        case UE_CONTEXT_ADD:
            add_pdu(ue_ctx, /* new PDU */);
            break;
        case UE_CONTEXT_REMOVE:
            remove_pdu(ue_ctx, /* removed PDU */);
            break;
        default:
            break;
    }
}

void event_handler(NFAPI_RRC_UECONTEXT_T* ue_ctx, int event_type) {
    if (!ue_ctx) return;

    log_performance(ue_ctx);

    handle_ue_context_change(ue_ctx, event_type);
}
