#define MAX_SESSIONS 1000
#define MAX_SESSION_DATA 1024
#define MEMORY_THRESHOLD 75 // in percentage

typedef struct {
    char id[32];
    char username[64];
    char password[64];
    time_t timestamp;
    void* data;
} Session;

Session** sessions = NULL;
int session_count = 0;
int memory_usage = 0;

void validate_session_data(Session* s) {
    if (!s->data || !s->timestamp) {
        printf("Invalid session data: %s\n", s->id);
        return;
    }
}

void add_session(Session* s) {
    // resize the sessions array when necessary
    if (session_count >= MAX_SESSIONS) {
        Session** new_sessions = realloc(sessions, sizeof(Session*) * (MAX_SESSIONS * 2));
        if (!new_sessions) {
            printf("Memory allocation failed for session addition.\n");
            return;
        }
        sessions = new_sessions;
    }

    // update the session map
    s->data = malloc(MAX_SESSION_DATA);
    if (!s->data) {
        printf("Memory allocation failed for session data.\n");
        return;
    }

    // add the session to the list
    sessions[session_count] = s;
    session_count++;

    memory_usage += sizeof(Session) + strlen(s->id) + strlen(s->username) + strlen(s->password);
}

void update_session(char* id, char* key, void* value) {
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i]->id, id) == 0) {
            // resize the data map when necessary
            size_t new_size = strlen(key) + sizeof(void*) * 2;
            void* new_data = realloc(sessions[i]->data, new_size);
            if (!new_data) {
                printf("Memory allocation failed for session update.\n");
                return;
            }
            sessions[i]->data = new_data;

            // store the updated value
            memcpy(new_data + strlen(key), value, sizeof(void*));
            break;
        }
    }
}

void invalidate_session(char* id) {
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i]->id, id) == 0) {
            free(sessions[i]->data);
            sessions[i]->data = NULL;
            break;
        }
    }

    // garbage collection
    int deleted_sessions = 0;
    for (int i = 0; i < session_count; i++) {
        if (difftime(time(NULL), sessions[i]->timestamp) > 24 * 60 * 60) {
            free(sessions[i]->data);
            sessions[i]->data = NULL;
            deleted_sessions++;
        }
    }

    // reclaim memory
    Session** new_sessions = realloc(sessions, sizeof(Session*) * (session_count - deleted_sessions));
    if (!new_sessions) {
        printf("Memory allocation failed for session invalidation.\n");
        return;
    }
    sessions = new_sessions;
    session_count -= deleted_sessions;

    memory_usage -= sizeof(Session) + strlen(id) + strlen(sessions[i]->username) + strlen(sessions[i]->password);
}

void periodic_garbage_collection() {
    // check the timestamp of each session
    for (int i = 0; i < session_count; i++) {
        if (difftime(time(NULL), sessions[i]->timestamp) > 24 * 60 * 60) {
            invalidate_session(sessions[i]->id);
        }
    }
}

void monitor_memory_usage() {
    int threshold = memory_usage / 100.0 * MEMORY_THRESHOLD;
    if (memory_usage >= threshold) {
        printf("Memory usage exceeds %d%% of the maximum limit.\n", MEMORY_THRESHOLD);
    }
}

int main(int argc, char* argv[]) {
    // initialize the sessions array
    sessions = malloc(sizeof(Session*) * MAX_SESSIONS);
    if (!sessions) {
        printf("Memory allocation failed for session initialization.\n");
        return 1;
    }

    // configure periodic garbage collection
    int gc_interval = atoi(argv[1]);
    if (gc_interval <= 0) {
        printf("Invalid garbage collection interval: %d\n", gc_interval);
        return 1;
    }
    else {
        while (true) {
            sleep(gc_interval);
            periodic_garbage_collection();
        }
    }

    return 0;
}

void handle_external_update(char* id, char* key, void* value) {
    // update the session data
    for (int i = 0; i < session_count; i++) {
        if (strcmp(sessions[i]->id, id) == 0) {
            update_session(id, key, value);
            break;
        }
    }
}
