#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FILENAME_LENGTH 256
#define MAX_KEYWORD_LENGTH 128

int main(int argc, char *argv[]) {
    FILE *output_file = NULL;
    bool debug_mode = false;
    bool print_manpage = false;
    bool compile_source_code = false;

    int c;
    while ((c = getopt(argc, argv, "o:cs:d--manpage")) != -1) {
        switch (c) {
            case 'o':
                output_file = fopen(optarg, "w");
                if (!output_file) {
                    fprintf(stderr, "Error opening output file: %s\n", optarg);
                    return 1;
                }
                break;
            case 'd':
                debug_mode = true;
                break;
            case 'c':
                compile_source_code = true;
                break;
            case '?':
            case '-':
                print_manpage = true;
                break;
        }
    }

    if (print_manpage) {
        printf("Usage: %s [-o output_file] [-cs] [-d debug] --manpage\n", argv[0]);
        return 0;
    }

    char keyword[MAX_KEYWORD_LENGTH];
    fgets(keyword, MAX_KEYWORD_LENGTH, stdin);

    char *input_filenames = getenv("INPUT_FILES");
    if (!input_filenames) {
        fprintf(stderr, "No input files provided.\n");
        return 1;
    }

    char **filenames = NULL;
    int num_files = 0;

    // Split the comma-separated filenames
    char *token = strtok(input_filenames, ",");
    while (token) {
        filenames = realloc(filenames, (num_files + 2) * sizeof(char *));
        filenames[num_files] = token;
        num_files++;
        token = strtok(NULL, ",");
    }

    for (int i = 0; i < num_files; i++) {
        char filename[MAX_FILENAME_LENGTH];
        strcpy(filename, filenames[i]);

        FILE *file = fopen(filename, "r");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", filename);
            return 1;
        }

        char line[MAX_LINE_LENGTH];
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            bool found = strstr(strcasestr(line, keyword), keyword) != NULL;
            if (found) {
                if (output_file) {
                    fprintf(output_file, "%s: %s\n", filename, line);
                } else {
                    printf("%s: %s\n", filename, line);
                }
            }
        }

        fclose(file);
    }

    for (int i = 0; i < num_files; i++) {
        free(filenames[i]);
    }
    free(filenames);

    if (output_file) {
        fclose(output_file);
    }

    return 0;
}
