using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;

public class AdvancedFileStateManager : IDisposable
{
    private const int DefaultMaxStates = 1000;
    private readonly int _maxStates;
    private readonly object _lock = new object();
    private List<State> _states;
    private FileSystemWatcher _fileSystemWatcher;

    public AdvancedFileStateManager(int maxStates = DefaultMaxStates)
    {
        _maxStates = maxStates;
        _states = new List<State>();
    }

    public void AddState(string stateName, int sequenceNumber, string fileType)
    {
        lock (_lock)
        {
            if (_states.Count >= _maxStates)
            {
                // Evict less frequently used states
                var oldestState = _states.OrderBy(x => x.SequenceNumber).First();
                _states.Remove(oldestState);
            }

            _states.Add(new State(stateName, sequenceNumber, fileType));
        }
    }

    public void UpdateState(string stateName, int newSequenceNumber)
    {
        lock (_lock)
        {
            var existingState = _states.Find(x => x.Name == stateName);
            if (existingState != null)
            {
                existingState.SequenceNumber = newSequenceNumber;
            }
        }
    }

    public void RemoveState(string stateName)
    {
        lock (_lock)
        {
            _states.RemoveAll(x => x.Name == stateName);
        }
    }

    public string GenerateNewFilename(int sequenceNumber, string fileType)
    {
        return $"state_{sequenceNumber}_{DateTime.Now:yyyy-MM-dd_HH-mm-ss}.{fileType}";
    }

    public void ValidateStates()
    {
        lock (_lock)
        {
            if (_states.Count > _maxStates)
            {
                throw new InvalidOperationException("Maximum number of states exceeded.");
            }
        }
    }

