            os.makedirs('keys')

        try:
            with open(os.path.join('keys', 'key.key'), 'rb') as f:
                key = Fernet(f.read()).decrypt(b'secret')
                cipher_suite = Fernet(key)

            encrypted_config = {}
            for key, value in config.items():
