        with open('schema.yaml', 'r') as f:
            schema = yaml.safe_load(f)

        try:
            if not isinstance(schema, dict) or any(not isinstance(sub_schema, dict) for sub_schema in schema.values()):
                raise ValueError("Invalid schema")
        except Exception as e:
            raise ValueError(f"Failed to validate schema: {e}")

    def log_performance(self):
        self.logger.info(f"Processed file {self.file_path} in {os.path.getsize(self.file_path)} bytes")

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description='Configuration File Processor')
    parser.add_argument('file_path', help='path to the configuration file')
    parser.add_argument('-a', '--algorithm', help='specify encryption algorithm (default is AES)')
