#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SIZE 1000
#define GARbage_COLLECTION_INTERVAL 30 // in days

typedef struct {
    int cell_id;
    enum { RRC_STATE_IDLE, RRC_STATE_CONNECTED } rrc_state;
    struct {
        int timestamp;
        // additional fields as needed
    } *connection_info;
} NFPAI_RRC_CELL_CONTEXT_T;

typedef struct {
    int cell_id;
    int timestamp;
    // additional fields as needed
} RRC_CONNECTION_INFO_T;

void init_cell_context(NFPAI_RRC_CELL_CONTEXT_T **cell_context, int *size) {
    *cell_context = (NFPAI_RRC_CELL_CONTEXT_T *)malloc(MAX_SIZE * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
    *size = MAX_SIZE;
}

int add_connection_info(NFPAI_RRC_CELL_CONTEXT_T *cell_context, int size, RRC_CONNECTION_INFO_T *connection_info) {
    for (int i = 0; i < size; i++) {
        if (cell_context[i].cell_id == connection_info->cell_id) {
            cell_context[i].rrc_state = connection_info->rrc_state;
            cell_context[i].connection_info->timestamp = connection_info->timestamp;
            return 0; // update existing entry
        }
    }
    if (size >= MAX_SIZE) {
        // resize the array and reallocate memory
        NFPAI_RRC_CELL_CONTEXT_T *new_cell_context = (NFPAI_RRC_CELL_CONTEXT_T *)realloc(cell_context, (size + 1) * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
        cell_context = new_cell_context;
        size++;
    }
    // allocate memory for the new connection info
    NFPAI_RRC_CELL_CONTEXT_T *new_entry = (NFPAI_RRC_CELL_CONTEXT_T *)malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T));
    new_entry->cell_id = connection_info->cell_id;
    new_entry->rrc_state = connection_info->rrc_state;
    new_entry->connection_info = (RRC_CONNECTION_INFO_T *)malloc(sizeof(RRC_CONNECTION_INFO_T));
    new_entry->connection_info->timestamp = connection_info->timestamp;
    cell_context[size] = *new_entry;
    return size + 1; // add new entry
}

int remove_connection_info(NFPAI_RRC_CELL_CONTEXT_T *cell_context, int size) {
    for (int i = 0; i < size; i++) {
        if (cell_context[i].connection_info->timestamp <= GARbage_COLLECTION_INTERVAL) {
            free(cell_context[i].connection_info);
            // shift remaining entries to fill the gap
            for (int j = i + 1; j < size; j++) {
                cell_context[j - 1] = cell_context[j];
            }
            size--;
            i--; // recheck the same index after shifting
        }
    }
    return size;
}

void garbage_collection(NFPAI_RRC_CELL_CONTEXT_T *cell_context, int size) {
    for (int i = 0; i < size; i++) {
        if (cell_context[i].connection_info->timestamp <= GARbage_COLLECTION_INTERVAL) {
            free(cell_context[i].connection_info);
        }
    }
}

int main() {
    NFPAI_RRC_CELL_CONTEXT_T *cell_context;
    int size;

    init_cell_context(&cell_context, &size);

    // add connection info
    RRC_CONNECTION_INFO_T connection_info1 = { 123, 1643723400 };
    RRC_CONNECTION_INFO_T connection_info2 = { 456, 1644723400 };
    size = add_connection_info(cell_context, size, &connection_info1);
    size = add_connection_info(cell_context, size, &connection_info2);

    // remove connection info
    size = remove_connection_info(cell_context, size);

    garbage_collection(cell_context, size);

    return 0;
}
```']

