    if (!record_pool) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
}

int add_record(int caller_id, int called_id, time_t timestamp, int call_duration, int call_type, char* status) {
    // Allocate a new record
    CallDetailRecord* record = (CallDetailRecord*)malloc(sizeof(CallDetailRecord));
    if (!record) {
        printf("Memory allocation failed!\n");
        return -1;
    }

    // Initialize the record fields
    record->caller_id = caller_id;
    record->called_id = called_id;
    record->timestamp = timestamp;
    record->call_duration = call_duration;
    record->call_type = call_type;
    strcpy(record->status, status);

    // Add the new record to the pool
    if (record_count < MAX_RECORDS) {
        records[record_count] = record;
        record_count++;
    } else {
