                   records[i]->caller_id, records[i]->called_id,
                   records[i]->timestamp, records[i]->call_duration,
                   records[i]->status);
        }
    }
}

void free_record_pool() {
    // Free the record pool
    for (int i = 0; i < record_count; i++) {
        free(records[i]);
    }
    free(record_pool);
}
