void* record_pool = NULL;
int pool_size = 0;
int current_index = -1;

CallDetailRecord_t* allocate_record() {
    if (record_pool == NULL || current_index >= pool_size) {
        record_pool = realloc(record_pool, (pool_size + MAX_RECORDS) * RECORD_SIZE);
        pool_size += MAX_RECORDS;
    }
    return (CallDetailRecord_t*) ((char*) record_pool + current_index++ * RECORD_SIZE);
}

void deallocate_record(CallDetailRecord_t* record) {
    if (record != NULL) {
        free(record->status);
        memset(record, 0, RECORD_SIZE);
    }
}

