typedef struct SensorData {
    float reading;
    int timestamp;
    char* label;
} SensorData;

// Define the maximum number of sensors and readings
#define MAX_SENSORS 100
#define MAX_READINGS 1000

// Function to manage dynamic memory allocation and initialization
SensorData** initializeSensors(int numSensors) {
    // Allocate memory for sensor data arrays
    float* sensorReadings = (float*)malloc(numSensors * sizeof(float));
    int* timestamps = (int*)malloc(numSensors * sizeof(int));
    char** labels = (char**)malloc(numSensors * sizeof(char*));

    // Initialize the array of SensorData structures
    SensorData** sensorData = (SensorData**)malloc(numSensors * sizeof(SensorData*));

    for (int i = 0; i < numSensors; i++) {
        sensorReadings[i] = rand() / (float)RAND_MAX;
        timestamps[i] = time(NULL);
        labels[i] = (char*)malloc(10 * sizeof(char));
        strcpy(labels[i], "Sensor ");
        sprintf(labels[i] + strlen("Sensor "), "%d", i);

        // Initialize the SensorData structure
        sensorData[i] = (SensorData*)malloc(sizeof(SensorData));
        sensorData[i]->reading = sensorReadings[i];
        sensorData[i]->timestamp = timestamps[i];
        sensorData[i]->label = labels[i];
    }

    return sensorData;
}

// Function to manage data buffer and query readings
void processSensors(int numSensors, SensorData** sensorData) {
    // Define the maximum number of readings per sensor
    int maxReadingsPerSensor = MAX_READINGS / numSensors;

    // Initialize the data buffer
    SensorReading_t* dataBuffer = (SensorReading_t*)malloc(maxReadingsPerSensor * sizeof(SensorReading_t));

    for (int i = 0; i < numSensors; i++) {
        // Add new readings to the data buffer
        for (int j = 0; j < maxReadingsPerSensor; j++) {
            SensorData* sensorReading = &sensorData[i][j];
            dataBuffer[j].sensorID = i;
            dataBuffer[j].timestamp = sensorReading->timestamp;
            dataBuffer[j].readingValue = sensorReading->reading;
            // Add other fields as needed
        }
    }

    // Query readings based on sensor ID, timestamp range, and value thresholds
    for (int i = 0; i < numSensors; i++) {
        for (int j = 0; j < maxReadingsPerSensor; j++) {
            if (dataBuffer[j].sensorID == i && dataBuffer[j].timestamp >= startTime && dataBuffer[j].timestamp <= endTime && dataBuffer[j].readingValue > threshold) {
                // Process the reading
            }
        }
    }

    // Release readings that are no longer needed
    for (int i = 0; i < numSensors; i++) {
        for (int j = 0; j < maxReadingsPerSensor; j++) {
            if (dataBuffer[j].timestamp <= startTime) {
                free(&sensorData[i][j]);
            }
        }
    }

    // Clean up the data buffer
    free(dataBuffer);
}

// Function to garbage collect and release readings that are no longer needed
void garbageCollectSensors(SensorData** sensorData, int numSensors) {
    for (int i = 0; i < numSensors; i++) {
        for (int j = 0; j < MAX_READINGS; j++) {
            if (sensorData[i][j] == NULL || j >= MAX_READINGS) {
                // Release the reading
                free(sensorData[i][j]);
            }
        }
    }

    // Clean up the sensor data arrays
    for (int i = 0; i < numSensors; i++) {
        free(labels[i]);
        labels[i] = NULL;
    }
    free(labels);
    free(timestamps);
    free(sensorReadings);

    // Free the array of SensorData structures
    for (int i = 0; i < numSensors; i++) {
        free(sensorData[i]);
    }
    free(sensorData);
}
