#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRC_INDICATION_REL8_TAG[16];
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_CRC_INDICATION_PDU(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 100;
        list[i].RNTI = rand() % 100;
        char* CRCFLAG = (char*)malloc(2);
        sprintf(CRCFLAG, "%02x", rand() % 256);
        strcpy(list[i].CRC_INDICATION_REL8_TAG, CRCFLAG);
    }
    return list;
}

void categorize_web_traffic(char* directory) {
    FILE* log_file;
    char file_path[1024];
    int num_requests = 0;
    int categories[64][3]; // category name, number of requests, average payload size
    int category_index = 0;

    DIR* dir;
    struct dirent* ent;
    if ((dir = opendir(directory)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            sprintf(file_path, "%s/%s", directory, ent->d_name);
            log_file = fopen(file_path, "r");
            if (log_file == NULL) continue;

            char request_method[16], timestamp[32], sequence_number[16];
            char* payload_size_str;
            char category[64];

            while(fscanf(log_file, "%s %s %s %x", request_method, timestamp, sequence_number, &payload_size) != EOF) {
                int hash = 0;
                for(int i = 0; i < 1024 && i < strlen(request_body); i++) {
                    hash += request_body[i];
                }
                char category_name[32] = "";
                sprintf(category_name, "%s_%016x_%016x", request_method, hash, sequence_number);
                if(strncmp(category_name, "malformed", 8) == 0) strcat(category_name, "_malformed");
                strcpy(category, category_name);

                categories[category_index][0] = strcmp(category, "");
                categories[category_index][1]++;
                categories[category_index][2] += payload_size;
                category_index++;
            }

            fclose(log_file);
        }
    } else perror(directory);

    FILE* metadata_file = fopen("traffic_summary.txt", "w");
    for(int i = 0; i < category_index; i++) {
        fprintf(metadata_file, "%s: %d requests, average payload size: %d bytes\n",
            categories[i][0] ? "malformed" : categories[i][0],
            categories[i][1], categories[i][2] / categories[i][1]);
    }
    fclose(metadata_file);
}

int main() {
    int n = 10;
    NFAPI_CRC_INDICATION_PDU_T* list = generate_CRC_INDICATION_PDU(n);

    // usage example
    char directory[] = "/path/to/log/files";
    categorize_web_traffic(directory);

    return 0;
}
