    public class UpdateController : ControllerBase
    {
        private readonly ILogger<UpdateController> _logger;
        private readonly IRedisService _redisService;
        private readonly ILocalizationService _localizationService;
        private readonly ILogRotationService _logRotationService;
        private readonly ICDNService _cdnService;

        public UpdateController(ILogger<UpdateController> logger, IRedisService redisService, ILocalizationService localizationService, ILogRotationService logRotationService, ICDNService cdnService)
        {
            _logger = logger;
            _redisService = redisService;
            _localizationService = localizationService;
            _logRotationService = logRotationService;
            _cdnService = cdnService;
        }

        [HttpPost]
        public async Task<ActionResult> Update([FromBody] UpdateRequest request)
        {
            if (!ValidateSessionToken(request))
                return BadRequest("Invalid session token");

            if (await _redisService.LockAsync($"update-{request.ElementId}", TimeSpan.FromSeconds(30)))
            {
                try
                {
                    string updatedContent = await UpdateElementHtml(request);
                    await _logRotationService.LogAsync(updatedContent);

                    return Ok("Page should be refreshed");
                }
                finally
                {
                    await _redisService.UnlockAsync($"update-{request.ElementId}");
                }
            }
            else
                return Conflict("Concurrent update in progress");

            // Implement custom exception handling and response generation logic for error responses
        }

        private bool ValidateSessionToken(UpdateRequest request)
        {
            // Your session token validation logic here
            return true;
        }

        private async Task<string> UpdateElementHtml(UpdateRequest request)
        {
            string updatedContent = await _localizationService.UpdateElementHtml(request, "search-string", "new-string");
            if (updatedContent.Contains("old-string"))
                updatedContent = updatedContent.Insert(updatedContent.IndexOf("old-string"), "new-string");
            return updatedContent;
        }
    }

    public class UpdateRequest
    {
        public int UserId { get; set; }
        public string SessionToken { get; set; }
        public int PageSectionId { get; set; }
        public int ElementId { get; set; }
        public string HtmlContent { get; set; }
    }
}
