typedef struct {
    uint8_t* data;
    size_t size;
} CommandPacket;

CommandPacket* command_packet_new() {
    CommandPacket* packet = (CommandPacket*)malloc(sizeof(CommandPacket));
    if (!packet) return NULL;

    packet->data = (uint8_t*)malloc(1024);
    if (!packet->data) {
        free(packet);
        return NULL;
    }
    packet->size = 0;
    return packet;
}

void command_packet_free(CommandPacket* packet) {
    if (!packet) return;
    if (packet->data) free(packet->data);
    free(packet);
}

typedef struct {
    uint16_t id;
    time_t timestamp;
    CommandPacket* data;
} NetworkPacket;

NetworkPacket* network_packet_new() {
    NetworkPacket* packet = (NetworkPacket*)malloc(sizeof(NetworkPacket));
    if (!packet) return NULL;

    packet->id = rand();
    packet->timestamp = time(NULL);
    packet->data = command_packet_new();
    return packet;
}

void network_packet_free(NetworkPacket* packet) {
    if (!packet) return;
    command_packet_free(packet->data);
    free(packet);
}

typedef struct {
    NetworkPacket** packets;
    size_t capacity;
    size_t size;
} CommandQueue;

CommandQueue* command_queue_new(size_t initial_capacity) {
    CommandQueue* queue = (CommandQueue*)malloc(sizeof(CommandQueue));
    if (!queue) return NULL;

    queue->capacity = initial_capacity;
    queue->size = 0;
    queue->packets = (NetworkPacket**)malloc(queue->capacity * sizeof(NetworkPacket*));
    for (size_t i = 0; i < queue->capacity; i++) {
        queue->packets[i] = NULL;
    }
    return queue;
}

void command_queue_free(CommandQueue* queue) {
    if (!queue) return;
    for (size_t i = 0; i < queue->size; i++) {
        network_packet_free(queue->packets[i]);
    }
    free(queue->packets);
    free(queue);
}
