using System;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Services;

namespace WebApp.Controllers
{
    [ApiController]
    [Route("api/update-html-content")]
    public class UpdateHtmlContentController : ControllerBase
    {
        private readonly ILogger _logger;
        private readonly HtmlUpdateService _htmlUpdateService;
        private readonly RedisService _redisService;

        public UpdateHtmlContentController(ILogger logger, HtmlUpdateService htmlUpdateService, RedisService redisService)
        {
            _logger = logger;
            _htmlUpdateService = htmlUpdateService;
            _redisService = redisService;
        }

        [HttpPost]
        public IActionResult UpdateHtmlContent([FromBody]UpdateHtmlContentRequest request)
        {
            try
            {
                // Validate session token
                if (!_htmlUpdateService.ValidateSessionToken(request.UserId, request.SessionToken))
                {
                    return BadRequest("Invalid session token");
                }

                // Update HTML content using service class
                _htmlUpdateService.UpdateElementHtmlContent(request.PageSectionId, request.ElementId, request.NewHtmlContent);

                // Log the update action for auditing purposes
                _logger.LogInformation($"Updated HTML content of element {request.ElementId} in page section {request.PageSectionId}");

                // Modify the HTML content by inserting a new string after the first occurrence of a specific search string within the HTML content
                var modifiedHtmlContent = InsertNewStringAfterSearch(request.NewHtmlContent, request.SearchString);

                return Ok("Page should be refreshed");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating HTML content");

                // Handle custom error responses
                if (ex is InvalidSessionTokenException)
                {
                    return Unauthorized();
                }
                else
                {
                    return StatusCode(500, "Internal Server Error");
                }
            }
        }

        private string InsertNewStringAfterSearch(string htmlContent, string searchString)
        {
            int index = htmlContent.IndexOf(searchString);
            if (index != -1)
            {
                return htmlContent.Substring(0, index) + request.NewString + htmlContent.Substring(index);
            }
            else
            {
                return htmlContent + request.NewString;
            }
        }
    }

    public class UpdateHtmlContentRequest
    {
        public int UserId { get; set; }
        public string SessionToken { get; set; }
        public int PageSectionId { get; set; }
        public int ElementId { get; set; }
        public string NewHtmlContent { get; set; }
        public string SearchString { get; set; }
    }
}
