} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* nfapi_rrc_uecontext_init(int initial_capacity) {
    NFAPI_RRC_UECONTEXT_T* ue_context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!ue_context) return NULL;

    ue_context->pdu_list = (NFAPI_UL_CCCH_pdu_t**)malloc(initial_capacity * sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!ue_context->pdu_list) {
        free(ue_context);
        return NULL;
    }
    ue_context->pdu_list_size = 0;
    ue_context->pdu_list_capacity = initial_capacity;

    return ue_context;
}

void nfapi_rrc_uecontext_free(NFAPI_RRC_UECONTEXT_T* ue_context) {
    if (!ue_context) return;

    for (int i = 0; i < ue_context->pdu_list_size; i++) {
        free(ue_context->pdu_list[i]);
    }
    free(ue_context->pdu_list);
    free(ue_context);
}

int nfapi_rrc_uecontext_validate(NFAPI_RRC_UECONTEXT_T* ue_context) {
    if (!ue_context) return -1;

    if (ue_context->pdu_list_size > ue_context->pdu_list_capacity) {
        // list is full, need to reallocate
        int new_capacity = ue_context->pdu_list_size * 2;
        NFAPI_UL_CCCH_pdu_t** new_pdu_list = (NFAPI_UL_CCCH_pdu_t**)realloc(ue_context->pdu_list, new_capacity * sizeof(NFAPI_UL_CCCH_pdu_t*));
        if (!new_pdu_list) return -1; // allocation failed
        ue_context->pdu_list = new_pdu_list;
        ue_context->pdu_list_capacity = new_capacity;
    }

    return 0;
}

void nfapi_rrc_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!ue_context || !pdu) return;

    int new_size = ue_context->pdu_list_size + 1;
    if (new_size > ue_context->pdu_list_capacity) {
        // list is full, need to reallocate
        nfapi_rrc_uecontext_validate(ue_context);
    }

    NFAPI_UL_CCCH_pdu_t** new_pdu_list = (NFAPI_UL_CCCH_pdu_t**)realloc(ue_context->pdu_list, ue_context->pdu_list_size * sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!new_pdu_list) return; // allocation failed

    ue_context->pdu_list = new_pdu_list;
    ue_context->pdu_list[ue_context->pdu_list_size] = pdu;
    ue_context->pdu_list_size = new_size;
}

void nfapi_rrc_uecontext_remove_pdu(NFAPI_RRC_UECONTEXT_T* ue_context, int index) {
    if (!ue_context || index < 0 || index >= ue_context->pdu_list_size) return;

    for (int i = index; i < ue_context->pdu_list_size - 1; i++) {
        ue_context->pdu_list[i] = ue_context->pdu_list[i + 1];
    }
    free(ue_context->pdu_list[ue_context->pdu_list_size - 1]);
    ue_context->pdu_list_size--;
}

void nfapi_rrc_uecontext_clear(NFAPI_RRC_UECONTEXT_T* ue_context) {
    if (!ue_context) return;

    for (int i = 0; i < ue_context->pdu_list_size; i++) {
        free(ue_context->pdu_list[i]);
    }
    ue_context->pdu_list_size = 0;
}
