#include <stdlib.h>
#include <stdio.h>

typedef struct {
    uint32_t UE_ID;
    RRC_STATE rrc_state;
    NFAPI_UL_CCCH_pdu_t** messages;
    size_t message_count;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* nfapi_rrc_uecontext_init(size_t capacity) {
    NFAPI_RRC_UECONTEXT_T* ue_context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!ue_context) return NULL;

    ue_context->messages = (NFAPI_UL_CCCH_pdu_t**)calloc(capacity, sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!ue_context->messages) {
        free(ue_context);
        return NULL;
    }

    ue_context->message_count = 0;

    return ue_context;
}

void nfapi_rrc_uecontext_add_message(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* message) {
    if (!ue_context || !message || ue_context->message_count >= ue_context->messages) {
        printf("Error: unable to add message. UE context is full.\n");
        return;
    }

    ue_context->messages[ue_context->message_count++] = message;
}

void nfapi_rrc_uecontext_remove_message(NFAPI_RRC_UECONTEXT_T* ue_context, size_t index) {
    if (!ue_context || index >= ue_context->message_count) {
        printf("Error: unable to remove message. Index out of bounds.\n");
        return;
    }

    free(ue_context->messages[index]);
    for (size_t i = index; i < ue_context->message_count - 1; i++) {
        ue_context->messages[i] = ue_context->messages[i + 1];
    }
    ue_context->message_count--;
}

void nfapi_rrc_uecontext_clear(NFAPI_RRC_UECONTEXT_T* ue_context) {
    if (!ue_context) return;

    for (size_t i = 0; i < ue_context->message_count; i++) {
        free(ue_context->messages[i]);
    }
    free(ue_context->messages);
    free(ue_context);
}

void nfapi_rrc_uecontext_free(NFAPI_RRC_UECONTEXT_T* ue_context) {
    if (!ue_context) return;

    for (size_t i = 0; i < ue_context->message_count; i++) {
        free(ue_context->messages[i]);
    }
    free(ue_context->messages);
    free(ue_context);
}
