    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;

void addElement(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    Node* newNode = (Node*) malloc(sizeof(Node));
    if(newNode == NULL) return; // allocation failed

    newNode->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    newNode->data.RNTI = RNTI;
    newNode->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    newNode->CRCFLAG = rand() % 2;

    if(head == NULL) {
        head = newNode;
    } else {
        Node* current = head;
        while(current->next != NULL) current = current->next;
        current->next = newNode;
    }
}

void removeElement(int index) {
    if(index < 0 || head == NULL) return; // out of bounds

    Node* current = head;
    Node* previous = NULL;

    for(int i = 0; i < index && current != NULL; i++) {
        previous = current;
        current = current->next;
    }

    if(current == NULL) return; // element not found

    if(previous == NULL) {
        head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
}

void clearList() {
    Node* current = head;
    while(current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    head = NULL;
}
