#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure NFAPI_RRC_PDU_T
typedef struct {
    int PHY_RX;
    int UE_INFO_TAG;
    int RNTI;
    int PHY_RRC_RECONFIGURATION_TAG;
    int RECONFIGFLAG;
} NFAPI_RRC_PDU_T;

// Define the structure for linked list node
typedef struct Node {
    NFAPI_RRC_PDU_T data;
    struct Node* next;
} Node;

// Function to generate random number
int rand_num(int max) {
    return (rand() % (max + 1));
}

// Function to add new element at the end of the list
void addElement(Node** headRef, NFAPI_RRC_PDU_T data) {
    Node* newElement = (Node*)malloc(sizeof(Node));
    if (*headRef == NULL || data.PHY_RX < (*headRef)->data.PHY_RX) {
        newElement->next = *headRef;
        *headRef = newElement;
    } else {
        Node* last = *headRef;
        while (last->next != NULL && last->next->data.PHY_RX >= data.PHY_RX) {
            last = last->next;
        }
        newElement->next = last->next;
        last->next = newElement;
    }
    newElement->data.PHY_RX = rand_num(1000);
    newElement->data.UE_INFO_TAG = rand_num(1000);
    newElement->data.RNTI = rand_num(1000);
    newElement->data.PHY_RRC_RECONFIGURATION_TAG = rand_num(1000);
    newElement->data.RECONFIGFLAG = rand_num(2); // 0 or 1
}

// Function to remove element at a given index
void removeElement(Node** headRef, int index) {
    if (*headRef == NULL || index < 0)
        return;

    Node* temp = *headRef;
    if (index == 0) {
        *headRef = (*headRef)->next;
        free(temp);
        return;
    }

    for (int i = 0; i < index - 1; i++) {
        temp = temp->next;
        if (temp == NULL)
            break;
    }

    if (temp != NULL && temp->next != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
}

// Function to clear the entire list
void clearList(Node** headRef) {
    Node* temp = *headRef;
    Node* prev = NULL;

    while (temp != NULL) {
        Node* next = temp->next;
        free(temp);
        temp = next;
    }
    *headRef = NULL;
}

// Function to serialize the linked list
void serializeList(Node* head, FILE* file) {
    while (head != NULL) {
        fwrite(&head->data.PHY_RX, sizeof(int), 1, file);
        fwrite(&head->data.UE_INFO_TAG, sizeof(int), 1, file);
        fwrite(&head->data.RNTI, sizeof(int), 1, file);
        fwrite(&head->data.PHY_RRC_RECONFIGURATION_TAG, sizeof(int), 1, file);
        fwrite(&head->data.RECONFIGFLAG, sizeof(int), 1, file);
        head = head->next;
    }
}

// Function to deserialize the linked list
Node* deserializeList(FILE* file) {
    Node* head = NULL;
    NFAPI_RRC_PDU_T data;

    while (fread(&data.PHY_RX, sizeof(int), 1, file) == 1 &&
           fread(&data.UE_INFO_TAG, sizeof(int), 1, file) == 1 &&
           fread(&data.RNTI, sizeof(int), 1, file) == 1 &&
           fread(&data.PHY_RRC_RECONFIGURATION_TAG, sizeof(int), 1, file) == 1 &&
           fread(&data.RECONFIGFLAG, sizeof(int), 1, file) == 1) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        newNode->data = data;
        newNode->next = head;
        head = newNode;
    }

    return head;
}

// Function to initialize the list
void initList(Node** headRef) {
    *headRef = NULL;
}

int main() {
    // Initialize the linked list and file pointer
    Node* head = NULL;
    FILE* file = fopen("output.txt", "wb");

    // Add elements to the list
    addElement(&head, data);
    addElement(&head, data);

    // Serialize the linked list
    serializeList(head, file);

    // Close the file and free memory
    fclose(file);
    clearList(&head);
    return 0;
}
