using System;
using System.Net.Http;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;

namespace YourNamespace
{
    [ApiController]
    [Route("api/[controller]")]
    public class UpdateElementController : ControllerBase
    {
        private readonly IElementService _elementService;
        private readonly ILogger<UpdateElementController> _logger;
        private readonly IRateLimiter _rateLimiter;

        public UpdateElementController(IElementService elementService, ILogger<UpdateElementController> logger, IRateLimiter rateLimiter)
        {
            _elementService = elementService;
            _logger = logger;
            _rateLimiter = rateLimiter;
        }

        [HttpPost]
        public async Task<IActionResult> UpdateElement(int userId, string sessionToken, int pageSectionId, int elementId, string htmlContent, string newContent, string searchString)
        {
            if (!_elementService.ValidateSessionToken(userId, sessionToken))
                return Forbid();

            if (!_rateLimiter.AllowRequest())
                return StatusCode(429);

            try
            {
                var updatedHtml = _elementService.UpdateElement(htmlContent, newContent, searchString);
                await _logger.LogInformationAsync($"Updated element {elementId} with HTML content: {updatedHtml}");

                // Fetch metadata from third-party API (rate-limited)
                var metadata = await _rateLimiter.LimitedApiCallAsync(() => ThirdPartyApi.GetMetadata(elementId));
                updatedHtml = _elementService.IntegrateMetadata(updatedHtml, metadata);

                return Ok("Page should be refreshed");
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error updating element");
                return StatusCode(500);
            }
        }
    }
}

