    if (!context) return NULL;

    context->VM_ID = 0;
    context->VM_STATE = 0;
    context->event_list_size = 0;
    context->event_list_capacity = 1;
    context->event_list = (struct NFVI_VM_EVENT_T**)malloc(sizeof(struct NFVI_VM_EVENT_T*) * context->event_list_capacity);

