    if (!context) return;

    for (size_t i = 0; i < context->event_list_size; i++) {
        free(context->event_list[i]);
    }

    free(context->event_list);
    free(context);
}

int vm_context_add_event(NFVI_VM_CONTEXT_T* context, NFVI_VM_EVENT_T* event) {
    if (!context || !event) return -1;

    if (context->event_list_size >= context->event_list_capacity) {
        // Reallocate and resize the event list
        context->event_list = (struct NFVI_VM_EVENT_T**)realloc(context->event_list, sizeof(struct NFVI_VM_EVENT_T*) * (context->event_list_capacity * 2));
        if (!context->event_list) return -1;

        context->event_list_capacity *= 2;
    }

    // Add the event to the list
    context->event_list[context->event_list_size] = (struct NFVI_VM_EVENT_T*)malloc(sizeof(NFVI_VM_EVENT_T));
    if (!context->event_list[context->event_list_size]) return -1;

    memcpy(context->event_list[context->event_list_size], event, sizeof(NFVI_VM_EVENT_T));

    context->event_list_size++;

    return 0;
}

int vm_context_validate_integrity(NFVI_VM_CONTEXT_T* context) {
    if (!context) return -1;

    // Validate the integrity of the event list
    for (size_t i = 0; i < context->event_list_size; i++) {
        if (!context->event_list[i]) return -1;
    }

    return 0;
}
