const express = require('express');
const app = express();
app.use(express.json());

const syncProfiles = (req, res) => {
  const { userId, profileFields, applications } = req.body;
  if (!userId || !profileFields || !applications) {
    return res.status(400).json({ status: 'failure', messages: ['Invalid request'] });
  }

  // Map of application profiles
  const appProfiles = {};

  // Iterate through all applications and update profiles accordingly
  applications.forEach((app) => {
    if (!appProfiles[app.name]) {
      appProfiles[app.name] = {};
    }
    profileFields.forEach((field) => {
      if (app.profiles[field]) {
        appProfiles[app.name][field] = app.profiles[field];
      }
    });
  });

  // Iterate through all profiles and update the specified fields
  Object.keys(appProfiles).forEach((appName) => {
    appProfiles[appName].forEach((profile, profileId) => {
      applications.forEach((app) => {
        if (app.name === appName && app.profiles[profileId]) {
          const updatedProfile = {};
          profileFields.forEach((field) => {
            if (app.profiles[profileId][field]) {
              updatedProfile[field] = app.profiles[profileId][field];
            }
          });
          app.profiles[profileId] = { ...app.profiles[profileId], ...updatedProfile };
        }
      });
    });
  });

  // Return the response
  res.json({ status: 'success', messages: [] });
};

app.post('/syncProfiles', syncProfiles);

const logger = (req, res) => {
  const { userId, profileFields, applications } = req.body;
  console.log(`Synced profiles for user ${userId} with fields ${profileFields} and applications ${applications}`);
};

app.use((req, res, next) => {
  logger(req, res);
  next();
});

const port = process.env.PORT || 3000;

app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
