typedef struct {
    int id;
    time_t timestamp;
    double metricValue;
    char unit[4];
    int status;
} Event_t;

void initEventLog(Event_t** eventLogs, int numLogs) {
    int i;

    for(i = 0; i < numLogs; i++) {
        (*eventLogs)[i].id = i;
        (*eventLogs)[i].timestamp = time(NULL);
        (*eventLogs)[i].metricValue = (double)(rand() % 100);
        sprintf((*eventLogs)[i].unit, "%c", 'M');
        (*eventLogs)[i].status = rand() % 2;
    }
}

void printEventLog(Event_t* eventLogs, int numLogs) {
    int i;

    for(i = 0; i < numLogs; i++) {
        printf("Event ID: %d\n", eventLogs[i].id);
        printf("Timestamp: %ld\n", eventLogs[i].timestamp);
