public class UpdateElementContentController : ApiController
{
    private readonly IUpdateService _updateService;
    private readonly IRateLimitingService _rateLimitingService;
    private readonly ICacheService _cacheService;
    private readonly IHttpClientFactory _httpClientFactory;

    public UpdateElementContentController(IUpdateService updateService, IRateLimitingService rateLimitingService, ICacheService cacheService, IHttpClientFactory httpClientFactory)
    {
        _updateService = updateService;
        _rateLimitingService = rateLimitingService;
        _cacheService = cacheService;
        _httpClientFactory = httpClientFactory;
    }

    [HttpPost]
    public IHttpActionResult UpdateElementContent([FromBody]UpdateElementContentRequest request)
    {
        if (!_rateLimitingService.HasAvailableTier())
            return BadRequest("Rate limit exceeded");

        if (!_validateSessionToken(request.SessionToken))
            return Unauthorized();

        string elementMetadata = _cacheService.GetCachedElementMetadata(request.ElementId);
        if (elementMetadata == null)
        {
            elementMetadata = _fetchMetadataFromThirdPartyApi(request.ElementId).Result;
            _cacheService.StoreInCache(elementMetadata, request.ElementId);
        }

        string updatedHtmlContent = UpdateHtmlContent(request.HtmlContent, request.NewString, request.SearchString);
        _updateService.UpdateElementHtmlContent(request.PageSectionId, request.ElementId, updatedHtmlContent);

        // Log update action for auditing purposes
        _logUpdateAction(request.User.Id, request.ElementId, updatedHtmlContent);

        return Ok("Page should be refreshed");
    }

    private bool _validateSessionToken(string sessionToken)
    {
        // Implement your custom validation logic here
        // For demonstration purposes, assume a simple token validation
        return sessionToken != null && sessionToken.StartsWith("VALID_TOKEN_");
    }

    private async Task<string> _fetchMetadataFromThirdPartyApi(int elementId)
    {
        // Implement your custom API call logic here
        // For demonstration purposes, assume a simple API fetch
        using (var client = _httpClientFactory.CreateClient())
        {
            var response = await client.GetAsync($"https://api.example.com/elements/{elementId}");
            response.EnsureSuccessStatusCode();
            return await response.Content.ReadAsStringAsync();
        }
    }

    private string UpdateHtmlContent(string htmlContent, string newString, string searchString)
    {
        // Implement your custom HTML content manipulation logic here
        // For demonstration purposes, assume a simple string manipulation
        int index = htmlContent.IndexOf(searchString);
        if (index != -1)
            return htmlContent.Substring(0, index) + newString + htmlContent.Substring(index);
        else
            return htmlContent + newString;
    }

    private void _logUpdateAction(int userId, int elementId, string updatedHtmlContent)
    {
        // Implement your custom logging logic here
        // For demonstration purposes, assume a simple log statement
        Console.WriteLine($"Updated HTML content for element {elementId} by user {userId}: {updatedHtmlContent}");
    }
}

public class UpdateElementContentRequest
{
    public int UserId { get; set; }
    public string SessionToken { get; set; }
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
    public string HtmlContent { get; set; }
    public string NewString { get; set; }
    public string SearchString { get; set; }
