    *ptr = NULL;
}

int validate(LTE_UESessionContext_t* session) {
    if (!session->ue_id || !session->ue_id[0])
        return -1;

    LTE_UL_CCCH_pdu_t* pdu = session->pdu_list;
    while (pdu) {
        if (!pdu->data)
            return -2;
        pdu = pdu->next;
    }
    return 0;
}

void add_pdu(LTE_UESessionContext_t** sessions, size_t* num_sessions, LTE_UL_CCCH_pdu_t* new_pdu) {
    if (*num_sessions == 0) {
        *num_sessions = 1;
        *sessions = allocate(sizeof(LTE_UESessionContext_t));
    } else {
        LTE_UESessionContext_t* temp = *sessions;
        *sessions = allocate((size_t)sizeof(LTE_UESessionContext_t) + (size_t)*num_sessions * sizeof(LTE_UL_CCCH_pdu_t));
        memcpy(*sessions, temp, (size_t)*num_sessions * sizeof(LTE_UESessionContext_t));
        free(temp);
    }
}

void remove_pdu(LTE_UESessionContext_t** sessions, size_t* num_sessions) {
    if (*num_sessions > 0) {
        free(sessions[0]->pdu_list);
        sessions[0]->pdu_list = NULL;
        *num_sessions -= 1;
    }
}

void print_performance() {
    printf("Memory usage: %f%%\n", (double)sprintf);
}
