// Function to initialize a new VM context
NFVI_VM_CONTEXT_T* nfvi_vm_context_new() {
    NFVI_VM_CONTEXT_T* vm_ctx = (NFVI_VM_CONTEXT_T*)malloc(sizeof(NFVI_VM_CONTEXT_T));
    vm_ctx->vm_id = 0;
    vm_ctx->vm_state = 0;
    vm_ctx->events = NULL;
    pthread_mutex_init(&vm_ctx->mutex, NULL);
    return vm_ctx;
}

// Function to add a new event to the VM context
void nfvi_vm_context_add_event(NFVI_VM_CONTEXT_T* vm_ctx, NFVI_VM_EVENT_T* event) {
    if (event == NULL) {
        printf("Error: Adding null event\n");
        return;
    }

    pthread_mutex_lock(&vm_ctx->mutex);

    // Dynamically allocate memory for the new event
    int* new_event = (int*)malloc(sizeof(int));
    *new_event = event->event_type;

    if (vm_ctx->events == NULL) {
        vm_ctx->events = (struct NFVI_VM_EVENT_T**)malloc(sizeof(struct NFVI_VM_EVENT_T*));
        vm_ctx->events[0] = new_event;
    } else {
        // Dynamically allocate memory for the new event list
        int* new_events = (int*)malloc((vm_ctx->events != NULL ? strlen(vm_ctx->events) : 0) + sizeof(struct NFVI_VM_EVENT_T));
        for (int i = 0; i < vm_ctx->events && i < (vm_ctx->events[0] - 1); i++) {
            new_events[i] = event[i];
        }
        free(vm_ctx->events);
        vm_ctx->events = &new_events;
    }

    pthread_mutex_unlock(&vm_ctx->mutex);
}

// Function to verify the integrity of the VM context
void nfvi_vm_context_verify(NFVI_VM_CONTEXT_T* vm_ctx) {
    if (vm_ctx == NULL || vm_ctx->events == NULL) {
        printf("Error: Invalid VM context\n");
        return;
    }

    pthread_mutex_lock(&vm_ctx->mutex);
    for (int i = 0; i < vm_ctx->events && i < (vm_ctx->events[0] - 1); i++) {
        if (vm_ctx->events[i] == NULL) {
            printf("Error: Corrupted event list at index %d\n", i);
        }
    }

    pthread_mutex_unlock(&vm_ctx->mutex);
}

// Function to free the VM context
void nfvi_vm_context_free(NFVI_VM_CONTEXT_T* vm_ctx) {
    if (vm_ctx == NULL || vm_ctx->events == NULL) {
        return;
    }

    pthread_mutex_lock(&vm_ctx->mutex);

    // Free each event in the list
    for (int i = 0; i < vm_ctx->events && i < (vm_ctx->events[0] - 1); i++) {
        free(vm_ctx->events[i]);
    }
    free(vm_ctx->events);

    pthread_mutex_unlock(&vm_ctx->mutex);
}

