NFAPI_RRC_UECONTEXT_T** ue_contexts;
size_t ue_contexts_count = 0;

// Function to initialize and manage the dynamic array of UE contexts
void nfaPI_rrc_uecontext_init(size_t max_capacity) {
    // Initialize the array with a default size
    ue_contexts = (NFAPI_RRC_UECONTEXT_T**)malloc(sizeof(NFAPI_RRC_UECONTEXT_T*) * 10);
    for (size_t i = 0; i < 10; i++) {
        ue_contexts[i] = NULL;
    }

    // Set the max capacity
    ue_contexts_count = 10;

    // Initialize a lock for concurrent access
    pthread_mutex_init(&ue_context_lock, NULL);
}

// Function to add a new UE context
void nfaPI_rrc_uecontext_add(NFAPI_RRC_UECONTEXT_T* ue_ctx) {
    // Validate the integrity of the PDU list before adding
    if (ue_ctx->pdus_count > 0) {
        for (size_t i = 0; i < ue_ctx->pdus_count; i++) {
            if (!ue_ctx->pdus[i]) {
                // Find an empty slot to insert new PDUs
                size_t j;
                for (j = 0; j < ue_contexts_count; j++) {
                    if (!ue_contexts[j]) {
                        break;
                    }
                }

                // Move existing UE contexts to the front of the array
                memmove(ue_contexts, &ue_contexts[j], sizeof(NFAPI_RRC_UECONTEXT_T*) * (j - 1));
                ue_contexts_count -= j;

                // Insert the new UE context at the end of the array
                ue_contexts[j] = ue_ctx;
                ue_contexts_count++;

                // Update the PDUs count for the new UE context
                ue_ctx->pdus_count++;
                break;
            }
        }
    }

    log_ue_context_operation(ue_ctx, "Added");
}

// Function to remove a UE context
void nfaPI_rrc_uecontext_remove(NFAPI_RRC_UECONTEXT_T* ue_ctx) {
    size_t i;
    for (i = 0; i < ue_contexts_count; i++) {
        if (ue_contexts[i] == ue_ctx) {
            break;
        }
    }

    // Remove the UE context from the array
    memmove(ue_contexts, &ue_contexts[i + 1], sizeof(NFAPI_RRC_UECONTEXT_T*) * (ue_contexts_count - i - 1));
    ue_contexts_count--;

    log_ue_context_operation(ue_ctx, "Removed");
}

// Function to periodically compact the UE context array
void nfaPI_rrc_uecontext_compact() {
    // Find the first non-empty slot in the array
    size_t i;
    for (i = 0; i < ue_contexts_count; i++) {
        if (ue_contexts[i]) {
            break;
        }
    }

    // Compact the array by moving the UE contexts to the front of the array
    memmove(ue_contexts, &ue_contexts[i], sizeof(NFAPI_RRC_UECONTEXT_T*) * (ue_contexts_count - i));
    ue_contexts_count -= i;

    log_ue_context_operation(NULL, "Compacted");
}

// Logging function implementation
void log_ue_context_operation(NFAPI_RRC_UECONTEXT_T* ue_ctx, char* operation) {
    // Implement logging system here
    printf("UE context %u %s\n", ue_ctx->ue_id, operation);
}
