    int id;
    NFAPI_RRC_UECONTEXT_STATE_T state;
    sqlite3_stmt* statement;
    NFAPI_UL_CCCH_pdu_node_t* pdus;
    int pdu_count;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* create_ue_context(int id, NFAPI_RRC_UECONTEXT_STATE_T state) {
    NFAPI_RRC_UECONTEXT_T* ue_context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    ue_context->id = id;
    ue_context->state = state;
    ue_context->pdu_count = 0;
    return ue_context;
}

int add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_PDU_NODE_T* pdu) {
    // Allocate memory for the new PDU node
    NFAPI_UL_CCCH_PDU_NODE_T* new_pdu = (NFAPI_UL_CCCH_PDU_NODE_T*)malloc(sizeof(NFAPI_UL_CCCH_PDU_NODE_T));
    *new_pdu = *pdu;

    // Add the new PDU to the linked list and update the count
    NFAPI_UL_CCCH_PDU_NODE_T** pdus = &ue_context->pdus;
    (*pdus) = realloc(*pdus, (ue_context->pdu_count + 1) * sizeof(NFAPI_UL_CCCH_PDU_NODE_T));
    (*pdus)[ue_context->pdu_count++] = new_pdu;

    return 0;
}

int main() {
    // Initialize the SQLite database
    sqlite3* db;
    int rc = sqlite3_open("database.db", &db);
    if (rc != SQLITE_OK) {
        printf("Failed to open the database: %s\n", sqlite3_errmsg(db));
        return -1;
    }

    // Create a UE context with ID 1 and state CONNECTED
    NFAPI_RRC_UECONTEXT_T* ue_context = create_ue_context(1, CONNECTED);

