    NFAPI_UL_CCCH_PDU_NODE_T pdu2;
    pdu2.id = 67890;
    pdu2.precision_score = 0.95f;

    add_pdu_to_ue_context(ue_context, &pdu1);
    add_pdu_to_ue_context(ue_context, &pdu2);

    // Serialize the UE context to a JSON file
    json_object* ue_context_json = json_object_new_object();
    json_object_object_add(ue_context_json, "id", json_object_new_int(ue_context->id));
    json_object_object_add(ue_context_json, "state", json_object_new_string(ue_context->state == IDLE ? "IDLE" : "CONNECTED"));
    for (int i = 0; i < ue_context->pdu_count; i++) {
        NFAPI_UL_CCCH_PDU_NODE_T* pdu = ue_context->pdus[i];
