        json_object_object_add(pdu_json, "id", json_object_new_int(pdu->id));
        json_object_object_add(pdu_json, "precision_score", json_object_new_double(pdu->precision_score));
        json_object_object_add(ue_context_json, "pdus", json_object_object_add(ue_context_json, "pdu", pdu_json));
    }

    FILE* file = fopen("ue_context.json", "w");
