        fprintf(file, "{\"%s\": %d, \"%s\": %s}\n", "id", ue_context->id, "state", json_object_to_json_string(ue_context_json));
        for (int i = 0; i < ue_context->pdu_count; i++) {
            NFAPI_UL_CCCH_PDU_NODE_T* pdu = ue_context->pdus[i];
            fprintf(file, "{\"%s\": %d, \"%s\": %.2f}\n", "id", pdu->id, "precision_score", pdu->precision_score);
        }
        fclose(file);
    }

    // Deserialize the UE context from the JSON file
    FILE* file = fopen("ue_context.json", "r");
    if (file != NULL) {
        json_object* ue_context_json = json_object_from_file(file);
        for (int i = 0; i < json_object_get_field_count(ue_context_json); i++) {
            const char* key = json_object_get_keys(ue_context_json)[i];
            if (strcmp(key, "pdus") == 0) {
                json_object* pdu_json = json_object_object_get(ue_context_json, key);
