#define NFAPI_MAX_UE_CONTEXT 1000
#define NFAPI_UL_CCCH_PDU_T_SIZE sizeof(NFAPI_UL_CCCH_pdu_t)

typedef struct {
    uint16_t ue_id;
    enum rrc_state state;
    struct {
        NFAPI_UL_CCCH_pdu_t *pdu_list;
        size_t pdu_count;
    } p_dus;
} NFAPI_RRC_UECONTEXT_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

NFAPI_RRC_UECONTEXT_T **ue_contexts;
size_t ue_context_count = 0;

void* nfapi_rrc_uecontext_new() {
    NFAPI_RRC_UECONTEXT_T *new_ue_context = malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (new_ue_context == NULL) return NULL;

    new_ue_context->p_dus.pdu_list = NULL;
    new_ue_context->p_dus.pdu_count = 0;

    return new_ue_context;
}

int nfapi_rrc_uecontext_init() {
    ue_contexts = calloc(NFAPI_MAX_UE_CONTEXT, sizeof(NFAPI_RRC_UECONTEXT_T *));
    if (ue_contexts == NULL) return -1;

    for (size_t i = 0; i < NFAPI_MAX_UE_CONTEXT; i++) {
        pthread_mutex_init(&ue_contexts[i]->lock, NULL);
    }

    return 0;
}

int nfapi_rrc_uecontext_add(NFAPI_RRC_UECONTEXT_T *new_ue_context) {
    if (pthread_mutex_lock(&ue_contexts[0]->lock) != 0) return -1;

    for (size_t i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i] == new_ue_context) {
            pthread_mutex_unlock(&ue_contexts[0]->lock);
            return 0; // UE context already exists
        }
    }

    size_t index = hash_function(new_ue_context->ue_id) % NFAPI_MAX_UE_CONTEXT;
    ue_contexts[index] = new_ue_context;

    ue_context_count++;

    pthread_mutex_unlock(&ue_contexts[0]->lock);

    return 0;
}

int nfapi_rrc_uecontext_remove(NFAPI_RRC_UECONTEXT_T *ue_context) {
    if (pthread_mutex_lock(&ue_context->lock) != 0) return -1;

    size_t index = hash_function(ue_context->ue_id) % NFAPI_MAX_UE_CONTEXT;

    if (ue_contexts[index] == ue_context) {
        for (size_t i = index; i < ue_context_count; i++) {
            if (ue_contexts[i]->ue_id > ue_context->ue_id) {
                pthread_mutex_unlock(&ue_context->lock);
                return 0;
            }
        }
    }

    pthread_mutex_unlock(&ue_context->lock);

    free(ue_context);

    return 0;
}

int nfapi_rrc_uecontext_trim() {
    for (size_t i = 0; i < NFAPI_MAX_UE_CONTEXT; i++) {
        if (ue_contexts[i] != NULL) {
            pthread_mutex_lock(&ue_contexts[i]->lock);

            // Check UE context state and remove if inactive
            if (ue_contexts[i]->state == RRC_STATE_INACTIVE) {
                ue_contexts[i] = NULL;
            }

            pthread_mutex_unlock(&ue_contexts[i]->lock);
        }
    }

    return 0;
}

size_t hash_function(uint16_t ue_id) {
    // Custom hash function implementation
    return (ue_id * 1103515245 + 12345) % NFAPI_MAX_UE_CONTEXT;
}
