    int max_ue_contexts = atoi(getenv("MAX_UE_CONTEXTS"));
    int trim_period = atoi(getenv("TRIM_PERIOD"));

    // Initialize the device structure
    struct nfa_device* dev = (struct nfa_device*)malloc(sizeof(struct nfa_device));
    dev->ue_context_count = 0;
    pthread_mutex_init(&dev->lock, NULL);
    INIT_LIST_HEAD(&dev->ue_contexts);

    // Read settings from file and validate
    FILE* f = fopen(settings_file, "r");
    if (f == NULL) {
        printf("Failed to open settings file\n");
        exit(1);
    }

    // ... validation logic ...

    fclose(f);

    return dev;
}

// Serialize the entire structure of NFAPI_RRC_UECONTEXT_T
void nfa_device_serialize(struct nfa_device* dev, char* buffer) {
    int len = 0;

    // Write device metadata to buffer
    len += sprintf(buffer + len, "%d", dev->ue_context_count);

    // Serialize each UE context
    struct list_head* ue_ctx_iter = &dev->ue_contexts;
    while (ue_ctx_iter != NULL) {
        NFAPI_RRC_UECONTEXT_T* ue_ctx = list_entry(ue_ctx_iter, typeof(*ue_ctx_iter), pdu_list);
        len += sprintf(buffer + len, "%u:%d:", ue_ctx->ue_id, ue_ctx->state);

        // Serialize each PDU
        struct list_head* pdu_iter = &ue_ctx->pdu_list;
        while (pdu_iter != NULL) {
            NFAPI_UL_CCCH_pdu_t* pdu = list_entry(pdu_iter, typeof(*pdu_iter), link);
            len += sprintf(buffer + len, "%hu:", pdu->length);

            // Serialize PDU data
            memcpy(buffer + len, pdu->data, pdu->length);
            len += pdu->length;
            pdu_iter = pdu_iter->next;
        }
        ue_ctx_iter = ue_ctx_iter->next;
    }

    return;
}

// Deserialize the entire structure of NFAPI_RRC_UECONTEXT_T
int nfa_device_deserialize(struct nfa_device** dev, char* buffer) {
    // Read device metadata from buffer
    int ue_context_count;
    sscanf(buffer, "%d", &ue_context_count);

    *dev = (struct nfa_device*)malloc(sizeof(struct nfa_device));
    (*dev)->ue_context_count = ue_context_count;
    pthread_mutex_init(&(*dev)->lock, NULL);
    INIT_LIST_HEAD(&(*dev)->ue_contexts);

    // Deserialize each UE context
    char* p = buffer + strlen(buffer) - 1;
    while (p > buffer && *p == ':') {
        NFAPI_RRC_UECONTEXT_T* ue_ctx = rrc_ue_ctx_init(MAX_UE_CONTEXTS);
        // ... deserialization logic ...

        // Deserialize each PDU
        struct list_head* pdu_iter = &ue_ctx->pdu_list;
        while (p > buffer && *p == ':') {
            NFAPI_UL_CCCH_pdu_t* pdu;
            int length;
            sscanf(p, "%hu:", &length);
            pdu = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
            pdu->length = length;
            // Deserialize PDU data
            memcpy(pdu->data, p + 2, length);
            p += length;
            list_add(&pdu->link, &ue_ctx->pdu_list);

            pdu_iter = pdu_iter->next;
        }

        list_add(&ue_ctx->link, &((*dev)->ue_contexts));
    }

    return 0;
}

void rrc_ue_ctx_trim() {
    // ... trimming logic ...
}

NFAPI_RRC_UECONTEXT_T* find_ue_context_by_id(NFAPI_RRC_UECONTEXT_T* ue_ctxs, uint32_t id) {
    struct list_head* ue_ctx_iter = &ue_ctxs;
    while (ue_ctx_iter != NULL) {
        NFAPI_RRC_UECONTEXT_T* ue_ctx = list_entry(ue_ctx_iter, typeof(*ue_ctx_iter), link);
        if (ue_ctx->ue_id == id) {
            return ue_ctx;
        }
        ue_ctx_iter = ue_ctx_iter->next;
    }
    return NULL;
}

