        with open(self.kickstart_file_path, 'r') as file:
            content = file.read()

        placeholders = re.findall(r'\$\{\w+\}', content)

        for placeholder in placeholders:
            value = input_dict.get(placeholder[2:-1], '')
            encrypted_value = self.encrypt_value(value, algorithm)
            content = content.replace(f'${{{placeholder}}}', encrypted_value)

        new_content = f'{content}\n{self.encrypt_password(input_dict["password"], algorithm)}'

        with open(self.kickstart_file_path, 'w') as file:
            file.write(new_content)

