    parser.add_argument('-k', '--kickstart-file-path', type=str, required=True)
    parser.add_argument('-a', '--algorithm', type=str, default='aes-256-cbc')
    args = parser.parse_args()

    encryptor = KickstartEncryptor(args.kickstart_file_path)

    try:
        with ThreadPoolExecutor() as executor:
            executor.submit(encryptor.encrypt, {'password': 'my_secret_password'}, args.algorithm)
    except Exception as e:
        print(f"Error: {e}")

if __name__ == '__main__':
    main()
