#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int id;
    enum {IDLE, ESTABLISHED, CLOSED} state;
    struct {
        void* data;
        size_t size;
    }**headers;
    size_t header_count;
    pthread_mutex_t mutex;
} connection_ctx;

void connection_ctx_init(connection_ctx* ctx) {
    ctx->state = IDLE;
    ctx->header_count = 0;
    pthread_mutex_init(&ctx->mutex, NULL);
}

void connection_ctx_free(connection_ctx* ctx) {
    for(size_t i = 0; i < ctx->header_count; ++i) {
        free(ctx->headers[i]->data);
        free(ctx->headers[i]);
    }
    free(ctx->headers);
    pthread_mutex_destroy(&ctx->mutex);
}

int connection_ctx_add_header(connection_ctx* ctx, void* data, size_t size) {
    if(ctx->state != ESTABLISHED) return -1;
    if(size > 0) {
        ctx->headers = realloc(ctx->headers, (ctx->header_count + 1) * sizeof(*ctx->headers));
        ctx->headers[ctx->header_count] = malloc(sizeof(**ctx->headers));
        ctx->headers[ctx->header_count]->data = data;
        ctx->headers[ctx->header_count]->size = size;
        ++ctx->header_count;
    }
    return 0;
}

int connection_ctx_validate_headers(connection_ctx* ctx) {
    for(size_t i = 0; i < ctx->header_count; ++i) {
        if(!ctx->headers[i]->data || !ctx->headers[i]->size > 0) return -1;
    }
    return 0;
}
