int main() {
    FILE *fp = fopen("input.txt", "r");
    if (fp == NULL) {
        printf("Error opening file\n");
        return -1;
    }

    char line[1024];
    int line_num = 0;

    while (fgets(line, sizeof(line), fp)) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * strlen(line));
        char *token = strtok(line, ",");
        for (int i = 0; i < strlen(line); i++) {
            pdu[i].RX_UE_INFORMATION_TAG = atoi(token);
            token = strtok(NULL, ",");
            pdu[i].RNTI = atoi(token);
            token = strtok(NULL, ",");
            srand(time(NULL));
            pdu[i].CRCFLAG = rand() % 100;
        }

        printf("%s", line);

        int sum = 0;
        for (int i = 0; i < strlen(line); i++) {
            sum += pdu[i].RX_UE_INFORMATION_TAG + pdu[i].RNTI;
        }
        printf(",%.2f", (double)sum / strlen(line));

        free(pdu);

        line_num++;
    }

    fclose(fp);
    return 0;
}
