public class FileProcessor {

    private static final int CHUNK_SIZE = 1024 * 1024; // 1MB
    private static final int MAX_CONCURRENT_INSTANCES = 50;
    private static final int MAX_MEMORY_PER_INSTANCE = 256; // MB

    public void start(File directory, String configPath) throws Exception {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_INSTANCES);
        ScheduledExecutorService scheduledExecutor = Executors.newScheduledThreadPool(1);

        Config config = new Config(configPath);

        ScheduledFuture<?> healthCheck = scheduledExecutor.scheduleAtFixedRate(() -> {
            System.out.println("Health Check: Memory usage " + Runtime.getRuntime().freeMemory() / (1024 * 1024) + "MB");
        }, 0, config.getHealthCheckInterval(), TimeUnit.MINUTES);

        executor.submit(() -> {
            try {
                monitorDirectory(directory);
            } catch (Exception e) {
                System.out.println("Error monitoring directory: " + e.getMessage());
            }
        });

        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            healthCheck.cancel(true);
            executor.shutdown();
            scheduledExecutor.shutdown();
        }));
    }

    private void monitorDirectory(File directory) throws Exception {
        Files.walk(directory.toPath()).forEach(path -> {
            Path filePath = path.getFileName();
            if (Files.isRegularFile(filePath)) {
                try {
                    processFile(filePath);
                } catch (Exception e) {
                    System.out.println("Error processing file: " + filePath + ", message: " + e.getMessage());
                }
            }
        });
    }

    private void processFile(Path filePath) throws Exception {
        try (BufferedInputStream in = new BufferedInputStream(Files.newInputStream(filePath))) {
            ByteArrayOutputStream compressedData = new ByteArrayOutputStream();
            ByteArrayInputStream originalDataStream = new ByteArrayInputStream(IOUtils.toByteArray(in));
            int chunkSize = CHUNK_SIZE;
            byte[] buffer = new byte[chunkSize];

            while ((originalDataStream.available() > 0) || (compressedData.size() < chunkSize)) {
                int bytesRead = originalDataStream.read(buffer, 0, Math.min(originalDataStream.available(), buffer.length));
                if (bytesRead == -1) break;

                compressedData.write(compress(originalDataStream));
                originalDataStream.skip(bytesRead);
            }

            byte[] encryptedData = encrypt(compressedData.toByteArray());

            // store result in distributed database
        } catch (IOException e) {
            System.out.println("Error processing file: " + filePath + ", message: " + e.getMessage());
        }
    }

    private byte[] compress(ByteArrayInputStream originalDataStream) throws ArchiveException {
        // implement compression logic here
    }

    private byte[] encrypt(byte[] data) {
        // implement encryption logic here
    }
}

