    ue_id_to_uecontext_map = std::unordered_map<uint32_t, NFAPI_RRC_UECONTEXT_T*>(16);

    // Initialize the dynamic array of NFAPI_RRC_UECONTEXT_T structures
    int num_ue_contexts = 0;
    NFAPI_RRC_UECONTEXT_T** ue_context_array = (NFAPI_RRC_UECONTEXT_T**)malloc(sizeof(NFAPI_RRC_UECONTEXT_T*) * max_ue_contexts);
    for (int i = 0; i < max_ue_contexts; i++) {
        ue_context_array[i] = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
        ue_context_array[i]->pdu_list = (struct { size_t size; void* data; }*)aligned_malloc(16, sizeof(struct { size_t size; void* data; }));
    }

    // Initialize the UE_ID to NFAPI_RRC_UECONTEXT_T mapping
    pthread_mutex_init(&ue_id_to_uecontext_map_mutex, NULL);
    for (int i = 0; i < max_ue_contexts; i++) {
        ue_id_to_uecontext_map.insert({i, ue_context_array[i]});
    }

    // Initialize the external logging and monitoring systems
    extern void log_ue_context_activity();
    extern void monitor_pdu_traffic();

    return NULL;
}

// Function to add a new PDU to the list of NFAPI_RRC_UECONTEXT_T structures
void nfaapi_rrc_uecontext_add_pdu(uint32_t ue_id, size_t pdu_size, uint8_t* pdu_data) {
    // Lock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_lock(&ue_id_to_uecontext_map_mutex);

    // Get the corresponding NFAPI_RRC_UECONTEXT_T structure from the map
    NFAPI_RRC_UECONTEXT_T* ue_context = ue_id_to_uecontext_map[ue_id];

    // Allocate memory for the new PDU
    void* new_pdu_data = aligned_malloc(pdu_size, 16);
    memcpy(new_pdu_data, pdu_data, pdu_size);

    // Add the new PDU to the list of NFAPI_RRC_UECONTEXT_T structures
    ue_context->pdu_list[ue_context->size++] = (struct { size_t size; void* data; }){pdu_size, new_pdu_data};

    // Unlock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_unlock(&ue_id_to_uecontext_map_mutex);

    // Log and monitor PDU addition activity
    log_ue_context_activity();
    monitor_pdu_traffic();
}

// Function to validate the integrity of the PDU list before any operations are performed
void nfaapi_rrc_uecontext_validate_pdu_list() {
    // Lock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_lock(&ue_id_to_uecontext_map_mutex);

    // Iterate through each NFAPI_RRC_UECONTEXT_T structure in the map
    for (auto& ue_context : ue_id_to_uecontext_map) {
        // Validate the integrity of the PDU list for each UE context
        for (int i = 0; i < ue_context.second->size; i++) {
            if (ue_context.second->pdu_list[i].data == NULL) {
                // Handle invalid PDUs and trim the dynamic array as needed
                aligned_free(ue_context.second->pdu_list[i].data);
                ue_context.second->size--;
            }
        }
    }

    // Unlock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_unlock(&ue_id_to_uecontext_map_mutex);

    // Log and monitor PDU validation activity
    log_ue_context_activity();
}

// Function to periodically trim the dynamic array of NFAPI_RRC_UECONTEXT_T structures
void nfapi_rrc_uecontext_trim() {
    // Lock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_lock(&ue_id_to_uecontext_map_mutex);

    // Iterate through each NFAPI_RRC_UECONTEXT_T structure in the map
    for (auto& ue_context : ue_id_to_uecontext_map) {
        // Trim inactive UE contexts from the dynamic array
        if (ue_context.second->size == 0) {
            free(ue_context.second);
            ue_id_to_uecontext_map.erase(ue_context.first);
        }
    }

    // Unlock the UE_ID to NFAPI_RRC_UECONTEXT_T mapping for thread safety
    pthread_mutex_unlock(&ue_id_to_uecontext_map_mutex);

    // Log and monitor trimming activity
    log_ue_context_activity();
}

// Function to serialize the entire structure of NFAPI_RRC_UECONTEXT_T
void nfaapi_rrc_uecontext_serialize() {
    // Serialize each NFAPI_RRC_UECONTEXT_T structure in the map
    for (auto& ue_context : ue_id_to_uecontext_map) {
        // Serialize the UE_ID and RRC_STATE
        uint8_t serialized_data[16];
        memcpy(serialized_data, &ue_context.second->ue_id, 4);
        memcpy(serialized_data + 4, &ue_context.second->rrc_state, 4);

        // Serialize each PDU in the list
        for (int i = 0; i < ue_context.second->size; i++) {
            size_t pdu_size = ue_context.second->pdu_list[i].size;
            uint8_t* pdu_data = ue_context.second->pdu_list[i].data;

            // Serialize PDU size and data
            memcpy(serialized_data + 8, &pdu_size, 4);
            memcpy(serialized_data + 12, pdu_data, pdu_size);

            aligned_free(pdu_data);
        }
    }

    // Log serialization activity
    log_ue_context_activity();
}

// Function to deserialize the entire structure of NFAPI_RRC_UECONTEXT_T
void nfaapi_rrc_uecontext_deserialize() {
    // Deserialize each NFAPI_RRC_UECONTEXT_T structure in the map
    for (auto& ue_context : ue_id_to_uecontext_map) {
        // Deserialize UE_ID and RRC_STATE
        uint32_t deserialized_ue_id;
        int deserialized_rrc_state;
        memcpy(&deserialized_ue_id, serialized_data + 0, 4);
        memcpy(&deserialized_rrc_state, serialized_data + 4, 4);

        // Deserialize each PDU in the list
        for (int i = 0; i < ue_context.second->size; i++) {
            size_t pdu_size;
            uint8_t* pdu_data;

            // Deserialize PDU size and data
            memcpy(&pdu_size, serialized_data + 8, 4);
            pdu_data = aligned_malloc(pdu_size, 16);

            memcpy(pdu_data, serialized_data + 12, pdu_size);

            ue_context.second->pdu_list[i].size = pdu_size;
            ue_context.second->pdu_list[i].data = pdu_data;

            aligned_free(pdu_data);
        }
    }

    // Log deserialization activity
    log_ue_context_activity();
}
