    *ue_contexts = (NFAPI_RRC_UECONTEXT_T*)malloc(initial_capacity * sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!*ue_contexts) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }
    (*ue_contexts)[0].pdu_list_size = 1;
    (*ue_contexts)[0].allocated_pdu_list_size = sizeof(struct {
        void* pdu_data;
        size_t pdu_len;
