    void* pdu_data;
    size_t pdu_len;
} new_pdu) {
    if (ue_context->pdu_list_size == ue_context->allocated_pdu_list_size) {
        ue_context->allocated_pdu_list_size *= 2;
        ue_context->pdu_list = realloc(ue_context->pdu_list,
            ue_context->allocated_pdu_list_size * sizeof(struct {
                void* pdu_data;
                size_t pdu_len;
            }*));
    }
