#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMS 10000
#define VERSION_1 0x01
#define VERSION_2 0x02

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int countMatchingStructures(NFAPI_CRC_INDICATION_PDU_T **array, int rntiStart, int rntiEnd) {
    int count = 0;
    for (int i = 0; i < MAX_ELEMS; i++) {
        pthread_mutex_lock(&mutex);
        if (array[i]->RNTI >= rntiStart && array[i]->RNTI <= rntiEnd) {
            count++;
        }
        pthread_mutex_unlock(&mutex);
    }
    return count;
}

int randomizeCRCFLAG(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (rand() % 2) {
        structure->CRCFLAG = VERSION_1;
    } else {
        structure->CRCFLAG = VERSION_2;
    }
    if (structure->CRCFLAG > 0x02 || structure->CRCFLAG < 0x01) {
        printf("Warning: Invalid CRCFLAG value: %d\n", structure->CRCFLAG);
    }
    return structure->CRCFLAG;
}

int logStructure(NFAPI_CRC_INDICATION_PDU_T *structure, int id) {
    time_t timestamp = time(NULL);
    printf("Timestamp: %ld, Unique ID: %d, RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: 0x%x\n", 
           timestamp, id, structure->RX_UE_INFORMATION_TAG, structure->RNTI, structure->CRCFLAG);
    return 0;
}

int serializeArray(NFAPI_CRC_INDICATION_PDU_T **array) {
    FILE *file = fopen("data.txt", "wb");
    if (!file) {
        return -1;
    }
    for (int i = 0; i < MAX_ELEMS; i++) {
        fwrite(&array[i]->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&array[i]->RNTI, sizeof(int), 1, file);
        fwrite(&array[i]->CRCFLAG, sizeof(uint8_t), 1, file);
    }
    fclose(file);
    return 0;
}

int deserializeArray(NFAPI_CRC_INDICATION_PDU_T **array) {
    FILE *file = fopen("data.txt", "rb");
    if (!file) {
        return -1;
    }
    for (int i = 0; i < MAX_ELEMS; i++) {
        fread(&array[i]->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fread(&array[i]->RNTI, sizeof(int), 1, file);
        fread(&array[i]->CRCFLAG, sizeof(uint8_t), 1, file);
    }
    fclose(file);
    return 0;
}

int validateRXUETAGandRNTI(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (structure->RX_UE_INFORMATION_TAG < 0 || structure->RX_UE_INFORMATION_TAG > 255) {
        printf("Error: RX_UE_INFORMATION_TAG out of bounds\n");
        return -1;
    }
    if (structure->RNTI < 0 || structure->RNTI > 65535) {
        printf("Error: RNTI out of bounds\n");
        return -1;
    }
    return 0;
}

int manageArray(NFAPI_CRC_INDICATION_PDU_T ***array, int *count) {
    for (int i = 0; i < MAX_ELEMS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!structure) {
            printf("Error: Memory allocation failed\n");
            return -1;
        }
        structure->RX_UE_INFORMATION_TAG = rand() % 256;
        structure->RNTI = rand() % 65536;
        randomizeCRCFLAG(structure);
        validateRXUETAGandRNTI(structure);
        logStructure(structure, i);
        pthread_mutex_lock(&mutex);
        *count = countMatchingStructures(array[i], 0, 0);
        if (*count > MAX_ELEMS) {
            printf("Error: Integer overflow detected\n");
            return -1;
        }
        pthread_mutex_unlock(&mutex);
    }
    for (int i = 0; i < MAX_ELEMS; i++) {
        free(array[i]);
    }
    free(*array);
    return 0;
}

