#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    char state[20];
    struct log_event* event_log;
    size_t log_size;
    size_t capacity;
} network_interface_config;

typedef struct log_event {
    time_t timestamp;
    const char* description;
    struct log_event* next;
} log_event;

network_interface_config* create_network_interface(int id, char state[]) {
    network_interface_config* config = (network_interface_config*)malloc(sizeof(network_interface_config));
    if (!config) return NULL;

    config->id = id;
    strcpy(config->state, state);
    config->event_log = NULL;
    config->log_size = 0;
    config->capacity = 1;

    return config;
}

void add_event(network_interface_config* config, time_t timestamp, const char* description) {
    if (!config || !config->event_log) return;

    log_event* new_event = (log_event*)malloc(sizeof(log_event));
    if (!new_event) return;

    new_event->timestamp = timestamp;
    new_event->description = strdup(description);
    new_event->next = config->event_log;
    config->event_log = new_event;

    if (config->log_size >= config->capacity) {
        config->capacity *= 2;
        log_event* temp = config->event_log;
        while (temp && temp->next) {
            temp = temp->next;
        }
        temp->next = NULL;
    }

    config->log_size++;
}

int validate_event_log(network_interface_config* config) {
    if (!config || !config->event_log) return 1;

    log_event* current = config->event_log;
    while (current) {
        if (!current->description) return 0;
        current = current->next;
    }

    return 1;
}

void free_network_interface(network_interface_config* config) {
    if (!config) return;

    log_event* current = config->event_log;
    log_event* next = NULL;
    while (current) {
        next = current->next;
        free(current->description);
        free(current);
        current = next;
    }

    free(config);
}

void print_network_interface(network_interface_config* config) {
    if (!config || !config->event_log) return;

    log_event* current = config->event_log;
    printf("Interface ID: %d, State: %s\n", config->id, config->state);
    while (current) {
        printf("Timestamp: %lu, Description: %s\n", current->timestamp, current->description);
        current = current->next;
    }
}

int main() {
    network_interface_config* config = create_network_interface(1, "up");
    add_event(config, time(NULL), "Interface came up");
    print_network_interface(config);
    free_network_interface(config);

    return 0;
}
