network_interface_config* initialize_network_interfaces(size_t num_interfaces) {
    network_interface_config* interfaces = (network_interface_config*)malloc(num_interfaces * sizeof(network_interface_config));
    if (!interfaces) {
        // Handle memory allocation error
        return NULL;
    }
    for (size_t i = 0; i < num_interfaces; i++) {
        interfaces[i].id = -1;
        interfaces[i].state = DOWN;
        interfaces[i].log_size = 0;
        interfaces[i].logs = NULL;
    }
    return interfaces;
}

void add_event_to_log(network_interface_config* interface, char* event) {
    // Thread-safe operation
    pthread_mutex_lock(&interface->mutex);

    // Dynamically allocate memory for the log if necessary
    if (interface->log_size == 0) {
        interface->logs = (char**)malloc(sizeof(char*));
        interface->log_size = 1;
    } else {
        char** new_logs = (char**)realloc(interface->logs, (interface->log_size + 1) * sizeof(char*));
        if (!new_logs) {
            // Handle memory allocation error
            pthread_mutex_unlock(&interface->mutex);
            return;
        }
        interface->logs = new_logs;
    }

    // Add the event to the log
    interface->logs[interface->log_size] = (char*)malloc(strlen(event) + 1);
    strcpy(interface->logs[interface->log_size], event);
    interface->log_size++;

    pthread_mutex_unlock(&interface->mutex);
}

int validate_log(network_interface_config* interface) {
    if (!interface->logs || interface->log_size == 0) {
        return 0; // Log is valid
    }

    // Validate log integrity by checking for corruption or overflows
    for (size_t i = 0; i < interface->log_size; i++) {
        if (!interface->logs[i] || strlen(interface->logs[i]) > 1024) {
            return -1; // Log is invalid
        }
    }

    return 0; // Log is valid
}

void free_network_interfaces(network_interface_config* interfaces, size_t num_interfaces) {
    for (size_t i = 0; i < num_interfaces; i++) {
        network_interface_config* interface = &interfaces[i];

        // Free the log entries
        for (size_t j = 0; j < interface->log_size; j++) {
            free(interface->logs[j]);
        }

        free(interface->logs);
    }

    free(interfaces);
}

int main() {
    size_t num_interfaces = 10000;
    network_interface_config* interfaces = initialize_network_interfaces(num_interfaces);

    // Add events to the logs
    for (size_t i = 0; i < num_interfaces; i++) {
        char event[] = "Event %d occurred";
        add_event_to_log(&interfaces[i], sprintf(event, i));
    }

    // Validate the log integrity
    for (size_t i = 0; i < num_interfaces; i++) {
        if (!validate_log(&interfaces[i])) {
            // Handle invalid log error
            break;
        }
    }

    free_network_interfaces(interfaces, num_interfaces);

    return 0;
}
