typedef struct {
    int caller_id;
    int called_id;
    time_t timestamp;
    double duration;
    char* call_type;
    int status;
} CallDetailRecord;

void manage_memory() {
    long* offset_values = (long*)malloc(sizeof(long) * MAX_CALLS);
    double* precision_numbers = (double*)malloc(sizeof(double) * MAX_CALLS);
    int* keys = (int*)malloc(sizeof(int) * MAX_CALLS);

    record* call_history_pool = (record*)malloc(sizeof(record) * MAX_CALLS);

    // Initialize the offset_values array
    for (int i = 0; i < MAX_CALLS; i++) {
        offset_values[i] = i;
    }

    // Initialize the precision_numbers array
    for (int i = 0; i < MAX_CALLS; i++) {
        precision_numbers[i] = (double)i;
    }

    // Initialize the keys array
    for (int i = 0; i < MAX_CALLS; i++) {
        keys[i] = i;
    }

    // Initialize the call_history_pool array
    for (int i = 0; i < MAX_CALLS; i++) {
        CallDetailRecord* record = &call_history_pool[i];
        record->caller_id = i;
        record->called_id = i;
        record->timestamp = time(NULL);
        record->duration = (double)i;
        record->status = 1;

        char* call_type = (char*)malloc(strlen("Incoming") + strlen("Outgoing"));
        strcpy(call_type, "Incoming");
        record->call_type = call_type;
    }

    // Free dynamically allocated memory
    free(offset_values);
    free(precision_numbers);
    free(keys);

    // Iterate through the call_history_pool array and print records
    for (int i = 0; i < MAX_CALLS; i++) {
        CallDetailRecord* record = &call_history_pool[i];
        printf("Caller ID: %d, Called ID: %d, Timestamp: %ld, Duration: %.2lf, Status: %d, Call Type: %s\n",
            record->caller_id, record->called_id, record->timestamp, record->duration, record->status, record->call_type);
    }

    // Free the call_history_pool array
    for (int i = 0; i < MAX_CALLS; i++) {
        CallDetailRecord* record = &call_history_pool[i];
        free(record->call_type);
    }
    free(call_history_pool);
}
