    time_t timestamp;
    double metric_value;
    char* unit_of_measurement;
    int status_flag;
} Event_t;

typedef struct {
    Event_t* events;
    size_t capacity;
    size_t used;
} LogBuffer;

LogBuffer init_log_buffer(size_t initial_capacity) {
    LogBuffer buffer = (LogBuffer)malloc(sizeof(*buffer));
    buffer->events = (Event_t*)calloc(initial_capacity, sizeof(*buffer->events));
    buffer->capacity = initial_capacity;
    buffer->used = 0;
    return buffer;
}

void free_log_buffer(LogBuffer* buffer) {
    if (!buffer) return;
    for (size_t i = 0; i < buffer->used; ++i) {
        free(buffer->events[i].unit_of_measurement);
    }
    free(buffer->events);
    free(buffer);
}

EventLog init_event_log(double metric_value, time_t timestamp, char* tag) {
    EventLog log;
    log.metric_value = metric_value;
    log.timestamp = timestamp;
    log.tag = (char*)malloc(strlen(tag) + 1);
    strcpy(log.tag, tag);
    return log;
}

void free_event_log(EventLog* log) {
    if (!log) return;
    free(log->tag);
    free(log);
}
