    private readonly IHtmlService _htmlService;
    private readonly ILogger _logger;

    public UpdatePageContent(IHtmlService htmlService, ILogger logger)
    {
        _htmlService = htmlService;
        _logger = logger;
    }

    [HttpPost]
    public async Task<IActionResult> HandleUpdate([FromBody]UpdateRequest request)
    {
        // Validate session token
        if (!ValidateSessionToken(request.SessionToken))
            return new BadRequestResult();

        // Update HTML content using the service class
        var updatedContent = _htmlService.UpdateElementContent(request.UserId, request.PageSectionId, request.ElementId, request.HtmlContent);

        // Log update action for auditing purposes
        await _logger.LogAsync(LogLevel.Information, "Updated page content");

        // Modify HTML content by inserting new string after search string
        var newHtmlContent = InsertNewStringAfterSearchString(request.HtmlContent, request.NewString, request.SearchString);

        return new ContentResult(newHtmlContent) { StatusCode = (int)HttpStatusCode.OK };
    }

    private bool ValidateSessionToken(string sessionToken)
    {
        // Implement your custom validation logic here
        return true; // For demonstration purposes only
    }

    private string InsertNewStringAfterSearchString(string htmlContent, string newString, string searchString)
    {
        int index = htmlContent.IndexOf(searchString);
        if (index >= 0)
            htmlContent = htmlContent.Substring(0, index + searchString.Length) + newString + htmlContent.Substring(index + searchString.Length);

        return htmlContent;
    }
}

public class UpdateRequest
{
    public Guid UserId { get; set; }
    public string SessionToken { get; set; }
    public int PageSectionId { get; set; }
    public int ElementId { get; set; }
