        pool_size = PAGE_SIZE;
    } else if (record_count >= pool_size - RECORD_SIZE) {
        size_t new_size = pool_size + PAGE_SIZE;
        void* new_pool = realloc(record_pool, new_size);
        pool_size = new_size;
        record_pool = new_pool;
    }
    return (CallDetailRecord*)((char*)record_pool + (record_count * RECORD_SIZE));
}

void release_record(CallDetailRecord* record) {
    if (record->call_type != NULL) {
        free(record->call_type);
        record->call_type = NULL;
    }
    if (record->status != NULL) {
        free(record->status);
        record->status = NULL;
    }
}

void gc_records() {
    for (size_t i = 0; i < record_count; i++) {
        CallDetailRecord* record = &((CallDetailRecord*)record_pool)[i];
        if (record->caller_id == 0 && record->called_id == 0) {
            release_record(record);
            memmove(&((CallDetailRecord*)record_pool)[i], &((CallDetailRecord*)record_pool)[i + 1], (record_count - i - 1) * RECORD_SIZE);
            record_count--;
            if (i >= record_count) {
                break;
            }
        }
    }
}

CallDetailRecord* add_record(int caller_id, int called_id, time_t timestamp, size_t duration, const char* call_type, const char* status) {
    CallDetailRecord* new_record = allocate_record();
    new_record->caller_id = caller_id;
    new_record->called_id = called_id;
    new_record->timestamp = timestamp;
    new_record->duration = duration;
    if (call_type != NULL) {
        size_t call_type_len = strlen(call_type);
        new_record->call_type = malloc(call_type_len + 1);
        strcpy(new_record->call_type, call_type);
        new_record->call_type[call_type_len] = '\0';
    } else {
        new_record->call_type = NULL;
    }
    if (status != NULL) {
        size_t status_len = strlen(status);
        new_record->status = malloc(status_len + 1);
        strcpy(new_record->status, status);
        new_record->status[status_len] = '\0';
    } else {
        new_record->status = NULL;
    }
    record_count++;
    return new_record;
}

CallDetailRecord* search_records(int caller_id, int called_id, time_t start_timestamp, time_t end_timestamp) {
    for (size_t i = 0; i < record_count; i++) {
        CallDetailRecord* record = &((CallDetailRecord*)record_pool)[i];
        if (caller_id == record->caller_id && called_id == record->called_id &&
            start_timestamp <= record->timestamp && record->timestamp <= end_timestamp) {
            return record;
        }
    }
    return NULL;
}

int main() {
    // example usage
    CallDetailRecord* record1 = add_record(123, 456, time(NULL), 30, "Voice", "Completed");
    CallDetailRecord* record2 = add_record(789, 901, time(NULL) + 60, 15, "SMS", "Failed");
    CallDetailRecord* search_result = search_records(123, 456, time(NULL) - 3600, time(NULL));
    if (search_result != NULL) {
        printf("Caller ID: %d\n", search_result->caller_id);
        printf("Called ID: %d\n", search_result->called_id);
        printf("Timestamp: %ld\n", search_result->timestamp);
        printf("Duration: %zu seconds\n", search_result->duration);
        printf("Call Type: %s\n", search_result->call_type);
        printf("Status: %s\n", search_result->status);
    } else {
        printf("No matching records found.\n");
    }
    gc_records();
    return 0;
}
