import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ServiceLifecycleManager {
    private ExecutorService executor = Executors.newCachedThreadPool();
    private Service service;

    public void startAndStopService() throws InterruptedException {
        while (true) {
            // Start the service
            startService();

            // Wait for a random delay between starts
            long delay = new java.util.Random().nextInt(1000);
            TimeUnit.MILLISECONDS.sleep(delay);

            // Stop the service
            stopService();
        }
    }

    private void startService() {
        if (service == null) {
            service = new Service();
        }
        executor.submit(() -> service.start());
    }

    private void stopService() {
        if (service != null) {
            executor.submit(() -> service.stop());
        }
    }

    public void sendMessage(String message) {
        // Send the message to the messaging system
        System.out.println(message);
    }
}
