typedef struct {
    int id;
    int source_id;
    time_t timestamp;
    char *type;
    size_t payload_size;
    char *payload;
    enum { NEW, PROCESSING, PROCESSED } status;
} Event;

Event *event_new(int id, int source_id, const char *type) {
    Event *event = malloc(sizeof(Event));
    event->id = id;
    event->source_id = source_id;
    event->timestamp = time(NULL);
    event->type = strdup(type);
    event->payload_size = 0;
    event->payload = NULL;
    event->status = NEW;
    return event;
}

void event_free(Event *event) {
    if (event) {
        free(event->type);
        free(event->payload);
        free(event);
    }
}

int main() {
    // Example usage:
    Event *events = NULL;
    int num_events = 0;

    for (int i = 0; i < 10; i++) {
        Event *event = event_new(i, i + 1, "Event Type");
        events = realloc(events, sizeof(Event) * ++num_events);
        events[num_events - 1] = event;
    }

    for (int i = 0; i < num_events; i++) {
        printf("Event %d: id=%d, source_id=%d, timestamp=%lu, type='%s', payload_size=%zu, status=%s\n",
              i, events[i]->id, events[i]->source_id, events[i]->timestamp,
              events[i]->type, events[i]->payload_size, (events[i]->status == NEW) ? "NEW" : (events[i]->status == PROCESSING) ? "PROCESSING" : "PROCESSED");
    }

    for (int i = 0; i < num_events; i++) {
        event_free(events[i]);
    }
    free(events);

