typedef struct {
    uint32_t vm_id;
    enum { NFVI_VM_STATE_CREATED, NFVI_VM_STATE_RUNNING, NFVI_VM_STATE_TERMINATED } vm_state;
    pthread_mutex_t event_list_lock;
    void* (*event_list)[];
} NFVI_VM_CONTEXT_T;

typedef struct {
    uint32_t event_type;
    char* details;
} NFVI_VM_EVENT_T;

NFVI_VM_CONTEXT_T* vm_context = NULL;
int num_vm_contexts = 0;

void init_vm_context(NFVI_VM_CONTEXT_T** context) {
    *context = (NFVI_VM_CONTEXT_T*)malloc(sizeof(NFVI_VM_CONTEXT_T));
    (*context)->vm_id = 1;
    (*context)->vm_state = NFVI_VM_STATE_CREATED;
    pthread_mutex_init(&((*context)->event_list_lock), NULL);
    (*context)->event_list = (void**)calloc(10, sizeof(void*));
    num_vm_contexts++;
}

int add_event(NFVI_VM_CONTEXT_T* context, void* event) {
    pthread_mutex_lock(&context->event_list_lock);
    if (context->vm_state == NFVI_VM_STATE_TERMINATED)
        return -1; // VM terminated
    size_t list_size = sizeof(void*) * strlen(context->event_list);
    context->event_list = (void**)realloc(context->event_list, list_size + 1);
    context->event_list[list_size / sizeof(void*)] = event;
    pthread_mutex_unlock(&context->event_list_lock);
    return 0; // success
}

int validate_event_list(NFVI_VM_CONTEXT_T* context) {
    pthread_mutex_lock(&context->event_list_lock);
    for (size_t i = 0; i < strlen(context->event_list); i++) {
        if (!context->event_list[i])
            return -1; // invalid event list
    }
    pthread_mutex_unlock(&context->event_list_lock);
    return 0; // valid event list
}

void destroy_vm_context(NFVI_VM_CONTEXT_T* context) {
    pthread_mutex_destroy(&context->event_list_lock);
    free(context->event_list);
    free(context);
    num_vm_contexts--;
}

int main() {
    init_vm_context(&vm_context);
    NFVI_VM_EVENT_T event = { 1, "VM started" };
    add_event(vm_context, &event);
    printf("Event list size: %ld\n", strlen(vm_context->event_list));
    if (validate_event_list(vm_context) < 0)
        printf("Invalid event list!\n");
    destroy_vm_context(vm_context);
    return 0;
}
