        // Check memory usage
        size_t total_memory_usage = malloc_usable_size(record_pool) + malloc_usable_size(offset_pool) + malloc_usable_size(key_pool);
        if (total_memory_usage > max_physical_ram()) {
            // Trim or delay record creation if necessary
