void add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (ue_context->pdus.pdu_count >= ue_context->pdus.pdu_capacity) {
        // Allocate more memory for the PDU array
        size_t new_capacity = ue_context->pdus.pdu_capacity * 2;
