    int pdu_list_size;
    pthread_mutex_t lock;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* nfapi_uecontext_init(void) {
    NFAPI_RRC_UECONTEXT_T* uectx = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!uectx) return NULL;

    uectx->ue_id = 0;
    uectx->state = RRC_STATE_UNKNOWN;
    uectx->pdu_list = NULL;
    uectx->pdu_list_size = 0;

    pthread_mutex_init(&uectx->lock, NULL);
    return uectx;
}

void nfapi_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* uectx, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uectx->lock);

    // Check for duplicates based on unique identifier
    if (pdu_list_contains_duplicate(uectx->pdu_list, uectx->pdu_list_size, pdu)) {
        free(pdu);
        pthread_mutex_unlock(&uectx->lock);
        return;
    }

    // Add PDU to the list
    NFAPI_UL_CCCH_pdu_t** new_pdu_list = (NFAPI_UL_CCCH_pdu_t**)realloc(uectx->pdu_list, sizeof(NFAPI_UL_CCCH_pdu_t*) * (uectx->pdu_list_size + 1));
    if (!new_pdu_list) {
        free(pdu);
        pthread_mutex_unlock(&uectx->lock);
        return;
    }

    new_pdu_list[uectx->pdu_list_size] = pdu;

    // Update the size
    uectx->pdu_list = new_pdu_list;
    uectx->pdu_list_size++;

    pthread_mutex_unlock(&uectx->lock);
}

int nfapi_uecontext_validate(NFAPI_RRC_UECONTEXT_T* uectx) {
    int hash = 0;
    for (int i = 0; i < uectx->pdu_list_size; i++) {
        NFAPI_UL_CCCH_pdu_t* pdu = uectx->pdu_list[i];
        hash ^= custom_hash_function(pdu);
    }
    return hash == 0;
}

void nfapi_uecontext_free(NFAPI_RRC_UECONTEXT_T* uectx) {
    pthread_mutex_lock(&uectx->lock);

    for (int i = 0; i < uectx->pdu_list_size; i++) {
        free(uectx->pdu_list[i]);
    }
    free(uectx->pdu_list);

    pthread_mutex_unlock(&uectx->lock);

    free(uectx);
}

// Custom hash function for quick validation checks
int custom_hash_function(NFAPI_UL_CCCH_pdu_t* pdu) {
    // Implement your custom hash function here
    return 0;
}

// Helper function to check if the PDU list contains a duplicate
int pdu_list_contains_duplicate(NFAPI_UL_CCCH_pdu_t** pdu_list, int size, NFAPI_UL_CCCH_pdu_t* pdu) {
    for (int i = 0; i < size; i++) {
        if (pdu == pdu_list[i]) return 1;
    }
    return 0;
}
