```php
function handleUserRequest(array $request): array {
    if (!isset($request['sub_action'])) {
        return ['status' => 'error', 'message' => 'Invalid request'];
    }

    switch ($request['sub_action']) {
        case 'create':
            return createAccount($request);
        case 'update':
            return updateAccount($request);
        case 'delete':
            return deleteAccount($request);
        default:
            return ['status' => 'error', 'message' => 'Invalid sub-action'];
    }
}

function createAccount(array $request): array {
    if (!Validate::email($request['email']) || strlen($request['password']) < 8) {
        return ['status' => 'error', 'message' => 'Invalid email or password'];
    }

    $user = new User();
    $user->name = $request['name'];
    $user->email = $request['email'];
    $user->role = $request['role'];

    if (!Save::create($user)) {
        return ['status' => 'error', 'message' => 'Failed to create user account'];
    }

    return ['status' => 'success', 'message' => 'User account created successfully', 'data' => $user];
}

function updateAccount(array $request): array {
    if (!isset($request['id'])) {
        return ['status' => 'error', 'message' => 'Invalid request'];
    }

    $user = Get::getUserById($request['id']);

    if (!$user || !Validate::email($request['email']) || strlen($request['password']) < 8) {
        return ['status' => 'error', 'message' => 'Invalid email or password'];
    }

    if ($request['role'] !== $user->role && !hasPermissionToUpdateRole()) {
        return ['status' => 'error', 'message' => 'Insufficient permissions to update user role'];
    }

    $user->name = $request['name'];
    $user->email = $request['email'];

    if (!Save::update($user)) {
        return ['status' => 'error', 'message' => 'Failed to update user account'];
    }

    return ['status' => 'success', 'message' => 'User account updated successfully', 'data' => $user];
}

function deleteAccount(array $request): array {
    if (!isset($request['id'])) {
        return ['status' => 'error', 'message' => 'Invalid request'];
    }

    $user = Get::getUserById($request['id']);

    if (!$user) {
        return ['status' => 'error', 'message' => 'User not found'];
    }

    if (!hasPermissionToDeleteAccount()) {
        return ['status' => 'error', 'message' => 'Insufficient permissions to delete user account'];
    }

    if (!Save::delete($user)) {
        return ['status' => 'error', 'message' => 'Failed to delete user account'];
    }

    return ['status' => 'success', 'message' => 'User account deleted successfully'];
}

