#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

#define MAX_LINE_LENGTH 1024
#define DEFAULT_DELIMITER "\n"
#define DEFAULT_OUTPUT_FILE "output.txt"

typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG
} LogLevel;

typedef struct {
    int count;
    char *delimiter;
    FILE *output_file;
    LogLevel log_level;
    int max_lines_per_file;
} Options;

Options options = {
    .count = 0,
    .delimiter = DEFAULT_DELIMITER,
    .output_file = NULL,
    .log_level = LOG_LEVEL_ERROR,
    .max_lines_per_file = INT_MAX
};

void parse_args(int argc, char **argv) {
    int c;
    while ((c = getopt(argc, argv, "d:o:v:m:l:")) != -1) {
        switch (c) {
            case 'd':
                options.delimiter = optarg;
                break;
            case 'o':
                options.output_file = fopen(optarg, "w");
                if (!options.output_file) {
                    fprintf(stderr, "Error opening output file: %s\n", optarg);
                    exit(1);
                }
                break;
            case 'v':
                if (strcmp(optarg, "true") == 0)
                    options.log_level = LOG_LEVEL_INFO;
                else
                    options.log_level = LOG_LEVEL_ERROR;
                break;
            case 'm':
                options.max_lines_per_file = atoi(optarg);
                break;
            case 'l':
                options.log_level = (LogLevel)atoi(optarg);
                break;
            default:
                break;
        }
    }
}

void process_files(const char *argv[]) {
    for (int i = 1; i < argc; i++) {
        FILE *file = fopen(argv[i], "r");
        if (!file) {
            fprintf(stderr, "Error opening file: %s\n", argv[i]);
            continue;
        }
        int line_count = 0;
        char buffer[MAX_LINE_LENGTH];
        while (fgets(buffer, MAX_LINE_LENGTH, file)) {
            if (ferror(file)) {
                perror("Error reading file");
                fclose(file);
                return;
            }
            line_count++;
            if (line_count >= options.max_lines_per_file) {
                fprintf(options.output_file ? options.output_file : stdout,
                        "Stopped processing at %d lines in file: %s\n",
                        line_count, argv[i]);
                break;
            }
        }
        fclose(file);
        if (options.log_level > LOG_LEVEL_ERROR)
            printf("Processed file: %s with %d lines\n", argv[i], line_count);
    }
}

int main(int argc, char **argv) {
    parse_args(argc, argv);
    process_files(argv);
    return 0;
}
