        printf("Task %d: Description - %s, Priority - %d, Deadline - %ld, Status - %d\n", 
               tasks[i].id, tasks[i].description, tasks[i].priority, tasks[i].deadline, tasks[i].status);
    }
}

int main(int argc, char *argv[]) {
    int c;
    opterr = 0;
    while ((c = getopt(argc, argv, "m:o:")) != -1) {
        switch (c) {
            case 'm':
                printf("manpage\n");
                break;
            case 'o':
                printf("output_file %s\n", optarg);
                break;
            default:
                printf("usage: %s [-m] [-o output_file]\n", argv[0]);
                return 1;
        }
    }

    if (argc < 2) {
        printf("No input file specified. Exiting...\n");
        return 1;
    }

    regex_t regex;
    regcomp(&regex, "^[A-Za-z0-9 _.-]+$", REG_EXTENDED);
    FILE *file = fopen(argv[argc - 1], "r");
    if (!file) {
        printf("Error opening file: %s\n", argv[argc - 1]);
        return 1;
    }

    int line_count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (regexec(&regex, line, 0, NULL, 0) == 0) {
            line_count++;
        }
    }

    printf("Number of valid lines: %d\n", line_count);

    fclose(file);
    regfree(&regex);

    return 0;
}

