    const char* query = "INSERT INTO user_profiles (id, precision_score, name, email, age, registration_date) VALUES (?, ?, ?, ?, ?)";
    int rc;

    // Prepare the SQL statement
    rc = sqlite3_prepare_v2(db, query, strlen(query), &stmt, NULL);
    if (rc != SQLITE_OK) {
        log_error("Failed to prepare SQL statement");
    }

    // Bind the parameters and execute the query
    sqlite3_bind_int(stmt, 1, ue_context->id);
    sqlite3_bind_double(stmt, 2, ue_context->precision_score);
    sqlite3_bind_text(stmt, 3, ue_context->user_details.name, -1, SQLITE_STATIC);
    sqlite3_bind_text(stmt, 4, ue_context->user_details.email, -1, SQLITE_STATIC);
    sqlite3_bind_int(stmt, 5, ue_context->user_details.age);
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        log_error("Failed to execute SQL statement");
    }

    // Reset the statement
    sqlite3_finalize(stmt);
}

void read_user_profile(NFAPI_RRC_UECONTEXT_T* ue_context, int id) {
    sqlite3_stmt* stmt;
    const char* query = "SELECT * FROM user_profiles WHERE id=?";
    int rc;

    // Prepare the SQL statement
    rc = sqlite3_prepare_v2(db, query, strlen(query), &stmt, NULL);
    if (rc != SQLITE_OK) {
        log_error("Failed to prepare SQL statement");
    }

    // Bind the parameter and execute the query
    sqlite3_bind_int(stmt, 1, id);
    rc = sqlite3_step(stmt);
    if (rc == SQLITE_ROW) {
        ue_context->id = sqlite3_column_int(stmt, 0);
        ue_context->precision_score = sqlite3_column_double(stmt, 1);
        ue_context->user_details.name = strdup((char*)sqlite3_column_text(stmt, 2));
        ue_context->user_details.email = strdup((char*)sqlite3_column_text(stmt, 3));
        ue_context->user_details.age = sqlite3_column_int(stmt, 4);
    } else {
        log_error("Failed to read user profile");
    }

    // Reset the statement
    sqlite3_finalize(stmt);
}

// Serialize and deserialize NFAPI_RRC_UECONTEXT_T structure
void serialize_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context) {
    json_object* json_obj = json_object_new();
    json_object_object_add(json_obj, "id", json_real(ue_context->id));
    json_object_object_add(json_obj, "precision_score", json_real(ue_context->precision_score));
    json_object_object_add(json_obj, "user_details", json_object_new());
    json_object_object_add(json_object_object(json_obj, "user_details"), "name", json_string(ue_context->user_details.name));
    json_object_object_add(json_object_object(json_obj, "user_details"), "email", json_string(ue_context->user_details.email));
    json_object_object_add(json_object_object(json_obj, "user_details"), "age", json_real(ue_context->user_details.age));
    json_object_object_add(json_object_object(json_obj, "user_details"), "registration_date", json_real(ue_context->user_details.registration_date));

    // Write the JSON object to the file
    json_file = fopen("user_data.json", "w");
    if (json_file == NULL) {
        log_error("Failed to open JSON file for writing");
    }
    fprintf(json_file, "%s\n", json_object_to_json_string(json_obj));
    fclose(json_file);
}

void deserialize_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context) {
    json_object* json_obj = json_object_from_file("user_data.json");
    if (json_obj == NULL) {
        log_error("Failed to read JSON file");
    }

    // Extract the values from the JSON object
    ue_context->id = json_real(json_object_object_get(json_obj, "id"));
    ue_context->precision_score = json_real(json_object_object_get(json_obj, "precision_score"));
    ue_context->user_details.name = strdup((char*)json_string(json_object_object_get(json_obj, "user_details", "name")));
    ue_context->user_details.email = strdup((char*)json_string(json_object_object_get(json_obj, "user_details", "email")));
    ue_context->user_details.age = json_real(json_object_object_get(json_obj, "user_details", "age"));
    ue_context->user_details.registration_date = json_real(json_object_object_get(json_obj, "user_details", "registration_date"));

    // Clean up
    json_decref(json_obj);
}

int main() {
    db = sqlite3_open(USER_DB, SQLITE_OPEN_READWRITE | SQLITE_OPEN_CREATE);
    if (db == NULL) {
        log_error("Failed to open database");
    }

    // Initialize the logging system
    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        log_error("Failed to open log file for writing");
    }

    // Read user profiles from the database
    NFAPI_RRC_UECONTEXT_T* ue_contexts = malloc(10000 * sizeof(NFAPI_RRC_UECONTEXT_T));
    int num_ue_contexts = 0;
    sqlite3_stmt* stmt;
    const char* query = "SELECT * FROM user_profiles";
    int rc;

    // Prepare the SQL statement
    rc = sqlite3_prepare_v2(db, query, strlen(query), &stmt, NULL);
    if (rc != SQLITE_OK) {
        log_error("Failed to prepare SQL statement");
    }

    // Execute the query and read user profiles
    while ((rc = sqlite3_step(stmt)) == SQLITE_ROW) {
        NFAPI_RRC_UECONTEXT_T* ue_context = &ue_contexts[num_ue_contexts++];
        ue_context->id = sqlite3_column_int(stmt, 0);
        ue_context->precision_score = sqlite3_column_double(stmt, 1);
        ue_context->user_details.name = strdup((char*)sqlite3_column_text(stmt, 2));
        ue_context->user_details.email = strdup((char*)sqlite3_column_text(stmt, 3));
        ue_context->user_details.age = sqlite3_column_int(stmt, 4);

        // Serialize and deserialize the UE context
        serialize_ue_context(ue_context);
    }

    // Clean up
    sqlite3_finalize(stmt);
    free(ue_contexts);

    return 0;
}
