#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    int valid_cell_id;
    NFPAPI_DL_SRB_T* srb_list;
    pthread_mutex_t lock;
} NFPAPI_LTE_CELL_CONTEXT_T;

NFPAPI_LTE_CELL_CONTEXT_T* nfpapi_lte_cell_context_create(int capacity) {
    NFPAPI_LTE_CELL_CONTEXT_T* context = (NFPAPI_LTE_CELL_CONTEXT_T*)malloc(sizeof(NFPAPI_LTE_CELL_CONTEXT_T));
    if (!context) return NULL;

    context->valid_cell_id = -1; // invalid cell ID initially
    context->srb_list = malloc(sizeof(NFPAPI_DL_SRB_T)*capacity);
    if (!context->srb_list) {
        free(context);
        return NULL;
    }

    pthread_mutex_init(&context->lock, NULL);
    return context;
}

void nfpapi_lte_cell_context_destroy(NFPAPI_LTE_CELL_CONTEXT_T* context) {
    if (context) {
        pthread_mutex_unlock(&context->lock);
        free(context->srb_list);
        free(context);
    }
}

int nfpapi_lte_cell_context_add_srb(NFPAPI_LTE_CELL_CONTEXT_T* context, NFPAPI_DL_SRB_T* srb) {
    pthread_mutex_lock(&context->lock);

    // validate the integrity of the SRB list and cell configurations
    if (!context || !srb || context->valid_cell_id == -1) {
        pthread_mutex_unlock(&context->lock);
        return -1; // invalid operation
    }

    // add the new SRB to the list
    int idx = 0;
    while (idx < context->srb_list && context->srb_list[idx]) {
        idx++;
    }
    if (idx == context->srb_list_capacity) return -1; // array full

    context->srb_list[idx] = srb;

    pthread_mutex_unlock(&context->lock);
    return 0;
}

int nfpapi_lte_cell_context_remove_srb(NFPAPI_LTE_CELL_CONTEXT_T* context, NFPAPI_DL_SRB_T* srb) {
    pthread_mutex_lock(&context->lock);

    // validate the integrity of the SRB list and cell configurations
    if (!context || !srb || context->valid_cell_id == -1) {
        pthread_mutex_unlock(&context->lock);
        return -1; // invalid operation
    }

    int idx = 0;
    while (idx < context->srb_list_size && context->srb_list[idx] != srb) {
        idx++;
    }
    if (idx == context->srb_list_size) return -1; // SRB not found

    // remove the SRB from the list
    for (int i = idx; i < context->srb_list_size; i++) {
        context->srb_list[i] = context->srb_list[i+1];
    }

    pthread_mutex_unlock(&context->lock);
    return 0;
}

int nfpapi_lte_cell_context_update_config(NFPAPI_LTE_CELL_CONTEXT_T* context, int new_cell_id) {
    pthread_mutex_lock(&context->lock);

    // validate the integrity of the SRB list and cell configurations
    if (!context || context->valid_cell_id != -1 && context->cell_id == new_cell_id) {
        pthread_mutex_unlock(&context->lock);
        return -1; // invalid operation or duplicate cell ID
    }

    // update the cell ID configuration
    context->valid_cell_id = new_cell_id;

    pthread_mutex_unlock(&context->lock);
    return 0;
}
