typedef struct {
    int ue_id;
    enum { RRC_IDLE, RRC_CONNECTED } rrc_state;
    void** pdcp_pdu_list;
    int pdcp_pdu_count;
} LTE_UESession;

void lte_ue_session_init(LTE_UESession* session) {
    session->ue_id = 0;
    session->rrc_state = RRC_IDLE;
    session->pdcp_pdu_list = NULL;
    session->pdcp_pdu_count = 0;
}

int lte_ue_session_add_pdu(LTE_UESession* session, int pdu_size) {
    void** new_pdu_list = realloc(session->pdcp_pdu_list, (session->pdcp_pdu_count + 1) * sizeof(void*));
    if (!new_pdu_list) return -1;

    session->pdcp_pdu_list = new_pdu_list;
    new_pdu_list[session->pdcp_pdu_count] = malloc(pdu_size);
    if (!new_pdu_list[session->pdcp_pdu_count]) {
        free(new_pdu_list);
        return -1;
    }

    session->pdcp_pdu_count++;
    return 0;
}

void lte_ue_session_remove_pdu(LTE_UESession* session, int index) {
    if (index < 0 || index >= session->pdcp_pdu_count) return;

    free(session->pdcp_pdu_list[index]);
    memmove(&session->pdcp_pdu_list[index], &session->pdcp_pdu_list[index + 1], (session->pdcp_pdu_count - index - 1) * sizeof(void*));
    session->pdcp_pdu_count--;
}

void lte_ue_session_validate_pdu_list(LTE_UESession* session) {
    for (int i = 0; i < session->pdcp_pdu_count; i++) {
        if (!session->pdcp_pdu_list[i]) {
            printf("Invalid PDU list: PDU %d is null\n", i);
            return;
        }
    }
}

LTE_UESession lte_ue_session_new() {
    LTE_UESession session = (LTE_UESession)malloc(sizeof(LTE_UESession));
    if (!session) return NULL;

    lte_ue_session_init(&session);

    return session;
}

void lte_ue_session_free(LTE_UESession* session) {
    for (int i = 0; i < session->pdcp_pdu_count; i++) free(session->pdcp_pdu_list[i]);
    free(session->pdcp_pdu_list);
    free(session);
}
