typedef struct {
    int UE_ID;
    int RRC_STATE;
    struct LTE_PDCP_PDU_t **pdu_list;
    size_t pdu_list_size;
    pthread_mutex_t lock;
} LTE_UESession;

typedef struct {
    int sequence_number;
    char *data;
    time_t timestamp;
} LTE_PDCP_PDU_t;

LTE_UESession* ue_session_init() {
    LTE_UESession* session = (LTE_UESession*)malloc(sizeof(LTE_UESession));
    session->pdu_list_size = 10;
    session->pdu_list = (struct LTE_PDCP_PDU_t**)malloc(session->pdu_list_size * sizeof(struct LTE_PDCP_PDU_t*));
    pthread_mutex_init(&session->lock, NULL);
    return session;
}

void ue_session_free(LTE_UESession* session) {
    for(size_t i = 0; i < session->pdu_list_size; i++) {
        free(session->pdu_list[i]->data);
        free(session->pdu_list[i]);
    }
    free(session->pdu_list);
    free(session);
}

void ue_session_add_pdu(LTE_UESession* session, LTE_PDCP_PDU_t* pdu) {
    pthread_mutex_lock(&session->lock);
    for(size_t i = 0; i < session->pdu_list_size; i++) {
        if(session->pdu_list[i] == NULL) {
            session->pdu_list[i] = (LTE_PDCP_PDU_t*)malloc(sizeof(LTE_PDCP_PDU_t));
            session->pdu_list[i]->sequence_number = pdu->sequence_number;
            session->pdu_list[i]->data = strdup(pdu->data);
            session->pdu_list[i]->timestamp = time(NULL);
            break;
        }
    }
    pthread_mutex_unlock(&session->lock);
}

void ue_session_purge_outdated(LTE_UESession* session, int age_threshold) {
    pthread_mutex_lock(&session->lock);
    for(size_t i = 0; i < session->pdu_list_size; i++) {
        if(session->pdu_list[i]->timestamp + age_threshold < time(NULL)) {
            free(session->pdu_list[i]->data);
            free(session->pdu_list[i]);
            session->pdu_list[i] = NULL;
        }
    }
    pthread_mutex_unlock(&session->lock);
}

