int ue_session_export(LTE_UESession* session, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if(file == NULL) {
        return -1;
    }
    fwrite(&session, sizeof(LTE_UESession), 1, file);
    for(size_t i = 0; i < session->pdu_list_size; i++) {
        if(session->pdu_list[i] != NULL) {
            fwrite(&session->pdu_list[i]->sequence_number, sizeof(int), 1, file);
            fwrite(session->pdu_list[i]->data, strlen(session->pdu_list[i]->data) + 1, 1, file);
            fwrite(&session->pdu_list[i]->timestamp, sizeof(time_t), 1, file);
