#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct LTE_UESession {
    char UE_ID[16];
    int RRC_STATE;
    struct LTE_PDCP_PDU_t** PDUs;
    int PDU_count;
    pthread_mutex_t lock;
} LTE_UESession;

typedef struct LTE_PDCP_PDU_t {
    uint32_t sequence_number;
    uint32_t timestamp;
    char data[1024];
} LTE_PDCP_PDU_t;

void* init_UE_session() {
    LTE_UESession* session = malloc(sizeof(LTE_UESession));
    session->PDUs = NULL;
    session->PDU_count = 0;
    pthread_mutex_init(&session->lock, NULL);
    return session;
}

int add_pdu_to_ue(LTE_UESession* session, uint32_t sequence_number, char data[1024]) {
    if (session == NULL) return -1;

    LTE_PDCP_PDU_t* pdu = malloc(sizeof(LTE_PDCP_PDU_t));
    pdu->sequence_number = sequence_number;
    pdu->timestamp = time(NULL);
    strcpy(pdu->data, data);

    session->PDUs = realloc(session->PDUs, (session->PDU_count + 1) * sizeof(LTE_PDCP_PDU_t*));
    session->PDUs[session->PDU_count] = pdu;
    session->PDU_count++;

    pthread_mutex_unlock(&session->lock);
    return 0;
}

int validate_pdu_list(LTE_UESession* session) {
    if (session == NULL || session->PDUs == NULL) return -1;

    for (int i = 0; i < session->PDU_count; i++) {
        if (session->PDUs[i] == NULL) continue;
        if (session->PDUs[i]->sequence_number < 0 || session->PDUs[i]->timestamp > time(NULL)) {
            free(session->PDUs[i]);
            for (int j = i; j < session->PDU_count - 1; j++) {
                session->PDUs[j] = session->PDUs[j + 1];
            }
            session->PDU_count--;
        }
    }

    return 0;
}

void export_ue_session(LTE_UESession* session, FILE* file) {
    if (session == NULL || file == NULL) return;

    fwrite(&session->UE_ID, sizeof(char), 16, file);
    fwrite(&session->RRC_STATE, sizeof(int), 1, file);

    for (int i = 0; i < session->PDU_count; i++) {
        LTE_PDCP_PDU_t* pdu = session->PDUs[i];
        if (pdu == NULL) continue;

        fwrite(&pdu->sequence_number, sizeof(uint32_t), 1, file);
        fwrite(&pdu->timestamp, sizeof(uint32_t), 1, file);
        fwrite(pdu->data, sizeof(char), 1024, file);

        free(pdu);
    }

    free(session->PDUs);
}

void flush_ue_sessions_to_file(LTE_UESession* session) {
    if (session == NULL || !session->PDU_count) return;

    FILE* file = fopen("uesessions.bin", "wb");
    if (!file) return;

    for (int i = 0; i < session->PDU_count; i++) {
        LTE_PDCP_PDU_t* pdu = session->PDUs[i];
        if (pdu == NULL) continue;

        fwrite(&pdu->sequence_number, sizeof(uint32_t), 1, file);
        fwrite(&pdu->timestamp, sizeof(uint32_t), 1, file);
        fwrite(pdu->data, sizeof(char), 1024, file);

        free(pdu);
    }

    free(session->PDUs);

    fclose(file);
}

void* flush_ue_sessions_to_file_thread(void* arg) {
    LTE_UESession* session = (LTE_UESession*)arg;
    if (!session || !session->PDU_count) return NULL;

    FILE* file = fopen("uesessions.bin", "wb");
    if (!file) return NULL;

    for (int i = 0; i < session->PDU_count; i++) {
        LTE_PDCP_PDU_t* pdu = session->PDUs[i];
        if (pdu == NULL) continue;

        fwrite(&pdu->sequence_number, sizeof(uint32_t), 1, file);
        fwrite(&pdu->timestamp, sizeof(uint32_t), 1, file);
        fwrite(pdu->data, sizeof(char), 1024, file);

        free(pdu);
    }

    free(session->PDUs);

    fclose(file);
}

int main() {
    LTE_UESession* session = init_UE_session();

    add_pdu_to_ue(session, 1, "Hello");
    add_pdu_to_ue(session, 2, "World");

    validate_pdu_list(session);

    export_ue_session(session, fopen("ue.bin", "wb"));

    pthread_t thread;
    pthread_create(&thread, NULL, flush_ue_sessions_to_file_thread, session);
}
