    node->nodeID.id = 0;
    node->nodeID.mode = 0;
    node->operationalMode = 0;
    node->rrbCount = 0;
    node->maxRRBCount = 10; // initial max RRB count
    node->aggregateEnabled = 0;
    node->aggregationThreshold = 50; // aggregation threshold in milliseconds
    pthread_mutex_init(&node->mutex, NULL);
    return node;
}

void networkNodeDestroy(NetworkNode* node) {
    for (int i = 0; i < node->rrbCount; i++) {
        free(node->rrbList[i]->data);
        free(node->rrbList[i]);
    }
    free(node->rrbList);
    free(node);
}

void networkNodeAddRRB(NetworkNode* node, RadioResourceBlock* rrb) {
    pthread_mutex_lock(&node->mutex);
    if (node->rrbCount < node->maxRRBCount) {
        node->rrbList = (RadioResourceBlock**)realloc(node->rrbList,
            sizeof(RadioResourceBlock*) * (node->rrbCount + 1));
        node->rrbList[node->rrbCount++] = rrb;
    } else {
        // handle full RRB list
    }
    pthread_mutex_unlock(&node->mutex);
}

int main() {
    NetworkNode* node = networkNodeCreate();
    // Add RRBs to the node...
    return 0;
}
