void* constructStateList(int** states, size_t numStates, struct FSA* fsa, int lastState) {
    void* stateList = malloc(sizeof(struct StateList));
    if (!stateList) return NULL;

    struct StateList* list = (struct StateList*) stateList;
    list->states = realloc(NULL, sizeof(int) * (numStates + 1));
    if (!list->states) {
        free(stateList);
        return NULL;
    }

    // Initialize the new state list
    list->size = numStates;

    for (int i = 0; i < lastState; i++) {
        // Update the 'next' pointer of each state in the input list to point to the new list
        fsa->states[i].next = &list->states;
    }

    return stateList;
}
