#define RRC_CONNECTION_INFO_T struct {
    int connection_id;
    char* info;
};

// Function to initialize and manage the dynamic array of NFPAI_RRC_CELL_CONTEXT_T structures
void* init_cell_context_array(int capacity) {
    // Initialize the dynamic array
    void* cell_context_array = malloc(sizeof(NFPAI_RRC_CELL_CONTEXT_T*) * capacity);
    if (cell_context_array == NULL) {
        return NULL;
    }

    // Initialize each element in the array to point to a null map of RRC_CONNECTION_INFO_T objects
    for (int i = 0; i < capacity; i++) {
        ((NFPAI_RRC_CELL_CONTEXT_T*)cell_context_array)[i].map_of_rrc_connection_info_t = NULL;
    }

    return cell_context_array;
}

// Function to add a new connection information for a given cell ID
void add_connection_info(void* cell_context_array, int cell_id, RRC_CONNECTION_INFO_T* info) {
    // Find the corresponding NFPAI_RRC_CELL_CONTEXT_T structure in the array
    NFPAI_RRC_CELL_CONTEXT_T* cell_context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context_array;
    for (int i = 0; i < strlen(cell_context); i++) {
        if (cell_context[i].valid_cell_id == cell_id) {
            // Allocate memory for the new RRC_CONNECTION_INFO_T object
            void* new_info = malloc(sizeof(RRC_CONNECTION_INFO_T));
            ((RRC_CONNECTION_INFO_T*)new_info).connection_id = info->connection_id;
            ((RRC_CONNECTION_INFO_T*)new_info).info = info->info;

            // Add the new connection information to the map of RRC_CONNECTION_INFO_T objects
            cell_context[i].map_of_rrc_connection_info_t = new_info;
            break;
        }
    }
}

// Function to update existing entries in the map of RRC_CONNECTION_INFO_T objects
void update_connection_info(void* cell_context_array, int cell_id, RRC_CONNECTION_INFO_T* info) {
    // Find the corresponding NFPAI_RRC_CELL_CONTEXT_T structure in the array
    NFPAI_RRC_CELL_CONTEXT_T* cell_context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context_array;
    for (int i = 0; i < strlen(cell_context); i++) {
        if (cell_context[i].valid_cell_id == cell_id) {
            // Update the existing RRC_CONNECTION_INFO_T object in the map
            ((RRC_CONNECTION_INFO_T*)cell_context[i].map_of_rrc_connection_info_t).info = info->info;
            break;
        }
    }
}

// Function to remove connections when necessary
void remove_connection_info(void* cell_context_array, int cell_id) {
    // Find the corresponding NFPAI_RRC_CELL_CONTEXT_T structure in the array
    NFPAI_RRC_CELL_CONTEXT_T* cell_context = (NFPAI_RRC_CELL_CONTEXT_T*)cell_context_array;
    for (int i = 0; i < strlen(cell_context); i++) {
        if (cell_context[i].valid_cell_id == cell_id) {
            // Free the memory allocated for the RRC_CONNECTION_INFO_T object
            free(((RRC_CONNECTION_INFO_T*)cell_context[i].map_of_rrc_connection_info_t).info);
            break;
        }
    }
}

