LTE_UESession* lte_ue_session_init(void) {
    LTE_UESession* session = (LTE_UESession*)malloc(sizeof(LTE_UESession));
    if (!session) return NULL;

    session->PDU_list_size = 0;
    session->PDUs = NULL;

    pthread_mutex_init(&session->lock, NULL);
    return session;
}

void lte_ue_session_free(LTE_UESession* session) {
    if (!session) return;

    pthread_mutex_lock(&session->lock);

    // Free allocated memory
    for (size_t i = 0; i < session->PDU_list_size; ++i)
        free(session->PDUs[i]);

    free(session->PDUs);
    session->PDUs = NULL;
    session->PDU_list_size = 0;

    pthread_mutex_unlock(&session->lock);

    pthread_mutex_destroy(&session->lock);
    free(session);
}

