#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Define a struct to represent a NetworkNode entity
typedef struct {
    int NodeID;
    char OperationalMode;
    int RRBListLength;
    struct RRB **RRBList;
    pthread_mutex_t mutex;
} NetworkNode;

// Define a struct to represent a RadioResourceBlock (RRB) entity
typedef struct {
    int FrequencyBandID;
    int Timestamp;
} RRB;

void networkNodeInit(NetworkNode *node, int initialRRBCount) {
    node->NodeID = 0;
    node->OperationalMode = 'N'; // Normal mode
    node->RRBListLength = initialRRBCount;
    node->RRBList = (struct RRB **)malloc(initialRRBCount * sizeof(struct RRB *));
    for (int i = 0; i < initialRRBCount; i++) {
        node->RRBList[i] = NULL;
    }
    pthread_mutex_init(&node->mutex, NULL);
}

void networkNodeAddRRB(NetworkNode *node, int frequencyBandID) {
    pthread_mutex_lock(&node->mutex);
    // Allocate a new RRB and add it to the list
    RRB *newRRB = (RRB *)malloc(sizeof(RRB));
    newRRB->FrequencyBandID = frequencyBandID;
    newRRB->Timestamp = 0; // Initialize timestamp
    for (int i = 0; i < node->RRBListLength; i++) {
        if (node->RRBList[i] == NULL) {
            node->RRBList[i] = newRRB;
            break;
        }
    }
    pthread_mutex_unlock(&node->mutex);
}

void networkNodeUpdateRRB(NetworkNode *node, int frequencyBandID, int newTimestamp) {
    pthread_mutex_lock(&node->mutex);
    for (int i = 0; i < node->RRBListLength; i++) {
        if (node->RRBList[i] != NULL && node->RRBList[i]->FrequencyBandID == frequencyBandID) {
            node->RRBList[i]->Timestamp = newTimestamp;
            break;
        }
    }
    pthread_mutex_unlock(&node->mutex);
}

void networkNodePurgeOldRRBs(NetworkNode *node, int ageThreshold) {
    pthread_mutex_lock(&node->mutex);
    for (int i = 0; i < node->RRBListLength; i++) {
        if (node->RRBList[i] != NULL && node->RRBList[i]->Timestamp <= ageThreshold) {
            // Purge outdated RRBs
            free(node->RRBList[i]);
            node->RRBList[i] = NULL;
        }
    }
    pthread_mutex_unlock(&node->mutex);
}

void networkNodeExportData(NetworkNode *node, FILE *file) {
    // Export entire node data to the file in a standardized format
    fwrite(&node->NodeID, sizeof(int), 1, file);
    fwrite(&node->OperationalMode, sizeof(char), 1, file);
    int RRBListLength = 0;
    for (int i = 0; i < node->RRBListLength; i++) {
        if (node->RRBList[i] != NULL) {
            RRBListLength++;
        }
    }
    fwrite(&RRBListLength, sizeof(int), 1, file);
    for (int i = 0; i < RRBListLength; i++) {
        // Export each RRB's frequency band ID and timestamp
        fwrite(&node->RRBList[i]->FrequencyBandID, sizeof(int), 1, file);
        fwrite(&node->RRBList[i]->Timestamp, sizeof(int), 1, file);
    }
}

void networkNodeShutdown(NetworkNode *node) {
    // Release memory allocated for the RRB list
    for (int i = 0; i < node->RRBListLength; i++) {
        if (node->RRBList[i] != NULL) {
            free(node->RRBList[i]);
        }
    }
    free(node->RRBList);
    pthread_mutex_destroy(&node->mutex);
}
