#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>

#define LOG_LEVEL_ERROR 0
#define LOG_LEVEL_WARNING 1
#define LOG_LEVEL_INFO 2
#define DEFAULT_LOG_LEVEL LOG_LEVEL_INFO

typedef struct {
    int log_level;
} LogConfig;

int main(int argc, char* argv[]) {
    // Initialize default configuration
    LogConfig config = {DEFAULT_LOG_LEVEL};

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strncmp(argv[i], "-d=", 3) == 0) {
            config.log_level = atoi(&argv[i][2]);
        } else if (strncmp(argv[i], "--log-level=", 12) == 0) {
            config.log_level = atoi(&argv[i][13]);
        } else if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-d|--log-level=<level>] [files...]\n", argv[0]);
            return 1;
        }
    }

    int line_count = 0;
    FILE* output_file = stdout;

    for (int i = 1; i < argc; i++) {
        if (strncmp(argv[i], "-o=", 3) == 0) {
            char* output_path = &argv[i][2];
            output_file = fopen(output_path, "w");
            if (!output_file) {
                fprintf(stderr, "Error opening output file: %s\n", output_path);
                return 1;
            }
        } else {
            FILE* current_file = fopen(argv[i], "r");
            if (!current_file) {
                fprintf(stderr, "Error reading file: %s\n", argv[i]);
                continue;
            }

            int line_num = 0;
            char buffer[1024];
            while (fgets(buffer, sizeof(buffer), current_file)) {
                line_num++;
            }
            fclose(current_file);

            if (config.log_level > LOG_LEVEL_INFO) {
                printf("Processed file: %s (%d lines)\n", argv[i], line_num);
            }

            line_count += line_num;
        }
    }

    fprintf(output_file, "Total lines: %d\n", line_count);

    if (output_file != stdout) {
        fclose(output_file);
    }

    return 0;
}
```

