// Function to create a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;
    NFAPI_CRC_INDICATION_PDU_T** tail = &head;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Generate random data
        srand(time(NULL) + i);
        strcpy(node->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG");
        node->RNTI = rand() % 1000;
        strcpy(node->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
        node->CRCFLAG = rand() % 2;

        *tail = node;
        tail = &(*tail)->next;

        // Check for memory allocation failure
        if (*tail == NULL) {
            free(node);
            return head;
        }
    }

    return head;
}

// Function to serialize the linked list into a binary format
int serialize_linked_list(NFAPI_CRC_INDICATION_PDU_T* head, char* output) {
    int offset = 0;

    while (head != NULL) {
        // Serialize RX_UE_INFORMATION_TAG
        memcpy(output + offset, head->RX_UE_INFORMATION_TAG, strlen(head->RX_UE_INFORMATION_TAG));
        offset += strlen(head->RX_UE_INFORMATION_TAG);

        // Serialize RNTI
        memcpy(output + offset, &head->RNTI, sizeof(int));
        offset += sizeof(int);

        // Serialize CRC_INDICATION_REL8_TAG
        memcpy(output + offset, head->CRC_INDICATION_REL8_TAG, strlen(head->CRC_INDICATION_REL8_TAG));
        offset += strlen(head->CRC_INDATION_REL8_TAG);

        // Serialize CRCFLAG
        memcpy(output + offset, &head->CRCFLAG, sizeof(int));
        offset += sizeof(int);

        head = head->next;
    }

    return offset;
}

int main() {
    int n = 10000; // Number of elements to create

    NFAPI_CRC_INDICATION_PDU_T* linked_list = create_linked_list(n);

    // Serialize the linked list
    char buffer[1024];
    int serialized_size = serialize_linked_list(linked_list, buffer);

    printf("Serialized size: %d\n", serialized_size);

    return 0;
}
