void *lteseion_init(size_t initial_capacity) {
    return calloc(1, sizeof(lte_ue_session));
}

int lteseion_add_pdu(void *lte_session, const uint8_t *pdu_data, size_t pdu_size) {
    // Revalidate the entire PDU list upon any operation
    if (lteseion_validate_pdu_list(lte_session) != 0) return -1;

    lte_ue_session *session = (lte_ue_session *) lte_session;
    struct lte_pdu_t **pdu_list = session->pdus;
    size_t pdu_count = session->pdus_count;

    // Allocate a new PDU and update the list
    struct lte_pdu_t *new_pdu = malloc(sizeof(struct lte_pdu_t));
    if (!new_pdu) return -1;  // Out of memory

    // Set timestamp for logging purposes
    new_pdu->timestamp = time(NULL);

    memcpy(new_pdu->pdu_data, pdu_data, pdu_size);
    new_pdu->size = pdu_size;

    // Update the PDU list and count
    if (pdu_count >= initial_capacity) {
        // Reallocate the PDU list with double the capacity
        size_t new_capacity = initial_capacity * 2;
        struct lte_pdu_t **new_list = realloc(pdu_list, new_capacity * sizeof(*pdu_list));
        if (!new_list) return -1;  // Out of memory

        pdu_list = new_list;
    }

    pdu_list[pdu_count] = new_pdu;
    session->pdus_count++;

    return 0;  // Success
}

int lteseion_remove_pdu(void *lte_session, uint16_t seq_num) {
    // Revalidate the entire PDU list upon any operation
    if (lteseion_validate_pdu_list(lte_session) != 0) return -1;

    lte_ue_session *session = (lte_ue_session *) lte_session;
    struct lte_pdu_t **pdu_list = session->pdus;
    size_t pdu_count = session->pdus_count;

    for (size_t i = 0; i < pdu_count; i++) {
        if (pdu_list[i]->seq_num == seq_num) {
            free(pdu_list[i]);
            memmove(&pdu_list[i], &pdu_list[i + 1], sizeof(*pdu_list) * (pdu_count - i));
            session->pdus_count--;
            return 0;  // Success
        }
    }

    return -1;  // PDU not found
}

int lteseion_merge_sessions(void *lte_session, void *other_session) {
    lte_ue_session *this_session = (lte_ue_session *) lte_session;
    lte_ue_session *other_session = (lte_ue_session *) other_session;

    if (this_session->ue_id == other_session->ue_id) {
        // Merge PDUs
        for (size_t i = 0; i < other_session->pdus_count; i++) {
            struct lte_pdu_t *pdu = other_session->pdus[i];
            this_session->pdus = realloc(this_session->pdus, (this_session->pdus_count + i + 1) * sizeof(*this_session->pdus));
            memcpy(&this_session->pdus[this_session->pdus_count], pdu, sizeof(*pdu));
            this_session->pdus_count++;
        }

        free(other_session);
        return 0;  // Success
    }

    return -1;  // Sessions do not match
}

void lteseion_log_event(void *lte_session, int event_type) {
    lte_ue_session *session = (lte_ue_session *) lte_session;

