    NFAPI_RRC_STATE RRC_STATE;
    size_t pdu_count;
    NFAPI_UL_CCCH_pdu_t** puds;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* nfapi_rrc_uecontext_new(size_t initial_capacity) {
    NFAPI_RRC_UECONTEXT_T* context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!context) return NULL;

    context->puds = (NFAPI_UL_CCCH_pdu_t**)calloc(initial_capacity, sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!context->puds) {
        free(context);
        return NULL;
    }

    context->pdu_count = 0;
    return context;
}

void nfapi_rrc_uecontext_free(NFAPI_RRC_UECONTEXT_T** context) {
    if (*context) {
        for (size_t i = 0; i < (*context)->pdu_count; i++) {
            free((*context)->puds[i]);
        }
        free((*context)->puds);
        free(*context);
        *context = NULL;
    }
}

void nfapi_rrc_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!context || !pdu) return;

    size_t new_capacity = context->pud_count + 1;
    NFAPI_UL_CCCH_pdu_t** new_puds = (NFAPI_UL_CCCH_pdu_t**)realloc(context->puds, new_capacity * sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!new_puds) return;

    context->puds = new_puds;
    context->pds[context->pdu_count++] = pdu;
}

void nfapi_rrc_uecontext_insert_pdu_at(NFAPI_RRC_UECONTEXT_T* context, size_t index, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!context || !pdu) return;

    if (index >= context->pdu_count) {
        // Insert at the end
        nfapi_rrc_uecontext_add_pdu(context, pdu);
        return;
    }

    size_t new_capacity = context->pud_count + 1;
    NFAPI_UL_CCCH_pdu_t** new_puds = (NFAPI_UL_CCCH_pdu_t**)realloc(context->puds, new_capacity * sizeof(NFAPI_UL_CCCH_pdu_t*));
    if (!new_puds) return;

    context->puds = new_puds;
    for (size_t i = context->pdu_count; i > index; i--) {
        context->puds[i] = context->puds[i - 1];
    }
    context->puds[index] = pdu;
    context->pdu_count++;
}

void nfapi_rrc_uecontext_remove_pdu_at(NFAPI_RRC_UECONTEXT_T* context, size_t index) {
    if (!context) return;

    if (index >= context->pdu_count) return;

    for (size_t i = index; i < context->pdu_count - 1; i++) {
        context->puds[i] = context->puds[i + 1];
    }
    free(context->puds[context->pdu_count - 1]);
    --context->pdu_count;
}

void nfapi_rrc_uecontext_iterate(NFAPI_RRC_UECONTEXT_T* context, void (*callback)(NFAPI_UL_CCCH_pdu_t*)) {
    if (!context) return;

    for (size_t i = 0; i < context->pdu_count; i++) {
        callback(context->puds[i]);
    }
}
