// Enumerate error codes for memory allocation failures
typedef enum {
    MEMORY_ALLOCATION_FAILURE,
    INSUFFICIENT_MEMORY,
    OUT_OF_BOUNDS
} MemoryError;

// Structure for the finite state automaton (FSA)
typedef struct FSA {
    int* states;
    int num_states;
    int last_state;
} FSA;

// Function to construct a new state list from an FSA while managing memory efficiently
FSA* create_new_state_list(int** states, int num_states, FSA* fsa, int last_state) {
    // Check if sufficient memory is available
    void* ptr = malloc(sizeof(FSA));
    if (ptr == NULL) {
        return NULL;
    }

    // Initialize the new state list structure
    FSA* new_fsa = (FSA*)ptr;
    new_fsa->num_states = num_states + 1; // Add one for the new state list

    // Allocate memory for the new state list
    int** new_states = (int**)malloc(sizeof(int*) * (new_fsa->num_states));
    if (new_states == NULL) {
        free(ptr);
        return NULL;
    }

    // Copy the existing states to the new state list
    for (int i = 0; i < num_states; i++) {
        int* ptr_state = malloc(sizeof(int));
        if (ptr_state == NULL) {
            free(new_states);
            free(ptr);
            return NULL;
        }
        *ptr_state = *(states[i]);
        new_states[i] = ptr_state;
    }

    // Add the new state list to the end of the existing states
    int* ptr_new_state_list = malloc(sizeof(int));
    if (ptr_new_state_list == NULL) {
        free(new_states);
        free(ptr);
        return NULL;
    }
    *ptr_new_state_list = last_state + 1; // Increment by one for the new state list

    new_states[num_states] = ptr_new_state_list;

    // Update the 'next' pointer of the last state in the input list to point to the new state list
    states[last_state]->next = new_states;

    // Free the original state list and its memory
    for (int i = 0; i < num_states; i++) {
        free(states[i]);
    }
    free(states);

    return new_fsa;
}
