typedef struct {
    uint32_t length;
    char data[NFAPI_UL_CCCH_PDU_T_SIZE];
} NFAPI_UL_CCCH_pdu_t;

typedef struct {
    NFAPI_RRC_UECONTEXT_T* contexts;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} NFAPI_RRC_UECONTEXT_ARRAY_T;

NFAPI_RRC_UECONTEXT_ARRAY_T* nfaapi_rrc_uecontext_array_create(size_t initial_capacity) {
    NFAPI_RRC_UECONTEXT_ARRAY_T* array = malloc(sizeof(NFAPI_RRC_UECONTEXT_ARRAY_T));
    if (!array) return NULL;
    array->contexts = calloc(initial_capacity, sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!array->contexts) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void nfaapi_rrc_uecontext_array_destroy(NFAPI_RRC_UECONTEXT_ARRAY_T* array) {
    if (!array) return;
    for (size_t i = 0; i < array->size; i++) {
        free(array->contexts[i].pdu_list);
    }
    free(array->contexts);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int nfaapi_rrc_uecontext_array_add(NFAPI_RRC_UECONTEXT_ARRAY_T* array, NFAPI_RRC_UECONTEXT_T* context) {
    if (!array || !context) return -1;
    pthread_mutex_lock(&array->lock);
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->contexts = realloc(array->contexts, sizeof(NFAPI_RRC_UECONTEXT_T) * array->capacity);
    }
    context->pdu_list = malloc(NFAPI_UL_CCCH_PDU_T_SIZE);
    if (!context->pdu_list) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    array->contexts[array->size] = *context;
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int nfaapi_rrc_uecontext_array_insert(NFAPI_RRC_UECONTEXT_ARRAY_T* array, size_t index, NFAPI_RRC_UECONTEXT_T* context) {
    if (!array || !context) return -1;
    pthread_mutex_lock(&array->lock);
    if (index > array->size) return -1;
    for (size_t i = array->size; i > index; i--) {
        NFAPI_RRC_UECONTEXT_T* temp = &array->contexts[i-1];
        *temp = array->contexts[i];
    }
    context->pdu_list = malloc(NFAPI_UL_CCCH_PDU_T_SIZE);
    if (!context->pdu_list) {
        pthread_mutex_unlock(&array->lock);
        return -1;
    }
    array->contexts[index] = *context;
    array->size++;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int nfaapi_rrc_uecontext_array_remove(NFAPI_RRC_UECONTEXT_ARRAY_T* array, size_t index) {
    if (!array || index >= array->size) return -1;
    pthread_mutex_lock(&array->lock);
    for (size_t i = index; i < array->size-1; i++) {
