LTE_UESession* create_ue_session(uint32_t ue_id) {
    LTE_UESession* session = (LTE_UESession*)malloc(sizeof(LTE_UESession));
    session->ue_id = ue_id;
    session->rrc_state = 0;
    session->pdus = NULL;
    return session;
