void add_pdu_to_ue_session(LTE_UESession* session, LTE_PDCP_PDU_t pdu) {
    // Revalidate the entire PDU list upon adding a new PDU
    revalidate_pdu_list(session);

    // Check for out-of-sequence PDUs
    if (pdu.timestamp < get_last_timestamp(session->pdus)) {
        report_out_of_sequence_pdu(session, pdu);
    } else {
        // Add the new PDU to the list and update last timestamp
        session->pdus = realloc(session->pdus, sizeof(LTE_PDCP_PDU_t) * (session->pdus ? session->pdus->count + 1 : 1));
        session->pdus->last_timestamp = pdu.timestamp;
    }
}

void merge_ue_sessions(LTE_UESession* dest, LTE_UESession* src) {
    if (src->ue_id == dest->ue_id && src->rrc_state == dest->rrc_state) {
        // Merge PDUs and update last timestamp
        dest->pdus = realloc(dest->pdus, sizeof(LTE_PDCP_PDU_t) * (dest->pdus ? dest->pdus->count + src->pdus->count : src->pdus->count));
        memcpy(dest->pdus->last_timestamp = src->pdus->last_timestamp;
    } else {
        // Handle mismatched UE_IDs or RRC States
    }
}

void export_ue_session_to_file(LTE_UESession* session) {
    FILE* file = fopen("ue_session.txt", "w");
    if (file != NULL) {
        fwrite(&session->ue_id, sizeof(uint32_t), 1, file);
        fwrite(&session->rrc_state, sizeof(int), 1, file);
        // Write PDUs to the file
        for (int i = 0; i < session->pdus->count; i++) {
            fwrite(&session->pdus[i].timestamp, sizeof(uint64_t), 1, file);
        }
    }
}

void revalidate_pdu_list(LTE_UESession* session) {
    // Revalidate the entire PDU list upon any operation
    for (int i = 0; i < session->pdus->count; i++) {
        if (session->pdus[i].timestamp < get_last_timestamp(session->pdus)) {
            report_out_of_sequence_pdu(session, session->pdus[i]);
        }
    }
}

void report_out_of_sequence_pdu(LTE_UESession* session, LTE_PDCP_PDU_t pdu) {
    // Report out-of-sequence PDU and handle accordingly
}

uint64_t get_last_timestamp(struct LTE_PDCP_PDU_t* pdus) {
    if (!pdus) return 0;
    return pdus->last_timestamp;
}

int main() {
    // Initialize UE session management thread
    pthread_create(&ue_session_mgmt_thread, NULL, ue_session_mgmt_thread_func, NULL);

    // Handle periodic updates to UE states and PDUs from the NMS
    while (1) {
        // Read updated UE state and PDU data from the NMS
        LTE_UESession* new_ue_session = read_ue_state_from_nms();
        if (!new_ue_session) break;

