    num_cell_contexts = 0;
}

void add_connection(int cell_id, int connection_info_id) {
    // Find the corresponding CellContext
    for (int i = 0; i < num_cell_contexts; i++) {
        if (cell_contexts[i].cell_id == cell_id) {
            // Add new connection info to the list
            cell_contexts[i].connections = realloc(cell_contexts[i].connections, (num_cell_contexts[i].connections + 1) * sizeof(CellConnectionInfo));
            cell_contexts[i].connections[num_cell_contexts[i].connections++] = malloc(sizeof(CellConnectionInfo));
            ((CellConnectionInfo*)cell_contexts[i].connections[num_cell_contexts[i].connections - 1])->connection_info_id = connection_info_id;
            return;
        }
    }
