        if (cell_contexts[i].cell_id == cell_id) {
            // Update the existing connection info in the list
            for (int j = 0; j < cell_contexts[i].connections; j++) {
                if (((CellConnectionInfo*)cell_contexts[i].connections[j])->connection_info_id == connection_info_id) {
                    // Update the fields of the existing CellConnectionInfo
                    return;
                }
            }
            // Handle error: Connection ID not found in this CellContext
        }
    }
    // Handle error: Cell ID not found
}

void remove_connection(int cell_id, int connection_info_id) {
    // Find the corresponding CellContext and remove the connection info
    for (int i = 0; i < num_cell_contexts; i++) {
        if (cell_contexts[i].cell_id == cell_id) {
            // Remove the specified connection info from the list
            int j;
            for (j = 0; j < cell_contexts[i].connections; j++) {
                if (((CellConnectionInfo*)cell_contexts[i].connections[j])->connection_info_id == connection_info_id) {
                    break;
                }
            }
            // Shift and reassign the remaining connections
            memmove(&cell_contexts[i].connections[j], &cell_contexts[i].connections[j + 1], (num_cell_contexts[i].connections - j - 1) * sizeof(CellConnectionInfo));
            cell_contexts[i].connections--;
            free(cell_contexts[i].connections[j]);
            return;
        }
