from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend

def generate_modified_kickstart_file(path_to_kickstart_file, encryption_algorithm, placeholder_values):
    # Load the Kickstart file as a dictionary
    with open(path_to_kickstart_file, 'r') as f:
        kickstart_data = json.load(f)

    # Validate the structure of the Kickstart file against the predefined schema
    if not validate_schema(kickstart_data):
        raise ValueError("Invalid Kickstart file structure")

    # Replace placeholders within the file with actual values provided through the dictionary
    for key, value in placeholder_values.items():
        kickstart_data[key] = value

    # Encrypt the replaced values using the specified encryption algorithm
    encrypted_values = {}
    if encryption_algorithm == "aes-256-cbc":
        for key, value in kickstart_data.items():
            encrypted_value = OpenSSL.rand.bytes_random(32)
            encrypted_values[key] = encrypted_value.hex()
            print(f"Encrypted {key} with AES-256-CBC: {encrypted_value.hex()}")
    elif encryption_algorithm == "rsa-4096":
        for key, value in kickstart_data.items():
            encrypted_value = serialization.load_pem_public_key(OpenSSL.rand.generate_key("RSA", 4096), default_backend()).encrypt(value.encode())
            encrypted_values[key] = encrypted_value.hex()
            print(f"Encrypted {key} with RSA-4096: {encrypted_value.hex()}")
    else:
        raise ValueError("Unsupported encryption algorithm")

    # Write the encrypted values back to the Kickstart file
    with open(path_to_kickstart_file, 'w') as f:
        json.dump(encrypted_values, f)

    # Add a new line containing the encrypted password to the file
    with open(path_to_kickstart_file, 'a') as f:
        f.write("password: " + encrypted_password.hex() + "\n")

def validate_schema(kickstart_data):
    # Predefined schema for Kickstart files
    schema = {
        "network": {"ip": str},
        "storage": {"size": int}
    }

    # Check if the Kickstart file structure matches the predefined schema
    return all(isinstance(key, str) and isinstance(value, dict) for key, value in kickstart_data.items() if key in schema)

def main():
    import argparse
    parser = argparse.ArgumentParser()
    parser.add_argument("-p", "--path_to_kickstart_file", help="Path to the Kickstart file")
    parser.add_argument("-a", "--encryption_algorithm", help="Encryption algorithm (aes-256-cbc, rsa-4096)")
    parser.add_argument("-v", "--placeholder_values", help="JSON string of placeholder values")

    args = parser.parse_args()
    path_to_kickstart_file = args.path_to_kickstart_file
    encryption_algorithm = args.encryption_algorithm
    placeholder_values = json.loads(args.placeholder_values)

    try:
        generate_modified_kickstart_file(path_to_kickstart_file, encryption_algorithm, placeholder_values)
    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

if __name__ == "__main__":
    main()
