#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int id;
    enum { ESTABLISHED, SYN_SENT, FIN_WAIT_1, FIN_WAIT_2, TIME_WAIT, CLOSED } state;
    struct TCPDataPacket* packets;
} TCPConnection;

typedef struct {
    time_t timestamp;
    int sequenceNumber;
} TCPDataPacket;

void initTCPConnection(TCPConnection** connection, int id) {
    *connection = (TCPConnection*)malloc(sizeof(TCPConnection));
    (*connection)->id = id;
    (*connection)->state = ESTABLISHED;
    (*connection)->packets = NULL;
}

void addTCPDataPacket(TCPConnection* connection, TCPDataPacket* packet) {
    if (!connection->packets) {
        connection->packets = (TCPDataPacket*)malloc(sizeof(TCPDataPacket));
        *(connection->packets) = *packet;
    } else {
        TCPDataPacket* newPacket = (TCPDataPacket*)malloc(sizeof(TCPDataPacket));
        *(newPacket) = *packet;
        TCPDataPacket** packets = &connection->packets;
        while (*packets && (*packets)->sequenceNumber < packet->sequenceNumber)
            *packets = ((TCPDataPacket*)realloc(*packets, sizeof(TCPDataPacket)));
        *packets = newPacket;
    }
}

void mergeTCPConnections(TCPConnection** connection1, TCPConnection** connection2) {
    if ((*connection1)->id == (*connection2)->id) {
        (*connection1)->state = ESTABLISHED;
        if (!(*connection1)->packets) {
            (*connection1)->packets = *connection2->packets;
        } else {
            TCPDataPacket** packets = &(*connection1)->packets;
            while (*packets && *packets->sequenceNumber < connection2->packets->sequenceNumber)
                *packets = ((TCPDataPacket*)realloc(*packets, sizeof(TCPDataPacket)));
            *packets = connection2->packets;
        }
    }
}

void exportTCPConnections(TCPConnection* connection) {
    FILE* file = fopen("tcp_connections.txt", "w");
    if (file) {
        fprintf(file, "%d\n", connection->id);
        for (TCPDataPacket* packet = connection->packets; packet; packet = packet->next)
            fprintf(file, "%ld %d\n", packet->timestamp, packet->sequenceNumber);
        fclose(file);
    }
}

void tcpConnectionLogger(TCPConnection* connection) {
    FILE* file = fopen("tcp_connection_log.txt", "a");
    if (file) {
        fprintf(file, "TCP Connection ID: %d\n", connection->id);
        fprintf(file, "State: %s\n", (connection->state == ESTABLISHED ? "ESTABLISHED" : (connection->state == SYN_SENT ? "SYN_SENT" : (connection->state == FIN_WAIT_1 ? "FIN_WAIT_1" : (connection->state == FIN_WAIT_2 ? "FIN_WAIT_2" : (connection->state == TIME_WAIT ? "TIME_WAIT" : "CLOSED")))));
        for (TCPDataPacket* packet = connection->packets; packet; packet = packet->next)
            fprintf(file, "%ld %d\n", packet->timestamp, packet->sequenceNumber);
        fclose(file);
    }
}

int main() {
    TCPConnection* connection1 = NULL;
    initTCPConnection(&connection1, 1);

    TCPConnection* connection2 = NULL;
    initTCPConnection(&connection2, 2);

    addTCPDataPacket(connection1, (TCPDataPacket){.timestamp = time(NULL), .sequenceNumber = 0});
    addTCPDataPacket(connection2, (TCPDataPacket){.timestamp = time(NULL), .sequenceNumber = 10});

    mergeTCPConnections(&connection1, &connection2);

    exportTCPConnections(connection1);
    tcpConnectionLogger(connection1);

    return 0;
}
