// Thread-safe collection of MAC contexts
struct {
    NFIXX_MAC_CONTEXT_T* contexts;
    size_t num_contexts;
    pthread_mutex_t lock;
} mac_ctx_collection;

void init_mac_ctx_collection() {
    mac_ctx_collection.contexts = NULL;
    mac_ctx_collection.num_contexts = 0;
    pthread_mutex_init(&mac_ctx_collection.lock, NULL);
}

int add_mac_context(NFIXX_MAC_CONTEXT_T* context) {
    pthread_mutex_lock(&mac_ctx_collection.lock);

    NFIXX_MAC_CONTEXT_T** new_contexts = realloc(mac_ctx_collection.contexts,
        (mac_ctx_collection.num_contexts + 1) * sizeof(NFIXX_MAC_CONTEXT_T*));
    if (!new_contexts) {
        pthread_mutex_unlock(&mac_ctx_collection.lock);
        return -ENOMEM;
    }
    mac_ctx_collection.contexts = new_contexts;

    mac_ctx_collection.contexts[mac_ctx_collection.num_contexts] = context;
    mac_ctx_collection.num_contexts++;

    pthread_mutex_unlock(&mac_ctx_collection.lock);

    return 0;
}

int remove_mac_context(uint32_t mac_id) {
    pthread_mutex_lock(&mac_ctx_collection.lock);

    for (size_t i = 0; i < mac_ctx_collection.num_contexts; i++) {
        if (mac_ctx_collection.contexts[i]->mac_id == mac_id) {
            free(mac_ctx_collection.contexts[i]->pdu_list.pdus);
            memmove(&mac_ctx_collection.contexts[i],
                &mac_ctx_collection.contexts[i + 1],
                (mac_ctx_collection.num_contexts - i - 1) * sizeof(NFIXX_MAC_CONTEXT_T*));
            mac_ctx_collection.num_contexts--;
            free(mac_ctx_collection.contexts[i]);
            break;
        }
    }

    pthread_mutex_unlock(&mac_ctx_collection.lock);

    return 0;
}

int get_mac_context(uint32_t mac_id, NFIXX_MAC_CONTEXT_T** context) {
    pthread_mutex_lock(&mac_ctx_collection.lock);

    for (size_t i = 0; i < mac_ctx_collection.num_contexts; i++) {
        if (mac_ctx_collection.contexts[i]->mac_id == mac_id) {
            *context = mac_ctx_collection.contexts[i];
            pthread_mutex_unlock(&mac_ctx_collection.lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&mac_ctx_collection.lock);

    return -ENOTFOUND;
}

void free_mac_ctx_collection() {
    pthread_mutex_lock(&mac_ctx_collection.lock);

    for (size_t i = 0; i < mac_ctx_collection.num_contexts; i++) {
        free(mac_ctx_collection.contexts[i]->pdu_list.pdus);
        free(mac_ctx_collection.contexts[i]);
    }
    free(mac_ctx_collection.contexts);

    pthread_mutex_unlock(&mac_ctx_collection.lock);
}
