#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CHUNK_SIZE 5000
#define MAX_LINE_LENGTH 1024

// Structure to hold transaction data
typedef struct {
    char line[MAX_LINE_LENGTH];
    double avg_amount;
} Transaction;

// Function to process a chunk of transactions and calculate averages
void* process_chunk(void* arg) {
    int i, j;
    Transaction* transactions = (Transaction*)arg;
    int num_transactions = CHUNK_SIZE;

    // Calculate average transaction amount over the last three transactions for each line
    for(i = 0; i < num_transactions; i++) {
        char* token = strtok(transactions[i].line, ",");
        double sum = 0.0;
        for(j = 1; j <= 3 && token != NULL; j++, token = strtok(NULL, ",")) {
            sum += atof(token);
        }
        if(j > 1) {
            transactions[i].avg_amount = sum / (double)(j - 1);
        } else {
            transactions[i].avg_amount = 0.0;
        }
    }

    // Calculate running total and overall average
    double running_total = 0.0;
    for(i = 0; i < num_transactions; i++) {
        running_total += transactions[i].avg_amount;
    }
    double overall_avg = running_total / (double)num_transactions;

    return NULL;
}

// Function to write processed transactions to a file
void write_processed_transactions(Transaction* transactions, int num_transactions) {
    FILE* fptr = fopen("processed_transactions.txt", "w");

    for(int i = 0; i < num_transactions; i++) {
        fprintf(fptr, "%s,%.2f\n", transactions[i].line, transactions[i].avg_amount);
    }

    fclose(fptr);
}

int main() {
    // Open the file and initialize variables
    FILE* fptr = fopen("transactions.txt", "r");
    char line[MAX_LINE_LENGTH];
    int chunk_num = 0;
    pthread_t threads[5];
    Transaction* transactions[5];
    double running_total = 0.0;

    // Process each chunk of transactions in parallel using multiple threads
    while(fgets(line, sizeof(line), fptr)) {
        if(ferror(fptr) != 0) {
            break;
        }

        char* token = strtok(line, ",");
        int num_transactions = 1; // Initial number of transactions in the current chunk

        // Determine the number of transactions in the current chunk
        while(token != NULL && (token[0] == 'T' || token[0] == '\n')) {
            if(num_transactions >= CHUNK_SIZE) {
                break;
            }

            fgets(line, sizeof(line), fptr);
            num_transactions++;
        }

        // Allocate memory for transactions and process the chunk
        Transaction* chunk = (Transaction*)malloc(num_transactions * sizeof(Transaction));
        for(int i = 0; i < num_transactions; i++) {
            strcpy(chunk[i].line, line);
            chunk[i].avg_amount = 0.0;
        }

        pthread_create(&threads[chunk_num], NULL, process_chunk, chunk);
        transactions[chunk_num] = chunk;
        chunk_num++;

        // Reset the file pointer to the beginning of the next chunk
        if(num_transactions >= CHUNK_SIZE) {
            fseek(fptr, -num_transactions * (MAX_LINE_LENGTH + 1), SEEK_CUR);
        } else {
            rewind(fptr);
        }
    }

    // Wait for all threads to finish and calculate overall average
    for(int i = 0; i < chunk_num; i++) {
        pthread_join(threads[i], NULL);

        running_total += transactions[i]->avg_amount;
    }

    double overall_avg = running_total / (double)num_transactions;

    // Write processed transactions to a file and send analytics data
    write_processed_transactions(transactions, num_transactions);

    return 0;
}
