#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define CHUNK_SIZE 5000
#define AVERAGE_WINDOW 5

typedef struct {
    char* buffer;
    int size;
} chunk_t;

void* process_chunk(void* arg) {
    chunk_t* chunk = (chunk_t*)arg;
    FILE* file = fopen("output.txt", "a");
    double total_average = 0.0;
    int transactions_processed = 0;

    while (chunk->size > 0) {
        char* line = chunk->buffer;
        int transaction_amount = atoi(line + strlen(line) - 1);
        // Calculate average transaction amount
        double sum = 0.0;
        for (int i = 0; i < AVERAGE_WINDOW && i < transactions_processed; i++) {
            sum += transaction_amounts[i];
        }
        if (transactions_processed >= AVERAGE_WINDOW)
            total_average = sum / AVERAGE_WINDOW;

        // Append average to the line
        char* newline = (char*)malloc(strlen(line) + 20);
        strcpy(newline, line);
        strcat(newline, ",");
        sprintf(&newline[strlen(line)], "%f", total_average);
        int bytes_written = fwrite(newline, sizeof(char), strlen(newline), file);
        if (bytes_written != strlen(newline)) {
            printf("Error writing to file\n");
            return NULL;
        }
        free(newline);

        // Update transaction counts and amounts
        transactions_processed++;
        transaction_amounts[transactions_processed % AVERAGE_WINDOW] = transaction_amount;

        chunk->buffer += strlen(line) + 1;
        chunk->size -= strlen(line) + 1;
    }

    fclose(file);
    return NULL;
}

int main() {
    pthread_t threads[100];
    int num_threads = (int)sqrt(CHUNK_SIZE / AVERAGE_WINDOW);

    // Initialize transaction amounts array
    double* transaction_amounts = (double*)malloc(AVERAGE_WINDOW * sizeof(double));
    for (int i = 0; i < AVERAGE_WINDOW; i++)
        transaction_amounts[i] = 0.0;

    FILE* file = fopen("input.txt", "r");
    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    rewind(file);

    int num_chunks = (int)(file_size / CHUNK_SIZE) + 1;
    chunk_t chunks[num_chunks];
    for (int i = 0; i < num_chunks; i++) {
        fseek(file, i * CHUNK_SIZE, SEEK_SET);
        int bytes_read = fread(chunks[i].buffer, sizeof(char), CHUNK_SIZE, file);
        chunks[i].size = bytes_read;
        if (i > 0)
            pthread_create(&threads[i - 1], NULL, process_chunk, &chunks[i - 1]);
    }

    // Process last chunk
    int bytes_read = fread(chunks[num_chunks - 1].buffer, sizeof(char), file_size % CHUNK_SIZE, file);
    chunks[num_chunks - 1].size = bytes_read;
    pthread_create(&threads[num_chunks - 2], NULL, process_chunk, &chunks[num_chunks - 2]);

    for (int i = 0; i < num_threads; i++)
        pthread_join(threads[i], NULL);

    // Calculate overall average
    double total_sum = 0.0;
    for (int i = 0; i < AVERAGE_WINDOW; i++) {
        total_sum += transaction_amounts[i];
    }
    printf("Overall average: %f\n", total_sum / AVERAGE_WINDOW);

    return 0;
}
