// Function to periodically check and release unused memory
void manage_memory(Node* head) {
    // Check for unused nodes in the linked list
    Node* current = head;
    while (current != NULL && current->next != NULL) {
        if (!current->next->data) {  // Unused node found
            Node* next = current->next;
            current->next = next->next;
            free(next);
        }
        current = current->next;
