        printf("RNTI: %d, CRCFLAG: %d\n", current->pdu.rnti, current->pdu.crcflag);
        current = current->next;
    }
}

// Define array structure
typedef struct {
    NFPAI_RRC_CELL_CONTEXT_T* contexts;
    int size;
} Array;

Array* create_array(int size) {
    Array* new_array = (Array*) malloc(sizeof(Array));
    if (!new_array) {
        return NULL;
    }
    new_array->contexts = (NFPAI_RRC_CELL_CONTEXT_T*) malloc(size * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
    new_array->size = size;
    return new_array;
}

void free_array(Array* array) {
    if (!array) {
        return;
    }
    free(array->contexts);
    free(array);
}

// Define functions for linked list
Node* insert_node(Node* head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    Node* new_node = create_node(pdu);
    if (!head) {
        return new_node;
    }
    Node* current = head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = new_node;
    return head;
}

void remove_node(Node** head, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!*head) {
        return;
    }
    Node* current = *head;
    while (current != NULL && current->pdu.rnti != pdu.rnti) {
        current = current->next;
    }
    if (current == NULL || current->pdu.rnti != pdu.rnti) {
        return;
    }
    Node* temp = current->next;
    free(current);
    *head = temp;
}

// Define functions for array
void add_context(Array* array, int cell_id, char* connection_info) {
    if (array->size <= 0) {
        return;
    }
    NFPAI_RRC_CELL_CONTEXT_T* context = &array->contexts[array->size - 1];
    context->cell_id = cell_id;
    context->connection_info = connection_info;
}

void remove_context(Array* array, int cell_id) {
    if (array->size <= 0) {
        return;
    }
    NFPAI_RRC_CELL_CONTEXT_T* context = &array->contexts[0];
    for (int i = 0; i < array->size; i++) {
        if (context->cell_id == cell_id) {
            free(context->connection_info);
            memcpy(&array->contexts[i], &array->contexts[i + 1], (array->size - i - 1) * sizeof(NFPAI_RRC_CELL_CONTEXT_T));
            array->size--;
            return;
        }
        context++;
    }
}

// Define command line arguments
int main(int argc, char** argv) {
    // Initialize linked list and array
    Node* head = NULL;
    Array* array = create_array(10000);

    // Read lines from input files
    FILE* file1 = fopen("file1.txt", "r");
    FILE* file2 = fopen("file2.txt", "r");

    // Process files
    while (fscanf(file1, "%s\n") == 1) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Process line and add to linked list
        head = insert_node(head, pdu);
    }
    fclose(file1);

    while (fscanf(file2, "%s\n") == 1) {
        NFPAI_RRC_CELL_CONTEXT_T context;
        // Process line and add to array
        add_context(array, context.cell_id, context.connection_info);
    }
    fclose(file2);

    // Print linked list
    print_list(head);

    // Remove nodes from linked list
    remove_node(&head, pdu);

    // Free memory
    free_array(array);

    return 0;
}
