// Function to handle thread operations
void* crc_indication_thread_func(void*) {
    int i = 0;

    while (i < MAX_ARRAY_SIZE) {
        // Allocate memory for new structure...
        NFAPI_CRC_INDICATION_PDU_T* p = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (p == NULL)
            return NULL;  // Memory allocation failure...

