        int result = validate_struct(p);
        if (result != 0) {
            free(p);  // Discard invalid structure and log error...
            continue;
        }

        // Append valid structure to array
        append_to_array(p, i);

        i++;
    }

    return NULL;  // Thread operation complete.
}

