size_t nfapi_rrc_uecontext_array_size = 0;
pthread_mutex_t nfapi_rrc_uecontext_array_lock = PTHREAD_MUTEX_INITIALIZER;
int nfapi_rrc_uecontext_array_memory_usage = 0;

void nfapi_allocate_ue_context(int ue_id, RRC_STATE state) {
    NFAPI_RRC_UECONTEXT_T* new_ue_context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!new_ue_context) {
        printf("Memory allocation failure\n");
        return;
    }
    new_ue_context->ue_id = ue_id;
    new_ue_context->state = state;
    new_ue_context->pdu_list = NULL;
    new_ue_context->pdu_list_size = 0;
    pthread_mutex_lock(&nfapi_rrc_uecontext_array_lock);
    if (nfapi_rrc_uecontext_array_size >= MAX_UE_CONTEXTS) {
        printf("Memory warning: UE context array is full\n");
    }
    nfapi_rrc_uecontext_array = realloc(nfapi_rrc_uecontext_array, sizeof(NFAPI_RRC_UECONTEXT_T) * (nfapi_rrc_uecontext_array_size + 1));
    if (!nfapi_rrc_uecontext_array) {
        printf("Memory allocation failure\n");
        return;
    }
    nfapi_rrc_uecontext_array[nfapi_rrc_uecontext_array_size++] = new_ue_context;
    pthread_mutex_unlock(&nfapi_rrc_uecontext_array_lock);
}

void nfapi_free_ue_context(int ue_id) {
    int i;
    pthread_mutex_lock(&nfapi_rrc_uecontext_array_lock);
    for (i = 0; i < nfapi_rrc_uecontext_array_size; i++) {
        if (nfapi_rrc_uecontext_array[i]->ue_id == ue_id) {
            free(nfapi_rrc_uecontext_array[i]->pdu_list);
            free(nfapi_rrc_uecontext_array[i]);
            for (int j = i + 1; j < nfapi_rrc_uecontext_array_size; j++) {
                nfapi_rrc_uecontext_array[j - 1] = nfapi_rrc_uecontext_array[j];
            }
            nfapi_rrc_uecontext_array_size--;
            break;
        }
    }
    pthread_mutex_unlock(&nfapi_rrc_uecontext_array_lock);
}

