typedef struct NFNETLINK_MESSAGE_T {
    uint64_t message_id;
    uint8_t message_type;
    struct PDU *pdu_list;
    size_t pdu_count;
} NFNETLINK_MESSAGE_T;

typedef struct PDU {
    void *data;
    size_t data_size;
    struct PDU *next;
} PDU;

void nfnetlink_message_init(NFNETLINK_MESSAGE_T **message) {
    if (!(*message = (NFNETLINK_MESSAGE_T *)malloc(sizeof(NFNETLINK_MESSAGE_T)))) {
        return;
    }
    (*message)->pdu_list = NULL;
    (*message)->pdu_count = 0;
}

void nfnetlink_message_add_pdu(NFNETLINK_MESSAGE_T *message, void *data, size_t data_size) {
    PDU *new_pdu = (PDU *)malloc(sizeof(PDU));
    if (!new_pdu) return;

    new_pdu->data = malloc(data_size);
    if (!new_pdu->data) {
        free(new_pdu);
        return;
    }

    memcpy(new_pdu->data, data, data_size);
    new_pdu->data_size = data_size;
    new_pdu->next = NULL;

    if (message->pdu_list) {
        PDU *current = message->pdu_list;
        while (current->next) current = current->next;
        current->next = new_pdu;
    } else
        message->pdu_list = new_pdu;

    message->pdu_count++;
}

void nfnetlink_message_free(PDU **pdu_list, size_t *count) {
    PDU *current = *pdu_list;
    while (current) {
        PDU *next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    *count = 0;
}

int nfnetlink_message_validate(PDU *pdu_list, size_t count) {
    if (!pdu_list || count == 0)
        return 1;

    PDU *current = pdu_list;
    while (current && current->next) {
        current = current->next;
    }

    return (int)(current != NULL);
}

void nfnetlink_message_deinit(NFNETLINK_MESSAGE_T **message) {
    if (!*message) return;

    PDU *pdu_list = (*message)->pdu_list;
    size_t pdu_count = (*message)->pdu_count;

    (*message)->pdu_list = NULL;
    (*message)->pdu_count = 0;

    nfnetlink_message_free(&pdu_list, &pdu_count);

    free(*message);
    *message = NULL;
}
