#include <pthread.h>

// Define a structure to represent an event
typedef struct {
    int id;
    char* data;
} Event;

// Define a structure to represent a consumer
typedef struct {
    pthread_t thread_id;
    void (*callback)(Event*);
} Consumer;

// Define the event bus structure
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    Event** queue;
    int capacity, size, head, tail;
} EventBus;

// Initialize an event bus with a given capacity
EventBus* init_event_bus(int capacity) {
    EventBus* eb = (EventBus*)malloc(sizeof(EventBus));
    eb->queue = (Event**)malloc(capacity * sizeof(Event*));
    eb->capacity = capacity;
    eb->size = 0;
    eb->head = 0;
    eb->tail = 0;
    pthread_mutex_init(&eb->mutex, NULL);
    pthread_cond_init(&eb->cond, NULL);
    return eb;
}

// Publish an event to the event bus
void publish_event(Event* event, EventBus* eb) {
    pthread_mutex_lock(&eb->mutex);
    if (eb->size == eb->capacity) {
        // Handle overflow condition
        printf("Event bus is full. Discarding event.\n");
    } else {
        eb->queue[eb->tail] = event;
        eb->tail = (eb->tail + 1) % eb->capacity;
        eb->size++;
        pthread_cond_signal(&eb->cond);
    }
    pthread_mutex_unlock(&eb->mutex);
}

// Consume events from the event bus
void consume_events(EventBus* eb, Consumer consumer) {
    while (1) {
        pthread_mutex_lock(&eb->mutex);
        while (eb->size == 0) {
            pthread_cond_wait(&eb->cond, &eb->mutex);
        }
        Event* event = eb->queue[eb->head];
        eb->head = (eb->head + 1) % eb->capacity;
        eb->size--;
        pthread_mutex_unlock(&eb->mutex);
        consumer.callback(event);
    }
}

// Example usage:
int main() {
    EventBus* eb = init_event_bus(10);
    Consumer c;
    c.thread_id = pthread_self();
    c.callback = (void (*)(Event*))my_consumer_callback;

    // Publish events
    for (int i = 0; i < 5; i++) {
        Event* event = (Event*)malloc(sizeof(Event));
        event->id = i;
        event->data = "Hello, World!";
        publish_event(event, eb);
        free(event);
    }

    // Consume events
    consume_events(eb, c);

    return 0;
}

