    enum RRC_STATE rrc_state;
    struct map *connection_info_map;
} NFPAI_RRC_CELL_CONTEXT_T;

typedef struct {
    char *key;
    void *value;
} MAP_ENTRY_T;

typedef struct {
    MAP_ENTRY_T *entries;
    int size;
    int capacity;
} MAP_T;

NFPAI_RRC_CELL_CONTEXT_T *cells = NULL;
int cell_count = 0;

MAP_T connection_info_map;

void init_connection_info_map(int initial_capacity) {
    connection_info_map.entries = (MAP_ENTRY_T *)malloc(initial_capacity * sizeof(MAP_ENTRY_T));
    connection_info_map.size = 0;
    connection_info_map.capacity = initial_capacity;
}

void add_connection_info(int cell_id, char *key, void *value) {
    // validate integrity of connection information map
    for (int i = 0; i < connection_info_map.size; i++) {
        if (strcmp(connection_info_map.entries[i].key, key) == 0) {
            return; // duplicate key found
        }
    }

    // add new entry to map
    if (connection_info_map.size >= connection_info_map.capacity) {
        int new_capacity = connection_info_map.capacity * 2;
        MAP_ENTRY_T *new_entries = (MAP_ENTRY_T *)realloc(connection_info_map.entries, new_capacity * sizeof(MAP_ENTRY_T));
        connection_info_map.entries = new_entries;
        connection_info_map.capacity = new_capacity;
    }

    MAP_ENTRY_T new_entry = {key, value};
    connection_info_map.entries[connection_info_map.size++] = new_entry;
}

void update_connection_info(int cell_id, char *key, void *value) {
    // find entry in map with matching key
    for (int i = 0; i < connection_info_map.size; i++) {
        if (strcmp(connection_info_map.entries[i].key, key) == 0) {
            // update value and return
            connection_info_map.entries[i].value = value;
            return;
        }
    }

    // entry not found in map
    printf("Error: no such entry in map\n");
}

void remove_connection_info(int cell_id, char *key) {
    // find entry in map with matching key
    for (int i = 0; i < connection_info_map.size; i++) {
        if (strcmp(connection_info_map.entries[i].key, key) == 0) {
            // remove entry and shift remaining entries up
            for (int j = i + 1; j < connection_info_map.size; j++) {
                connection_info_map.entries[j - 1] = connection_info_map.entries[j];
            }
            connection_info_map.size--;
