void nfaapi_uecontext_init() {
    // Initialize dynamic array with initial capacity
    nfaapi_uecontexts = (NFAPI_RRC_UECONTEXT_T**)malloc(10 * sizeof(NFAPI_RRC_UECONTEXT_T*));
    nfaapi_num_uecontexts = 0;
