    // Allocate memory for new UE context
    NFAPI_RRC_UECONTEXT_T* uecontext = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    uecontext->ue_id = ue_id;
