    // Add PDU to UE context's list
    if (!uecontext->pdus.length) {
        uecontext->pdus.pdu = pdu;
        uecontext->pdus.length = 1;
    } else {
        // Reallocate memory for growing list
        NFAPI_UL_CCCH_pdu_t** pdus = (NFAPI_UL_CCCH_pdu_t**)realloc(uecontext->pdus.pdu, (uecontext->pdus.length + 1) * sizeof(NFAPI_UL_CCCH_pdu_t*));
        pdus[uecontext->pdus.length++] = pdu;
    }

    // Add UE context to dynamic array
    nfaapi_uecontexts = (NFAPI_RRC_UECONTEXT_T**)realloc(nfaapi_uecontexts, ++nfaapi_num_uecontexts * sizeof(NFAPI_RRC_UECONTEXT_T*));
    nfaapi_uecontexts[nfaapi_num_uecontexts - 1] = uecontext;

    pthread_rwlock_unlock(&nfaapi_uecontext_lock);
}

void nfaapi_uecontext_validate() {
    pthread_rwlock_rdlock(&nfaapi_uecontext_lock);

    // Validate integrity of PDU lists
