}

// Function to add a new PDU to an existing UE context
void add_pdu(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (!ue_context || !pdu) {
        printf("Error: Invalid input.\n");
        return;
    }

    // Check integrity of PDU list before adding a new PDU
    if (ue_context->pdu_list.pdu_count >= ue_context->pdu_list.pdu_capacity) {
        // Increase the capacity of the PDU list
        size_t new_capacity = ue_context->pdu_list.pdu_capacity * 2;
        NFAPI_UL_CCCH_pdu_t* new_pdu_list = (NFAPI_UL_CCCH_pdu_t*)realloc(ue_context->pdu_list.pdu_list, new_capacity * sizeof(NFAPI_UL_CCCH_pdu_t));

        if (!new_pdu_list) {
