#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    int service_id;
    int status_code;
    double response_time;
} LogEntry;

LogEntry* read_log_file(const char* filename, size_t* entry_count) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return NULL;

    *entry_count = 0;
    LogEntry* entries = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Tokenize the line and allocate memory for a new entry
        int tokens = 1;
        if ((strtok(line, ",")) != NULL) tokens++;
        if ((strtok(NULL, ",")) != NULL) tokens++;
        if ((strtok(NULL, ",")) != NULL) tokens++;
        LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
        *new_entry = (LogEntry){0};

        // Parse the entry fields
        char* token = strtok(line, ",");
        if (token != NULL) {
            new_entry->timestamp = atoi(token);
            token = strtok(NULL, ",");
            if (token != NULL) new_entry->service_id = atoi(token);
            token = strtok(NULL, ",");
            if (token != NULL) {
                new_entry->status_code = atoi(token);
                token = strtok(NULL, ",");
                if (token != NULL && strlen(token) > 0) {
                    new_entry->response_time = atof(token);
                }
            }
        }

        // Add the entry to the list
        LogEntry** entries_ptr = &entries;
        size_t entry_idx = *entry_count++;
        while (*entries_ptr && entry_idx > 0) {
            --entry_idx;
            --(*entries_ptr);
        }
        if (entry_idx == 0) {
            *entries_ptr = new_entry;
        } else {
            LogEntry* prev_entry = *(--entries_ptr);
            free(prev_entry);
            *entries_ptr = new_entry;
        }
    }

    fclose(file);

    return entries;
}

void compute_aggregate_metrics(LogEntry** entries, size_t entry_count) {
    for (size_t i = 0; i < entry_count; ++i) {
        LogEntry* current_entry = entries[i];
        if (current_entry->status_code >= 200 && current_entry->status_code <= 299 && current_entry->response_time > 0) {
            // Compute the average response time over the last three valid entries
            double sum = 0;
            size_t count = 1;
            for (size_t j = i; j < entry_count; ++j) {
                LogEntry* next_entry = entries[j];
                if (next_entry->status_code >= 200 && next_entry->status_code <= 299 && next_entry->response_time > 0) {
                    sum += next_entry->response_time;
                    ++count;
                    if (count == 4) break;
                } else {
                    break;
                }
            }

            // Print the aggregate metric
            printf("Service %d: Average response time over last three valid entries = %.2f\n", current_entry->service_id, sum / count);
        }
    }
}

int main() {
    const char* filename = "log.txt";
    size_t entry_count;
    LogEntry* entries = read_log_file(filename, &entry_count);

    if (entries != NULL) {
        compute_aggregate_metrics(entries, entry_count);

        // Deallocate memory
        for (size_t i = 0; i < entry_count; ++i) {
            free(entries[i]);
        }
        free(entries);
    }

    return 0;
}

