    if (!newMCS)
        return -1;
    newMCS->mcsIndex = mcsIndex;
    newMCS->modulation = modulation;
    newMCS->codingScheme = codingScheme;

    // Add the new MCS configuration to the list
    phylayer->mcsConfigurations = realloc(phylayer->mcsConfigurations, 
        (phylayer->mcsConfigCount + 1) * sizeof(PhylayerConfig));
    if (!phylayer->mcsConfigurations)
        return -1;
    phylayer->mcsConfigurations[phylayer->mcsConfigCount++] = newMCS;

    return 0;
}

// Release resources for an LTE PHY layer configuration
void freephylayerconfig(PhylayerConfig* phylayer) {
    // Free each MCS configuration in the list
    for (int i = 0; i < phylayer->mcsConfigCount; i++) {
        free(phylayer->mcsConfigurations[i]);
    }
    free(phylayer->mcsConfigurations);
    free(phylayer);
}

// Example usage: demonstrate concurrent access and data integrity
