    // Initialize the dynamic array of LTE PHY layer configurations
    PhylayerConfig* phylayers = initphylayerconfig(10);

    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        // Create a new thread to add MCS configurations concurrently
        pthread_create(&threads[i], NULL, (void*)addMCSconfig_wrapper, phylayers);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++)
        pthread_join(threads[i]);

    // Release resources for the LTE PHY layer configuration
    freephylayerconfig(phylayers);

    return 0;
}

// Wrap addMCSconfig function for concurrent execution by threads
void* addMCSconfig_wrapper(void* phylayer) {
    PhylayerConfig* phylayer = (PhylayerConfig*)phylayer;
    // Add MCS configurations concurrently without introducing race conditions
    int mcsIndex, mcsCount = 0;
    float modulation, codingScheme;

    for (int i = 0; i < 5; i++) {
        mcsIndex = i % 10 + 1;
        modulation = (float)i / 2.0f;
        codingScheme = (float)(i * i) / 100.0f;
        addMCSconfig(phylayer, mcsIndex, modulation, codingScheme);
    }

    return NULL;
}
