#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the LTE PHY layer configuration structure
typedef struct {
    int bandwidth;
    float subcarrierSpacing;
    struct MCSConfig* mcsConfigs;
    int numMCSConfigs;
} PhyConfig;

// Define the MCS configuration structure
typedef struct {
    int modulationOrder;
    int codingRate;
} MCSConfig;

// Initialize and manage a dynamic array of LTE PHY layer configurations
PhyConfig* phyConfigInit(int initialCapacity) {
    PhyConfig* phyConfig = (PhyConfig*)malloc(sizeof(PhyConfig));
    phyConfig->mcsConfigs = (MCSConfig*)calloc(initialCapacity, sizeof(MCSConfig));
    phyConfig->numMCSConfigs = 0;
    return phyConfig;
}

// Add a new MCS configuration to the list
void phyConfigAddMCS(PhyConfig* phyConfig, int modulationOrder, int codingRate) {
    // Check if there is enough capacity in the array
    if (phyConfig->numMCSConfigs >= sizeof(phyConfig->mcsConfigs)/sizeof(MCSConfig)) {
        // Allocate a new block of memory for MCS configurations
        MCSConfig* newMCSConfigs = (MCSConfig*)realloc(phyConfig->mcsConfigs, (phyConfig->numMCSConfigs + 1) * sizeof(MCSConfig));
        phyConfig->mcsConfigs = newMCSConfigs;
    }

    // Add the new MCS configuration to the list
    phyConfig->mcsConfigs[phyConfig->numMCSConfigs].modulationOrder = modulationOrder;
    phyConfig->mcsConfigs[phyConfig->numMCSConfigs].codingRate = codingRate;
    phyConfig->numMCSConfigs++;
}

// Update an existing MCS configuration in the list
void phyConfigUpdateMCS(PhyConfig* phyConfig, int index, int modulationOrder, int codingRate) {
    // Check if the index is within the valid range
    if (index >= 0 && index < phyConfig->numMCSConfigs) {
        phyConfig->mcsConfigs[index].modulationOrder = modulationOrder;
        phyConfig->mcsConfigs[index].codingRate = codingRate;
    }
}

// Delete a specific MCS configuration from the list
void phyConfigDeleteMCS(PhyConfig* phyConfig, int index) {
    // Check if the index is within the valid range
    if (index >= 0 && index < phyConfig->numMCSConfigs) {
        // Shift all subsequent MCS configurations down by one position
        memmove(&phyConfig->mcsConfigs[index], &phyConfig->mcsConfigs[index + 1],
                (phyConfig->numMCSConfigs - index - 1) * sizeof(MCSConfig));
        phyConfig->numMCSConfigs--;
    }
}

// Serialize the LTE PHY layer configuration structure to a binary file
void phyConfigSerialize(PhyConfig* phyConfig, FILE* file) {
    // Write the bandwidth and subcarrier spacing to the file
    fwrite(&phyConfig->bandwidth, sizeof(int), 1, file);
    fwrite(&phyConfig->subcarrierSpacing, sizeof(float), 1, file);

    // Write the number of MCS configurations to the file
    fwrite(&phyConfig->numMCSConfigs, sizeof(int), 1, file);

    // Write each MCS configuration to the file
    for (int i = 0; i < phyConfig->numMCSConfigs; i++) {
        fwrite(&phyConfig->mcsConfigs[i].modulationOrder, sizeof(int), 1, file);
        fwrite(&phyConfig->mcsConfigs[i].codingRate, sizeof(int), 1, file);
    }
}

// Deserialize the LTE PHY layer configuration structure from a binary file
PhyConfig* phyConfigDeserialize(FILE* file) {
    PhyConfig* phyConfig = (PhyConfig*)malloc(sizeof(PhyConfig));

    // Read the bandwidth and subcarrier spacing from the file
    fread(&phyConfig->bandwidth, sizeof(int), 1, file);
    fread(&phyConfig->subcarrierSpacing, sizeof(float), 1, file);

    // Read the number of MCS configurations from the file
    fread(&phyConfig->numMCSConfigs, sizeof(int), 1, file);

    // Allocate memory for the MCS configurations and read them from the file
    phyConfig->mcsConfigs = (MCSConfig*)calloc(phyConfig->numMCSConfigs, sizeof(MCSConfig));
    for (int i = 0; i < phyConfig->numMCSConfigs; i++) {
        fread(&phyConfig->mcsConfigs[i].modulationOrder, sizeof(int), 1, file);
        fread(&phyConfig->mcsConfigs[i].codingRate, sizeof(int), 1, file);
    }

    return phyConfig;
}

// Initialize and manage a thread-safe data structure to handle concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Serialize the LTE PHY layer configuration structure to a binary file (thread-safe)
void* phyConfigSerializeThreadSafe(void* arg) {
    PhyConfig* phyConfig = (PhyConfig*)arg;
    pthread_mutex_lock(&lock);
    phyConfigSerialize(phyConfig, stdout);
    pthread_mutex_unlock(&lock);
    return NULL;
}

// Deserialize the LTE PHY layer configuration structure from a binary file (thread-safe)
void* phyConfigDeserializeThreadSafe(void* arg) {
    FILE* file = (FILE*)arg;
    PhyConfig* phyConfig = phyConfigDeserialize(file);
    pthread_mutex_lock(&lock);
    // Perform any necessary thread-safe operations with the deserialized configuration
    pthread_mutex_unlock(&lock);
    return phyConfig;
}

// Example usage:
int main() {
    PhyConfig* phyConfig = phyConfigInit(10);

    // Add MCS configurations to the list
    phyConfigAddMCS(phyConfig, 16, 3/4);
    phyConfigAddMCS(phyConfig, 64, 1/2);
    phyConfigAddMCS(phyConfig, 256, 5/6);

    // Update an existing MCS configuration
    phyConfigUpdateMCS(phyConfig, 0, 16, 3/4);

    // Delete a specific MCS configuration
    phyConfigDeleteMCS(phyConfig, 1);

    // Serialize the LTE PHY layer configuration structure to a binary file (thread-safe)
    pthread_t thread;
    pthread_create(&thread, NULL, phyConfigSerializeThreadSafe, phyConfig);
    pthread_join(thread, NULL);

    return 0;
}

