            if (source->socket == -1) {
                log_error(errno, "Failed to read from", source->source_name);
            }
        }

        // Check for user-specified limits
        int incomplete_processing = 0;
        for (int i = 0; i < num_sources; i++) {
            DataSource* source = &sources[i];
            if (getsockopt(source->socket, SOL_SOCKET, SO_ERROR, NULL, 0) == -1) {
                log_error(errno, "Failed to read from", source->source_name);
                incomplete_processing = 1;
                break;
            }
        }

        // Exit early if user-specified limit reached
        if (incomplete_processing) {
            for (int i = 0; i < num_sources; i++) {
                DataSource* source = &sources[i];
                close(source->socket);
            }
            return 1;
