    // Initialize UE context array
    *contexts = (NFAPI_RRC_UECONTEXT_T*)malloc(num_ue * sizeof(NFAPI_RRC_UECONTEXT_T));
    for (int i = 0; i < num_ue; i++) {
        (*contexts)[i].ue_id = i;
        (*contexts)[i].state = RRC_STATE_IDLE;
        (*contexts)[i].pdu_list = NULL;
    }

    // Add new PDU to list
    void add_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t pdu) {
        // Allocate memory for new PDU
        NFAPI_UL_CCCH_pdu_t* new_pdu = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        if (!new_pdu) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Add new PDU to list
        context->pdu_list = (NFAPI_UL_CCCH_pdu_t*)realloc(context->pdu_list, (context->pdu_list ? context->pdu_list->size + 1 : 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
        if (!context->pdu_list) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Insert new PDU at end of list
        context->pdu_list[context->pdu_list->size++] = pdu;
    }

    // Validate integrity of PDU list before operations
    bool validate_pdu_list(NFAPI_RRC_UECONTEXT_T* context) {
        for (int i = 0; i < context->pdu_list->size; i++) {
            if (!context->pdu_list[i].offset || !context->pdu_list[i].val) {
                return false;
            }
        }
        return true;
    }

    // External API integration
    void update_ue_contexts(NFAPI_RRC_UECONTEXT_T* contexts, int num_ue) {
        // Process updates in a thread-safe manner
        pthread_mutex_lock(&lock);
        for (int i = 0; i < num_ue; i++) {
            // Update UE context
            update_ue_context(contexts[i]);
        }
        pthread_mutex_unlock(&lock);
    }

    // Logging mechanism
    void log_memory_usage(size_t memory_used) {
        if (memory_used > MAX_MEMORY_USAGE) {
            printf("Memory usage exceeded limit. Reducing number of active UE contexts.\n");
            reduce_active_ue_contexts();
        }
    }

    // Dynamic resizing of UE context array
    void resize_ue_context_array(NFAPI_RRC_UECONTEXT_T** contexts, int new_size) {
        *contexts = (NFAPI_RRC_UE_CONTEXT_T*)realloc(*contexts, new_size * sizeof(NFAPI_RRC_UECONTEXT_T));
    }

    // Record population
    record_t* populate_records(int num_records, char* data_distribution) {
        record_t* records = (record_t*)malloc(num_records * sizeof(record_t));
        for (int i = 0; i < num_records; i++) {
            records[i].id = i;
            records[i].text = strdup(data_distribution);
        }
        return records;
    }

    // Garbage collection mechanism
    void collect_garbage() {
        // Release unreferenced records
        record_t* current = records;
        while (current) {
            if (!referenced(current)) {
                free(current->text);
                free(current);
                current = next_record();
            }
        }
    }

