#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct {
    uint32_t UE_ID;
    RRC_STATE state;
    List* pdus; // dynamic list of NFAPI_UL_CCCH_pdu_t
} NFAPI_RRC_UECONTEXT_T;

List* uecontexts = NULL; // global collection of UE contexts

// initialization and validation
void uecontext_init() {
    pthread_mutex_init(&uecontext_lock, NULL);
    uecontexts = List_create();
}

// destroy UE context and release resources
void uecontext_destroy(NFAPI_RRC_UECONTEXT_T* context) {
    pthread_mutex_lock(&uecontext_lock);
    for (Node* node = List_head(context->pdus); node != NULL; ) {
        NFAPI_UL_CCCH_pdu_t* pdu = (NFAPI_UL_CCCH_pdu_t*)node->data;
        if (pdu != NULL) free(pdu);
        node = node->next;
    }
    pthread_mutex_unlock(&uecontext_lock);
}

// add PDU to UE context list
void uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uecontext_lock);
    List_append(context->pdus, (void*)pdu);
    pthread_mutex_unlock(&uecontext_lock);
}

// remove PDU from UE context list
void uecontext_remove_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uecontext_lock);
    for (Node* node = List_head(context->pdus); node != NULL; ) {
        if (((NFAPI_UL_CCCH_pdu_t*)node->data) == pdu) {
            List_remove(context->pdus, node);
            free(pdu);
            break;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&uecontext_lock);
}

// modify UE context state
void uecontext_modify_state(NFAPI_RRC_UECONTEXT_T* context, RRC_STATE new_state) {
    pthread_mutex_lock(&uecontext_lock);
    context->state = new_state;
    pthread_mutex_unlock(&uecontext_lock);
}

// validate PDU list integrity
bool uecontext_validate() {
    for (Node* node = List_head(uecontexts); node != NULL; ) {
        NFAPI_RRC_UECONTEXT_T* context = (NFAPI_RRC_UECONTEXT_T*)node->data;
        if (context == NULL || context->pdus == NULL) return false;
        for (Node* pdu_node = List_head(context->pdus); pdu_node != NULL; ) {
            NFAPI_UL_CCCH_pdu_t* pdu = (NFAPI_UL_CCCH_pdu_t*)pdu_node->data;
            if (pdu == NULL || context->state != RRC_STATE_VALID) return false;
            pdu_node = pdu_node->next;
        }
    }
    return true;
}

// logging mechanism
void uecontext_log_change(NFAPI_RRC_UECONTEXT_T* context, int log_level) {
    // implement logging logic here based on log level (DEBUG, INFO, WARNING, ERROR)
}
