using System;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class WebsiteManager
{
    private static readonly string[] allowedFormats = new[] { "token1", "token2", "token3" };

    public static void AddWebsite(string directoryPath, string siteName)
    {
        if (!Directory.Exists(directoryPath))
            throw new DirectoryNotFoundException();

        if (!File.Exists(Path.Combine(directoryPath, "web.config")))
            return;

        ProcessStartInfo startInfo = new ProcessStartInfo("iisreset", "/start " + siteName);
        startInfo.CreateNoWindow = true;
        startInfo.UseShellExecute = false;

        using (Process process = Process.Start(startInfo))
        {
            process.WaitForExit();
        }
    }

    public static void ManageSessionTokens(string directoryPath)
    {
        Dictionary<string, string> tokenMap = new Dictionary<string, string>();

        foreach (string file in Directory.GetFiles(directoryPath, "*.token"))
        {
            string token = File.ReadAllText(file).ToLower().Trim();

            if (!allowedFormats.Any(f => token.StartsWith(f)))
                continue;

            token = NormalizeToken(token);

            if (token.Length > 64)
            {
                token = token.Substring(0, 63);
                token += GenerateHash(token);
            }

            if (token.Length > 128)
            {
                token = "default_" + token;
            }

            if (!tokenMap.ContainsKey(token))
                tokenMap.Add(token, file);

            using (StreamWriter writer = File.CreateText(file))
            {
                writer.WriteLine(token);
            }
        }
    }

    private static string NormalizeToken(string token)
    {
        return System.Text.RegularExpressions.Regex.Replace(token, @"[^a-zA-Z0-9_\-\.]", "").Normalize(NormalizationForm.FormC);
    }

    private static string GenerateHash(string text)
    {
        using (SHA256 sha256 = SHA256.Create())
        {
            return Convert.ToBase64String(sha256.ComputeHash(Encoding.UTF8.GetBytes(text)));
        }
    }
}
