typedef struct {
    int id;
    char serial_number[20];
    char location[50];
    int power_status;
    float firmware_version;
} device;

device* add_device(device** devices, int* num_devices, long timestamp, float humidity) {
    // Allocate memory for a new device
    device* new_device = (device*)malloc(sizeof(device));
    if (!new_device) return NULL;  // Handle allocation failure

    // Initialize the device's fields
    new_device->id = rand();
    strcpy(new_device->serial_number, "S12345");
    strcpy(new_device->location, "Room 101");
    new_device->power_status = (rand() % 2);
    new_device->firmware_version = (float)rand() / RAND_MAX;

    // Update the device list and return the new device
    (*num_devices)++;
    *devices = (device**)realloc(*devices, (*num_devices)*sizeof(device*));
    *devices[(*num_devices)-1] = new_device;
    return new_device;
}

int update_device(device** devices, int num_devices, int id, float humidity) {
    // Find the device with the specified ID
    for (int i = 0; i < num_devices; i++) {
        if (devices[i]->id == id) {
            // Update the device's humidity reading and return success
            devices[i]->humidity = humidity;
            return 1;
        }
    }
    // Device not found, return failure
    return -1;
}

int remove_device(device** devices, int* num_devices, int id) {
    // Find the device with the specified ID
    for (int i = 0; i < *num_devices; i++) {
        if (devices[i]->id == id) {
            // Remove the device and return success
            free(devices[i]);
            memmove(devices+i, devices+i+1, (*num_devices-i)*sizeof(device*));
            (*num_devices)--;
            return 1;
        }
    }
    // Device not found, return failure
    return -1;
}

int query_devices(device** devices, int num_devices, int power_status, float firmware_version) {
    int count = 0;
    for (int i = 0; i < num_devices; i++) {
        if (devices[i]->power_status == power_status && devices[i]->firmware_version == firmware_version) {
            count++;
        }
    }
    return count;
}

void garbage_collect(device** devices, int* num_devices) {
    // Iterate through the device list and free unreferenced devices
    for (int i = 0; i < *num_devices; i++) {
        if (!devices[i]->referenced) {
            free(devices[i]);
            memmove(devices+i, devices+i+1, (*num_devices-i)*sizeof(device*));
            (*num_devices)--;
        }
    }
}

