#include <fcntl.h>

void* load_library(const char *library_name, const char *function_name, const unsigned int checksum) {
    void *handle = dlopen(library_name, RTLD_LAZY);

    if (!handle) {
        fprintf(stderr, "Error: %s\n", dlerror());
        return NULL;
    }

    printf("Loaded library '%s' successfully.\n", library_name);

    // Verify checksum
    int file_descriptor = open(library_name, O_RDONLY);
    if (file_descriptor < 0) {
        perror("open");
        dlclose(handle);
        return NULL;
    }

    struct stat library_info;
    fstat(file_descriptor, &library_info);

    unsigned int actual_checksum = library_info.st_mtime;
    close(file_descriptor);

    if (checksum != actual_checksum) {
        printf("Error: Library checksum mismatch.\n");
        dlclose(handle);
        return NULL;
    }

    // Invoke function
    void (*loaded_function)(void) = dlsym(handle, function_name);

    if (!loaded_function) {
        fprintf(stderr, "Error: Unable to load function '%s'.\n", function_name);
        dlclose(handle);
        return NULL;
    }

    loaded_function();

    // Log successful load and invocation
    FILE *log_file = fopen("library_load_log.txt", "a");
    if (log_file) {
        fprintf(log_file, "Loaded library '%s' successfully.\nInvoked function '%s'.\n\n", library_name, function_name);
        fclose(log_file);
    }

    // Unload library
    dlclose(handle);
    printf("Unloaded library '%s' successfully.\n", library_name);
}
