// Define the SensorReading structure
typedef struct {
    int timestamp;
    float temperature;
    float humidity;
    float pressure;
} SensorReading;

// Define the DataQueue structure
typedef struct {
    SensorReading* readings;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DataQueue;

// Function to create a new DataQueue with initial capacity
DataQueue* streamProcessor_create(size_t initial_capacity) {
    DataQueue* queue = (DataQueue*)malloc(sizeof(DataQueue));
    if (!queue) return NULL; // Memory allocation failed

    queue->readings = (SensorReading*)malloc(initial_capacity * sizeof(SensorReading));
    if (!queue->readings) {
        free(queue);
        return NULL; // Memory allocation failed
    }

    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->lock, NULL); // Initialize the lock

    return queue;
}

// Function to enqueue a sensor reading into the DataQueue
void streamProcessor_enqueue(DataQueue* queue, SensorReading* reading) {
    pthread_mutex_lock(&queue->lock);
    if (queue->size >= queue->capacity) { // Dynamic resizing needed
        size_t new_capacity = queue->capacity * 2; // Double the capacity
        SensorReading* new_readings = (SensorReading*)realloc(queue->readings, new_capacity * sizeof(SensorReading));
        if (!new_readings) {
            pthread_mutex_unlock(&queue->lock);
            return; // Memory allocation failed
        }
        queue->readings = new_readings;
        queue->capacity = new_capacity;
    }

    queue->readings[queue->size++] = *reading;

    pthread_mutex_unlock(&queue->lock);
}

// Function to dequeue sensor readings from the DataQueue within a given timestamp range and sensor ID
void streamProcessor_dequeue(DataQueue* queue, int start_timestamp, int end_timestamp, int sensor_id) {
