#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <fcntl.h>
#include <zlib.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FILE_PATH_LENGTH 256
#define DEFAULT_DELIMITER ", "
#define DEFAULT_OUTPUT_FILE "output.txt"
#define LOG_LEVEL_ERROR 0
#define LOG_LEVEL_WARNING 1

typedef struct {
    int lines;
    double sum;
} FileStats;

void print_usage() {
    printf("Usage: %s [options] file1 [file2 ...]\n", argv[0]);
    printf("Options:\n");
    printf("  -h, --help        Show this help message and exit\n");
    printf("  -d, --delimiter=DELIMITER   Set the delimiter (default: , )\n");
    printf("  -o, --output=FILE      Output to FILE instead of standard output\n");
    printf("  -v, --verbose     Enable verbose mode\n");
    printf("  -l, --log-level=LEVEL    Set the log level (0 for error only, 1 for warnings)\n");
}

int main(int argc, char *argv[]) {
    int c;
    FILE *output = stdout;
    int verbose = 0;
    int log_level = LOG_LEVEL_ERROR;
    char *delimiter = DEFAULT_DELIMITER;
    char *output_file = DEFAULT_OUTPUT_FILE;

    static struct option long_options[] = {
        {"help",       no_argument,      0, 'h'},
        {"delimiter", required_argument, 0, 'd'},
        {"output",     required_argument, 0, 'o'},
        {"verbose",    no_argument,      0, 'v'},
        {"log-level",  required_argument, 0, 'l'},
        {0,             0,               0, 0}
    };

    while ((c = getopt_long(argc, argv, "hd:o:v:l:", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                print_usage();
                return 0;
            case 'd':
                delimiter = optarg;
                break;
            case 'o':
                output_file = optarg;
                if (!strcmp(output_file, "-")) {
                    output = stdout;
                } else {
                    output = fopen(output_file, "w");
                    if (output == NULL) {
                        perror("fopen");
                        return 1;
                    }
                }
                break;
            case 'v':
                verbose = 1;
                break;
            case 'l':
                if (strcmp(optarg, "0") == 0)
                    log_level = LOG_LEVEL_ERROR;
                else if (strcmp(optarg, "1") == 0)
                    log_level = LOG_LEVEL_WARNING;
                else {
                    fprintf(stderr, "Invalid log level\n");
                    return 1;
                }
                break;
            default:
                print_usage();
                return 1;
        }
    }

    int num_files = argc - optind;

    for (int i = 0; i < num_files; i++) {
        FILE *file = fopen(argv[optind + i], "r");
        if (file == NULL) {
            perror("fopen");
            return 1;
        }

        FileStats stats;
        stats.lines = 0;
        stats.sum = 0.0;

        char line[MAX_LINE_LENGTH];
        while (fgets(line, MAX_LINE_LENGTH, file)) {
            char *token = strtok(line, delimiter);
            int total = 0;
            double avg = 0.0;
            int last_two_fields = 0;

            while (token) {
                int value = atoi(token);
                if (last_two_fields == 2)
                    break;
                total += value;
                token = strtok(NULL, delimiter);
                last_two_fields++;
            }

            if (last_two_fields >= 2) {
                avg = (double)total / (last_two_fields - 1);
            }

            fprintf(output, "%s", line);
            stats.lines++;
            stats.sum += avg;
        }

        fclose(file);

        if (verbose) {
            printf("Processed file %s: %d lines\n", argv[optind + i], stats.lines);
        }
    }

    fclose(output);

    return 0;
}
