NFAPI_CRC_INDICATION_PDU_T** create_crc_indication_pdu(int n) {
    NFAPI_CRC_INDATION_PDU_T** list = (NFAPI_CRC_INDATION_PDU_T**)malloc((n + 1) * sizeof(NFAPI_CRC_INDATION_PDU_T*));
    if (!list) return NULL;

    for (int i = 0; i <= n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!entry) {
            free(list);
            return NULL;
        }

        srand(time(NULL));
        entry->rx_ue_info_tag = rand() % 1000 + 1;
        entry->rnti = rand() % 500 + 1;
        entry->crc_flag = rand() % 2;

        list[i] = entry;
    }

    return list;
}

void insert_crc_indication_pdu(NFAPI_CRC_INDATION_PDU_T** list, int n, int index, NFAPI_CRC_INDICATION_PDU_T* entry) {
    if (index > n || index < 0) return;

    NFAPI_CRC_INDICATION_PDU_T** new_list = (NFAPI_CRC_INDATION_PDU_T**)malloc((n + 2) * sizeof(NFAPI_CRC_INDATION_PDU_T*));
    if (!new_list) {
        free(list);
        return;
    }

    for (int i = 0; i < index; i++) new_list[i] = list[i];
    new_list[index] = entry;
    for (int i = index + 1; i <= n + 1; i++) new_list[i] = list[i - 1];

    free(list);
    *list = new_list;
}

void update_crc_indication_pdu(NFAPI_CRC_INDATION_PDU_T** list, int n, int index) {
    if (index > n || index < 0) return;

    NFAPI_CRC_INDICATION_PDU_T* entry = list[index];
    free(entry);
    srand(time(NULL));
    entry->rx_ue_info_tag = rand() % 1000 + 1;
    entry->rnti = rand() % 500 + 1;
    entry->crc_flag = rand() % 2;
}

void remove_crc_indication_pdu(NFAPI_CRC_INDATION_PDU_T** list, int n, int index) {
    if (index > n || index < 0) return;

    for (int i = index; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = list[i];
        free(entry);
        list[i] = list[n];
        n--;
    }
}

void destroy_crc_indication_pdu(NFAPI_CRC_INDATION_PDU_T** list, int n) {
    for (int i = 0; i <= n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* entry = list[i];
        free(entry);
    }

    free(list);
