void manage_LTE_Transport_Context_list(LTE_TRANSPORT_CONTEXT ***list, size_t *list_size, int *max_size) {
    if (!(*list)) {
        (*list) = (LTE_TRANSPORT_CONTEXT ***)malloc(1 * sizeof(LTE_TRANSPORT_CONTEXT *));
        (*list)[0] = NULL;
        (*list_size) = 0;
        (*max_size) = 1;
    }
}

void populate_list(LTE_TRANSPORT_CONTEXT ***list, size_t *list_size, int *max_size) {
    for (size_t i = 0; i < (*list_size); i++) {
        if (!(*list)[i]) {
            (*list)[i] = (LTE.TRANSPORT_CONTEXT *)malloc(1 * sizeof(LTE_TRANSPORT_CONTEXT));
            (*list)[i]->LTE_PLMN_ID = i;
            (*list)[i]->E_UTRAN_BAND = 'A' + i % 26;
        }
    }
}

int update_list(LTE_TRANSPORT_CONTEXT ***list, size_t *list_size, int *max_size, int index, LTE_TRANSPORT_CONTEXT *entry) {
    if (index >= (*list_size)) return -1;
    if (!(*list)[index]) return -2;
    memcpy(&((*list)[index]->LTE_PLMN_ID), &entry->LTE_PLMN_ID, sizeof(int));
    memcpy(&((*list)[index]->E_UTRAN_BAND), &entry->E_UTRAN_BAND, 1);
    return 0;
}

int insert_list(LTE_TRANSPORT_CONTEXT ***list, size_t *list_size, int *max_size, int index, LTE_TRANSPORT_CONTEXT *entry) {
    if (index > (*list_size)) {
        if (!(*list)) return -3;
        if ((*list)[*list_size]) {
            for (int i = *list_size; i > index; i--) {
                (*list)[i] = (*list)[i-1];
            }
        } else (*list)[index] = NULL;
    } else return -4;
    if (!(*list)) return -5;
    if ((*list)[*list_size]) {
        for (int i = *list_size; i > index; i--) {
            (*list)[i] = (*list)[i-1];
        }
    } else (*list)[index] = NULL;
    size_t new_size = (*list_size) + 1;
    if (!((*list) = realloc(*list, (new_size + 1) * sizeof(LTE_TRANSPORT_CONTEXT *)))){
        return -6;
    }
    for (size_t i = new_size; i > index; i--) {
        if (!(*list)[i]) (*list)[i] = NULL;
    }
    (*list)[index] = entry;
    (*list_size) = new_size;
    return 0;
}

int remove_list(LTE_TRANSPORT_CONTEXT ***list, size_t *list_size, int *max_size, int index) {
    if (index >= (*list_size)) return -7;
    if (!(*list)[index]) return -8;
    for (size_t i = index; i < (*list_size)-1; i++) {
        if (!((*list)[i+1] = (*list)[i])) {
            free((*list)[i]);
            (*list)[i] = NULL;
        }
    }
    size_t new_size = (*list_size) - 1;
    if (!((*list) = realloc(*list, (new_size + 1) * sizeof(LTE_TRANSPORT_CONTEXT *)))){
        return -9;
    }
    (*list_size) = new_size;
    return 0;
}

