    ue_ctx->ue_id = id;
    ue_ctx->rrc_state = state;
    ue_ctx->pdu_count = 0;
    pthread_mutex_init(&ue_ctx->mutex, NULL);
    return ue_ctx;
}

int add_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&ue_ctx->mutex);

    if (ue_ctx->pdu_count >= MAX_PDU_PER_CONTEXT) {
        LOG_EVENT("PDU limit exceeded for UE context");
        pthread_mutex_unlock(&ue_ctx->mutex);
        return -1;
    }

    validate_pdu(pdu);

    ue_ctx->pdus = realloc(ue_ctx->pdus, (ue_ctx->pdu_count + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
    ue_ctx->pdus[ue_ctx->pdu_count++] = pdu;

    pthread_mutex_unlock(&ue_ctx->mutex);
    return 0;
}

void validate_pdu(NFAPI_UL_CCCH_pdu_t* pdu) {
    // Perform PDU validation
    if (!validate_pdu_content(pdu)) {
        LOG_EVENT("PDU validation failed");
        free(pdu);
    }
}

void gc_periodic(void* data) {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = (NFAPI_RRC_UECONTEXT_T*)data;

    pthread_mutex_lock(&ue_ctx->mutex);

    for (int i = 0; i < ue_ctx->pdu_count; ++i) {
        if (!is_pdu_associated_with_ue(ue_ctx->pdus[i])) {
            free(ue_ctx->pdus[i]);
            memmove(ue_ctx->pdus + i, ue_ctx->pdus + i + 1, (ue_ctx->pdu_count - i - 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
            --ue_ctx->pdu_count;
        }
    }

    pthread_mutex_unlock(&ue_ctx->mutex);
}
