    ctx->ue_id = ue_id;
    ctx->rrc_state = rrc_state;
    ctx->pdus = NULL;
    ctx->pdu_count = 0;
    return ctx;
}

void nfapi_rrc_uecontext_free(NFAPI_RRC_UECONTEXT_T* ctx) {
    if (ctx != NULL) {
        free(ctx->pdus);
        free(ctx);
    }
}

void nfapi_rrc_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* ctx, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&ctx->mutex);

    if (ctx->pdu_count >= MAX_PDU_PER_CTX) {
        // log event and do not add the PDU to the list
        printf("Resource limit exceeded for UE context %u\n", ctx->ue_id);
    } else {
        NFAPI_UL_CCCH_pdu_t* new_pds = (NFAPI_UL_CCCH_pdu_t*)realloc(ctx->pdus, sizeof(NFAPI_UL_CCCH_pdu_t) * (ctx->pdu_count + 1));
        if (new_pds == NULL) {
            // log error and do not add the PDU to the list
            printf("Failed to allocate memory for UE context %u\n", ctx->ue_id);
        } else {
            new_pds[ctx->pdu_count] = *pdu;
            ctx->pdus = new_pds;
            ctx->pdu_count++;
        }
    }

    pthread_mutex_unlock(&ctx->mutex);

    // perform PDU validation
    for (int i = 0; i < ctx->pdu_count; i++) {
        if (!nfapi_ul_ccch_pdu_validate(ctx->pdus[i])) {
            // log error and remove the invalid PDU from the list
            printf("Invalid PDU detected in UE context %u\n", ctx->ue_id);
            // reallocate memory to reduce fragmentation
            NFAPI_UL_CCCH_pdu_t* new_pds = (NFAPI_UL_CCCH_pdu_t*)realloc(ctx->pdus, sizeof(NFAPI_UL_CCCH_pdu_t) * (i));
            if (new_pds != NULL) {
                ctx->pdus = new_pds;
                ctx->pdu_count = i;
            } else {
                // log error and do not add the PDU to the list
                printf("Failed to allocate memory for UE context %u\n", ctx->ue_id);
            }
        }
    }
}

void nfapi_rrc_uecontext_gc(NFAPI_RRC_UECONTEXT_T* ctx, int gc_interval) {
    pthread_mutex_lock(&ctx->mutex);

    // periodic garbage collection routine
    for (int i = 0; i < ctx->pdu_count; i++) {
        if (ctx->pdus[i].valid == 0 && time(NULL) - ctx->pdus[i].timestamp > gc_interval) {
            free(ctx->pdus[i].data);
            // reallocate memory to reduce fragmentation
            NFAPI_UL_CCCH_pdu_t* new_pds = (NFAPI_UL_CCCH_pdu_t*)realloc(ctx->pdus, sizeof(NFAPI_UL_CCCH_pdu_t) * (i));
            if (new_pds != NULL) {
                ctx->pdus = new_pds;
                ctx->pdu_count = i;
            } else {
                // log error and do not perform garbage collection
                printf("Failed to allocate memory for UE context %u\n", ctx->ue_id);
            }
        }
    }

    pthread_mutex_unlock(&ctx->mutex);
}
