void add_element(NFAPI_CRC_INDICATION_PDU_T* new_elem, int M) {
    pthread_mutex_lock(&mutex);
    // Check for duplicates and update count if CRCFLAG is set
    int i;
    for (i = 0; i < M; i++) {
        if (!memcmp(list[i], new_elem, sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
            if (new_elem->CRCFLAG) {
                total_crc_count++;
            }
            pthread_mutex_unlock(&mutex);
            return;
        }
    }
    // Add the new element
    for (i = M - 1; i > 0; i--) {
        list[i] = list[i - 1];
    }
    list[0] = *new_elem;
    M++;
    pthread_mutex_unlock(&mutex);
}

// Function to remove an element from the list, handling out-of-bounds access
void remove_element(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= total_elements || index < 0) {
        pthread_mutex_unlock(&mutex);
        return;
    }
    // Shift elements down after removing
    memmove(&list[index], &list[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (total_elements - index - 1));
    total_elements--;
    pthread_mutex_unlock(&mutex);
}

// Function to query an element from the list, handling out-of-bounds access
NFAPI_CRC_INDICATION_PDU_T* get_element(int index) {
    pthread_mutex_lock(&mutex);
    if (index >= total_elements || index < 0) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    return &list[index];
}

// Function to flush the list to persistent storage and compact
void flush_list() {
    pthread_mutex_lock(&mutex);
    // Write data to file or database
    // Compact the list
    total_elements = 0;
    pthread_mutex_unlock(&mutex);
}

// Retry logic for temporary failures in persistence mechanism
int retry_flush(int attempts) {
    int i;
    for (i = 0; i < attempts; i++) {
        if (flush_list()) {
            return 1;
        }
        // Exponential backoff before retrying
        sleep(pow(2, i));
    }
    return 0;
}

// Function to print metrics and logging information
void log_metrics(int total_operations) {
    printf("Total operations: %d\n", total_operations);
    printf("CRCFLAG set elements: %d\n", total_crc_count);
}
