typedef enum {
    INITIAL,
    REACHABLE,
    FINAL
} state_t;

state_t* allocate_states(int max_states) {
    return (state_t*)malloc((max_states + 1) * sizeof(state_t));
}

void process_filenames(char** filenames, int num_filenames, int* digit_count, char* file_type, int is_reversible) {
    // Process each filename
    for (int i = 0; i < num_filenames; i++) {
        // Modify the extension according to specified criteria
        sprintf(filenames[i], "%s_%d.%s", filenames[i], *digit_count, file_type);

        // Update state list using FSA
        int current_state = INITIAL;
        for (int j = 0; j < strlen(filenames[i]); j++) {
            if (j % 2 == 0) {
                // Transition logic based on filename characters
                if (filenames[i][j] >= 'a' && filenames[i][j] <= 'z') {
                    current_state = REACHABLE;
                } else if (filenames[i][j] >= 'A' && filenames[i][j] <= 'Z') {
                    current_state = FINAL;
                }
            }
        }

        // Serialize and deserialize states for efficient I/O
        FILE* file = fopen("states.csv", "w");
        fprintf(file, "%s,%d\n", filenames[i], current_state);
        fclose(file);
    }
}

int main() {
    char** filenames = malloc(10 * sizeof(char*));
    int num_filenames = 5;

    for (int i = 0; i < num_filenames; i++) {
        filenames[i] = malloc(30 * sizeof(char));
        sprintf(filenames[i], "input_%d.txt", i);
    }

    int digit_count[10];
    char* file_type = ".txt";

    // Process filenames
    process_filenames(filenames, num_filenames, &digit_count, file_type, 1);

    // Free memory allocated for filenames
    for (int i = 0; i < num_filenames; i++) {
        free(filenames[i]);
    }
    free(filenames);

    return 0;
}

