// Define a struct to hold UE context information
typedef struct {
    uint64_t ue_id;
    enum RRC_STATE rrc_state;
    NFAPI_UL_CCCH_pdu_t* pdus; // Dynamically allocated list of PDUs
    pthread_mutex_t mutex; // Mutex for thread-safe access
} NFAPI_RRC_UECONTEXT_T;

// Define a struct to hold PDU information with timestamp
typedef struct {
    uint64_t timestamp;
    // Other PDU fields...
} NFAPI_UL_CCCH_pdu_t;

// Function to manage dynamic array of UE contexts
void* manage_ue_contexts(int num_ue, void** ue_contexts) {
    // Allocate memory for each UE context structure
    NFAPI_RRC_UECONTEXT_T* ue_context = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    pthread_mutex_init(&ue_context->mutex, NULL);

    // Initialize UE context fields
    ue_context->ue_id = 0;
    ue_context->rrc_state = RRC_STATE_UNKNOWN;

    // Dynamically allocate list for PDUs and initialize
    ue_context->pdus = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
    pthread_mutex_init(&ue_context->mutex, NULL);

    // Add UE context to the dynamic array
    *ue_contexts = ue_context;

    return ue_context;
}

// Function to add a new PDU to an existing UE context
void add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* pdu) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&ue_context->mutex);

    // Dynamically allocate memory for new PDU if necessary
    if (!ue_context->pdus) {
        ue_context->pdus = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
    }

    // Add the new PDU to the list and update timestamp
    pdu->timestamp = time(NULL);
    ue_context->pdus = realloc(ue_context->pdus, (ue_context->pdus + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));

    // Record the addition of the PDU for auditing purposes
    printf("Added PDU with timestamp %lu to UE context %llu\n", pdu->timestamp, ue_context->ue_id);

    // Release the mutex
    pthread_mutex_unlock(&ue_context->mutex);
}

// Function to validate the integrity of a UE context's PDU list
bool validate_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context) {
    // Acquire the mutex for thread-safe access
    pthread_mutex_lock(&ue_context->mutex);

    // Check if the PDU list is null or empty
    if (!ue_context->pdus || !ue_context->pdus[0].timestamp) {
        return false;
    }

    // Release the mutex
    pthread_mutex_unlock(&ue_context->mutex);

    return true;
}

// Example usage:
int main() {
    int num_ue = 5;
    void** ue_contexts = (void**)malloc(num_ue * sizeof(void*));

    for (int i = 0; i < num_ue; i++) {
        NFAPI_RRC_UECONTEXT_T* ue_context = manage_ue_contexts(1, &ue_contexts[i]);
