#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define MAX_DISK_SPACE 1048576 // 1MB

typedef struct NFAPI_RRC_UECONTEXT_T {
    uint32_t UE_ID;
    int RRC_STATE;
    struct NFAPI_UL_CCCH_pdu_t* pdu_list;
} NFAPI_RRC_UECONTEXT_T;

typedef struct NFAPI_UL_CCCH_pdu_t {
    uint64_t timestamp;
    char* data;
} NFAPI_UL_CCCH_pdu_t;

typedef struct fileEntry {
    FILE* fd;
    time_t timestamp;
} fileEntry;

NFAPI_RRC_UECONTEXT_T* ue_contexts = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int num_ue_contexts = 0;
fileEntry* file_entries = NULL;
int num_file_entries = 0;
int total_disk_space_usage = 0;

void add_pdu_to_uecontext(NFAPI_RRC_UECONTEXT_T* ue_context, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&lock);
    // Validate PDU and UE context before adding
    if (ue_context->pdu_list == NULL || !validate_pdu(pdu)) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Add PDU to the list
    ue_context->pdu_list = realloc(ue_context->pdu_list, (++ue_context->pdu_list_size) * sizeof(NFAPI_UL_CCCH_pdu_t));
    if (ue_context->pdu_list == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }
    memcpy(&ue_context->pdu_list[ue_context->pdu_list_size - 1], pdu, sizeof(NFAPI_UL_CCCH_pdu_t));

    // Update disk space usage
    total_disk_space_usage += pdu->data_length;

    pthread_mutex_unlock(&lock);
}

void manage_file_entries() {
    while (total_disk_space_usage > MAX_DISK_SPACE) {
        int i;
        for (i = 0; i < num_file_entries; ++i) {
            if (file_entries[i].fd != NULL && file_entries[i].timestamp <= time(NULL) - 60 * 60) { // Close idle file entries
                fclose(file_entries[i].fd);
                free(file_entries[i].fd);
                --num_file_entries;
                break;
            }
        }

        if (i == num_file_entries) {
            break; // No idle files to close
        }

        total_disk_space_usage -= file_entries[i].data_length;

        for (int j = i + 1; j < num_file_entries; ++j) {
            file_entries[j - 1] = file_entries[j];
        }
        --num_file_entries;
    }
}

void init_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context, uint32_t UE_ID, int RRC_STATE) {
    pthread_mutex_lock(&lock);
    // Initialize UE context
    ue_context->UE_ID = UE_ID;
    ue_context->RRC_STATE = RRC_STATE;
    ue_context->pdu_list_size = 0;
    ue_context->pdu_list = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
    if (ue_context->pdu_list == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    // Initialize file entries
    file_entry* temp_file_entries = (fileEntry*)malloc(sizeof(fileEntry) * MAX_SIZE);
    for (int i = 0; i < MAX_SIZE; ++i) {
        temp_file_entries[i].fd = NULL;
        temp_file_entries[i].timestamp = 0;
    }
    num_file_entries = MAX_SIZE;

    pthread_mutex_unlock(&lock);
}

void remove_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context) {
    pthread_mutex_lock(&lock);
    // Remove UE context and its associated file entries
    free(ue_context->pdu_list);
    for (int i = 0; i < num_file_entries; ++i) {
        if (file_entries[i].fd != NULL && file_entries[i].timestamp <= time(NULL) - 60 * 60) { // Close idle file entries
            fclose(file_entries[i].fd);
            free(file_entries[i].fd);
        }
    }

    free(file_entries);

    pthread_mutex_unlock(&lock);
}

void log_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context) {
    printf("UE context added: UE ID - %d, RRC State - %d\n", ue_context->UE_ID, ue_context->RRC_STATE);
}
