#define JPEG ".jpg"
#define PNG ".png"
#define BMP ".bmp"

int process_images(char *dir_path, char *target_ext, int max_file_size, int concurrency_level) {
    DIR *d = opendir(dir_path);
    if (!d) {
        printf("Error opening directory\n");
        return 1;
    }

    int processed_files = 0;
    int total_size = 0;

    for (struct dirent *ent; (ent = readdir(d)) != NULL;) {
        if ((strcmp(ent->d_name + strlen(target_ext), target_ext) == 0) &&
            (strlen(ent->d_name) > strlen(target_ext))) {
            char file_path[1024];
            sprintf(file_path, "%s/%s", dir_path, ent->d_name);

            int fd = open(file_path, O_RDONLY);
            if (fd < 0) {
                printf("Error opening file %s\n", file_path);
                continue;
            }

            struct stat sb;
            fstat(fd, &sb);
            if (sb.st_size > max_file_size) {
                printf("Warning: File %s is larger than the allowed size\n", file_path);
                close(fd);
                continue;
            }

            // Image processing logic goes here...

            processed_files++;
            total_size += sb.st_size;

            close(fd);
        }
    }

    closedir(d);

    if (processed_files > 0) {
        printf("Processed %d files, totaling %d bytes\n", processed_files, total_size);
    } else {
        printf("No image files found\n");
    }

    return 0;
}
