#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_id;
    int rrc_state;
    size_t pdu_count;
    NFAPI_UL_CCCH_pdu_t** pdus;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T* nfapi_rrc_uecontext_init(size_t capacity) {
    NFAPI_RRC_UECONTEXT_T* uecontext = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    uecontext->ue_id = 0;
    uecontext->rrc_state = -1;
    uecontext->pdu_count = 0;
    uecontext->pdus = (NFAPI_UL_CCCH_pdu_t**)calloc(capacity, sizeof(NFAPI_UL_CCCH_pdu_t*));
    pthread_mutex_init(&uecontext->mutex, NULL);
    return uecontext;
}

void nfapi_rrc_uecontext_free(NFAPI_RRC_UECONTEXT_T* uecontext) {
    for (size_t i = 0; i < uecontext->pdu_count; i++) {
        free(uecontext->pdus[i]);
    }
    free(uecontext->pdus);
    free(uecontext);
}

void nfapi_rrc_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uecontext->mutex);
    if (uecontext->pdu_count < uecontext->capacity) {
        uecontext->pdus[uecontext->pdu_count++] = pdu;
    } else {
        // handle full capacity
    }
    pthread_mutex_unlock(&uecontext->mutex);
}

void nfapi_rrc_uecontext_delete_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, size_t index) {
    pthread_mutex_lock(&uecontext->mutex);
    if (index < uecontext->pdu_count) {
