    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (contexts[i].ue_id == ue_id) {
            // Realloc the PDU list if necessary
            if (contexts[i].pdu_list.size >= contexts[i].pdu_list.capacity) {
                contexts[i].pdu_list.capacity *= 2;
                contexts[i].pdu_list.pdus = realloc(contexts[i].pdu_list.pdus, contexts[i].pdu_list.capacity * sizeof(NFAPI_UL_CCCH_pdu_t));
            }
