            contexts[i].pdu_list.pdus[contexts[i].pdu_list.size++] = pdu;
            return;
        }
    }
}

void rrc_uecontext_delete_pdu(NFAPI_RRC_UECONTEXT_T* contexts, int ue_id, int index) {
