    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (contexts[i].ue_id == ue_id) {
            // Delete the PDU at the specified index
            free(contexts[i].pdu_list.pdus[index]);
            memmove(&contexts[i].pdu_list.pdus[index], &contexts[i].pdu_list.pdus[index + 1], (contexts[i].pdu_list.size - index - 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
            contexts[i].pdu_list.size--;
            return;
        }
    }
}

