            contexts[i].rrc_state = new_state;
            return;
        }
    }
}

void rrc_uecontext_merge_contexts(NFAPI_RRC_UECONTEXT_T* contexts, int ue_id1, int ue_id2) {
    // Find the contexts for the given UE_IDs
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (contexts[i].ue_id == ue_id1 || contexts[i].ue_id == ue_id2) {
            // Merge the PDU lists
            NFAPI_UL_CCCH_pdu_t* pdus = (NFAPI_UL_CCCH_pdu_t*)malloc((contexts[i].pdu_list.size + contexts[i - 1].pdu_list.size) * sizeof(NFAPI_UL_CCCH_pdu_t));
            memcpy(pdus, contexts[i].pdu_list.pdus, contexts[i].pdu_list.size * sizeof(NFAPI_UL_CCCH_pdu_t));
            for (int j = 0; j < contexts[i - 1].pdu_list.size; j++) {
                pdus[contexts[i].pdu_list.size + j] = contexts[i - 1].pdu_list.pdus[j];
            }
            free(contexts[i - 1].pdu_list.pdus);
            contexts[i].pdu_list.pdus = pdus;
            contexts[i].pdu_list.size += contexts[i - 1].pdu_list.size;
