            NFAPI_UL_CCCH_pdu_t* compressed_pdus = (NFAPI_UL_CCCH_pdu_t*)malloc((threshold + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
            for (int j = 0; j <= threshold; j++) {
                compressed_pdus[j] = contexts[i].pdu_list.pdus[j];
