    // Validate the integrity of the PDU list
    if (!(*ue_contexts)->pdus) {
        (*ue_contexts)->pdus = malloc(sizeof(struct list));
        if (!(*ue_contexts)->pdus) {
            printf("Memory allocation failed\n");
            return;
        }
    }

    // Add new PDUs to the dynamically allocated list
    struct list *new_pdu = malloc(sizeof(struct list));
    new_pdu->next = (*ue_contexts)->pdus;
    (*ue_contexts)->pdus = new_pdu;

    // Update UE_ID and RRC_STATE in the NFAPI_RRC_UECONTEXT_T structure
    (*ue_contexts)->ue_id = ue_id;
    (*ue_contexts)->rrc_state = rrc_state;
}

// Function to delete PDUs by index
void delete_pdu(NFAPI_RRC_UECONTEXT_T **ue_contexts, int ue_id) {
    // Find the PDU list for the given UE_ID
    struct list *current_pdu = (*ue_contexts)->pdus;
    while (current_pdu && current_pdu->ue_id != ue_id) {
        current_pdu = current_pdu->next;
    }

    if (!current_pdu) {
        printf("PDU not found for UE_ID %d\n", ue_id);
        return;
    }

    // Delete the PDU list
    struct list *prev_pdu = NULL;
    while (current_pdu && current_pdu->ue_id == ue_id) {
        prev_pdu = current_pdu;
        current_pdu = current_pdu->next;
    }

    if (prev_pdu) {
        free(prev_pdu);
    }
}

