    struct list_head entry;
} PDU;

struct list_head {
    struct list_head *next, *prev;
};

void init_list(struct list_head *head) {
    head->next = head->prev = head;
}

int list_add(struct list_head *new) {
    struct list_head *head = new->prev;
    new->next = head->next;
    new->prev = head;
    head->next->prev = new;
    head->next = new;
    return 0;
}

int list_remove(struct list_head *entry) {
    entry->prev->next = entry->next;
    entry->next->prev = entry->prev;
    entry->next = entry->prev = NULL;
    return 0;
}

void validate_pdu_list(UEContext *context) {
    // Ensure all PDUs have valid payload lengths and no null pointers
    struct list_head *entry = context->pdus.next;
    while (entry != &context->pdus) {
        PDU *pdu = container_of(entry, PDU, entry);
        if (!pdu->payload || strlen(pdu->payload) == 0) {
            printf("Invalid PDU found in UE context %d\n", context->UE_ID);
            return;
        }
        entry = entry->next;
    }
}

