    ue_contexts = (NFAPI_RRC_UECONTEXT_T*)malloc(size * sizeof(NFAPI_RRC_UECONTEXT_T));
    ue_contexts_size = size;
}

void add_pdu(int ue_id, NFAPI_UL_CCCH_pdu_t* pdu) {
    // Validate PDU list
    if (!ue_contexts || ue_contexts[0].pdu_list_size == 0) return;

    // Find UE context by ID
    int i;
    for (i = 0; i < ue_contexts_size; i++) {
        if (ue_contexts[i].ue_id == ue_id) break;
    }
    if (i >= ue_contexts_size) return;

    // Add PDU to list
    ue_contexts[i].pdu_list = realloc(ue_contexts[i].pdu_list, (ue_contexts[i].pdu_list_size + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
    ue_contexts[i].pdu_list[ue_contexts[i].pdu_list_size++] = pdu;
}

void delete_pdu(int ue_id, int index) {
