    int i;
    for (i = 0; i < ue_contexts_size; i++) {
        if (ue_contexts[i].ue_id == ue_id) break;
    }
    if (i >= ue_contexts_size) return;

    // Delete PDU from list
    if (index >= ue_contexts[i].pdu_list_size) return;
    memmove(&ue_contexts[i].pdu_list[index], &ue_contexts[i].pdu_list[index + 1], (ue_contexts[i].pdu_list_size - index - 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
