public class JsonDataProcessor
{
    public async Task<FilteredResult> ProcessJsonFileAsync(string filePath, string filterConfig)
    {
        using var fileStream = File.OpenRead(filePath);
        using var jsonReader = new Utf8JsonReader(fileStream);

        var data = await ParseJsonAsync(jsonReader, filterConfig);
        return await FilterDataAsync(data);
    }

    private async Task<JsonNode> ParseJsonAsync(Utf8JsonReader reader, string filterConfig)
    {
        var rootNode = new JsonNode();
        await ParseJsonRecursiveAsync(reader, rootNode);

        // Handle malformed sections
        if (reader.TokenEndOfStream())
        {
            return rootNode;
        }

        throw new Exception("Malformed JSON file");
    }

    private async Task ParseJsonRecursiveAsync(Utf8JsonReader reader, JsonNode parentNode)
    {
        while (true)
        {
            switch (reader.Read())
            {
                case Utf8JsonReader.Token.StartArray:
                    var arrayNode = new JsonArray();
                    await ParseJsonArrayAsync(reader, arrayNode);
                    parentNode.AddChild(arrayNode);
                    break;
                case Utf8JsonReader.Token.StartObject:
                    var objectNode = new JsonObject();
                    await ParseJsonObjectAsync(reader, objectNode);
                    parentNode.AddChild(objectNode);
                    break;
            }
        }
    }

    private async Task ParseJsonArrayAsync(Utf8JsonReader reader, JsonArray array)
    {
        while (true)
        {
            switch (reader.Read())
            {
                case Utf8JsonReader.Token.EndArray:
                    return;
                default:
                    var valueNode = new JsonValue();
                    await ParseJsonValueAsync(reader, valueNode);
                    array.Add(valueNode);
                    break;
            }
        }
    }

    private async Task ParseJsonValueAsync(Utf8JsonReader reader, JsonValue value)
    {
        switch (reader.TokenType)
        {
            case Utf8JsonReader.Token.String:
