NFAPI_CELLULAR_DATA_RECORD* create_data_records(int num_records) {
    NFAPI_CELLULAR_DATA_RECORD* records = (NFAPI_CELLULAR_DATA_RECORD*)malloc(num_records * sizeof(NFAPI CELLULAR DATA RECORD));

    for (int i = 0; i < num_records; i++) {
