    NFPAPI_LTE_CELL_CONTEXT_T* cell = (NFPAPI_LTE_CELL_CONTEXT_T*)malloc(sizeof(NFPAPI_LTE_CELL_CONTEXT_T));
    if (!cell) return NULL;
    cell->srbs_count = 0;
    return cell;
}

void add_srb(NFPAPI_LTE_CELL_CONTEXT_T* cell, NFPAPI_DL_SRB_T* srb) {
    // Add the SRB to the cell's list
    // Implement mechanism to validate SRB integrity before adding
    if (cell->srbs_count >= MAX_SRBS) {
        printf("Error: Maximum number of SRBs reached for this cell.\n");
        return;
    }
    cell->srbs = realloc(cell->srbs, sizeof(NFPAPI_DL_SRB_T*) * (cell->srbs_count + 1));
    if (!cell->srbs) {
        printf("Error: Memory allocation failure.\n");
        return;
    }
    cell->srbs[cell->srbs_count] = srb;
    cell->srbs_count++;
}

void remove_srb(NFPAPI_LTE_CELL_CONTEXT_T* cell, NFPAPI_DL_SRB_T* srb) {
    // Remove the SRB from the cell's list
    int i;
    for (i = 0; i < cell->srbs_count; i++) {
        if (cell->srbs[i] == srb) {
            // Shift all remaining SRBs to fill the gap
            memmove(&cell->srbs[i], &cell->srbs[i + 1], sizeof(NFPAPI_DL_SRB_T*) * (cell->srbs_count - i - 1));
            cell->srbs = realloc(cell->srbs, sizeof(NFPAPI_DL_SRB_T*) * (cell->srbs_count - 1));
            if (!cell->srbs) {
                printf("Error: Memory allocation failure.\n");
                return;
            }
            cell->srbs_count--;
            break;
        }
    }
}

