            printf("Processing NICP message %d...\n", i);
            // Simulate asynchronous processing
            sleep(1);
            printf("NICP message %d processed\n", i);
        } else {
            // Perform synchronous processing
            printf("Processing NICP message %d...\n", i);
            sleep(2);
            printf("NICP message %d processed\n", i);
        }

        if (log_file) {
            fprintf(log_file, "Processed NICP message %d\n", i);
        }
    }
}

void free_nicp_array(NICP_message** nicp_array, int num_messages) {
    for (int i = 0; i < num_messages; i++) {
