#include <stdlib.h>
#include <stdio.h>

#define MAX_CALLS 1000
#define MAX_PDU_SIZE 256

typedef struct {
    uint32_t ue_id;
    enum rrc_state state;
    NFAPI_UL_CCCH_pdu_t* pdus;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T** ue_context_array = NULL;
int num_ue_contexts = 0;

NFAPI_RRC_UECONTEXT_T** allocate_ue_context(int size) {
    if (ue_context_array != NULL && size < num_ue_contexts)
        return ue_context_array;

    int i;
    NFAPI_RRC_UECONTEXT_T** new_array = realloc(ue_context_array, sizeof(NFAPI_RRC_UECONTEXT_T*) * (size + 1));
    if (!new_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = num_ue_contexts; i < size; i++)
        new_array[i] = malloc(sizeof(NFAPI_RRC_UECONTEXT_T));

    ue_context_array = new_array;
    num_ue_contexts = size + 1;
    return ue_context_array;
}

void deallocate_ue_context(int start, int end) {
    if (start >= end)
        return;

    for (int i = start; i <= end; i++) {
        free(ue_context_array[i]);
        ue_context_array[i] = NULL;
    }
}

NFAPI_RRC_UECONTEXT_T** manage_ue_contexts(int new_size, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (new_size > MAX_CALLS) {
        printf("Call limit exceeded. No more UE contexts can be added.\n");
        return NULL;
    }

    if (new_size <= num_ue_contexts)
        return ue_context_array;

    NFAPI_RRC_UECONTEXT_T** new_array = allocate_ue_context(new_size);
    if (!new_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < new_size; i++) {
        new_array[i]->ue_id = pdu->id;
        new_array[i]->state = pdu->state;
        new_array[i]->pdus = malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        *new_array[i]->pdus = *pdu;
    }

    deallocate_ue_context(num_ue_contexts, new_size - 1);
    ue_context_array = new_array;
    num_ue_contexts = new_size;

    return ue_context_array;
}
