#define MAX_CALLS 1000
#define MAX_PDUS_PER_UE 10
#define LOG_MSG_SIZE 256

typedef struct {
    uint32_t ue_id;
    enum rrc_state state;
    struct list_head pdus;
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    uint16_t len;
    char data[1];
} NFAPI_UL_CCCH_pdu_t;

int manage_ue_contexts(NFAPI_RRC_UECONTEXT_T **ue_ctxs, int *num_ue_ctxs) {
    static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    static int call_count = 0;
    static int max_pdu_per_ue = MAX_PDUS_PER_UE;
    NFAPI_RRC_UECONTEXT_T *new_ue_ctx;

    pthread_mutex_lock(&lock);

    if (call_count >= MAX_CALLS) {
        printf("Call limit exceeded. Returning NULL.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    call_count++;

    new_ue_ctx = (NFAPI_RRC_UECONTEXT_T *)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!new_ue_ctx) {
        printf("Memory allocation failed. Returning NULL.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    new_ue_ctx->ue_id = 0; // Initialize UE ID
    new_ue_ctx->state = RRC_STATE_IDLE; // Initialize RRC state
    INIT_LIST_HEAD(&new_ue_ctx->pdus);

    if (*num_ue_ctxs >= MAX_PDUS_PER_UE) {
        printf("Maximum PDUs per UE reached. Returning NULL.\n");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    list_add_tail(&new_ue_ctx->pdus, &(*ue_ctxs)->pdus);

    *num_ue_ctxs++;

    pthread_mutex_unlock(&lock);

    return ue_ctxs;
}

void free_ue_context(NFAPI_RRC_UECONTEXT_T *ue_ctx) {
    pthread_mutex_lock(&lock);

    list_del(&ue_ctx->pdus);
    free(ue_ctx);

    pthread_mutex_unlock(&lock);
}
