    if (!Directory.Exists(directoryPath))
        return false;

    var webApplication = new WebApplication();
    if (!webApplication.VirtualDirectories.Count > 0
        || !File.Exists(Path.Combine(directoryPath, "web.config"))
        || !File.Exists(Path.Combine(directoryPath, "appsettings.json"))
        || !Directory.GetFiles(directoryPath, "*.cshtml").Any())
        return false;

