        return false;

    try
    {
        WebAdministration.AddWebApplication(site.Name, directoryPath);
    }
    catch (Exception ex)
    {
        LogError(ex.Message);
        return false;
    }

    try
    {
        WebAdministration.StartWebApplication(site.Name);
    }
    catch (Exception ex)
    {
        LogError(ex.Message);
        return false;
    }

