class ConfigEncryptor:
    def __init__(self, config_file_path, encryption_algorithm):
        self.config_file_path = config_file_path
        self.encryption_algorithm = encryption_algorithm
        self.schema = {
            'placeholders': ['{PASSWORD}', '{USERNAME}'],
            'required_fields': ['password', 'username']
        }
        self.kms = None

    def validate_schema(self, config_data):
        for field in self.schema['required_fields']:
            if field not in config_data:
                raise ValueError(f"Missing required field {field}")
        return True

    def encrypt_config(self, config_data):
        encrypted_config = {}
        for key, value in config_data.items():
            encrypted_value = None
            if isinstance(value, str) and '{' in value:
                placeholder = value.split('{')[1].split('}')[0]
                if placeholder in self.schema['placeholders']:
                    if self.encryption_algorithm == 'aes':
                        encrypted_value = self.encrypt_aes(placeholder)
                    elif self.encryption_algorithm == 'rsa':
                        encrypted_value = self.encrypt_rsa(placeholder)
                    else:
                        raise ValueError(f"Unsupported encryption algorithm {self.encryption_algorithm}")
                else:
                    encrypted_value = value
            else:
                encrypted_value = value
            encrypted_config[key] = encrypted_value
        return encrypted_config

    def encrypt_aes(self, plaintext):
        key = self.generate_key('aes')
        cipher = Cipher(algorithms.AES(key), modes.CBC(os.urandom(16)), default_backend())
        encryptor = cipher.encryptor()
        ciphertext = encryptor.update(plaintext.encode()) + encryptor.finalize()
        return {'ciphertext': ciphertext, 'iv': encryptor_nonce().decode()}

    def encrypt_rsa(self, plaintext):
        key = self.generate_key('rsa')
        encrypted_value = crypto_encrypt(key, plaintext)
        return {'encrypted_value': encrypted_value, 'public_key': key.publickey().dumpToString()}

    def generate_key(self, algorithm):
        if not self.kms:
            raise ValueError("KMS is not initialized")
        key_id = self.kms.get_key_id(algorithm)
        if not key_id:
            raise ValueError(f"No available {algorithm} key found in KMS")
        return self.kms.get_key(key_id)

    def write_config(self, encrypted_config):
        with open(self.config_file_path, 'w') as file:
            json.dump(encrypted_config, file)

def main():
    if len(sys.argv) < 3:
        print("Usage: python config_encryptor.py <config_file_path> <encryption_algorithm>")
        sys.exit(1)
    config_file_path = sys.argv[1]
    encryption_algorithm = sys.argv[2]

    try:
        with open(config_file_path, 'r') as file:
            config_data = json.load(file)
    except FileNotFoundError:
        print(f"Config file {config_file_path} not found")
        sys.exit(1)

    if not os.path.exists(config_file_path):
        raise ValueError(f"Config file {config_file_path} does not exist")

    try:
