NFAPI_CRC_INDICATION_PDU_T* createCRCIndicationPDUList(int n, int* error) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        *error = -1;
        return NULL;
    }

    for (int i = 0; i < n; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        list[i].RNTI = rand() % 65536;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        int flag = rand() % 2; // Randomly generate CRCFLAG, ensure no two consecutive are same
        if (i > 0 && flag == list[i-1].CRCFLAG) {
            flag = 1 - flag; // Adjust if necessary to avoid consecutive duplicates
        }
        list[i].CRCFLAG = flag;
    }

    return list;
