#include <stdlib.h>
#include <string.h>

typedef struct LTE_RRC_CELLS_T {
    int id;
    int state;
    struct LTE_RRC_MESSAGES_T* messages;
    size_t message_count;
} LTE_RRC_CELLS_T;

typedef struct LTE_RRC_MESSAGES_T {
    char* data;
    size_t length;
    struct LTE_RRC_MESSAGES_T* next;
} LTE_RRC_MESSAGES_T;

LTE_RRC_CELLS_T* init_cell(int id, int state) {
    LTE_RRC_CELLS_T* cell = (LTE_RRC_CELLS_T*)malloc(sizeof(LTE_RRC_CELLS_T));
    if (!cell) return NULL;
    cell->id = id;
    cell->state = state;
    cell->messages = NULL;
    cell->message_count = 0;
    return cell;
}

void add_message(LTE_RRC_CELLS_T* cell, char* data, size_t length) {
    LTE_RRC_MESSAGES_T* new_message = (LTE_RRC_MESSAGES_T*)malloc(sizeof(LTE_RRC_MESSAGES_T));
    if (!new_message) return;
    new_message->data = (char*)malloc(length + 1);
    if (!new_message->data) {
        free(new_message);
        return;
    }
    memcpy(new_message->data, data, length);
    new_message->length = length;
    new_message->next = cell->messages;
    cell->messages = new_message;
    cell->message_count++;
}

void remove_message(LTE_RRC_CELLS_T* cell) {
    if (!cell->messages) return;
    LTE_RRC_MESSAGES_T* current = cell->messages;
    LTE_RRC_MESSAGES_T* previous = NULL;
    while (current && current->next) {
        previous = current;
        current = current->next;
    }
    if (current) {
        free(current->data);
        free(current);
        if (previous) {
            previous->next = NULL;
        } else {
            cell->messages = NULL;
        }
        cell->message_count--;
    }
}

void update_message(LTE_RRC_CELLS_T* cell, char* data, size_t length) {
    LTE_RRC_MESSAGES_T* current = cell->messages;
    while (current) {
        if (current->length == length && memcmp(current->data, data, length) == 0) {
            free(current->data);
            current->data = (char*)malloc(length + 1);
            memcpy(current->data, data, length);
            return;
        }
        current = current->next;
    }
}

bool validate_cell(LTE_RRC_CELLS_T* cell) {
    if (!cell || !cell->messages) return true;
    LTE_RRC_MESSAGES_T* current = cell->messages;
    while (current) {
        if (!current->data || current->length == 0) return false;
        current = current->next;
    }
    return true;
}

void free_cell(LTE_RRC_CELLS_T* cell) {
    LTE_RRC_MESSAGES_T* current = cell->messages;
    while (current) {
        LTE_RRC_MESSAGES_T* next = current->next;
        free(current->data);
        free(current);
        current = next;
    }
    free(cell);
}

void init_cell_data(LTE_RRC_CELLS_T** cells, int num_cells) {
    for (int i = 0; i < num_cells; i++) {
        cells[i] = init_cell(i, 0);
    }
}
