// Define message structure
typedef struct {
    int sender_id;
    int recipient_id;
    time_t timestamp;
    char** segments;
    int segment_count;
} Message;

// Define custom memory pool
typedef struct {
    void* buffer;
    size_t capacity;
    size_t current_size;
} MemoryPool;

// Initialize memory pool
MemoryPool* init_memory_pool(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->buffer = malloc(capacity);
    pool->capacity = capacity;
    pool->current_size = 0;
    return pool;
}

// Allocate memory from custom pool
void* allocate_from_pool(MemoryPool* pool, size_t size) {
    if (pool->current_size + size > pool->capacity) {
        // Pool is full; resize and reallocate
        pool->buffer = realloc(pool->buffer, 2 * pool->capacity);
        pool->capacity *= 2;
    }
    void* ptr = (char*)pool->buffer + pool->current_size;
    pool->current_size += size;
    return ptr;
}

// Deallocate memory from custom pool
void deallocate_from_pool(MemoryPool* pool, void* ptr) {
    if (ptr != NULL) {
        char* addr = (char*)ptr;
        // Find the next available block in the pool
        size_t offset = 0;
        for (; offset < pool->current_size; offset++) {
            if (*((char*)pool->buffer + offset) == '\0') {
                break;
            }
        }
        // Shift blocks to fill gap
        memmove(pool->buffer, addr, pool->current_size - offset);
        pool->current_size -= offset;
    }
}

// Process message contexts (thread-safe)
void processMessageContexts(Message* msg, MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex); // Acquire lock for thread safety

    // Validate and add segment
    if (msg != NULL && pool != NULL) {
        // Check segment format, size, and integrity checksum
        if (validateSegment(msg->segments[0], msg->segment_count)) {
            // Segment is valid; add it to the message context
            void* ptr = allocate_from_pool(pool, msg->segment_count * sizeof(char));
            memcpy(ptr, msg->segments[0], msg->segment_count);
            deallocate_from_pool(pool, msg->segments[0]);
        } else {
            // Invalid segment; log error and report
            logError("Invalid segment");
            reportError("Segment validation failed");
        }
    }

    pthread_mutex_unlock(&pool->mutex); // Release lock for thread safety
}

// Helper function to find and print the largest integer
void printLargestInteger(int* arr, int size) {
    int max = *arr;
    for (int i = 1; i < size; i++) {
        if (*arr > max) {
            max = *arr;
        }
    }
    printf("The largest integer is %d.\n", max);
}

