```python
import socket

def process_connections(addresses):
    server_counts = {}
    total_requests = 0

    for address in addresses:
        try:
            sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            sock.connect((address, 80))  # Replace with actual port

            # Process the connection
            requests = 0
            while True:
                # Receive data from the server
                data = sock.recv(BUFFER_SIZE)

                if not data:
                    break

                requests += 1

            sock.close()

            if address in server_counts:
                server_counts[address] += requests
            else:
                server_counts[address] = requests

            total_requests += requests

        except Exception as e:
            # Handle errors and log the exception
            print(f"Error processing {address}: {e}")

    return {"counts": server_counts, "total": total_requests}
