typedef struct {
    char *filename;
    int packet_count;
    double total_bandwidth;
} NetworkPacket;

void manage_states(int *initial_states, int num_initial_states, void **protocol_stack, int last_state) {
    // Initialize the state list
    int *states = (int *)malloc((num_initial_states + 1) * sizeof(int));
    states[0] = last_state;

    for (int i = 0; i < num_initial_states; i++) {
        states[i+1] = initial_states[i];
    }

    // Initialize the state transition table
    int **transition_table = (int **)malloc((num_initial_states + 1) * sizeof(int *));
    for (int i = 0; i <= num_initial_states; i++) {
        transition_table[i] = (int *)malloc((last_state + 1) * sizeof(int));
    }

    // Initialize the packet list
    NetworkPacket **packets = (NetworkPacket **)malloc(num_initial_states * sizeof(NetworkPacket *));
    for (int i = 0; i < num_initial_states; i++) {
        packets[i] = (NetworkPacket *)malloc(sizeof(NetworkPacket));
        packets[i]->filename = strdup("packet");
        packets[i]->packet_count = 1;
        packets[i]->total_bandwidth = 0.0;
    }

    // Initialize the logging mechanism
    FILE *log_file = fopen("state_log.txt", "w");
    setvbuf(log_file, NULL, _IONBF);

    // Main loop
    while (true) {
        // Handle new states
        int new_state;
        if (!fgets(&new_state, sizeof(int), stdin)) break;
        int *new_states = realloc(states, (num_initial_states + 1) * sizeof(int));
        new_states[num_initial_states++] = new_state;

        // Handle packet additions and retrievals
        for (int i = 0; i < num_initial_states; i++) {
            if (!fgets(&packets[i]->packet_count, sizeof(int), stdin)) break;
            packets[i]->total_bandwidth += atof(fgets(&packets[i]->total_bandwidth, sizeof(double), stdin));
        }

        // Serialize the state list
        FILE *state_file = fopen("states.txt", "w");
        for (int i = 0; i < num_initial_states; i++) {
            fprintf(state_file, "%d\n", states[i]);
        }
        fclose(state_file);
    }

    // Clean up
    for (int i = 0; i < num_initial_states; i++) {
        free(packets[i]->filename);
        free(packets[i]);
    }
    free(packets);
    for (int i = 0; i <= num_initial_states; i++) {
        free(transition_table[i]);
    }
    free(transition_table);
    free(states);
}
