#include <unistd.h>
#include <xmlparse.h>

#define XML_FILE "config.xml"
#define LIB_CHECKSUM "lib_checksum"
#define LOG_FILE "app_log.txt"

void* lib_handle = NULL;
int (*lib_func)(int, int);

int load_library(const char* lib_name) {
    void* handle = dlopen(lib_name, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "Error loading library: %s\n", dlerror());
        return 1;
    }

    // Load the XML config
    xmlDocPtr doc = xmlReadFile(XML_FILE, NULL, XML_PARSE_NOERROR | XML_PARSE_NOWARNING);
    if (doc == NULL) {
        fprintf(stderr, "Failed to load configuration file.\n");
        return 1;
    }

    xmlNodePtr root = xmlDocGetRootElement(doc);
    lib_func = (int (*)(int, int))xmlGetIntAttribute(root, LIB_CHECKSUM);

    // Check the library checksum
    if (lib_func == NULL || *lib_func != get_int_value_from_xml(root, "checksum")) {
        fprintf(stderr, "Error: Loaded library checksum does not match expected value.\n");
        dlclose(handle);
        return 1;
    }

    // Verify and log the loaded library
    FILE* log_file = fopen(LOG_FILE, "a+");
    if (log_file != NULL) {
        fprintf(log_file, "[LOAD] Successfully loaded library: %s\n", lib_name);
        fclose(log_file);
    }

    return 0;
}

void unload_library() {
    dlclose(lib_handle);
}

int main(int argc, char* argv[]) {
    // Load the library
    if (load_library("mylib.so")) {
        fprintf(stderr, "Error: Failed to load library.\n");
        return 1;
    }

    lib_handle = dlopen("mylib.so", RTLD_LAZY);
    int result = (*lib_func)(10, 20); // Call the loaded function with parameters
    if (result < 0) {
        fprintf(stderr, "Error: Library function call failed.\n");
    } else {
        printf("Result: %d\n", result);
    }

    // Unload the library and log the unload operation
    unload_library();
    FILE* log_file = fopen(LOG_FILE, "a+");
    if (log_file != NULL) {
        fprintf(log_file, "[UNLOAD] Successfully unloaded library.\n");
        fclose(log_file);
    }

    return 0;
}
