# Define a retry mechanism for failed jobs with exponential backoff
def retry_exponential(max_retries, delay):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            for _ in range(max_retries):
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    time.sleep(delay)
                    if delay < 60: 
                        delay *= 2
                    else: break
            raise Exception(f"Failed to execute {func.__name__} after {max_retries} retries")
        return wrapper
    return decorator

# Implement auto-scaling based on current workload
