    struct list_head *pdu_list_head;
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    uint64_t timestamp;
    // Add other PDU attributes as needed
} NFAPI_UL_CCCH_pdu_t;

void *uecontext_malloc(size_t size) {
    return malloc(size);
}

void uecontext_free(void *ptr) {
    free(ptr);
}

int add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T *ue_ctx, NFAPI_UL_CCCH_pdu_t *pdu) {
    pthread_mutex_lock(&ue_ctx->pdu_list_lock);
    // Add the PDU to the end of the list
    struct list_head *new_node = (struct list_head *)uecontext_malloc(sizeof(struct list_head));
    new_node->next = NULL;
    new_node->prev = ue_ctx->pdu_list_head;
    if(ue_ctx->pdu_list_head != NULL)
        ue_ctx->pdu_list_head->prev = &new_node->next;
    else
        ue_ctx->pdu_list_head = &new_node->next;
    *new_node.next = pdu;
    pthread_mutex_unlock(&ue_ctx->pdu_list_lock);
}

void remove_pdu_from_ue_context(NFAPI_RRC_UECONTEXT_T *ue_ctx, NFAPI_UL_CCCH_pdu_t *pdu) {
    pthread_mutex_lock(&ue_ctx->pdu_list_lock);
    // Find and remove the PDU from the list
    struct list_head *node = ue_ctx->pdu_list_head;
    while(node != NULL) {
        if(node->next == pdu) {
            node->prev->next = node->next;
            node->next->prev = node->prev;
            uecontext_free(pdu);
            return;
        }
        node = node->next;
    }
    pthread_mutex_unlock(&ue_ctx->pdu_list_lock);
}

int main() {
    // Initialize UE contexts and PDU lists
    NFAPI_RRC_UECONTEXT_T *ue_contexts = (NFAPI_RRC_UECONTEXT_T *)malloc(MAXUECONTEXT * sizeof(NFAPI_RRC_UECONTEXT_T));
    pthread_mutex_init(&ue_contexts[0].pdu_list_lock, NULL);
    struct list_head *pdu_list_head = &ue_contexts[0].pdu_list_head;

    // Add PDUs to UE contexts
    NFAPI_UL_CCCH_pdu_t pdus[] = {(1), (2), (3)};
    for(int i = 0; i < sizeof(pdus) / sizeof(pdus[0]); i++) {
        add_pdu_to_ue_context(&ue_contexts[0], &pdus[i]);
    }

    // Remove PDUs from UE contexts
    for(int i = 0; i < sizeof(pdus) / sizeof(pdus[0]); i++) {
        remove_pdu_from_ue_context(&ue_contexts[0], &pdus[i]);
    }

    free(ue_contexts);
    return 0;
}
