#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int session_id;
    int protocol_state;
    struct message* messages;
} session_context;

typedef struct {
    char* data;
    size_t size;
} message;

session_context* create_session(int id, int state) {
    session_context* ctx = (session_context*) malloc(sizeof(session_context));
    ctx->session_id = id;
    ctx->protocol_state = state;
    ctx->messages = NULL;
    return ctx;
}

void add_message(session_context* ctx, char* data, size_t size) {
    message* msg = (message*) malloc(sizeof(message));
    msg->data = (char*) malloc(size);
    strcpy(msg->data, data);
    msg->size = size;

    if (ctx->messages == NULL) {
        ctx->messages = (message*) malloc(sizeof(message));
        ctx->messages->data = msg->data;
        ctx->messages->size = msg->size;
    } else {
        message* current = ctx->messages;
        while (current != NULL) {
            if (current->size + size > 1048576) { // max allowed size
                free(current->data);
                current->data = (char*) malloc(size + current->size);
                strcpy(current->data, data);
                current->size += size;
                break;
            }
            current = current->next;
        }
    }
}

void remove_message(session_context* ctx) {
    message* msg = ctx->messages;
    while (msg != NULL) {
        free(msg->data);
        msg = msg->next;
    }
    free(ctx->messages);
    ctx->messages = NULL;
}

int validate_session(session_context* ctx) {
    if (ctx == NULL || ctx->session_id < 0 || ctx->protocol_state < 0) {
        return -1; // invalid session
    }

    message* msg = ctx->messages;
    while (msg != NULL) {
        if (strlen(msg->data) > 1048576) { // max allowed size
            return -2; // message too large
        }
        msg = msg->next;
    }
    return 0; // valid session
}

void free_session(session_context* ctx) {
    remove_message(ctx);
    free(ctx);
}
