public:
    UEContextManager() : lock_(mutex_) {}

    void addPdu(NFAPI_RRC_UECONTEXT_T* ueContext, NFAPI_UL_CCCH_pdu_t* pdu) {
        unique_lock<mutex> lk(lock_);
        if (!validatePdu(ueContext, pdu)) return;
        ueContext->pdu_list.push_back(pdu);
    }

    void removePdu(NFAPI_RRC_UECONTEXT_T* ueContext, NFAPI_UL_CCCH_pdu_t* pdu) {
        unique_lock<mutex> lk(lock_);
        if (!findPdu(ueContext, pdu)) return;
        ueContext->pdu_list.erase(remove(ueContext->pdu_list.begin(), ueContext->pdu_list.end(), pdu), ueContext->pdu_list.end());
    }

    void serializeToJson(const string& filename) {
        json j;

        for (const auto& ueContext : ue_contexts_) {
            json UEContextJ;
            UEContextJ["UE_ID"] = ueContext.UE_ID;
            UEContextJ["RRC_STATE"] = ueContext.RRC_STATE;
            vector<json> pduList;

            for (const auto& pdu : ueContext.pdu_list) {
                json PDUJ;
                // Serialize PDU attributes
                pduList.push_back(PDUJ);
            }

            UEContextJ["PDU_List"] = pduList;
            j[ueContext.UE_ID] = UEContextJ;
        }

        ofstream file(filename);
        if (!file.is_open()) {
            cerr << "Error: Unable to open file for writing." << endl;
            return;
        }
        file << std::setw(4) << json(j).dump(2);
    }

    void deserializeFromJson(const string& filename) {
        ifstream file(filename);
        if (!file.is_open()) {
            cerr << "Error: Unable to open file for reading." << endl;
            return;
        }
        json j = json::parse(file);

        for (const auto& [ueID, UEContextJ] : j.items()) {
            NFAPI_RRC_UECONTEXT_T* ueContext = &getUEContext(ueID);
            if (!ueContext) continue;

            int RRC_STATE = UEContextJ["RRC_STATE"].get<int>();
            vector<NFAPI_UL_CCCH_pdu_t*> pduList;
            for (const auto& PDUJ : UEContextJ["PDU_List"].as<vector<json>>()) {
                // Deserialize PDU attributes
                NFAPI_UL_CCCH_pdu_t* pdu = new NFAPI_UL_CCCH_pdu_t();
                pduList.push_back(pdu);
            }
            ueContext->RRC_STATE = RRC_STATE;
            ueContext->pdu_list = move(pduList);
        }
    }

private:
    vector<NFAPI_RRC_UECONTEXT_T> ue_contexts_;
    mutex lock_;

    NFAPI_RRC_UECONTEXT_T* getUEContext(const string& UE_ID) {
        for (const auto& ueContext : ue_contexts_) {
            if (ueContext.UE_ID == UE_ID) return &ueContext;
        }
        return nullptr;
    }

    bool validatePdu(NFAPI_RRC_UECONTEXT_T* ueContext, NFAPI_UL_CCCH_pdu_t* pdu) {
        // Validate PDU attributes
