    bool findPdu(NFAPI_RRC_UECONTEXT_T* ueContext, NFAPI_UL_CCCH_pdu_t* pdu) {
        for (const auto& p : ueContext->pdu_list) {
            if (*p == *pdu) return true;
        }
        return false;
    }
