import json
from datetime import datetime, timedelta
from flask import jsonify

class ProductAPI:
    def __init__(self):
        self.products = []
        self.batches = {}
        self.threshold = 1000
        self.categories = ['Electronics', 'Fashion', 'Home Goods']

    def validate(self, data):
        if data['price'] < 0 or data['stock'] > self.threshold:
            return False
        if data['category'] not in self.categories:
            return False
        return True

    def persist(self, batch):
        try:
            db.connect()
            for product in batch:
                if product['action'] == 'create':
                    db.insert(product)
                elif product['action'] == 'update':
                    db.update(product)
                elif product['action'] == 'delete':
                    db.delete(product)
            db.commit()
        except Exception as e:
            db.rollback()
            return {'status': 'error', 'message': str(e)}
        finally:
            db.close()

    def get(self, id):
        for product in self.products:
            if product['id'] == id:
                return product
        return None

    def handle_request(self, data):
        try:
            if data['sub_action'] == 'delete':
                product = self.get(data['id'])
                if product:
                    self.products.remove(product)
                    batch_id = datetime.now().strftime('%Y%m%d%H%M%S')
                    self.batches[batch_id] = [{'action': 'delete', 'product': product}]
                    return {'status': 'success', 'message': f"Product {data['id']} deleted successfully"}
                else:
                    return {'status': 'error', 'message': "Product not found"}
            elif data['sub_action'] == 'update':
                if self.get(data['id']):
                    self.products[self.products.index(self.get(data['id']))] = data
                    batch_id = datetime.now().strftime('%Y%m%d%H%M%S')
                    self.batches[batch_id] = [{'action': 'update', 'product': data}]
                    return {'status': 'success', 'message': f"Product {data['id']} updated successfully"}
                else:
                    return {'status': 'error', 'message': "Product not found"}
            elif data['sub_action'] == 'create':
                if self.validate(data):
                    self.products.append(data)
                    batch_id = datetime.now().strftime('%Y%m%d%H%M%S')
                    self.batches[batch_id] = [{'action': 'create', 'product': data}]
                    return {'status': 'success', 'message': f"Product created successfully"}
                else:
                    return {'status': 'error', 'message': "Invalid product data"}
            else:
                return {'status': 'error', 'message': "Invalid sub-action"}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}

    def execute_batches(self):
        try:
            for batch_id, batch in self.batches.items():
                self.persist(batch)
                del self.batches[batch_id]
            self.products = []
            self.batches = {}
        except Exception as e:
            return {'status': 'error', 'message': str(e)}

    def run(self):
        while True:
            try:
                for batch_id, batch in list(self.batches.items()):
                    if (datetime.now() - datetime.strptime(batch_id, '%Y%m%d%H%M%S')).total_seconds() > 300:  # 5 minutes
                        self.execute_batches()
                        break
                time.sleep(1)
            except Exception as e:
                return {'status': 'error', 'message': str(e)}

api = ProductAPI()
