    [ApiController]
    [Route("api/[controller]")]
    public class UpdateController : ControllerBase
    {
        private readonly IUpdateService _updateService;

        public UpdateController(IUpdateService updateService)
        {
            _updateService = updateService;
        }

        [HttpPost]
        public async Task<IActionResult> Post([FromBody] JObject payload, string userId, string sessionToken)
        {
            if (!ValidateSessionToken(sessionToken))
                return BadRequest("Invalid session token");

            var updates = payload["updates"].ToObject<List<Update>>();
            foreach (var update in updates)
            {
                await _updateService.UpdateElement(userId, update.Id, update.NewContent);
            }

            return Ok(new Response
            {
                RefreshPage = true,
                StatusMessages = updates.Select(u => new StatusMessage { Id = u.Id, Message = "Updated successfully" })
            });
        }
    }

    public class Update
    {
        public string Id { get; set; }
        public string NewContent { get; set; }
    }

    public class Response
    {
        public bool RefreshPage { get; set; }
        public List<StatusMessage> StatusMessages { get; set; }
    }

    public class StatusMessage
    {
        public string Id { get; set; }
        public string Message { get; set; }
    }
}
