typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    uint16_t crcflag; // Unique CRC flag for each structure
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int N) {
    if (N < 0 || N == 0) {
        return NULL;
    }

    int max_structures = 10000; // Maximum allowed structures
    int bytes_per_structure = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (N > max_structures) {
        N = max_structures;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;

    for (int i = 0; i < N; i++) {
        pdu_array[i].rx_ue_info = (RX_UE_INFORMATION_TAG)i; // Initialize with unique values
        pdu_array[i].rnti = (RNTI)(i % 256); // Initialize RNTI with random value
        pdu_array[i].crc_indication_rel8_tag = (CRC_INDICATION_REL8_TAG)i; // Initialize with unique values

        // Generate unique CRC flag for each structure
        srand((unsigned int)time(NULL));
        pdu_array[i].crcflag = (uint16_t)(rand() % 65535);

        if (!pdu_array) {
            pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(bytes_per_structure * N);
            if (!pdu_array) {
                // Log error and return
                printf("Error allocating memory.\n");
                return NULL;
            }
        } else {
            pdu_array[i].crcflag = (uint16_t)(rand() % 65535); // Assign new CRC flag for each structure
        }

        // Validate CRC flag integrity across all structures
        int crc_flag_valid = 1; // Assume all flags are valid initially

        for (int j = 0; j < i; j++) {
            if (pdu_array[j].crcflag == pdu_array[i].crcflag) {
                crc_flag_valid = 0;
                break;
            }
        }

        if (!crc_flag_valid) {
            // Log error and return
            printf("CRC flag integrity failed.\n");
            return NULL;
        }
    }

    return pdu_array;
}
