                printf("Usage: %s [-h] [-v] [-d <delimiter>] [-o <output_file>] [files...]\n", argv[0]);
                exit(0);
            case 'v':
                log_level = DEBUG;
                break;
            case 'd':
                default_delimiter = optarg;
                break;
            case 'o':
                default_output_file = optarg;
                break;
        }
    }

    if (argc < 2) {
        printf("Error: No input file provided. Use -h for help.\n");
        return 1;
    }

    int line_count = 0;
    regex_t delimiter;
    regcomp(&delimiter, default_delimiter, REG_EXTENDED);

    for (int i = 1; i < argc; i++) {
        FILE* file = fopen(argv[i], "r");
        if (!file) {
            // implement error handling for file operations
        }

        char line[MAX_LINE_LENGTH];
        while (fgets(line, sizeof(line), file)) {
            line_count++;
        }
    }

    regfree(&delimiter);

    printf("Total lines: %d\n", line_count);

    return 0;
}
