using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;

public class UpdatePage
{
    public async Task<Response> HandleUpdate(HttpRequestMessage request)
    {
        var requestBody = await request.Content.ReadAsJsonAsync<UpdatePayload>();
        if (requestBody == null) return new Response { Status = "Invalid Request" };

        var sessionTokenService = new SessionTokenService();
        var permissionService = new PermissionService();

        if (!sessionTokenService.Validate(requestBody.SessionToken)) 
            return new Response { Status = "Unauthorized Access" };

        if (!permissionService.HasPermission(requestBody.UserID, request.Method))
            return new Response { Status = "Access Denied" };

        var updateService = new UpdateService();
        var response = await Task.Run(() => 
        {
            try
            {
                foreach (var element in requestBody.Elements)
                {
                    await updateService.UpdateElement(element.ID, element.NewContent);
                }
                return new Response { Refresh = true, StatusMessage = "Updates Applied Successfully" };
            }
            catch (Exception ex) when (ex is InvalidOperationException || ex is HttpRequestException)
            {
                // Handle concurrent updates gracefully
                return new Response { Refresh = false, StatusMessage = $"Failed to Update Element '{element.ID}' due to {ex.Message}" };
            }
            catch (Exception ex)
            {
                // Rollback on partial failure
                foreach (var element in requestBody.Elements)
                {
                    await updateService.RollbackUpdate(element.ID);
                }
                return new Response { Refresh = false, StatusMessage = $"Partial Update Failed: {ex.Message}" };
            }
        });

        // Integrate with external notification system for critical errors
        if (response.Status == "Failed to Update Element" || response.StatusMessage.Contains("Error"))
        {
            await NotifyAdminsOfCriticalErrors(requestBody);
        }

        return response;
    }
}

public class UpdatePayload
{
    public int UserID { get; set; }
    public string SessionToken { get; set; }
    public Element[] Elements { get; set; }
}

public class Element
{
    public int ID { get; set; }
    public string NewContent { get; set; }
    public int PriorityLevel { get; set; }
}
