    uint64_t vnfc_instance_id;
    VNF_CIRCUIT_CONFIG_T* circuit_config;
} VNFC_INSTANCE_CONFIG_T;

typedef struct {
    pthread_mutex_t lock;
    int num_vnfs;
    NFV_API_VNF_CONTEXT_T** vnf_contexts;
} VNF_MANAGER_T;

void vnf_manager_init(VNF_MANAGER_T* manager, int num_vnfs) {
    manager->num_vnfs = num_vnfs;
    manager->vnf_contexts = (NFV_API_VNF_CONTEXT_T**)malloc(num_vnfs * sizeof(NFV_API_VNF_CONTEXT_T*));
}

void vnf_manager_destroy(VNF_MANAGER_T* manager) {
    for(int i = 0; i < manager->num_vnfs; i++) {
        if(manager->vnf_contexts[i]->config_map)
            hashmap_destroy(manager->vnf_contexts[i]->config_map);
        free(manager->vnf_contexts[i]);
    }
    free(manager->vnf_contexts);
}

void vnf_manager_update_circuit_config(VNF_MANAGER_T* manager, uint32_t vnf_id, uint64_t vnfc_instance_id, VNF_CIRCUIT_CONFIG_T* circuit_config) {
    pthread_mutex_lock(&manager->lock);

    for(int i = 0; i < manager->num_vnfs; i++) {
        if(manager->vnf_contexts[i]->vnf_id == vnf_id) {
            HashMap* config_map = manager->vnf_contexts[i]->config_map;
            VNFC_INSTANCE_CONFIG_T* instance_config = (VNFC_INSTANCE_CONFIG_T*)malloc(sizeof(VNFC_INSTANCE_CONFIG_T));
            instance_config->vnfc_instance_id = vnfc_instance_id;
            instance_config->circuit_config = circuit_config;
            hashmap_put(config_map, vnfc_instance_id, instance_config);

            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

void vnf_manager_notify_vnf_reached_threshold(VNF_MANAGER_T* manager, uint32_t vnf_id) {
    pthread_mutex_lock(&manager->lock);

    for(int i = 0; i < manager->num_vnfs; i++) {
        if(manager->vnf_contexts[i]->vnf_id == vnf_id) {
            // Notify clients asynchronously
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }

    pthread_mutex_unlock(&manager->lock);
}

