// Structure to represent a session
typedef struct {
    char *session_id;
    time_t expiration_timestamp;
    int num_endpoints;
    struct endpoint **endpoints;
} Session;

// Structure to represent an endpoint
typedef struct {
    char *ip_address;
    int port;
    time_t last_access_time;
} Endpoint;

// Function to initialize a new session
Session *init_session(char *session_id, int num_endpoints) {
    // Initialize the session structure
    Session *s = (Session *)malloc(sizeof(Session));
    s->session_id = strdup(session_id);
    s->expiration_timestamp = time(NULL) + 3600; // Set expiration timestamp to 1 hour from now
    s->num_endpoints = num_endpoints;
    s->endpoints = (struct endpoint **)malloc(num_endpoints * sizeof(struct endpoint *));
    for (int i = 0; i < num_endpoints; i++) {
        s->endpoints[i] = (Endpoint *)malloc(sizeof(Endpoint));
    }
    return s;
}

// Function to update an existing session
void update_session(Session *s, char *new_ip_address, int new_port) {
    // Update the endpoint structure
    for (int i = 0; i < s->num_endpoints; i++) {
        if (strcmp(s->endpoints[i]->ip_address, new_ip_address) == 0 &&
            s->endpoints[i]->port == new_port) {
            s->endpoints[i]->last_access_time = time(NULL);
            break;
        }
    }
}

// Function to terminate a session
void term_session(Session *s) {
    // Free the session structure and its endpoints
    for (int i = 0; i < s->num_endpoints; i++) {
        free(s->endpoints[i]);
    }
    free(s->session_id);
    free(s);
}

// Function to notify clients when a session reaches expiration
void notify_session_expiration(Session *s) {
    // Notify clients that the session has expired
    printf("Session %s has expired.\n", s->session_id);
}
