import threading
from collections import defaultdict
from typing import Dict, List

class SessionManager:
    def __init__(self):
        self.session_pool = []
        self.packets_by_session: Dict[int, List[dict]] = defaultdict(list)
        self.packet_count_by_session: Dict[int, int] = {}
        self.max_sessions = 100
        self.max_packets_per_session = 100
        self.payload_size_limit = 4096
        self.garbage_collection_interval = 600  # seconds (10 minutes)

    def _expand_session_pool(self):
        if len(self.session_pool) < self.max_sessions:
            new_max_sessions = int(self.max_sessions * 1.5)
            self.max_sessions = new_max_sessions
            return True
        return False

    def add_packet(self, session_id: int, packet_data: dict) -> bool:
        if not self._validate_packet(session_id, packet_data):
            return False
        if session_id not in self.packets_by_session:
            self.session_pool.append(session_id)
            self._expand_session_pool()
        self.packets_by_session[session_id].append(packet_data)
        self.packet_count_by_session[session_id] += 1
        if len(self.packets_by_session[session_id]) > self.max_packets_per_session:
            raise Exception(f"Session {session_id} has reached packet limit (max: {self.max_packets_per_session})")
        return True

    def _validate_packet(self, session_id: int, packet_data: dict) -> bool:
        if not isinstance(packet_data.get('payload'), bytes):
            raise ValueError("Packet payload must be a bytes object")
        if len(packet_data['payload']) > self.payload_size_limit:
            raise ValueError(f"Packet payload size exceeds limit (max: {self.payload_size_limit} bytes)")
        return True

    def close_session(self, session_id: int) -> None:
        if session_id not in self.packets_by_session:
            return
        self.session_pool.remove(session_id)
        del self.packets_by_session[session_id]
        del self.packet_count_by_session[session_id]

    def garbage_collect(self) -> None:
        current_time = int(time.time())
        for session_id, packets in list(self.packets_by_session.items()):
            if not any(packet['timestamp'] > current_time - 600 for packet in packets):
                self.close_session(session_id)

    def log_performance(self) -> None:
        print(f"Session count: {len(self.session_pool)}")
        print(f"Packets added: {sum(self.packet_count_by_session.values())}")
        print(f"Avg. packet size: {(sum(len(packet['payload']) for packets in self.packets_by_session.values() for packet in packets) / sum(len(packets) for packets in self.packets_by_session.values())):.2f} bytes")

    def start_garbage_collection_thread(self) -> None:
        threading.Thread(target=self.garbage_collect, daemon=True).start()

    def log_session_data(self, session_id: int) -> None:
        # Implement integration with external logging service
        pass

# Example usage:
session_manager = SessionManager()
session_manager.start_garbage_collection_thread()
try:
    for i in range(5):
        session_manager.add_packet(i, {'payload': b'Hello World!', 'timestamp': int(time.time())})
except Exception as e:
    print(f"Error: {e}")
finally:
    for session_id in range(5):
        session_manager.close_session(session_id)
session_manager.log_performance()
