#define DEFAULT_DELIMITER "\n"
#define DEFAULT_OUTPUT_FILE "aggregated_stats.txt"

typedef enum {
    VERBOSE_MODE = 1,
    SILENT_MODE
} mode_t;

void process_file(const char* file_path, const char* delimiter, int* total_lines);
void log_error(const char* message);
void log_warning(const char* message);

int main(int argc, char* argv[]) {
    int total_lines = 0;
    FILE *output_file = stdout;
    mode_t mode = SILENT_MODE;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0) {
            if (i + 1 < argc) {
                char* delimiter_str = argv[i + 1];
                int len = strlen(delimiter_str);
                for (int j = 0; j < len; j++) {
                    if (!strchr(DEFAULT_DELIMITER, delimiter_str[j])) {
                        log_error("Invalid delimiter character");
                        return 1;
                    }
                }
                // Set the custom delimiter
                free((void*)DEFAULT_DELIMITER);
                DEFAULT_DELIMITER = (char*)malloc(len + 1);
                strcpy(DEFAULT_DELIMITER, delimiter_str);
            } else {
                log_warning("Missing delimiter value");
            }
        } else if (strcmp(argv[i], "-o") == 0) {
            if (i + 1 < argc) {
                const char* output_file_path = argv[i + 1];
                // Check if the file exists
                FILE *temp_file = fopen(output_file_path, "w");
                if (!temp_file) {
                    log_error("Invalid output file path");
                    return 1;
                }
                fclose(temp_file);
                output_file = fopen(output_file_path, "w");
            } else {
                log_warning("Missing output file path");
            }
        } else if (strcmp(argv[i], "-v") == 0) {
            mode = VERBOSE_MODE;
        }

    }

    // Process each input file
    for (int i = 1; i < argc; i++) {
        const char* file_path = argv[i];
        process_file(file_path, DEFAULT_DELIMITER, &total_lines);
    }

    // Output the aggregated statistics
    fprintf(output_file, "Total lines: %d\n", total_lines);

    return 0;
}

void process_file(const char* file_path, const char* delimiter, int* total_lines) {
    FILE *file = fopen(file_path, "r");
    if (!file) {
        log_error("Failed to open file");
        return;
    }

    int lines_in_file = 0;

    while (1) {
        char buffer[1024];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read == 0)
            break;

        for (char* p = strtok(buffer, delimiter); p; p = strtok(NULL, delimiter)) {
            lines_in_file++;
        }
    }

    fclose(file);

    *total_lines += lines_in_file;

    if (mode == VERBOSE_MODE) {
        printf("Processed file '%s' with %d lines.\n", file_path, lines_in_file);
    }
}

