function loadScripts(scriptList) {
  const scriptOrder = {};
  const scriptDependencies = {};

  // Initialize script order and dependencies
  for (let i = 0; i < scriptList.length; i++) {
    scriptOrder[scriptList[i]] = i;
    scriptDependencies[scriptList[i]] = [];
  }

  // Resolve dependencies
  function resolveDependencies(script) {
    if (scriptDependencies[script].length === 0) return;

    const promises = scriptDependencies[script].map((dep) => loadScript(dep));
    Promise.all(promises).then(() => {
      // Execute the current script once all dependencies are resolved
      loadScript(script);
    });
  }

  function loadScript(script) {
    if (!script) throw new Error('Invalid script');

    return new Promise((resolve, reject) => {
      const scriptTag = document.createElement('script');
      scriptTag.src = `scripts/${script}.js`;
      scriptTag.onload = () => resolve();
      scriptTag.onerror = (error) => reject(error);

      document.body.appendChild(scriptTag);
    });
  }

  // Load scripts in the correct order
  for (let i = 0; i < scriptList.length; i++) {
    const script = scriptList[i];
    if (!scriptDependencies[script].length) {
      loadScript(script);
    } else {
      resolveDependencies(script);
    }
  }
}
