    NFAPI_RRC_UECONTEXT_T* uecontext = (NFAPI_RRC_UECONTEXT_T*)arg;

    // Initialize and handle a dynamic array of structures
    init_ue_context();

    while (1) {
        // Validate the integrity of the PDU list before any operations
        validate_pdu_list(uecontext->pdus);

        for (int i = 0; i < MAX_TOKENS; i++) {
