void add_call_record(CallRecord** call_records, int num_call_records, int caller_id, int called_id, int start_time, int end_time, int duration) {
    // Initialize a new call record
    CallRecord* call_record = (CallRecord*)malloc(sizeof(CallRecord));

    if (call_record == NULL) {
        printf("Out of memory!\n");
        exit(1);
    }

    // Set the caller and called IDs, start time, end time, and duration for the call record
    call_record->caller_id = caller_id;
    call_record->called_id = called_id;
    call_record->start_time = start_time;
    call_record->end_time = end_time;
    call_record->duration = duration;

