// Function to remove a call record by ID
void remove_call_record(CallRecord** call_records, int num_call_records, int id) {
    for (int i = 0; i < num_call_records; i++) {
        if (call_records[i]->id == id) {
            // Free the memory allocated for the call record
            free(call_records[i]);

            // Shift all subsequent call records down by one position
            for (int j = i + 1; j < num_call_records; j++) {
                call_records[j - 1] = call_records[j];
