#define MAX_UE_CONTEXTS 10000
#define MAX_PDUS_PER_CONTEXT 1000

typedef struct {
    uint32_t ue_id;
    enum NFAPI_RRC_STATE state;
    struct PDU_list {
        size_t size;
        size_t capacity;
        struct PDU **pdus;
    } pdu_list;
} NFAPI_RRC_UECONTEXT_T;

NFAPI_RRC_UECONTEXT_T *ue_contexts = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_ue_contexts() {
    ue_contexts = (NFAPI_RRC_UECONTEXT_T *)malloc(MAX_UE_CONTEXTS * sizeof(NFAPI_RRC_UECONTEXT_T));
    for (size_t i = 0; i < MAX_UE_CONTEXTS; ++i) {
        ue_contexts[i].pdu_list.size = 0;
        ue_contexts[i].pdu_list.capacity = MAX_PDUS_PER_CONTEXT;
        ue_contexts[i].pdu_list.pdus = (struct PDU **)malloc(MAX_PDUS_PER_CONTEXT * sizeof(struct PDU *));
    }
}

void add_pdu_to_uecontext(size_t context_id, NFAPI_UL_CCCH_PDU_T *pdu) {
    pthread_mutex_lock(&lock);
    if (ue_contexts[context_id].pdu_list.size >= ue_contexts[context_id].pdu_list.capacity) {
        // Double the capacity
        size_t new_capacity = ue_contexts[context_id].pdu_list.capacity * 2;
        struct PDU **new_pdus = (struct PDU **)realloc(ue_contexts[context_id].pdu_list.pdus, new_capacity * sizeof(struct PDU *));
        if (!new_pdus) {
            // Handle memory error
            pthread_mutex_unlock(&lock);
            return;
        }
        ue_contexts[context_id].pdu_list.capacity = new_capacity;
        ue_contexts[context_id].pdu_list.pdus = new_pdus;
    }
    ue_contexts[context_id].pdu_list.pdus[ue_contexts[context_id].pdu_list.size++] = pdu;
    pthread_mutex_unlock(&lock);
}

void remove_pdu_from_uecontext(size_t context_id, size_t index) {
    pthread_mutex_lock(&lock);
    if (index >= ue_contexts[context_id].pdu_list.size) {
        // Handle out-of-bounds error
        pthread_mutex_unlock(&lock);
        return;
    }
    for (size_t i = index; i < ue_contexts[context_id].pdu_list.size - 1; ++i) {
        ue_contexts[context_id].pdu_list.pdus[i] = ue_contexts[context_id].pdu_list.pdus[i + 1];
    }
    free(ue_contexts[context_id].pdu_list.pdus[--ue_contexts[context_id].pdu_list.size]);
    pthread_mutex_unlock(&lock);
}

void iterate_pdus_in_reverse_order(size_t context_id) {
    pthread_mutex_lock(&lock);
    for (size_t i = ue_contexts[context_id].pdu_list.size - 1; i >= 0; --i) {
        // Process PDU
    }
    pthread_mutex_unlock(&lock);
}

int is_uecontext_valid(size_t context_id) {
    pthread_mutex_lock(&lock);
    int valid = 1;
    for (size_t i = 0; i < ue_contexts[context_id].pdu_list.size; ++i) {
        if (!ue_contexts[context_id].pdu_list.pdus[i]) {
            // Handle invalid PDU
            valid = 0;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
    return valid;
}
