#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MAX_CELLS 500
#define MAX_PDUS 20000

typedef struct {
    CELL_ID cell_id;
    RRC_STATE rrc_state;
    map_t* pdu_map;
} NFAPI_RRC_CELLCONTEXT_T;

typedef struct {
    PREAMBLE_ID id;
    UL_CCCH_pdu_t pdu;
} map_entry_t;

typedef struct {
    map_entry_t** entries;
    int size;
    pthread_mutex_t lock;
} map_t;

NFAPI_RRC_CELLCONTEXT_T* initialize_cell_context() {
    NFAPI_RRC_CELLCONTEXT_T* cell_ctx = (NFAPI_RRC_CELLCONTEXT_T*)malloc(sizeof(NFAPI_RRC_CELLCONTEXT_T));
    cell_ctx->cell_id = 0;
    cell_ctx->rrc_state = RRC_STATE_IDLE;
    cell_ctx->pdu_map = create_map();
    return cell_ctx;
}

void add_pdu_to_cell_context(NFAPI_RRC_CELLCONTEXT_T* cell_ctx, PREAMBLE_ID id, UL_CCCH_pdu_t pdu) {
    pthread_mutex_lock(&cell_ctx->pdu_map->lock);
    map_entry_t* entry = (map_entry_t*)malloc(sizeof(map_entry_t));
    entry->id = id;
    entry->pdu = pdu;
    cell_ctx->pdu_map->entries = realloc(cell_ctx->pdu_map->entries, (++cell_ctx->pdu_map->size) * sizeof(map_entry_t*));
    cell_ctx->pdu_map->entries[cell_ctx->pdu_map->size - 1] = entry;
    pthread_mutex_unlock(&cell_ctx->pdu_map->lock);
}

void remove_pdu_from_cell_context(NFAPI_RRC_CELLCONTEXT_T* cell_ctx, PREAMBLE_ID id) {
    pthread_mutex_lock(&cell_ctx->pdu_map->lock);
    for (int i = 0; i < cell_ctx->pdu_map->size; i++) {
        if (cell_ctx->pdu_map->entries[i]->id == id) {
            free(cell_ctx->pdu_map->entries[i]);
            memmove(&cell_ctx->pdu_map->entries[i], &cell_ctx->pdu_map->entries[i + 1], sizeof(map_entry_t*) * (cell_ctx->pdu_map->size - i - 1));
            cell_ctx->pdu_map->size--;
            break;
        }
    }
    pthread_mutex_unlock(&cell_ctx->pdu_map->lock);
}

void iterate_over_pdus(NFAPI_RRC_CELLCONTEXT_T* cell_ctx, int (*callback)(PREAMBLE_ID, UL_CCCH_pdu_t)) {
    pthread_mutex_lock(&cell_ctx->pdu_map->lock);
    for (int i = 0; i < cell_ctx->pdu_map->size; i++) {
        callback(cell_ctx->pdu_map->entries[i]->id, cell_ctx->pdu_map->entries[i]->pdu);
    }
    pthread_mutex_unlock(&cell_ctx->pdu_map->lock);
}

void iterate_over_pdus_in_reverse(NFAPI_RRC_CELLCONTEXT_T* cell_ctx, int (*callback)(PREAMBLE_ID, UL_CCCH_pdu_t)) {
    pthread_mutex_lock(&cell_ctx->pdu_map->lock);
    for (int i = cell_ctx->pdu_map->size - 1; i >= 0; i--) {
        callback(cell_ctx->pdu_map->entries[i]->id, cell_ctx->pdu_map->entries[i]->pdu);
    }
    pthread_mutex_unlock(&cell_ctx->pdu_map->lock);
}

map_t* create_map() {
    map_t* map = (map_t*)malloc(sizeof(map_t));
    map->entries = (map_entry_t**)malloc(sizeof(map_entry_t*) * MAX_PDUS);
    map->size = 0;
    pthread_mutex_init(&map->lock, NULL);
    return map;
}

void destroy_map(map_t* map) {
    for (int i = 0; i < map->size; i++) {
        free(map->entries[i]);
    }
    free(map->entries);
    free(map);
    pthread_mutex_destroy(&map->lock);
}
