use std::fs;
use std::env;
use log::{info, error};
use std::path::Path;

pub fn manage_log_directory() -> Result<(), Box<dyn std::error::Error>> {
    let home_dir = dirs::home_dir().unwrap();
    let target_path = home_dir.join("logs");

    if env::var("LOGS_DIR").is_ok() {
        info!("Using existing logs directory: {}", &env::var("LOGS_DIR")?.as_str());
        return Ok(()); // already set, no need to create
    }

    match fs::create_dir_all(&target_path) {
        Ok(_) => {
            info!("Created new logs directory at: {}", target_path.display());
            env::set_var("LOGS_DIR", target_path.to_str().unwrap())?;
        }
        Err(err) => {
            error!("Failed to create logs directory: {}", err);
            return Err(Box::new(err));
        }
    };

    Ok(())
}
