#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_id;
    enum RRC_STATE rrc_state;
    struct PDU_list* pdu_list;
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    NFAPI_UL_CCCH_pdu_t* pdu;
    time_t age;
} PDU_list_item;

struct PDU_list {
    int size;
    int capacity;
    PDU_list_item** pdus;
    pthread_mutex_t lock;
};

void uecontext_init(NFAPI_RRC_UECONTEXT_T* uecontext) {
    pthread_mutex_init(&uecontext->pdu_list->lock, NULL);
}

void uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t* pdu) {
    PDU_list_item* item = malloc(sizeof(PDU_list_item));
    item->pdu = pdu;
    item->age = time(NULL);

    pthread_mutex_lock(&uecontext->pdu_list->lock);
    if (uecontext->pdu_list->size == uecontext->pdu_list->capacity) {
        // Reallocate and resize the PDU list
        uecontext->pdu_list->capacity *= 2;
        uecontext->pdu_list->pdus = realloc(uecontext->pdu_list->pdus, 
                                             sizeof(PDU_list_item*) * uecontext->pdu_list->capacity);
    }

    int i;
    for (i = 0; i < uecontext->pdu_list->size; ++i) {
        if (item->age - uecontext->pdu_list->pdus[i]->age > MAX_AGE_THRESHOLD) {
            // Remove outdated PDUs
            free(uecontext->pdu_list->pdus[i]);
            for (; i < uecontext->pdu_list->size - 1; ++i) {
                uecontext->pdu_list->pdus[i] = uecontext->pdu_list->pdus[i + 1];
            }
            --uecontext->pdu_list->size;
        }
    }

    if (uecontext->pdu_list->size < uecontext->pdu_list->capacity / 2) {
        // Reallocate and resize the PDU list
        uecontext->pdu_list->capacity /= 2;
        uecontext->pdu_list->pdus = realloc(uecontext->pdu_list->pdus, 
                                             sizeof(PDU_list_item*) * uecontext->pdu_list->capacity);
    }

    pthread_mutex_unlock(&uecontext->pdu_list->lock);

    uecontext->pdu_list->pdus[uecontext->pdu_list->size++] = item;
}

void uecontext_remove_pdu(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uecontext->pdu_list->lock);
    int i;
    for (i = 0; i < uecontext->pdu_list->size; ++i) {
        if (uecontext->pdu_list->pdus[i]->pdu == pdu) {
            // Remove the PDU
            free(uecontext->pdu_list->pdus[i]);
            for (; i < uecontext->pdu_list->size - 1; ++i) {
                uecontext->pdu_list->pdus[i] = uecontext->pdu_list->pdus[i + 1];
            }
            --uecontext->pdu_list->size;
        }
    }
    pthread_mutex_unlock(&uecontext->pdu_list->lock);
}

void uecontext_merge_data(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t** pdus) {
    // Merge incoming data with existing contexts
    int i, j;
    for (i = 0; i < uecontext->pdu_list->size; ++i) {
        for (j = 0; j < MAX_PDUS_PER_CONTEXT && i + j < uecontext->pdu_list->size; ++j) {
            NFAPI_UL_CCCH_pdu_t* pdu = pdus[i + j];
            if (pdu != NULL) {
                // Add the PDU to the context
                uecontext_add_pdu(uecontext, pdu);
                pdus[i + j] = NULL;
            }
        }
    }
}

void uecontext_validate(NFAPI_RRC_UECONTEXT_T* uecontext) {
