NFAPI_RRC_UECONTEXT_T* create_ue_context(int size) {
    NFAPI_RRC_UECONTEXT_T* ue_ctx = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!ue_ctx)
        return NULL;
    pthread_mutex_init(&ue_ctx->lock, NULL);
    ue_ctx->pdu_list = (NFAPI_UL_CCCH_pdu_t*)calloc(size, sizeof(NFAPI_UL_CCCH_pdu_t));
    if (!ue_ctx->pdu_list) {
        free(ue_ctx);
        return NULL;
    }
    return ue_ctx;
}

void destroy_ue_context(NFAPI_RRC_UECONTEXT_T* ue_ctx) {
    pthread_mutex_destroy(&ue_ctx->lock);
    free(ue_ctx->pdu_list);
    free(ue_ctx);
}

void add_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&ue_ctx->lock);
    // Validate PDU before adding
    if (!validate_pdu(pdu)) {
        pthread_mutex_unlock(&ue_ctx->lock);
        return;
    }
    // Add PDU to the list
    ue_ctx->pdu_list = realloc(ue_ctx->pdu_list, (ue_ctx->list_size + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
    memcpy((void*)&ue_ctx->pdu_list[ue_ctx->list_size], pdu, sizeof(NFAPI_UL_CCCH_pdu_t));
    ue_ctx->list_size++;
    pthread_mutex_unlock(&ue_ctx->lock);
}

int remove_pdu(NFAPI_RRC_UECONTEXT_T* ue_ctx, int index) {
    pthread_mutex_lock(&ue_ctx->lock);
    if (index < 0 || index >= ue_ctx->list_size)
        return -1;
    // Remove PDU from the list
    memmove((void*)&ue_ctx->pdu_list[index], &ue_ctx->pdu_list[index + 1],
            (ue_ctx->list_size - index - 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
    ue_ctx->list_size--;
    pthread_mutex_unlock(&ue_ctx->lock);
    return 0;
}

