typedef struct Edge {
    int edge_id;
    pthread_mutex_t lock;
} Edge;

Node nodes[MAX_NODES];
Edge edges[MAX_EDGES];

void init_node(int node_id) {
    nodes[node_id].node_id = node_id;
    nodes[node_id].edges = (int *)malloc(sizeof(int));
    nodes[node_id].edge_count = 0;
    pthread_mutex_init(&nodes[node_id].mutex, NULL);
}

void add_edge(int node_id, int edge_id) {
    pthread_mutex_lock(&nodes[node_id].mutex);

    if (nodes[node_id].edge_count >= MAX_EDGES) {
        printf("Maximum edges reached for node %d.\n", node_id);
        return;
    }

    Edge new_edge = {edge_id, PTHREAD_MUTEX_INITIALIZER};
    nodes[node_id].edges[nodes[node_id].edge_count++] = edge_id;

    pthread_mutex_unlock(&nodes[node_id].mutex);
}

void remove_edge(int node_id, int edge_id) {
    pthread_mutex_lock(&nodes[node_id].mutex);

    for (int i = 0; i < nodes[node_id].edge_count; i++) {
        if (nodes[node_id].edges[i] == edge_id) {
            memmove(&nodes[node_id].edges[i], &nodes[node_id].edges[i + 1], 
                    (nodes[node_id].edge_count - i - 1) * sizeof(int));
            nodes[node_id].edge_count--;
            break;
        }
    }

    pthread_mutex_unlock(&nodes[node_id].mutex);
}

void iterate_edges(int node_id, int (*func)(int)) {
    pthread_mutex_lock(&nodes[node_id].mutex);

    for (int i = 0; i < nodes[node_id].edge_count; i++) {
        func(nodes[node_id].edges[i]);
    }

    pthread_mutex_unlock(&nodes[node_id].mutex);
}

void iterate_edges_desc(int node_id, int (*func)(int)) {
    pthread_mutex_lock(&nodes[node_id].mutex);

    for (int i = nodes[node_id].edge_count - 1; i >= 0; i--) {
        func(nodes[node_id].edges[i]);
    }

    pthread_mutex_unlock(&nodes[node_id].mutex);
}

