public class UpdatePageService
{
    private readonly IUpdateService _updateService;
    private readonly ILogger _logger;

    public UpdatePageService(IUpdateService updateService, ILogger logger)
    {
        _updateService = updateService;
        _logger = logger;
    }

    public async Task<HttpResponse> HandleUpdate(HttpRequest request)
    {
        var userSessionToken = GetSessionTokenFromRequest(request);
        if (string.IsNullOrEmpty(userSessionToken))
            return new HttpResponse { StatusCode = 401, StatusMessage = "Unauthorized" };

        try
        {
            var payload = JsonConvert.DeserializeObject<Payload>(await request.Content.ReadAsStringAsync());
            await _updateService.UpdatePage(userSessionToken, payload);
            return new HttpResponse { StatusCode = 200 };
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating page");
            if (_updateService.HasFailedToUpdate(userSessionToken))
                return new HttpResponse { StatusCode = 500 };

            await Task.Delay(_updateService.GetRetryDelay());
            return HandleUpdate(request);
        }
    }

    private class HttpResponse
    {
        public int StatusCode { get; set; }
        public string StatusMessage { get; set; }
    }

    private class Payload
    {
        public int[] Elements { get; set; }
    }

    public interface IUpdateService
    {
        Task UpdatePage(string userSessionToken, Payload payload);
        bool HasFailedToUpdate(string userSessionToken);
        TimeSpan GetRetryDelay();
    }
}

public class UpdateService : IUpdateService
{
    private readonly IDatabaseConnection _databaseConnection;
    private readonly ILogger _logger;

    public UpdateService(IDatabaseConnection databaseConnection, ILogger logger)
    {
        _databaseConnection = databaseConnection;
        _logger = logger;
    }

