    {
        try
        {
            await _databaseConnection.UpdatePage(userSessionToken, payload);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating page");
            if (!await _databaseConnection.HasFailedToUpdate(userSessionToken))
                throw;
        }
    }

    public bool HasFailedToUpdate(string userSessionToken) => _databaseConnection.HasFailedToUpdate(userSessionToken);

    public TimeSpan GetRetryDelay() => _databaseConnection.GetRetryDelay();
}

