// Structure to manage a dynamic array of NFAPI_RRC_UECONTEXT_T structures
typedef struct {
    int size;
    NFAPI_RRC_UECONTEXT_T **ueContexts;
} UE_Context_Manager;

// Function to initialize and manage the UE context manager
UE_Context_Manager* ueContextManagerInit(int maxUeContexts) {
    UE_Context_Manager *manager = (UE_Context_Manager*)malloc(sizeof(UE_Context_Manager));
    if (!manager) return NULL;

    manager->size = 0;
    manager->ueContexts = (NFAPI_RRC_UECONTEXT_T**)calloc(maxUeContexts, sizeof(NFAPI_RRC_UECONTEXT_T*));

    return manager;
}

// Function to add a new PDU to the UE context
int ueContextAddPdu(UE_Context_Manager *manager, int ueId, NFAPI_UL_CCCH_PDU_t *pdu) {
    if (!manager || !pdu) return -1; // Validation check

    // Find the corresponding UE context based on UE_ID
    for (int i = 0; i < manager->size; i++) {
        if (manager->ueContexts[i]->ueId == ueId) {
            // Append the new PDU to the existing UE context's list of PDUs
            NFAPI_UL_CCCH_PDU_t **pdus = &manager->ueContexts[i]->pdus;
            *pdus = (NFAPI_UL_CCCH_PDU_t*)realloc(*pdus, (*pdus ? (*pdus)->size + 1 : 1) * sizeof(NFAPI_UL_CCCH_PDU_t));
            if (!*pdus) return -2; // Memory allocation failure

            (*pdus)[(*pdus)->size++] = pdu;

            return i; // Return the index of the updated UE context
        }
    }

    // UE context not found, create a new one and add the PDU
    if (manager->size >= manager->ueContexts) {
        // Resize the array of UE contexts
        NFAPI_RRC_UECONTEXT_T **newUeContexts = (NFAPI_RRC_UECONTEXT_T**)realloc(manager->ueContexts, ++manager->size * sizeof(NFAPI_RRC_UECONTEXT_T*));
        if (!newUeContexts) return -3; // Memory allocation failure

        manager->ueContexts = newUeContexts;
    }

    NFAPI_RRC_UECONTEXT_T *newUeContext = (NFAPI_RRC_UECONTEXT_T*)malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!newUeContext) return -4; // Memory allocation failure

    newUeContext->ueId = ueId;
    newUeContext->rrcState = NFAPI_RRC_STATE_UNKNOWN;
    newUeContext->pdus = (NFAPI_UL_CCCH_PDU_t*)malloc(sizeof(NFAPI_UL_CCCH_PDU_t));
    if (!newUeContext->pdus) return -5; // Memory allocation failure

    (*newUeContext->pdus) = pdu;

    manager->ueContexts[manager->size++] = newUeContext;

    return manager->size - 1; // Return the index of the newly created UE context
}

// Function to update a UE context from an external data source asynchronously
void ueContextUpdateAsync(UE_Context_Manager *manager, int ueId) {
    // Asynchronous operation to retrieve updated UE context information

    // Update the UE context's RRC state and PDUs based on the retrieved information

    // Validate integrity of the updated PDU list before updating the UE context
}

// Function to perform garbage collection and clean up unused contexts and PDUs
void ueContextGC(UE_Context_Manager *manager) {
    for (int i = 0; i < manager->size; i++) {
        if (!manager->ueContexts[i]->pdus || !manager->ueContexts[i]->pdus[0]) {
            // UE context is empty or has no PDUs, release memory and move to the next one
            free(manager->ueContexts[i]);

            // Shift remaining UE contexts down by one position
            for (int j = i; j < manager->size - 1; j++) {
                manager->ueContexts[j] = manager->ueContexts[j + 1];
            }

            manager->size--;
        }
    }
}

// Function to handle UE context changes and log updates with timestamp, UE_ID, and operation type
void ueContextLogUpdate(UE_Context_Manager *manager, int ueId, NFAPI_RRC_STATE state) {
