}

// Function to release resources and free memory allocated for the UE context manager
void ueContextManagerFree(UE_Context_Manager **manager) {
    if (*manager) {
        for (int i = 0; i < (*manager)->size; i++) {
            free((*manager)->ueContexts[i]->pdus);
            free((*manager)->ueContexts[i]);
        }

        free((*manager)->ueContexts);
        free(*manager);
