// Custom error handling mechanism
class SandeshError : public std::runtime_error {
public:
    enum class Type { NETWORK_ERROR, TRANSIENT_APP_ERROR, PERSISTENT_APP_FAILURE };
    explicit SandeshError(Type type) : runtime_error(getErrorMsg(type)) {}
private:
    static const char* getErrorMsg(SandeshError::Type type) {
        switch (type) {
            case SandeshError::NETWORK_ERROR: return "Network error";
            case SandeshError::TRANSIENT_APP_ERROR: return "Transient application-specific error";
            case SandeshError::PERSISTENT_APP_FAILURE: return "Persistent application-specific failure";
        }
    }
};

// Test double for InterfaceTable class
class MockInterfaceTable {
public:
    std::string FindVmUuidFromMetadataIp(const std::string& metadataIp) override {
        // Simulate different network configurations and potential errors
        if (metadataIp.find("192.168") != std::string::npos)
            return "expected_vm_uuid";
        else if (metadataIp.find("10.0") != std::string::npos)
            throw SandeshError(SandeshError::PERSISTENT_APP_FAILURE);
        else
            return "unexpected_vm_uuid";
    }
};

// Main program
int main() {
    // Initialize Boost Asio and thread pool
    boost::asio::io_context io;
    boost::thread_pool::limits limits(10, 100); // configurable max threads (10) and queue size (100)
    boost::thread_pool tp(io, limits);

    // Initialize test double for InterfaceTable class
    MockInterfaceTable interfaceTable;

    int successfulRequests = 0;
    int proxySessions = 0;
    int internalErrors = 0;

    while (true) {
        // Send a series of GET requests to the server under varying load conditions
        for (int i = 0; i < 100; ++i) {
            // Create a new thread pool worker and send the request
            tp.apply([&io, &interfaceTable]() {
                try {
                    // Simulate sending a GET request to the server
                    boost::asio::ip::tcp::socket s(io);
                    s.connect(boost::asio::ip::tcp::endpoint(boost::asio::ip::tcp::v4(), 80));
                    std::string request = "GET / HTTP/1.1\r\nHost: example.com\r\n\r\n";
                    boost::asio::write(s, boost::asio::buffer(request));
                    // Update statistics
                    ++successfulRequests;
                } catch (SandeshError& e) {
                    if (e.type() == SandeshError::NETWORK_ERROR)
                        ++internalErrors;
                    else if (e.type() == SandeshError::TRANSIENT_APP_ERROR)
                        ++proxySessions; // simulate proxy session establishment
                    else
                        throw; // persistent application-specific failure, rethrow the exception
                } catch (...) {
                    // Handle unexpected exceptions
                    ++internalErrors;
                }
            });
        }

        // Log detailed statistics every minute
        std::cout << "Successful requests: " << successfulRequests << ", Proxy sessions: " << proxySessions << ", Internal errors: " << internalErrors << std::endl;

        // Sleep for 1 minute before sending the next batch of requests
        boost::this_thread::sleep_for(boost::chrono::minutes(1));
    }

    return 0;
}

