typedef struct NFAPI_UL_CCCH_pdu_t {
    // structure definition for UL CCCH PDU
} NFAPI_UL_CCCH_pdu_t;

// function to manage dynamic collection of UE contexts
void NFAPI_ue_context_manager(int num_ue_contexts) {
    // allocate memory for each UE context
    NFAPI_RRC_UECONTEXT_T* ue_contexts = (NFAPI_RRC_UECONTEXT_T*)malloc(num_ue_contexts * sizeof(NFAPI_RRC_UECONTEXT_T));

    // loop through each UE context and initialize its PDUs list
    for (int i = 0; i < num_ue_contexts; i++) {
        ue_contexts[i].PDUs = NULL;
    }
}

// function to add new PDU to a UE context's list
void NFAPI_add_pdu_to_ue_context(NFAPI_RRC_UECONTEXT_T* ue_context, struct NFAPI_UL_CCCH_pdu_t* pdu) {
    // check if the UE context already has PDUs
    if (ue_context->PDUs == NULL) {
        // allocate memory for the list and initialize it with a single PDU
        ue_context->PDUs = (struct NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(struct NFAPI_UL_CCCH_pdu_t));
        ue_context->PDUs[0] = *pdu;
    } else {
        // append the new PDU to the existing list
        struct NFAPI_UL_CCCH_pdu_t* new_pdu = (struct NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(struct NFAPI_UL_CCCH_pdu_t));
        *new_pdu = *pdu;
        // add the new PDU to the end of the list
        ue_context->PDUs = realloc(ue_context->PDUs, (size_t)(ue_context->PDUs + 1));
        ue_context->PDUs[ue_context->PDUs] = *new_pdu;
    }
}

// function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
void NFAPI_crc_indication_pdu_array(int num_entries) {
    // declare the array with initial size 0
    struct NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_array = NULL;

    for (int i = 0; i < num_entries; i++) {
        // allocate memory for each CRC indication PDU structure
        struct NFAPI_CRC_INDICATION_PDU_T* crc_pdu = (struct NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));

        // set the RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG for each CRC indication PDU
        crc_pdu->RX_UE_INFORMATION_TAG = 1;
        crc_pdu->RNTI = i % 65535; // ensure valid RNTI within range [0, 65535]
        crc_pdu->CRCFLAG = rand() % 2; // set CRC flag randomly

        // if an invalid RNTI is provided, skip that entry and continue
        if (crc_pdu->RNTI < 0 || crc_pdu->RNTI > 65535) {
            free(crc_pdu);
            i--;
            continue;
        }

        // add the new CRC indication PDU to the array
        struct NFAPI_CRC_INDICATION_PDU_T** temp_array = &crc_indication_pdu_array;
        *temp_array = realloc(*temp_array, (size_t)(i + 1));
        (*temp_array)[i] = crc_pdu;

        // track the number of successfully populated structures
        int num_populated = i + 1;
    }
}

int main() {
    // example usage: manage a dynamic collection of UE contexts
    NFAPI_ue_context_manager(5);

    // example usage: add new PDU to a UE context's list
    NFAPI_RRC_UECONTEXT_T ue_context = {1, 0};
    struct NFAPI_UL_CCCH_pdu_t pdu = { /* initialize PDU structure */ };
    NFAPI_add_pdu_to_ue_context(&ue_context, &pdu);

    // example usage: dynamically allocate and populate an array of CRC indication PDUs
    int num_entries = 10;
    NFAPI_crc_indication_pdu_array(num_entries);
    printf("Number of populated structures: %d\n", num_populated);

    return 0;
}
