namespace beast = boost::beast;
namespace asio = boost::asio;

class RequestQueue {
public:
    void enqueueRequest(beast::http::request<> const& request) {
        std::unique_lock<std::mutex> lock(mutex_);
        requests_.emplace_back(request);
        lock.unlock();
        cond_.notify_one();
    }

    beast::http::response<beast::http::streambuf>
    dequeueAndProcessRequest() {
        std::unique_lock<std::mutex> lock(mutex_);
        while (requests_.empty()) {
            cond_.wait(lock);
        }
        beast::http::response<beast::http::streambuf> response = processRequest(requests_.front());
        requests_.pop();
        return response;
    }

private:
    std::queue<beast::http::request<> > requests_;
    std::mutex mutex_;
    std::condition_variable cond_;
};

class ThreadPool {
public:
    void enqueueTask(std::function<void()> task) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            tasks_.emplace_back(task);
        }
        cond_.notify_one();
    }

    void start(int numThreads) {
        threads_.reserve(numThreads);
        for (int i = 0; i < numThreads; ++i) {
            threads_.emplace_back([this] {
                while (true) {
                    std::unique_lock<std::mutex> lock(mutex_);
                    tasks_.wait(lock, [this] { return tasks_.empty(); });
                    if (tasks_.empty()) {
                        break;
                    }
                    task_ = tasks_.front();
                    tasks_.pop();
                    lock.unlock();
                    task_();
                }
            });
        }
    }

    void stop() {
        for (auto& thread : threads_) {
            thread.join();
        }
        threads_.clear();
    }

private:
    std::vector<std::thread> threads_;
    std::mutex mutex_;
    std::condition_variable cond_;
    std::function<void()> task_;
};

