void add_pdu(NFAPI_RRC_UECONTEXT_T *ue_context, NFAPI_UL_CCCH_pdu_t *pdu) {
    pthread_mutex_lock(&ue_context_lock);
    if (ue_context->PDU_list == NULL) {
        ue_context->PDU_list = malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        ue_context->PDU_list[0] = *pdu;
        total_allocated_memory += sizeof(NFAPI_UL_CCCH_pdu_t);
    } else {
        NFAPI_UL_CCCH_pdu_t *new_pdu_list = realloc(ue_context->PDU_list, (ue_context->PDU_list[0].PDU_data + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
        new_pdu_list[ue_context->PDU_list[0].PDU_data].PDU_data = pdu->PDU_data;
        ue_context->PDU_list = new_pdu_list;
        total_allocated_memory += sizeof(NFAPI_UL_CCCH_pdu_t);
    }
    pthread_mutex_unlock(&ue_context_lock);

    // Log the operation
    if (log_level >= 1) {
        printf("Added PDU to UE Context %d\n", ue_context->UE_ID);
    }

    // Check for memory overflow
    if (total_allocated_memory > THRESHOLD) {
        int overflow_count = 0;
        while (overflow_count < MAX_PDU && ue_context->PDU_list[overflow_count].PDU_data != NULL) {
            overflow_count++;
        }
        if (overflow_count >= MAX_PDU) {
            printf("UE Context %d has exceeded the maximum number of PDUs. Limiting to %d PDUs.\n", ue_context->UE_ID, MAX_PDU);
            // Queue excess PDUs for delayed processing or logging
        }
    }
}

// Function to remove a PDU from a UE_CONTEXT
void remove_pdu(NFAPI_RRC_UECONTEXT_T *ue_context, int pdu_index) {
