        if (context->pdus == NULL)
            return; // out of memory
        context->pdus->next = NULL;
    }
    struct NFAPI_UL_CCCH_PDU_T* current = context->pdus;
    while (current && current->next) {
        current = current->next;
    }
    current->next = malloc(sizeof(struct NFAPI_UL_CCCH_PDU_T));
    if (current->next == NULL)
        return; // out of memory
    *current->next = *pdu;
    current->next->next = NULL;
}

