#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int ue_id;
    int rrc_state;
    struct {
        time_t timestamp;
        void* data;
    } pdus[];
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    time_t timestamp;
    // PDU data goes here
} NFAPI_UL_CCCH_pdu_t;

// Custom memory pool to minimize fragmentation
void** memory_pool;
size_t memory_pool_size = 0;
size_t memory_pool_capacity = 0;

// Lock for concurrent access
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Flag for periodic cleanup
int do_cleanup = 1;

// Grace period for cleanup
time_t grace_period = 60; // seconds

void* malloc_from_memory_pool(size_t size) {
    if (memory_pool_size + size > memory_pool_capacity) {
        // Need to reallocate the pool
        void** new_pool = realloc(memory_pool, (memory_pool_size + size * sizeof(void*)));
        if (!new_pool) {
            return NULL;
        }
        memory_pool = new_pool;
        memory_pool_capacity += size;
    }
    return memory_pool[memory_pool_size++];
}

void free_from_memory_pool(void* ptr) {
    for (size_t i = 0; i < memory_pool_size; i++) {
        if (memory_pool[i] == ptr) {
            memmove(&memory_pool[i], &memory_pool[i + 1], (memory_pool_size - i - 1) * sizeof(void*));
            memory_pool_size--;
            return;
        }
    }
}

NFAPI_RRC_UECONTEXT_T* add_pdu(NFAPI_RRC_UECONTEXT_T* context, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&lock);

    // Add the new PDU to the list
    void* new_pdu = malloc_from_memory_pool(sizeof(NFAPI_UL_CCCH_pdu_t));
    if (!new_pdu) {
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    NFAPI_UL_CCCH_pdu_t* new_pdu = (NFAPI_UL_CCCH_pdu_t*)new_pdu;
    new_pdu->timestamp = time(NULL);

    // Check integrity before adding the PDU
    if (!context || !pdu || context->ue_id <= 0) {
        free_from_memory_pool(new_pdu);
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Add the PDU to the list
    size_t new_size = sizeof(NFAPI_UL_CCCH_pdu_t) * (context->size + 1);
    context->pdus = realloc(context->pdus, new_size);
    if (!context->pdus) {
        free_from_memory_pool(new_pdu);
        pthread_mutex_unlock(&lock);
        return NULL;
    }
    context->pdus[context->size++] = *new_pdu;

    // Log the insertion time
    printf("Inserted PDU with timestamp %lu at index %zu.\n", (unsigned long)new_pdu->timestamp, context->size - 1);

    pthread_mutex_unlock(&lock);
    return context;
}

void cleanup(NFAPI_RRC_UECONTEXT_T* context) {
    if (!do_cleanup || !context) {
        return;
    }

    pthread_mutex_lock(&lock);

    // Find unused PDUs
    for (size_t i = 0; i < context->size; i++) {
        time_t age = time(NULL) - context->pdus[i].timestamp;
        if (age > grace_period) {
            free_from_memory_pool(context->pdus[i].data);
            memmove(&context->pdus[i], &context->pdus[i + 1], (context->size - i - 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
            context->size--;
        }
    }

    pthread_mutex_unlock(&lock);
}

int main() {
    NFAPI_RRC_UECONTEXT_T* context = malloc(sizeof(NFAPI_RRC_UECONTEXT_T));
    if (!context) {
        return 1;
    }
    context->ue_id = 42;
    context->rrc_state = 0;

    // Add some PDUs
    for (int i = 0; i < 5; i++) {
        NFAPI_UL_CCCH_pdu_t* pdu = malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        if (!pdu) {
            break;
        }
        pdu->timestamp = time(NULL);
        // Add PDU data here
        context = add_pdu(context, pdu);
    }

    cleanup(context);

    return 0;
}
