#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>

typedef struct {
    int client_id;
    int state;
    char* buffer;
    size_t buffer_size;
} Connection;

Connection* add_connection(Connection** connections, size_t* num_connections) {
    // Allocate memory for the new connection
    Connection* new_conn = (Connection*)malloc(sizeof(Connection));

    if (!new_conn) {
        return NULL; // Out of memory
    }

    new_conn->client_id = -1;
    new_conn->state = 0;
    new_conn->buffer_size = 1024;

    // Add the new connection to the array
    (*num_connections)++;

    // Ensure the array has enough space for the new connection
    if (*num_connections >= sizeof(Connection*) / sizeof(*connections)) {
        size_t new_size = *num_connections * 2;
        Connection** new_array = (Connection**)realloc(connections, new_size * sizeof(*connections));

        if (!new_array) {
            free(new_conn);
            return NULL; // Out of memory
        }

        connections = new_array;
    }

    // Move the last connection to make room for the new one
    memmove(&connections[*num_connections - 1], &connections[*num_connections - 2], sizeof(Connection));

    connections[*num_connections - 1] = new_conn;

    return connections[*num_connections - 1];
}

int handle_data(Connection** connections, size_t num_connections) {
    for (size_t i = 0; i < num_connections; ++i) {
        if (!connections[i]->buffer || connections[i]->buffer_size <= 0) {
            continue; // Connection is invalid or buffer is empty
        }

        // Process the data
        printf("Received %lu bytes from client %d\n", connections[i]->buffer_size, connections[i]->client_id);

        free(connections[i]->buffer); // Free the buffer
    }

    return 0;
}

void close_connection(Connection** connections, size_t* num_connections) {
    if (*num_connections <= 0) {
        return; // No connections to close
    }

    for (size_t i = *num_connections - 1; i > 0; --i) {
        free(connections[i]->buffer);
        free(connections[i]);
    }

    memmove(connections, &connections[1], (*num_connections -= 1) * sizeof(Connection*));
}

int get_protocols(int** protocols, size_t* num_protocols) {
    // Return a list of available network protocols
    static Connection protocol_1 = {"TCP", &tcp_handler};
    static Connection protocol_2 = {"UDP", &udp_handler};

    *num_protocols = 2;

    *protocols = (int*)malloc(*num_protocols * sizeof(int));

    if (!*protocols) {
        return -1; // Out of memory
    }

    (*protocols)[0] = protocol_1.client_id;
    (*protocols)[1] = protocol_2.client_id;

    return 0;
}

int main() {
    int** protocols;
    size_t num_protocols;

    if (get_protocols(&protocols, &num_protocols)) {
        perror("Error getting protocols");
        exit(EXIT_FAILURE);
    }

    // Initialize the list of connections
    Connection* connections = NULL;
    size_t num_connections = 0;

    while (1) {
        int choice;
        printf("1. Add connection\n2. Handle data\n3. Close connection\n4. Get protocols\n5. Exit\n");
        scanf("%d", &choice);

        switch (choice) {
            case 1:
                connections = add_connection(&connections, &num_connections);
                if (!connections) {
                    perror("Error adding connection");
                    exit(EXIT_FAILURE);
                }
                break;
            case 2:
                handle_data(&connections, num_connections);
                break;
            case 3:
                close_connection(&connections, &num_connections);
                break;
            case 4:
                // Print the list of protocols
                for (size_t i = 0; i < num_protocols; ++i) {
                    printf("Protocol %zu: client_id = %d\n", i, protocols[i]);
                }
                break;
            case 5:
                exit(EXIT_SUCCESS);
            default:
                perror("Invalid choice");
                exit(EXIT_FAILURE);
        }
    }

    // Free the memory
    for (size_t i = 0; i < num_connections; ++i) {
        free(connections[i]->buffer);
        free(connections[i]);
    }
    free(connections);
    free(protocols);

    return 0;
}

