#define MAX_SIZE 1000
#define GC_INTERVAL 30 // in seconds

typedef struct NFPAI_RRC_CELL_CONTEXT_T {
    int cell_id;
    enum RRC_STATE state;
    void** rrc_conn_info;
    int conn_info_size;
} NFPAI_RRC_CELL_CONTEXT_T;

typedef struct RRC_CONNECTION_INFO_T {
    time_t last_update;
    void* crc_indication_pdu;
} RRC_CONNECTION_INFO_T;

void init_rcc_ctx(NFPAI_RRC_CELL_CONTEXT_T* rcc_ctx, int max_size) {
    rcc_ctx->cell_id = 0;
    rcc_ctx->state = 0;
    rcc_ctx->rrc_conn_info = (void**)malloc(max_size * sizeof(void*));
    rcc_ctx->conn_info_size = 0;
}

void add_rcc_conn_info(NFPAI_RRC_CELL_CONTEXT_T* rcc_ctx, int cell_id) {
    if (rcc_ctx->conn_info_size >= MAX_SIZE) {
        printf("Connection info map is full\n");
        return;
    }

    RRC_CONNECTION_INFO_T* conn_info = (RRC_CONNECTION_INFO_T*)malloc(sizeof(RRC_CONNECTION_INFO_T));
    conn_info->last_update = time(NULL);

    NFAPI_CRC_INDICATION_PDU_T* crc_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // populate crc_pdu
    rcc_ctx->rrc_conn_info[rcc_ctx->conn_info_size++] = conn_info;
}

void update_rcc_conn_info(NFPAI_RRC_CELL_CONTEXT_T* rcc_ctx, int cell_id) {
    for (int i = 0; i < rcc_ctx->conn_info_size; i++) {
        if (((RRC_CONNECTION_INFO_T*)rcc_ctx->rrc_conn_info[i])->cell_id == cell_id) {
            ((RRC_CONNECTION_INFO_T*)rcc_ctx->rrc_conn_info[i])->last_update = time(NULL);
            break;
        }
    }
}

void remove_rcc_conn_info(NFPAI_RRC_CELL_CONTEXT_T* rcc_ctx, int cell_id) {
    for (int i = 0; i < rcc_ctx->conn_info_size; i++) {
        if (((RRC_CONNECTION_INFO_T*)rcc_ctx->rrc_conn_info[i])->cell_id == cell_id) {
            free(rcc_ctx->rrc_conn_info[i]);
            memmove(&rcc_ctx->rrc_conn_info[i], &rcc_ctx->rrc_conn_info[i+1], sizeof(void*) * (rcc_ctx->conn_info_size - i));
            rcc_ctx->conn_info_size--;
        }
    }
}

void gc_rcc_ctx(NFPAI_RRC_CELL_CONTEXT_T* rcc_ctx, int gc_interval) {
    time_t current_time = time(NULL);

    for (int i = 0; i < rcc_ctx->conn_info_size; i++) {
        if (difftime(current_time, ((RRC_CONNECTION_INFO_T*)rcc_ctx->rrc_conn_info[i])->last_update) > gc_interval) {
            free(rcc_ctx->rrc_conn_info[i]);
            memmove(&rcc_ctx->rrc_conn_info[i], &rcc_ctx->rrc_conn_info[i+1], sizeof(void*) * (rcc_ctx->conn_info_size - i));
            rcc_ctx->conn_info_size--;
        }
    }
}

int main() {
    NFPAI_RRC_CELL_CONTEXT_T rcc_ctx;
    init_rcc_ctx(&rcc_ctx, MAX_SIZE);

    add_rcc_conn_info(&rcc_ctx, 1);
    update_rcc_conn_info(&rcc_ctx, 1);
    remove_rcc_conn_info(&rcc_ctx, 1);

    gc_rcc_ctx(&rcc_ctx, GC_INTERVAL);

    return 0;
}
