    enum { ESTABLISHED, FIN_WAIT_1, FIN_WAIT_2, TIME_WAIT, CLOSED } state;
    struct DATA_PACKAGE_T* packages;
    size_t package_count;
} TCP_CONNECTION_T;

typedef struct {
    // custom data here
} DATA_PACKAGE_T;

TCP_CONNECTION_T* tcp_connection_init(int new_id) {
    TCP_CONNECTION_T* conn = malloc(sizeof(TCP_CONNECTION_T));
    if (!conn) return NULL;
    conn->id = new_id;
    conn->state = ESTABLISHED;
    conn->packages = NULL;
    conn->package_count = 0;
    return conn;
}

void tcp_connection_add_package(TCP_CONNECTION_T* conn, DATA_PACKAGE_T* package) {
    if (!conn || !package) return;

    // resize array if necessary
    if (conn->package_count >= sizeof(conn->packages) / sizeof(*conn->packages)) {
        conn->packages = realloc(conn->packages, 2 * sizeof(*conn->packages));
        conn->package_count++;
    }

    conn->packages[conn->package_count++] = package;
}

int tcp_connection_validate_package(TCP_CONNECTION_T* conn, int package_id) {
    for (size_t i = 0; i < conn->package_count; i++) {
        if (conn->packages[i]->id == package_id) return 1; // found
    }
    return 0; // not found
}

void tcp_connection_free(TCP_CONNECTION_T* conn) {
    if (!conn) return;

    for (size_t i = 0; i < conn->package_count; i++) {
        free(conn->packages[i]);
    }

    free(conn->packages);
    free(conn);
}
