typedef struct {
    int rnti;
    char* rx_ue_info_tag;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

void generateNFAPI_CRC_INDICATION_PDU_T(int n, NFAPI_CRC_INDICATION_PDU_T** pdu_list) {
    Range rnti_range = getRandomValue(1, 65535);
    char* rx_ue_info_tags[] = {"RX_UE_INFO_TAG_1", "RX_UE_INFO_TAG_2"};
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rnti = getRandomInt(rnti_range);
        pdu.rx_ue_info_tag = rx_ue_info_tags[i % 2];
        Range crc_flag_range = getRandomValue(0, 1);
        pdu.crc_flag = getRandomInt(crc_flag_range);
        (*pdu_list)[i] = pdu;
    }
}
