class RandomValueGen {
private:
    int _min;
    int _max;

public:
    RandomValueGen(int min, int max) : _min(min), _max(max) {}

    float getRandFloat() {
        return (_min + (rand() % ((int)_max - _min + 1))));
    }

    int getRandInt() {
        return rand() % (_max - _min + 1) + _min;
    }

    void logRandValue(int value) {
        printf("Random Value: %d\n", value);
    }

    std::string toString() {
        char buffer[100];
        sprintf(buffer, "Range: [%d, %d]", _min, _max);
        return buffer;
    }
};

void addStructure(NFAPI_CRC_INDICATION_PDU_T** list, int* size) {
    NFAPI_CRC_INDICATION_PDU_T* newStruct = new NFAPI_CRC_INDICATION_PDU_T();
    // Initialize new structure
    strcpy(newStruct->rx_ue_info.tag, "RX_UE_INFORMATION_TAG");
    newStruct->RNTI = 1;
    newStruct->crc_flag = CRCFLAG_SET;

    list[*size] = newStruct;
    (*size)++;
}

void removeStructure(NFAPI_CRC_INDICATION_PDU_T** list, int size) {
    if (size <= 0) {
        return;
    }

    for (int i = 0; i < size - 1; i++) {
        list[i] = list[i + 1];
    }
    free(list[size - 1]);
    *size -= 1;
}

NFAPI_CRC_INDICATION_PDU_T* getStructure(NFAPI_CRC_INDICATION_PDU_T** list, int size, int index) {
    if (index >= size || index < 0) {
        return NULL; // Index out of bounds
    }
    return list[index];
}
