void init_ue_context(NFAPI_RRC_UECONTEXT_T **ue_context, int size) {
    if (!*ue_context) {
        *ue_context = (NFAPI_RRC_UECONTEXT_T *)malloc(size * sizeof(NFAPI_RRC_UECONTEXT_T));
        if (*ue_context == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
    }
}

void add_message(NFAPI_RRC_UECONTEXT_T **ue_context, uint32_t UE_ID, RRC_STATE rrc_state, NFAPI_UL_CCCH_pdu_t *message) {
    // validate before adding
    if (!*ue_context || !message) {
        printf("Invalid input\n");
        return;
    }

    int i = 0;
    while ((*ue_context)[i].messages != NULL && i < (*ue_context)->size - 1) {
        i++;
    }

    if (i == (*ue_context)->size) {
        // resize the array
        *ue_context = realloc(*ue_context, sizeof(NFAPI_RRC_UECONTEXT_T) * ((*ue_context)->size * 2));
        if (*ue_context == NULL) {
            printf("Memory allocation failed\n");
            return;
        }
    }

    (*ue_context)[i].UE_ID = UE_ID;
    (*ue_context)[i].rrc_state = rrc_state;
    (*ue_context)[i].messages = message;
}

void remove_message(NFAPI_RRC_UECONTEXT_T **ue_context, uint32_t UE_ID) {
    int i = 0;
    while (i < (*ue_context)->size) {
        if ((*ue_context)[i].UE_ID == UE_ID) {
            // free the memory of the message
            free((*ue_context)[i].messages);
            // shift all elements after this one to fill the gap
            for (int j = i; j < (*ue_context)->size - 1; j++) {
                (*ue_context)[j] = (*ue_context)[j + 1];
            }
            // shrink the array
            *ue_context = realloc(*ue_context, sizeof(NFAPI_RRC_UECONTEXT_T) * ((*ue_context)->size - 1));
            if (*ue_context == NULL) {
                printf("Memory allocation failed\n");
                return;
            }
            break;
        }
        i++;
    }
}

void clear_ue_context(NFAPI_RRC_UECONTEXT_T **ue_context) {
    for (int i = 0; i < (*ue_context)->size; i++) {
        free((*ue_context)[i].messages);
    }
    free(*ue_context);
}

int main() {
    NFAPI_RRC_UECONTEXT_T *ue_context;
    init_ue_context(&ue_context, 10);

