int g_currentSize = 0;
int g_maxStructures = MAX_STRUCTURES;
LTE_UERadioResourceContext_t** g_structures = NULL;

void initRadioResourceManager(int maxStructures) {
    g_maxStructures = maxStructures;
    g_structures = (LTE_UERadioResourceContext_t**)malloc(g_maxStructures * sizeof(LTE_UERadioResourceContext_t*));
    for (int i = 0; i < g_maxStructures; i++) {
        g_structures[i] = (LTE_UERadioResourceContext_t*)malloc(sizeof(LTE_UERadioResourceContext_t));
        g_structures[i]->signalList = NULL;
    }
}

void addSignalInfo(int UE_ID, int frequency, int powerLevel) {
    if (g_currentSize >= g_maxStructures) {
        printf("Error: Maximum number of structures exceeded.\n");
        return;
    }

    LTE_UERadioResourceContext_t* currentStructure = &g_structures[g_currentSize];
    currentStructure->UE_ID = UE_ID;
    currentStructure->RRC_STATE = 0; // default state

    LTE_PHY_SignalInfo_t* signalInfo = (LTE_PHY_SignalInfo_t*)malloc(sizeof(LTE_PHY_SignalInfo_t));
    signalInfo->frequency = frequency;
    signalInfo->powerLevel = powerLevel;

    if (currentStructure->signalList == NULL) {
        currentStructure->signalList = (struct LTE_PHY_SignalInfo_t*)malloc(sizeof(struct LTE_PHY_SignalInfo_t*));
    }
    currentStructure->signalList = (struct LTE_PHY_SignalInfo_t*)realloc(currentStructure->signalList, (g_currentSize + 1) * sizeof(LTE_PHY_SignalInfo_t*));

    currentStructure->signalList[g_currentSize] = signalInfo;
    g_currentSize++;
}

void persistRadioResourceManager() {
    FILE* file = fopen("radio_resource_manager.bin", "wb");
    if (!file) {
        printf("Error: Unable to open file for writing.\n");
        return;
    }

    for (int i = 0; i < g_currentSize; i++) {
        LTE_UERadioResourceContext_t* currentStructure = &g_structures[i];
        fwrite(&currentStructure->UE_ID, sizeof(int), 1, file);
        fwrite(&currentStructure->RRC_STATE, sizeof(int), 1, file);

        for (int j = 0; j < i + 1; j++) {
            LTE_PHY_SignalInfo_t* signalInfo = currentStructure->signalList[j];
            fwrite(&signalInfo->frequency, sizeof(int), 1, file);
            fwrite(&signalInfo->powerLevel, sizeof(int), 1, file);
        }
    }

    fclose(file);
}

void compressSignalInfo() {
    // implementation of compression algorithm
}

int validateRadioResourceContext(LTE_UERadioResourceContext_t* context) {
    if (context == NULL) return 0;
    for (int i = 0; i < g_currentSize; i++) {
        LTE_PHY_SignalInfo_t* signalInfo = context->signalList[i];
        if (signalInfo == NULL || signalInfo->frequency <= 0 || signalInfo->powerLevel <= 0) {
            return 0;
        }
    }
    return 1;
}

void logFailedValidation(int numFailures) {
    FILE* file = fopen("validation_log.txt", "a");
    if (!file) {
        printf("Error: Unable to open file for writing.\n");
        return;
    }

    fprintf(file, "%d failures over the past %d seconds.\n", numFailures, TIME_WINDOW);

    fclose(file);
}
