    if (max_size > MAX_NFAPI_RRC_UECONTEXT_T) return -1; // error: maximum size exceeded
    if (nfapi_rrc_uecontext_array != NULL) {
        for (size_t i = 0; i < nfapi_rrc_uecontext_array_size; i++) {
            free(nfapi_rrc_uecontext_array[i].pdus);
        }
        free(nfapi_rrc_uecontext_array);
    }
