        size_t new_size = realloc(uecontext->pdus, (uecontext->pdus_size + 1) * sizeof(NFAPI_UL_CCCH_pdu_t));
        if (new_size == NULL) return -3; // error: memory reallocation failed
        uecontext->pdus = new_size;
    }
    uecontext->pdus[uecontext->pdus_size++] = pdu;
    return 0;
