int write_uecontext_to_disk(const char* filename, size_t offset) {
    int fd = open(filename, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) return -4; // error: file open failed
    off64_t pos = lseek(fd, offset, SEEK_SET);
    if (pos == -1L) close(fd); // error: seek failure
    write(fd, &nfapi_rrc_uecontext_array_size, sizeof(size_t));
    for (size_t i = 0; i < nfapi_rrc_uecontext_array_size; i++) {
        write(fd, &nfapi_rrc_uecontext_array[i], sizeof(NFAPI_RRC_UECONTEXT_T));
    }
    close(fd);
    return 0;
}

int read_uecontext_from_disk(const char* filename) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) return -5; // error: file open failed
    off64_t pos = lseek(fd, 0, SEEK_SET);
    if (pos == -1L) close(fd); // error: seek failure
    size_t* array_size = malloc(sizeof(size_t));
    read(fd, array_size, sizeof(size_t));
    nfapi_rrc_uecontext_array_size = *array_size;
    for (size_t i = 0; i < nfapi_rrc_uecontext_array_size; i++) {
