typedef struct {
    uint32_t ue_id;
    enum { RRC_IDLE, RRC_CONNECTED } rrc_state;
    size_t pdu_list_len;
    LTE_RRC_CCH_pdu_t** pdu_list;
} LTE_RRC_UE_CONTEXT_T;

void init_ue_context(LTE_RRC_UE_CONTEXT_T* ue_ctx) {
    if (!ue_ctx)
        return;

    ue_ctx->pdu_list = NULL;
}

int add_pdu_to_ue_context(LTE_RRC_UE_CONTEXT_T* ue_ctx, LTE_RRC_CCH_pdu_t* pdu) {
    if (!ue_ctx || !pdu)
        return -1; // Error: null pointer

    size_t new_len = ue_ctx->pdu_list_len + 1;
    LTE_RRC_CCH_pdu_t** new_list = realloc(ue_ctx->pdu_list, sizeof(LTE_RRC_CCH_pdu_t*) * new_len);
    if (!new_list)
        return -2; // Error: memory allocation failure

    ue_ctx->pdu_list = new_list;

    for (size_t i = 0; i < ue_ctx->pdu_list_len; i++)
        *(ue_ctx->pdu_list + i) = *(ue_ctx->pdu_list + i);
    *(ue_ctx->pdu_list + ue_ctx->pdu_list_len++) = pdu;

    return 0;
}

int remove_pdu_from_ue_context(LTE_RRC_UE_CONTEXT_T* ue_ctx, size_t idx) {
    if (!ue_ctx)
        return -1; // Error: null pointer

    if (idx >= ue_ctx->pdu_list_len || !*(ue_ctx->pdu_list + idx))
        return -2; // Error: invalid index or PDU is null

    memmove(ue_ctx->pdu_list + idx, ue_ctx->pdu_list + idx + 1, sizeof(LTE_RRC_CCH_pdu_t*) * (ue_ctx->pdu_list_len - idx - 1));
    free(*(ue_ctx->pdu_list + idx));

    return 0;
}

void log_ue_context_stats(LTE_RRC_UE_CONTEXT_T* ue_ctx) {
    printf("UE Context Stats: PDUs Added/Removed = %zu/%zu\n", ue_ctx->pdu_list_len, ue_ctx->pdu_list_len);
}
