char* modify_filename(char* filename) {
    char* new_filename = NULL;
    int digits = 0;
    int i = strlen(filename) - 1;

    while (i >= 0 && isdigit(filename[i])) {
        digits++;
        i--;
    }

    if (!strcmp(".log", strrchr(filename, '.'))) {
        if (digits > 0) {
            char temp[255];
            sprintf(temp, "%s_log", filename);
            new_filename = strdup(temp);
        } else {
            new_filename = strdup(strcat(filename, ".log"));
        }
    } else if (!strcmp(".txt", strrchr(filename, '.'))) {
        if (digits > 0) {
            char temp[255];
            sprintf(temp, "%s%dc_log", filename, digits);
            new_filename = strdup(temp);
        } else {
            new_filename = strdup(strcat(filename, ".log"));
        }
    } else {
        if (strlen(filename) == 0 || !isalnum(*filename)) {
            char temp[255];
            sprintf(temp, "%s.txt", filename);
            new_filename = strdup(temp);
        } else if (digits > 0) {
            char temp[255];
            sprintf(temp, "%s%dc_log", filename, digits);
            new_filename = strdup(temp);
        } else {
            new_filename = strdup(strcat(filename, ".log"));
        }
    }

    return new_filename;
}
