}

void free_connection_desc(ConnectionDesc* desc) {
    if(desc->buffers) {
        for(int i = 0; i < desc->state; i++) {
            free(desc->buffers[i]);
        }
        free(desc->buffers);
    }
    free(desc);
}

int main() {
    // Initialize logging system
    // ...

    // Initialize connection context array
    ConnectionDesc** conn_ctxs;
    int num_conn = 10000;

    for(int i = 0; i < num_conn; i++) {
        conn_ctxs[i] = init_connection_desc();
    }

    // Periodic compaction
    pthread_t compactor_thread;
    pthread_create(&compactor_thread, NULL, compactor_function, (void*)conn_ctxs);

    // Main thread
    while(1) {
        // Handle connections...
    }

    return 0;
}

void* compactor_function(void* arg) {
    ConnectionDesc** conn_ctxs = (ConnectionDesc**)arg;

    while(1) {
