#include <iostream>
#include <string>
#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>

// Thread-safe distributed messaging queue class
class DistributedMessagingQueue {
public:
    // Constructor with configurable maximum queue size
    DistributedMessagingQueue(size_t max_queue_size) : max_queue_size_(max_queue_size), queue_(), lock_() {}

    // Enqueue a message with unique ID, priority, and payload
    void enqueue(int id, int priority, std::string payload) {
        std::unique_lock<std::mutex> lock(lock_);
        while (queue_.size() >= max_queue_size_) {
            queue_.wait(lock);
        }
        Message msg(id, priority, payload);
        queue_.push(msg);
    }

    // Dequeue a message by ID
    bool dequeue(int id) {
        std::unique_lock<std::mutex> lock(lock_);
        while (queue_.empty()) {
            queue_.wait(lock);
        }
        for (auto& msg : queue_) {
            if (msg.id == id) {
                queue_.pop();
                return true;
            }
        }
        return false;
    }

private:
    struct Message {
        int id;
        int priority;
        std::string payload;
    };

    size_t max_queue_size_;
    std::queue<Message> queue_;
    std::mutex lock_;
    std::condition_variable cv;
};

// Example usage
int main() {
    DistributedMessagingQueue queue(1000);

    // Enqueue multiple messages concurrently
    std::thread t1([&queue]() {
        for (int i = 0; i < 10; ++i) {
            queue.enqueue(i, i % 2 + 1, "Message " + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });
    std::thread t2([&queue]() {
        for (int i = 10; i < 20; ++i) {
            queue.enqueue(i, i % 3 + 1, "Message " + std::to_string(i));
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
        }
    });

    // Dequeue a message
    if (queue.dequeue(5)) {
        std::cout << "Message with ID 5 dequeued successfully!" << std::endl;
    } else {
        std::cout << "Message with ID 5 not found or failed to dequeue." << std::endl;
    }

    t1.join();
    t2.join();

    return 0;
}

