#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int id;
    enum {CLOSED, LISTENING, ESTABLISHED} state;
    void** headers;  // dynamically allocated list of protocol-specific message headers
    size_t header_count;
    pthread_mutex_t lock;
} TcpConnectionContext;

TcpConnectionContext* tcp_connection_context_new(int id) {
    TcpConnectionContext* context = malloc(sizeof(TcpConnectionContext));
    context->id = id;
    context->state = CLOSED;
    context->headers = NULL;
    context->header_count = 0;
    pthread_mutex_init(&context->lock, NULL);
    return context;
}

void tcp_connection_context_free(TcpConnectionContext* context) {
    if (!context)
        return;

    // free dynamically allocated list of headers
    for (size_t i = 0; i < context->header_count; i++)
        free(context->headers[i]);
    free(context->headers);

    pthread_mutex_destroy(&context->lock);
    free(context);
}

void tcp_connection_context_add_header(TcpConnectionContext* context, void* header) {
    // validate integrity of the header list before adding a new header
    if (!header || !context->headers)
        return;

    // allocate space for the new header
    void** new_headers = realloc(context->headers, (context->header_count + 1) * sizeof(void*));
    if (!new_headers)
        return;  // handle memory allocation error

    context->headers = new_headers;
    context->headers[context->header_count++] = header;
}

void tcp_connection_context_remove_header(TcpConnectionContext* context, size_t index) {
    // validate integrity of the header list before removing a header
    if (!context || index >= context->header_count)
        return;

    // remove the header at the specified index and shift subsequent headers down
    void** new_headers = realloc(context->headers, context->header_count * sizeof(void*));
    if (!new_headers)
        return;  // handle memory allocation error

    context->headers = new_headers;
    for (size_t i = index; i < context->header_count - 1; i++)
        context->headers[i] = context->headers[i + 1];
    context->header_count--;
}

// logging and monitoring functions
void tcp_connection_context_log(TcpConnectionContext* context, const char* message) {
    // implement logging and monitoring logic here
}

size_t tcp_connection_context_get_header_count(const TcpConnectionContext* context) {
    return context ? context->header_count : 0;
}
