void process_directory(char *directory_path) {
    DIR *dir;
    struct dirent *ent;
    FILE *file;
    char file_path[256];
    char checksum_file_path[128];
    char classification_tag[16];
    time_t timestamp;
    srand(time(&timestamp));
    int i = 0, j = 0;

    dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
            continue;

        file_path[256];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        file = fopen(file_path, "rb");
        if (!file) {
            sprintf(checksum_file_path, "%s/_empty_%x.txt", directory_path, (uint32_t)time(&timestamp));
            printf("Error reading file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_END);
        int bytes = ftell(file);
        fseek(file, 0, SEEK_SET);

        if (bytes < 100) {
            sprintf(checksum_file_path, "%s/_empty_%x.txt", directory_path, (uint32_t)time(&timestamp));
            printf("Error reading file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_SET);
        char buffer[1024];
        fread(buffer, sizeof(char), 100, file);
        fclose(file);

        sprintf(classification_tag, "%x_%d_%x.txt", (uint32_t)rand(), time(&timestamp), (uint32_t)srand());
        if (strlen(classification_tag) > 128)
            classification_tag[127] = '\0';

        char checksum_file_path[128];
        sprintf(checksum_file_path, "%s/%s", directory_path, classification_tag);

        file = fopen(checksum_file_path, "w");
        if (!file) {
            printf("Error opening checksum file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_END);
        int bytes = ftell(file);
        fseek(file, 0, SEEK_SET);

        char buffer[1024];
        fread(buffer, sizeof(char), bytes - 100, file);
        fclose(file);

        MD5_CTX md5;
        MD5_Init(&md5);
        unsigned char output[16];

        file = fopen(checksum_file_path, "rb");
        if (!file) {
            printf("Error opening checksum file: %s\n", strerror(errno));
            continue;
        }

        fseek(file, 0, SEEK_END);
        int bytes = ftell(file);
        fseek(file, 0, SEEK_SET);

        char buffer[1024];
        fread(buffer, sizeof(char), bytes - 100, file);
        fclose(file);

        MD5_Final(output, &md5);

        fprintf(stdout, "Checksum: ");
        for (int i = 0; i < 16; i++)
            fprintf(stdout, "%02x", output[i]);
        fprintf(stdout, "\n");

        closedir(dir);
    }
}
