import json
import hashlib
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.backends import default_backend
import threading
import os
import logging
import base64
import re

class TransformationHandler:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def transform_data(self, user_data):
        transformed_data = {}
        for key, value in user_data.items():
            if key == "email":
                transformed_data[key] = value.lower()
            elif key == "phone":
                transformed_data[key] = re.sub(r'(\d{3})(\d{4})', r'\1****\2', value)
            else:
                transformed_data[key] = value
        return transformed_data

class EncryptionHandler:
    def __init__(self):
        self.logger = logging.getLogger(__name__)

    def encrypt_data(self, transformed_data):
        key = os.urandom(32)
        fernet = Fernet(key)
        encrypted_data = json.dumps(transformed_data).encode('utf-8')
        return base64.b64encode(fernet.encrypt(encrypted_data))

def main():
    import sys
    from PyInquirer import prompts, validator

    if len(sys.argv) != 4:
        print("Usage: python transform_and_encrypt.py <input_file> <output_file> <schema_file>")
        exit()

    input_file = sys.argv[1]
    output_file = sys.argv[2]
    schema_file = sys.argv[3]

    transformation_handler = TransformationHandler()
    encryption_handler = EncryptionHandler()

    try:
        with open(input_file, 'r') as file:
            user_data = json.load(file)

        transformed_data = transformation_handler.transform_data(user_data)
        encrypted_data = encryption_handler.encrypt_data(transformed_data)

        with open(output_file, 'w') as file:
            file.write(encrypted_data.decode('utf-8'))

    except FileNotFoundError:
        print(f"File '{input_file}' not found.")
    except json.JSONDecodeError:
        print(f"Invalid JSON in file '{input_file}'.")
    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
