// Function prototypes
void rename_and_categorize_directories(const char* directory_path);
int add_message_to_list(LTE_RRC_MESSAGING_T** messages, LTE_RRC_MESSAGING_T* new_message);
int add_pdu_to_list(NFAPI_UL_CCCH_pdu_t** pdus, NFAPI_UL_CCCH_pdu_t* new_pdu);

// Function implementations
void rename_and_categorize_directories(const char* directory_path) {
    // Initialize UE cell context structure
    UE_CELL_CONTEXT_T ue_cell_context = {"", 0, 0};

    // Initialize message and PDU lists
    LTE_RRC_MESSAGING_T** messages = NULL;
    NFAPI_UL_CCCH_pdu_t** pdus = NULL;

    // Scan directory for files
    DIR* dir = opendir(directory_path);
    if (dir == NULL) {
        printf("Error opening directory: %s\n", strerror(errno));
        return;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        char file_path[256];
        sprintf(file_path, "%s/%s", directory_path, ent->d_name);

        if (strcmp(ent->d_type == DT_DIR ? "directory" : "file") == 0) {
            // Read first 500 bytes of file content
            FILE* file = fopen(file_path, "rb");
            char buffer[501];
            fread(buffer, sizeof(char), 500, file);
            fclose(file);

            // Determine new directory structure and naming convention
            time_t timestamp = time(NULL);
            int sequence_number = (int)timestamp;
            char hash[33];
            sprintf(hash, "%x", (unsigned int)(hash_function(buffer, 500)));

            char classification_tag[16];
            sscanf(file_path, "/%s/", classification_tag);

            // Generate new directory path
            char new_directory_path[129];
            sprintf(new_directory_path, "%s/%04d-%s_%x_%s_", classification_tag, timestamp, hash, (int)sequence_number);
            if (ent->d_type == DT_REG && access(file_path, R_OK) == -1) {
                strcat(new_directory_path, "_empty");
            }

            // Rename directory
            rename(file_path, new_directory_path);

            // Initialize message and PDU structures
            LTE_RRC_MESSAGING_T* new_message = (LTE_RRC_MESSAGING_T*)malloc(sizeof(LTE_RRC_MESSAGING_T));
            new_message->message_id = sequence_number;
            new_message->data = (char*)malloc(128);
            sprintf(new_message->data, "%s", new_directory_path);

            LTE_RRC_MESSAGING_T* messages_tail = messages ? &messages[0] : NULL;
            if (!add_message_to_list(&messages, new_message)) {
                printf("Error adding message: %s\n", strerror(errno));
                return;
            }

            NFAPI_UL_CCCH_pdu_t* new_pdu = (NFAPI_UL_CCCH_pdu_t*)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
            new_pdu->pdu_id = sequence_number;
            new_pdu->data = (char*)malloc(128);
            sprintf(new_pdu->data, "%s", new_directory_path);

            NFAPI_UL_CCCH_pdu_t* pdus_tail = pdus ? &pdus[0] : NULL;
            if (!add_pdu_to_list(&pdus, new_pdu)) {
                printf("Error adding PDU: %s\n", strerror(errno));
                return;
            }
        }

        free(ent->d_name);
    }

    // Generate checksum of entire directory
    FILE* checksum_file = fopen("checksums.txt", "wb");
    if (checksum_file == NULL) {
        printf("Error opening checksum file: %s\n", strerror(errno));
        return;
    }

    for (int i = 0; messages[i] != NULL; i++) {
        fwrite(&messages[i]->message_id, sizeof(int), 1, checksum_file);
        fwrite(messages[i]->data, 128, 1, checksum_file);
        free(messages[i]->data);
        free(messages[i]);
    }

    for (int i = 0; pdus[i] != NULL; i++) {
        fwrite(&pdus[i]->pdu_id, sizeof(int), 1, checksum_file);
        fwrite(pdus[i]->data, 128, 1, checksum_file);
        free(pdus[i]->data);
        free(pdus[i]);
    }

    fclose(checksum_file);

    // Handle errors and log to error log file
    if (errno != 0) {
        FILE* error_log = fopen("error.log", "a");
        fprintf(error_log, "%s: %s\n", __FILE__, strerror(errno));
        fclose(error_log);
    }

    // Free allocated memory
    free(ue_cell_context.id);
    for (int i = 0; messages[i] != NULL; i++) {
        free(messages[i]->data);
        free(messages[i]);
    }
    free(messages);

    for (int i = 0; pdus[i] != NULL; i++) {
        free(pdus[i]->data);
        free(pdus[i]);
    }
    free(pdus);

    // Close directory handle
    closedir(dir);
}

// Hash function implementation
unsigned int hash_function(char* buffer, int length) {
    unsigned int hash = 0;
    for (int i = 0; i < length; i++) {
        hash = (hash << 4) ^ (hash >> 3) ^ (buffer[i]);
    }
    return hash;
}

// Add message to list
int add_message_to_list(LTE_RRC_MESSAGING_T** messages, LTE_RRC_MESSAGING_T* new_message) {
    // Allocate memory for new message and update list
    *messages = (LTE_RRC_MESSAGING_T*)realloc(*messages, sizeof(LTE_RRC_MESSAGING_T) * ((*messages != NULL) ? (*messages)[0].message_id + 1 : 1));
    if (!*messages) {
        printf("Error allocating memory: %s\n", strerror(errno));
        return 0;
    }

    (*messages)[(*messages)[0].message_id].data = new_message->data;

    // Return success
    return 1;
}

// Add PDU to list
int add_pdu_to_list(NFAPI_UL_CCCH_pdu_t** pdus, NFAPI_UL_CCCH_pdu_t* new_pdu) {
    // Allocate memory for new PDU and update list
    *pdus = (NFAPI_UL_CCCH_pdu_t*)realloc(*pdus, sizeof(NFAPI_UL_CCCH_pdu_t) * ((*pdus != NULL) ? (*pdus)[0].pdu_id + 1 : 1));
    if (!*pdus) {
        printf("Error allocating memory: %s\n", strerror(errno));
        return 0;
    }

    (*pdus)[(*pdus)[0].pdu_id].data = new_pdu->data;

    // Return success
    return 1;
}

int main() {
    rename_and_categorize_directories("/path/to/directory");
    return 0;
}
