#include <stdlib.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_id;
    uint16_t cell_id;
    rrc_state_t rrc_state;
    pthread_mutex_t lock;
    size_t size;
    struct message* messages;
} cell_context_t;

cell_context_t* cell_init() {
    cell_context_t* context = (cell_context_t*)malloc(sizeof(cell_context_t));
    context->size = 0;
    context->messages = NULL;
    pthread_mutex_init(&context->lock, NULL);
    return context;
}

void cell_add_message(cell_context_t* context, message_t* msg) {
    pthread_mutex_lock(&context->lock);
    context->messages = realloc(context->messages, (context->size + 1) * sizeof(message_t));
    context->messages[context->size] = msg;
    context->size++;
    pthread_mutex_unlock(&context->lock);
}

void cell_remove_message(cell_context_t* context, message_t* msg) {
    pthread_mutex_lock(&context->lock);
    for (int i = 0; i < context->size; i++) {
        if (context->messages[i] == msg) {
            memmove(&context->messages[i], &context->messages[i + 1], (context->size - i - 1) * sizeof(message_t));
            context->size--;
            break;
        }
    }
    pthread_mutex_unlock(&context->lock);
}

void cell_free(cell_context_t* context) {
    pthread_mutex_lock(&context->lock);
    for (int i = 0; i < context->size; i++) {
        free(context->messages[i]);
    }
    free(context->messages);
    pthread_mutex_unlock(&context->lock);
    free(context);
}

pthread_mutex_t cell_mutex;
cell_context_t* cells[128];
size_t num_cells;

void add_cell(cell_context_t* cell) {
    pthread_mutex_lock(&cell_mutex);
    for (int i = 0; i < num_cells; i++) {
        if (!cells[i]) {
            cells[i] = cell;
            break;
        }
    }
    pthread_mutex_unlock(&cell_mutex);
}

void remove_cell(cell_context_t* cell) {
    pthread_mutex_lock(&cell_mutex);
    for (int i = 0; i < num_cells; i++) {
        if (cells[i] == cell) {
            cells[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&cell_mutex);
}

void cell_init_system() {
    pthread_mutex_init(&cell_mutex, NULL);
    num_cells = 0;
}

void cell_deinit_system() {
    pthread_mutex_lock(&cell_mutex);
    for (int i = 0; i < num_cells; i++) {
        if (cells[i]) {
            cell_free(cells[i]);
        }
    }
    pthread_mutex_unlock(&cell_mutex);
}
