            printf("IDLE\n");
            break;
        case CONNECTED:
            printf("CONNECTED\n");
            break;
    }
    if (context->message_table) {
        printf("Message Table:\n");
        MessageNode *current = context->message_table;
        while (current) {
            printf("Message ID: %s, Message: ", current->message_id);
            // print the message content here
            printf("\n");
            current = current->next;
        }
    } else {
        printf("No messages in the table.\n");
    }
    if (context->pdu_list) {
        printf("PDU List:\n");
        PDUListNode *current = context->pdu_list;
        while (current) {
            // print the pdu content here
            printf("\n");
            current = current->next;
        }
    } else {
        printf("No PDUs in the list.\n");
    }
