int add_pdu_to_list(UE_CELL_CONTEXT_T *context, NFAPI_UL_CCCH_pdu_t *pdu) {
    if (!context || !pdu) return -1;

    PDUListNode *new_node = malloc(sizeof(PDUListNode));
    if (!new_node) return -1;

    new_node->pdu = *pdu;
    new_node->next = context->pdu_list;
    context->pdu_list = new_node;

    // Track the number of PDUs added for performance monitoring
    context->message_processed_count++;

    return 0;
}

// Function to free a UE_CELL_CONTEXT_T structure
void free_ue_context(UE CELL_CONTEXT_T *context) {
    if (!context) return;

    MessageListNode *temp = context->message_list;
    while (temp) {
        MessageListNode *next = temp->next;
        free(temp);
        temp = next;
    }

    PDUListNode *temp2 = context->pdu_list;
    while (temp2) {
        PDUListNode *next2 = temp2->next;
        free(temp2);
        temp2 = next2;
    }

    free(context);
}

int main() {
    UE_CELL_CONTEXT_T* ue_context = init_ue_context(1, 10, IDLE);
    if (!ue_context) return -1;

    // Adding messages to the message list
    LTE_RRC_MESSAGING_T msg1 = {"Message 1"};
    LTE_RRC_MESSAGING_T msg2 = {"Message 2"};
    add_message_to_list(ue_context, &msg1);
    add_message_to_list(ue_context, &msg2);

    // Adding PDUs to the PDU list
    NFAPI_UL_CCCH_pdu_t pdu1 = {"PDU 1"};
    NFAPI_UL_CCCH_pdu_t pdu2 = {"PDU 2"};
    add_pdu_to_list(ue_context, &pdu1);
    add_pdu_to_list(ue_context, &pdu2);

    // Freeing the UE cell context
    free_ue_context(ue_context);

    return 0;
}
