        strcpy(file_path, dir_path);
        strcat(file_path, "/");
        strcat(file_path, ent->d_name);

        // Check if file is empty or its content cannot be read
        FILE *file;
        int file_size;
        file = fopen(file_path, "rb");
        if (file == NULL || fseek(file, 100, SEEK_SET) != 0) {
            strcat(file_path, "_empty");
        }

        // Compute checksum of the entire directory and store it in a separate metadata file
        unsigned char checksum[16];
        MD5_CTX md5_ctx;
        MD5_Init(&md5_ctx);
        FILE *metadata_file;
        metadata_file = fopen("checksums.txt", "wb");
        if (metadata_file == NULL) {
            printf("Error: Unable to open checksum metadata file\n");
            return -1;
        }

        // Write checksum and last 100 bytes of each file's content to the metadata file
        while ((ent = readdir(dir)) != NULL) {
            char file_path[256];
            strcpy(file_path, dir_path);
            strcat(file_path, "/");
            strcat(file_path, ent->d_name);

            FILE *file;
            int file_size;
            file = fopen(file_path, "rb");
            if (file == NULL || fseek(file, 100, SEEK_SET) != 0) {
                // Handle errors gracefully
                printf("Error: Unable to read file %s\n", file_path);
                return -1;
            }

            // Compute checksum using a standard library function for generating the MD5 hash
            unsigned char checksum[16];
            MD5_CTX md5_ctx;
            MD5_Init(&md5_ctx);
            while (!feof(file)) {
                int bytes_read = fread(checksum, 1, sizeof(checksum), file);
                MD5_Update(&md5_ctx, checksum, bytes_read);
            }
            MD5_Final(checksum, &md5_ctx);

            // Write checksum and last 100 bytes of each file's content to the metadata file
            fwrite(checksum, 1, sizeof(checksum), metadata_file);
        }

        fclose(metadata_file);
    }

    closedir(dir);
    return 0;
}

