    LTE_UESession* session = (LTE_UESession*)malloc(sizeof(LTE_UESession));
    if (!session) return NULL;

    session->ue_id = ue_id;
    session->rrc_state = rrc_state;
    session->num_pdus = 0;
    session->pdus = (LTE_PDCP_PDU_t**)calloc(10, sizeof(LTE_PDCP_PDU_t*));
    if (!session->pdus) {
        free(session);
        return NULL;
    }

    return session;
}

// Define function to add a new PDU to the dynamic array
int lte_ue_session_add_pdu(LTE_UESession* session, LTE_PDCP_PDU_t* pdu) {
    if (session->num_pdus >= 10) {
        // Resize the array by a factor of 2
        int new_size = session->num_pdus * 2;
        LTE_PDCP_PDU_t** new_pdus = (LTE_PDCP_PDU_t**)realloc(session->pdus, new_size * sizeof(LTE_PDCP_PDU_t*));
        if (!new_pdus) return -1;

        session->pdus = new_pdus;
    }

    session->pdus[session->num_pdus++] = pdu;
    return 0;
}

// Define function to free the memory allocated for an LTE_UESession
void lte_ue_session_free(LTE_UESession* session) {
    for (int i = 0; i < session->num_pdus; i++) {
        if (session->pdus[i]) free(session->pdus[i]);
    }
    free(session->pdus);
    free(session);
}
