int num_uecontexts = 0;
pthread_mutex_t uecontext_lock = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("ue_context.log", "w");

void validate_uecontext(NFAPI_RRC_UECONTEXT_T* uecontext) {
    if (uecontext == NULL || uecontext->pdu_list == NULL) {
        fprintf(log_file, "Error: Invalid UE context\n");
        return;
    }
}

int add_pdu_to_uecontext(NFAPI_RRC_UECONTEXT_T* uecontext, NFAPI_UL_CCCH_pdu_t* pdu) {
    pthread_mutex_lock(&uecontext_lock);
    if (uecontext->pdu_list == NULL || uecontext->pdu_list[uecontext->num_pdus] == NULL) {
        return -1;
    }
    memcpy(uecontext->pdu_list[uecontext->num_pdus], pdu, sizeof(NFAPI_UL_CCCH_pdu_t));
    (uecontext->num_pdus)++;
    pthread_mutex_unlock(&uecontext_lock);
}

void remove_pdu_from_uecontext(NFAPI_RRC_UECONTEXT_T* uecontext) {
    pthread_mutex_lock(&uecontext_lock);
    for (int i = 0; i < uecontext->num_pdus - 1; i++) {
        memcpy(uecontext->pdu_list[i], uecontext->pdu_list[i + 1], sizeof(NFAPI_UL_CCCH_pdu_t));
    }
    free(uecontext->pdu_list[uecontext->num_pdus]);
    (uecontext->num_pdus)--;
    pthread_mutex_unlock(&uecontext_lock);
}

