#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    uint32_t ue_id;
    RRC_STATE rrc_state;
    NFAPI_UL_CCCH_pdu_t* pdus;
    int pdus_size;
} NFAPI_RRC_UECONTEXT_T;

typedef struct {
    NFAPI_RRC_UECONTEXT_T* contexts;
    int context_size;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} NFAPI_RRC_CTX_ARRAY_T;

NFAPI_RRC_CTX_ARRAY_T* nfaapi_rrc_ctx_array_new(int initial_capacity) {
    NFAPI_RRC_CTX_ARRAY_T* ctx_array = (NFAPI_RRC_CTX_ARRAY_T*)malloc(sizeof(NFAPI_RRC_CTX_ARRAY_T));
    ctx_array->contexts = (NFAPI_RRC_UECONTEXT_T*)calloc(initial_capacity, sizeof(NFAPI_RRC_UECONTEXT_T));
    ctx_array->context_size = initial_capacity;
    pthread_mutex_init(&ctx_array->lock, NULL);
    pthread_cond_init(&ctx_array->cond, NULL);
    return ctx_array;
}

void nfaapi_rrc_ctx_array_free(NFAPI_RRC_CTX_ARRAY_T* ctx_array) {
    for (int i = 0; i < ctx_array->context_size; i++) {
        if (ctx_array->contexts[i].pdus) free(ctx_array->contexts[i].pdus);
    }
    free(ctx_array->contexts);
    pthread_mutex_destroy(&ctx_array->lock);
    pthread_cond_destroy(&ctx_array->cond);
    free(ctx_array);
}

void nfaapi_rrc_ctx_array_add(NFAPI_RRC_CTX_ARRAY_T* ctx_array, NFAPI_RRC_UECONTEXT_T* new_context) {
    pthread_mutex_lock(&ctx_array->lock);
    if (ctx_array->context_size == 0) {
        ctx_array->contexts = (NFAPI_RRC_UECONTEXT_T*)calloc(1, sizeof(NFAPI_RRC_UECONTEXT_T));
        ctx_array->context_size = 1;
    } else if (ctx_array->context_size <= ctx_array->context_size * 2) {
        NFAPI_RRC_CTX_ARRAY_T* new_ctx_array = nfaapi_rrc_ctx_array_new(ctx_array->context_size * 2);
        memcpy(new_ctx_array->contexts, ctx_array->contexts, sizeof(NFAPI_RRC_UECONTEXT_T) * ctx_array->context_size);
        free(ctx_array->contexts);
        ctx_array->contexts = new_ctx_array->contexts;
        ctx_array->context_size *= 2;
    }
    int idx = ctx_array->context_size++;
    memcpy(&ctx_array->contexts[idx], new_context, sizeof(NFAPI_RRC_UECONTEXT_T));
    pthread_mutex_unlock(&ctx_array->lock);
}

void nfaapi_rrc_ctx_array_remove_at_index(NFAPI_RRC_CTX_ARRAY_T* ctx_array, int index) {
    if (index < 0 || index >= ctx_array->context_size) return;
    pthread_mutex_lock(&ctx_array->lock);
    for (int i = index; i < ctx_array->context_size - 1; i++) {
        memcpy(&ctx_array->contexts[i], &ctx_array->contexts[i + 1], sizeof(NFAPI_RRC_UECONTEXT_T));
    }
    free(ctx_array->contexts[--ctx_array->context_size]);
    pthread_mutex_unlock(&ctx_array->lock);
}

void nfaapi_rrc_ctx_array_insert_at_index(NFAPI_RRC_CTX_ARRAY_T* ctx_array, int index, NFAPI_RRC_UECONTEXT_T* new_context) {
    if (index < 0 || index > ctx_array->context_size) return;
    pthread_mutex_lock(&ctx_array->lock);
    for (int i = ctx_array->context_size; i > index; i--) {
        memcpy(&ctx_array->contexts[i], &ctx_array->contexts[i - 1], sizeof(NFAPI_RRC_UECONTEXT_T));
    }
    int idx = ctx_array->context_size++;
    memcpy(&ctx_array->contexts[idx], new_context, sizeof(NFAPI_RRC_UECONTEXT_T));
    pthread_mutex_unlock(&ctx_array->lock);
}

void nfaapi_rrc_ctx_array_compact(NFAPI_RRC_CTX_ARRAY_T* ctx_array) {
    for (int i = 0; i < ctx_array->context_size; i++) {
        if (!ctx_array->contexts[i].pdus || ctx_array->contexts[i].pdus_size == 0) {
            ctx_array->context_size--;
            for (int j = i; j < ctx_array->context_size; j++) {
                memcpy(&ctx_array->contexts[j], &ctx_array->contexts[j + 1], sizeof(NFAPI_RRC_UECONTEXT_T));
            }
            break;
        }
    }
}

void nfaapi_rrc_ctx_array_iterate(NFAPI_RRC_CTX_ARRAY_T* ctx_array, void (*callback)(NFAPI_RRC_UECONTEXT_T*)) {
    pthread_mutex_lock(&ctx_array->lock);
    for (int i = 0; i < ctx_array->context_size; i++) {
        callback(ctx_array->contexts[i]);
    }
    pthread_mutex_unlock(&ctx_array->lock);
}
