#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define structure for connection record
typedef struct {
    int id;
    enum { ESTABLISHED, CLOSING, FAILED } state;
    // Dynamically allocated list of network packets
    struct packet_list *packets;
} connection_record;

// Define structure for packet list node
typedef struct packet_node {
    void *packet;  // Pointer to the actual packet data
    struct packet_node *next;
} packet_node;

// Define structure for packet list
typedef struct {
    int size;  // Number of packets in the list
    packet_node *head;  // Head of the linked list
} packet_list;

// Function to create a new packet node
packet_node* packet_node_create(void *packet) {
    packet_node *node = (packet_node*)malloc(sizeof(packet_node));
    node->packet = packet;
    node->next = NULL;
    return node;
}

// Function to add a packet to the end of the list
void packet_list_append(packet_list *list, void *packet) {
    packet_node *new_node = packet_node_create(packet);
    if (list->head == NULL) {
        list->head = new_node;
    } else {
        packet_node *curr = list->head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = new_node;
    }
    list->size++;
}

// Function to free the memory allocated for a packet node
void packet_node_free(packet_node *node) {
    if (node != NULL) {
        free(node);
    }
}

// Function to free the memory allocated for a packet list
void packet_list_free(packet_list *list) {
    packet_node *curr = list->head;
    packet_node *next = NULL;
    while (curr != NULL) {
        next = curr->next;
        packet_node_free(curr);
        curr = next;
    }
    free(list);
}

// Define read-write lock for thread safety
pthread_rwlock_t connection_lock = PTHREAD_RWLOCK_INITIALIZER;

// Function to add a new connection record
connection_record* create_connection(int id, enum { ESTABLISHED, CLOSING, FAILED } state) {
    connection_record *conn = (connection_record*)malloc(sizeof(connection_record));
    conn->id = id;
    conn->state = state;
    conn->packets = NULL;  // Initialize packet list
    return conn;
}

// Function to add a new packet to the connection record
void add_packet(connection_record *conn, void *packet) {
    pthread_rwlock_wrlock(&connection_lock);
    if (conn->packets == NULL) {  // Create a new packet list if none exists
        conn->packets = (packet_list*)malloc(sizeof(packet_list));
        conn->packets->size = 0;
        conn->packets->head = NULL;
    }
    packet_list_append(conn->packets, packet);
    pthread_rwlock_unlock(&connection_lock);
}

// Function to remove a connection record
void free_connection(connection_record *conn) {
    pthread_rwlock_wrlock(&connection_lock);
    if (conn->packets != NULL) {  // Free the packet list
        packet_list_free(conn->packets);
    }
    free(conn);
    pthread_rwlock_unlock(&connection_lock);
}

// Function to validate packet integrity before operations
int validate_packet(void *packet) {
    // Implement your validation logic here
    return 1;  // Assume packet is valid for this example
}
