void handle_filenames(char* filename) {
    int len = strlen(filename);
    int digit_count = 0;
    for (int i = len - 1; i >= 0; --i) {
        if (isdigit(filename[i])) {
            ++digit_count;
        } else break;
    }
    char new_filename[255];
    strcpy(new_filename, filename);
    strcat(new_filename, "_");
    sprintf(&new_filename[strlen(new_filename)], "%d", digit_count);
    char* extension = strrchr(filename, '.');
    if (extension) {
        if (strspn(filename, "0123456789") > 0) {
            strcpy(extension, "log");
        }
    } else {
        strcat(new_filename, ".txt");
    }
}

char* manage_filenames(char* filename) {
    handle_filenames(filename);
    return strdup(filename);
}
