#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure representing a configuration object
typedef struct {
    int id;
    char name[20];
    struct Setting* settings; // dynamically allocated list of settings
} Configuration;

// Structure representing a setting
typedef struct {
    char key[10];
    char value[20];
} Setting;

// Hash table structure with collision resolution using chaining
typedef struct {
    int size;
    Configuration** buckets;
    pthread_mutex_t lock;
} HashTable;

// Function to create a new configuration object
Configuration* config_new(int id, const char* name) {
    Configuration* config = (Configuration*)malloc(sizeof(Configuration));
    config->id = id;
    strcpy(config->name, name);
    config->settings = NULL; // initialize settings list as empty
    return config;
}

// Function to add a new setting to a configuration object
void config_add_setting(Configuration* config, const char* key, const char* value) {
    Setting* setting = (Setting*)malloc(sizeof(Setting));
    strcpy(setting->key, key);
    strcpy(setting->value, value);

    // Check if settings list is empty and allocate it if necessary
    if (config->settings == NULL) {
        config->settings = (Setting**)malloc(sizeof(Setting*));
        config->settings[0] = setting;
    } else {
        // Allocate new slot for the setting and move existing settings to make room
        Setting** new_settings = (Setting**)realloc(config->settings, sizeof(Setting*) * (config->settings ? config->settings[0]->next : 1) + 1);
        new_settings[new_settings[0]->next] = setting;
    }
}

// Function to update the value of a setting in a configuration object
void config_update_setting(Configuration* config, const char* key, const char* value) {
    // Find the setting with matching key and update its value
    for (int i = 0; i < config->settings ? config->settings[0]->next : 0; i++) {
        if (strcmp(config->settings[i]->key, key) == 0) {
            strcpy(config->settings[i]->value, value);
            return;
        }
    }
}

// Function to delete a setting in a configuration object
void config_delete_setting(Configuration* config, const char* key) {
    // Find the setting with matching key and remove it from the list
    int i = 0;
    while (i < config->settings ? config->settings[0]->next : 0) {
        if (strcmp(config->settings[i]->key, key) == 0) {
            // Shift all subsequent settings one position back and free memory for removed setting
            memmove(&config->settings[i], &config->settings[i + 1], sizeof(Setting*) * (config->settings ? config->settings[0]->next : i));
            config->settings = (Setting**)realloc(config->settings, sizeof(Setting*) * --i);
            break;
        }
        i++;
    }
}

// Function to create a new hash table with given size
HashTable* hash_table_new(int size) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    hash_table->size = size;
    hash_table->buckets = (Configuration**)malloc(sizeof(Configuration*) * size);
    pthread_mutex_init(&hash_table->lock, NULL);
    return hash_table;
}

// Function to insert a configuration object into the hash table
void hash_table_insert(HashTable* hash_table, Configuration* config) {
    int index = config->id % hash_table->size;
    pthread_mutex_lock(&hash_table->lock);
    if (hash_table->buckets[index] == NULL)
        hash_table->buckets[index] = config;
    else
        // Handle collision using chaining by inserting the configuration into the existing list
        for (int i = 0; hash_table->buckets[index]->settings ? hash_table->buckets[index]->settings[0]->next : 0; i++) {
            if (hash_table->buckets[index]->id == config->id)
                break;
            // Move all subsequent configurations to make room and re-allocate the list
            memmove(&config, &hash_table->buckets[index]->settings[i], sizeof(Configuration) * --i);
        }
    pthread_mutex_unlock(&hash_table->lock);
}

// Function to retrieve a configuration object from the hash table
Configuration* hash_table_get(HashTable* hash_table, int id) {
    int index = id % hash_table->size;
    pthread_mutex_lock(&hash_table->lock);
    for (int i = 0; hash_table->buckets[index]->settings ? hash_table->buckets[index]->settings[0]->next : 0; i++) {
        if (hash_table->buckets[index]->id == id) {
            Configuration* config = hash_table->buckets[index];
            pthread_mutex_unlock(&hash_table->lock);
            return config;
        }
    }
    pthread_mutex_unlock(&hash_table->lock);
    return NULL; // configuration not found
}

// Function to clean up unused configurations and settings periodically
void hash_table_cleanup(HashTable* hash_table) {
    for (int i = 0; i < hash_table->size; i++) {
        for (int j = 0; hash_table->buckets[i]->settings ? hash_table->buckets[i]->settings[0]->next : 0; j--) {
            if (!hash_table->buckets[i]->settings[j]) {
                // Shift all subsequent settings to fill the gap and free memory
                memmove(&hash_table->buckets[i]->settings[j], &hash_table->buckets[i]->settings[j + 1], sizeof(Setting*) * --j);
                break;
            }
        }
    }
}

// Function to periodically check for and remove unused configurations and settings
void hash_table_maintenance(HashTable* hash_table) {
    int i, j;
    for (i = 0; i < hash_table->size; i++) {
        for (j = 0; hash_table->buckets[i]->settings ? hash_table->buckets[i]->settings[0]->next : 0; j--) {
            if (!hash_table->buckets[i]->settings[j]) {
                // Shift all subsequent settings to fill the gap and free memory
                memmove(&hash_table->buckets[i]->settings[j], &hash_table->buckets[i]->settings[j + 1], sizeof(Setting*) * --j);
                break;
            }
        }
    }
}
