#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int channels;
    int bits_per_sample;
    double sample_rate;
    int extra_channels;
} AudioInfo;

AudioInfo extract_audio_info(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return (AudioInfo){0, 0, 0.0, 0};
    }

    AudioInfo info = {0};

    // Read the WAV header
    unsigned char riff[4];
    fread(riff, sizeof(unsigned char), 4, file);
    if (memcmp(riff, "RIFF", 4) != 0) {
        fclose(file);
        return (AudioInfo){0, 0, 0.0, 0};
    }

    unsigned char wav[4];
    fread(wav, sizeof(unsigned char), 4, file);
    if (memcmp(wav, "WAVE", 4) != 0) {
        fclose(file);
        return (AudioInfo){0, 0, 0.0, 0};
    }

    // Read the format subchunk
    unsigned char fmt[4];
    fread(fmt, sizeof(unsigned char), 4, file);
    if (memcmp(fmt, "fmt ", 4) != 0) {
        fclose(file);
        return (AudioInfo){0, 0, 0.0, 0};
    }

    int chunk_size;
    fseek(file, 8, SEEK_SET);
    fread(&chunk_size, sizeof(int), 1, file);

    unsigned char audio_format;
    fread(&audio_format, sizeof(unsigned char), 2, file);

    short channels;
    fread(&channels, sizeof(short), 1, file);

    int sample_rate_int;
    fread(&sample_rate_int, sizeof(int), 1, file);
    double sample_rate = (double)sample_rate_int;

    int bits_per_sample_int;
    fread(&bits_per_sample_int, sizeof(int), 1, file);

    fseek(file, 16, SEEK_SET); // Skip the extra bytes

    if (channels == 1) {
        info.channels = channels;
    } else {
        int extra_channels = channels - 2; // Assuming stereo (2 channels)
        info.extra_channels = extra_channels;
    }

    if ((sample_rate_int > 96000) || (bits_per_sample_int > 24)) {
        fclose(file);
        return (AudioInfo){0, 0, 0.0, 0};
    }

    info.bits_per_sample = bits_per_sample_int;
    info.sample_rate = sample_rate;

    fclose(file);

    return info;
}

int main() {
    AudioInfo info = extract_audio_info("example.wav");
    printf("Channels: %d\n", info.channels);
    printf("Bits per sample: %d\n", info.bits_per_sample);
    printf("Sample rate: %.2f kHz\n", info.sample_rate / 1000.0);
    if (info.extra_channels > 0) {
        printf("Extra channels: %d\n", info.extra_channels);
    }
    return 0;
}

