typedef struct {
    int channel_width;
    double center_frequency;
    char **authentication_methods;
    int num_authentication_methods;
} wifi_config_t;

wifi_config_t *init_wifi_config() {
    wifi_config_t *config = (wifi_config_t *)malloc(sizeof(wifi_config_t));
    config->channel_width = 0;
    config->center_frequency = 0.0;
    config->authentication_methods = NULL;
    config->num_authentication_methods = 0;
    return config;
}

void add_auth_method(wifi_config_t *config, const char *method) {
    int i;
    for (i = 0; i < config->num_authentication_methods; i++) {
        if (strcmp(config->authentication_methods[i], method) == 0) {
            return;
        }
    }
    config->authentication_methods = (char **)realloc(config->authentication_methods, (config->num_authentication_methods + 1) * sizeof(char *));
    config->authentication_methods[config->num_authentication_methods] = strdup(method);
    config->num_authentication_methods++;
}

void update_auth_method(wifi_config_t *config, int idx, const char *method) {
    if (idx >= config->num_authentication_methods || !config->authentication_methods[idx]) {
        return;
    }
    free(config->authentication_methods[idx]);
    config->authentication_methods[idx] = strdup(method);
}

void delete_auth_method(wifi_config_t *config, int idx) {
    if (idx >= config->num_authentication_methods) {
        return;
    }
    free(config->authentication_methods[idx]);
    memmove(&config->authentication_methods[idx], &config->authentication_methods[idx + 1], (config->num_authentication_methods - idx - 1) * sizeof(char *));
    config->num_authentication_methods--;
}

void serialize_wifi_config(wifi_config_t *config, FILE *fp) {
    json_object *root = json_object_new_object();
    json_object_object_add(root, "channel_width", json_object_new_int(config->channel_width));
    json_object_object_add(root, "center_frequency", json_object_new_double(config->center_frequency));
    json_object_object_add(root, "authentication_methods", json_object_new_array());
    int i;
    for (i = 0; i < config->num_authentication_methods; i++) {
        json_object *method = json_object_new_string(config->authentication_methods[i]);
        json_object_array_add(json_object_object_get(root, "authentication_methods"), method);
    }
    fprintf(fp, "%s\n", json_object_to_json_string(root));
    json_decref(root);
}

void deserialize_wifi_config(wifi_config_t *config, FILE *fp) {
    json_object *root = json_object_from_file.fp;
    if (!root) {
        return;
    }
    config->channel_width = json_object_get_int(json_object_object_get(root, "channel_width"));
    config->center_frequency = json_object_get_double(json_object_object_get(root, "center_frequency"));
    json_object *auth_methods = json_object_object_get(root, "authentication_methods");
    int i;
    for (i = 0; i < json_object_array_length(auth_methods); i++) {
        const char *method = json_object_get_string(json_object_array_get_index(auth_methods, i));
        add_auth_method(config, method);
    }
}

void* thread_func(void* arg) {
    wifi_config_t *config = (wifi_config_t *)arg;
    // Perform operations on the config here
    return NULL;
}

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int main() {
    wifi_config_t *config = init_wifi_config();

    pthread_t thread1, thread2;
    pthread_create(&thread1, NULL, thread_func, (void*)config);
    pthread_create(&thread2, NULL, thread_func, (void*)config);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
