int commandHandler(char** commands, int maxExecutionTime) {
    pid_t pid;
    int status = 0;
    FILE* logFile = fopen("log.txt", "w");
    if (!logFile) {
        return 0;
    }

    for (int i = 0; i < sizeof(commands) / sizeof(char*); i++) {
        pid = fork();
        if (pid == 0) {
            // Child process
            execl("/bin/sh", "/bin/sh", "-c", commands[i], NULL);
            exit(1);
        } else if (pid > 0) {
            // Parent process
            int timeout = kill(pid, SIGALRM);
            sleep(maxExecutionTime);
            int ret = waitpid(pid, &status, WNOHANG);
            if (!ret) {
                printf("Timeout exceeded for command %s\n", commands[i]);
                return 0;
            }
        } else {
            // Error forking
            printf("Error forking process\n");
            return 0;
        }

        // Output redirection
        FILE* file = fopen("output.txt", "w+");
        dup2(file, STDOUT_FILENO);
        fclose(file);

        // Log command output and error
        fprintf(logFile, "%s\n", commands[i]);
        fflush(logFile);

        if (WIFEXITED(status)) {
            printf("Command %s executed successfully\n", commands[i]);
            return 1;
        }
    }

    fclose(logFile);
    return 0;
}

int main(int argc, char* argv[]) {
    char** commands = {"command1", "command2", ...};
    int maxExecutionTime = 10; // seconds
    commandHandler(commands, maxExecutionTime);
    return 0;
}
