#include <unistd.h>
#include <time.h>
#include <signal.h>

#define MAX_FILE_SIZE 1000000
#define MAX_THREADS 10
#define LOG_FILE "log.txt"

int fileProcessor(char *file_path, int max_execution_time) {
    // Initialize variables and data structures
    pthread_t threads[MAX_THREADS];
    FILE *file = fopen(file_path, "r+");
    if (file == NULL) return 0;

    // Read and process the file in parallel
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_create(&threads[i], NULL, fileWorker, (void *)file);
    }

    // Wait for all threads to finish
    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    fclose(file);

    return 1;
}

void *fileWorker(void *file) {
    FILE *f = file;
    char buffer[1024];
    int num_lines = 0;

    // Process the file line by line
    while (fgets(buffer, sizeof(buffer), f) != NULL) {
        num_lines++;
    }

    fclose(f);

    return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <file_path> <max_execution_time>\n", argv[0]);
        return 1;
    }

    fileProcessor(argv[1], atoi(argv[2]));

    return 0;
}
