using System;
using System.Security.Cryptography;
using System.Text;

public static byte[] DecryptAescbc(byte[] cipherText, byte[] encryptionKey, byte[] initializationVector, int paddingScheme = 0, byte[] hmacSignature = null, byte[] hmacKey = null)
{
    using var aes = Aes.Create();
    aes.Key = encryptionKey;
    aes.IV = initializationVector;

    using var decryptor = aes.CreateDecryptor();

    using var ms = new MemoryStream(cipherText);
    using var cs = new CryptoStream(ms, decryptor, CryptoStreamMode.Read);

    byte[] decryptedBytes = new byte[cs.Length];
    int bytesRead = cs.Read(decryptedBytes, 0, decryptedBytes.Length);

    if (paddingScheme == 1) // PKCS5
    {
        var pkcs5Padding = new PKCS5 Padding();
        decryptedBytes = pkcs5Padding.GetUnpaddedData(decryptedBytes);
    }
    else if (paddingScheme == 2) // ISO7816-4
    {
        var iso78164Padding = new Iso7816_4 Padding();
        decryptedBytes = iso78164Padding.GetUnpaddedData(decryptedBytes);
    }
    else // PKCS7 default
    {
        var pkcs7Padding = new PKCS7 Padding();
        decryptedBytes = pkcs7Padding.GetUnpaddedData(decryptedBytes);
    }

    if (hmacSignature != null && hmacKey != null)
    {
        using var sha256 = SHA256.Create();
        byte[] hmacBytes = sha256.ComputeHash(decryptedBytes);

        for (int i = 0; i < hmacBytes.Length; i++)
        {
            if (hmacBytes[i] != hmacSignature[i])
                throw new Exception("Decryption failed: HMAC signature mismatch");
        }
    }

    return decryptedBytes;
}
