#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the maximum number of headers per request and response size limit
#define MAX_HEADERS 1000
#define RESPONSE_SIZE_LIMIT 1024 * 1024 // 1MB

// Define the possible states of an HTTP request context
enum {
    PENDING,
    IN_PROGRESS,
    COMPLETED
};

typedef struct {
    uint64_t requestId;
    enum {PENDING, IN_PROGRESS, COMPLETED} state;
    size_t headerCount;
    char** headers; // dynamically allocated list of response headers
} RequestContext;

// Function to manage the dynamic array of HTTP request contexts
RequestContext* manageRequestContexts(int capacity, pthread_mutex_t* lock) {
    RequestContext* ctxArray = (RequestContext*)malloc(capacity * sizeof(RequestContext));
    for (int i = 0; i < capacity; i++) {
        ctxArray[i].requestId = 0;
        ctxArray[i].state = PENDING;
        ctxArray[i].headerCount = 0;
        ctxArray[i].headers = NULL;
    }
    return ctxArray;
}

// Function to add a response header to the context
int addResponseHeader(RequestContext* ctx, const char* key, const char* value) {
    // Lock the critical section for concurrent access
    pthread_mutex_lock(lock);

    // Check if the request ID is valid and the state is PENDING or IN_PROGRESS
    if (ctx->requestId == 0 || ctx->state != PENDING && ctx->state != IN_PROGRESS)
        return -1; // invalid request ID or wrong state

    // Allocate memory for the new header
    char* newHeader = (char*)malloc(strlen(key) + strlen(value) + 2);
    sprintf(newHeader, "%s: %s", key, value);

    // Update the context's header count and list
    ctx->headerCount++;
    if (!ctx->headers)
        ctx->headers = &newHeader;
    else {
        char** newHeaders = (char**)realloc(ctx->headers, sizeof(char*) * (ctx->headerCount + 1));
        newHeaders[ctx->headerCount - 1] = newHeader;
        ctx->headers = newHeaders;
    }

    // Check if the response size exceeds the limit
    size_t newSize = 0;
    for (int i = 0; i < ctx->headerCount; i++) {
        newSize += strlen(ctx->headers[i]) + 1;
    }
    if (newSize > RESPONSE_SIZE_LIMIT) {
        free(newHeader);
        pthread_mutex_unlock(lock);
        return NULL; // response size exceeds the limit
    }

    // Unlock the critical section and log the new header addition
    pthread_mutex_unlock(lock);

    return ctx->headers;
}

// Function to release memory for a request context
void releaseRequestContext(RequestContext* ctx) {
    if (ctx->headers)
        free(ctx->headers);
    free(ctx);
}

// Example usage:
int main() {
    int capacity = 10; // initialize with an initial capacity of 10
    pthread_mutex_t lock;
    pthread_mutex_init(&lock, NULL);

    RequestContext* ctxArray = manageRequestContexts(capacity, &lock);

    // Add response headers to the context
    char* header1 = addResponseHeader(ctxArray + 0, "Content-Type", "text/html");
    if (header1)
        printf("Added header: %s\n", header1);
    else
        printf("Failed to add header due to response size limit.\n");

    // Release the context and its memory
    releaseRequestContext(ctxArray);

    return 0;
}

