        // Check if the UE context has enough space for a new PDU
        if (uecontext->pdu_list == NULL || uecontext->pdu_list->len + len > 1024 * 1024) { // adjust this limit as needed
            // If not, allocate more memory and reallocate the list
            size_t new_len = uecontext->pdu_list ? uecontext->pdu_list->len : 0;
            size_t total_len = new_len + len;
            char** new_pdu_list = (char**)realloc(uecontext->pdu_list, (total_len / sizeof(char*)) * sizeof(char*));
            if (!new_pdu_list) {
                // Handle allocation failure
                return;
            }
            uecontext->pdu_list = new_pdu_list;
            for (int i = 0; i < total_len / sizeof(char*); i++) {
                uecontext->pdu_list[i] = NULL;
