    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPICRCINDICATIONPDU_T;

http_context_t *context_array[MAX_ARRAY_SIZE];
int context_count = 0;
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

void init_logging() {
    log_file = fopen("crc_indication.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
    }
}

void cleanup_logging() {
    fclose(log_file);
}

void* allocate_structure(size_t size) {
    void *ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    return ptr;
}

int validate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Validate pdu structure
    if (pdu->rx_ue_tag == 0 || pdu->rnti < 0 || pdu->crc_tag < 0) {
        return 0; // Validation failed, discard the structure
    }
    return 1;
}

int add_http_context(http_context_t *context) {
    pthread_mutex_lock(&array_lock);
    if (context_count >= MAX_ARRAY_SIZE) {
        fprintf(stderr, "Array full, cannot add more contexts\n");
        pthread_mutex_unlock(&array_lock);
        return -1;
    }
    context_array[context_count++] = context;
    pthread_mutex_unlock(&array_lock);
    return 0;
}

void* handle_http_request(void *arg) {
    // Process the request
    http_context_t *context = (http_context_t*) arg;
    if (!context) {
        fprintf(stderr, "Invalid request ID\n");
        return NULL;
    }

    // Allocate and initialize pdu structure
    NFAPICRCINDICATIONPDU_T *pdu = allocate_structure(sizeof(NFAPICRCINDICATIONPDU_T));
    if (!pdu) {
        return NULL; // Allocation failed
    }

    // Validate pdu structure
    if (validate_pdu(pdu)) {
        // Append pdu to context
        context->pdu = pdu;
        add_http_context(context);
    } else {
        free(pdu); // Discard the structure and log a warning
        pthread_mutex_lock(&log_lock);
        fprintf(log_file, "Discarded invalid pdu\n");
        pthread_mutex_unlock(&log_lock);
    }

    return NULL; // Request processed successfully
}

int main() {
    init_logging();

    // Initialize cache mechanism

    while (1) {
        // Handle HTTP requests

        // Process each request in a separate thread
        pthread_t threads[1024];
        for (int i = 0; i < context_count; i++) {
            pthread_create(&threads[i], NULL, handle_http_request, context_array[i]);
        }

        // Wait for all threads to finish
        for (int i = 0; i < context_count; i++) {
            pthread_join(threads[i], NULL);
        }

        cleanup_logging();
    }

    return 0;
}
