NFAPI_RRC_UECONTEXT_T* nfapi_ue_context = NULL;
size_t ue_context_size = 0;
size_t ue_context_capacity = MAX_CTX;

int init_ue_context() {
    if (nfapi_ue_context != NULL) {
        return -1; // Already initialized
    }

    nfapi_ue_context = malloc(MAX_CTX * sizeof(NFAPI_RRC_UECONTEXT_T));
    if (nfapi_ue_context == NULL) {
        return -2; // Memory allocation failed
    }

    ue_context_size = 0;
    ue_context_capacity = MAX_CTX;

    return 0; // Initialization successful
}

int add_pdu_to_ue_context(uint32_t ue_id, enum { IDLE, CONNECTED } rrc_state, NFAPI_UL_CCCH_pdu_t* pdu) {
    if (nfapi_ue_context == NULL || ue_context_size >= ue_context_capacity) {
        return -1; // UE context not initialized or out of memory
    }

    NFAPI_RRC_UECONTEXT_T* ctx = &nfapi_ue_context[ue_context_size];
    ctx->ue_id = ue_id;
    ctx->rrc_state = rrc_state;
    if (ctx->pdu_list.size + sizeof(NFAPI_UL_CCCH_pdu_t) > ctx->pdu_list.capacity) {
        // Resize the PDU list
        ctx->pdu_list.pdus = realloc(ctx->pdu_list.pdus, 
            (ctx->pdu_list.size + MAX_PDU) * sizeof(NFAPI_UL_CCCH_pdu_t));
        if (ctx->pdu_list.pdus == NULL) {
            return -2; // Memory allocation failed
        }

        ctx->pdu_list.capacity = ctx->pdu_list.size + MAX_PDU;
    }

    memcpy(&ctx->pdu_list.pdus[ctx->pdu_list.size], pdu, sizeof(NFAPI_UL_CCCH_pdu_t));
    ctx->pdu_list.size++;

    return 0; // PDU added successfully
}

int validate_ue_context() {
    for (size_t i = 0; i < ue_context_size; i++) {
        NFAPI_RRC_UECONTEXT_T* ctx = &nfapi_ue_context[i];
        if (ctx->pdu_list.size > PDU_THRESHOLD) {
            // PDU list exceeds threshold
            return -1;
        }

        if (ctx->rrc_state == CONNECTED && ctx->pdu_list.size < 2) {
            // Not enough PDUs for a connected state
            return -2;
        }
    }

    return 0; // UE context is valid
}

int clear_ue_context() {
    free(nfapi_ue_context);
    nfapi_ue_context = NULL;
    ue_context_size = 0;
    ue_context_capacity = MAX_CTX;

    return 0; // UE context cleared successfully
}

int report_memory_usage() {
    printf("Memory usage: %zu bytes\n", (size_t)malloc_usable_size(nfapi_ue_context));

    if (malloc_usable_size(nfapi_ue_context) > MEM_THRESHOLD) {
        // Memory usage exceeds threshold
        return -1;
    }

    return 0; // Memory usage is within limits
}

int main() {
    init_ue_context();

    for (size_t i = 0; i < ue_context_capacity; i++) {
