['```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.HashMap;
import java.util.Map;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.text.SimpleDateFormat;
import java.time.Duration;
import java.time.Instant;

public class ServiceManager {

    private Map<String, ServiceInstance> instances;
    private ScheduledExecutorService scheduler;
    private ExecutorService executor;

    public ServiceManager() {
        this.instances = new HashMap<>();
        this.scheduler = Executors.newScheduledThreadPool(1);
        this.executor = Executors.newCachedThreadPool();
    }

    public void startInstance(String id) {
        if (!instances.containsKey(id)) {
            instances.put(id, new ServiceInstance(id));
            scheduler.scheduleAtFixedRate(() -> checkHealth(id), 0, 10000, java.util.concurrent.TimeUnit.MILLISECONDS); // health check every 10 seconds
        }
    }

    public void stopInstance(String id) {
        if (instances.containsKey(id)) {
            scheduler.shutdownNow();
            instances.get(id).shutdown();
            instances.remove(id);
        }
    }

    public void shutdown() {
        for (ServiceInstance instance : instances.values()) {
            instance.shutdown();
        }
        scheduler.shutdownNow();
        executor.shutdownNow();
    }

    private void checkHealth(String id) {
        ServiceInstance instance = instances.get(id);
        if (instance != null && !instance.isRunning()) {
            restartInstance(id, Duration.ofSeconds(5).toMillis()); // delay for 5 seconds
        }
    }

    private void restartInstance(String id, long delay) {
        executor.submit(() -> {
            try {
                Thread.sleep(delay);
                ServiceInstance instance = instances.get(id);
                if (instance != null) {
                    instance.restart();
                }
            } catch (InterruptedException e) {
                // ignore
            }
        });
    }

    public class ServiceInstance {

        private String id;
        private Process process;

        public ServiceInstance(String id) {
            this.id = id;
        }

        public void start() {
            process = Runtime.getRuntime().exec("your service command here");
        }

        public boolean isRunning() {
            return process.isAlive();
        }

        public void restart() {
            if (isRunning()) {
                try {
                    process.destroy();
                } catch (Exception e) {
                    // ignore
                }
            }
            start();
        }

        public void shutdown() {
            if (isRunning()) {
                try {
                    process.destroy();
                } catch (Exception e) {
                    // ignore
                }
            }
        }
    }
}

