#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <resolv.h>

#define MAX_HOSTNAME 256
#define MAX_IP_ADDRESS 16

typedef struct {
    char hostname[MAX_HOSTNAME];
    char ip_address[MAX_IP_ADDRESS];
} HostIP;

HostIP* hostip_cache = NULL;
int cache_size = 0;

void* my_realloc(void* ptr, size_t newsize) {
    return realloc(ptr, newsize);
}

int resolve_hostname(const char* hostname, char* ip_address) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd == -1) {
        return -1;
    }

    struct hostent* host = gethostbyname(hostname);
    if (!host) {
        close(sockfd);
        return -1;
    }

    const char* ip = inet_ntoa(*((struct in_addr*)host->h_addr));
    if (ip == NULL) {
        close(sockfd);
        return -1;
    }

    strncpy(ip_address, ip, MAX_IP_ADDRESS-1);
    close(sockfd);

    return 0;
}

int resolve_hostname_with_cache(const char* hostname, char* ip_address) {
    int i;
    for (i = 0; i < cache_size; i++) {
        if (!strcmp(hostip_cache[i].hostname, hostname)) {
            strncpy(ip_address, hostip_cache[i].ip_address, MAX_IP_ADDRESS-1);
            return 0;
        }
    }

    char temp_ip_address[MAX_IP_ADDRESS];
    int result = resolve_hostname(hostname, temp_ip_address);
    if (result == -1) {
        strcpy(ip_address, "Unable to resolve hostname");
        return -1;
    }

    // Add new entry to cache
    hostip_cache = my_realloc(hostip_cache, sizeof(HostIP)*(cache_size+1));
    memcpy(&hostip_cache[cache_size], &hostname, strlen(hostname)+1);
    memcpy(&hostip_cache[cache_size], &temp_ip_address, strlen(temp_ip_address)+1);
    cache_size++;

    strncpy(ip_address, temp_ip_address, MAX_IP_ADDRESS-1);

    return 0;
}

int main() {
    // Initialize the hostip_cache
    hostip_cache = my_realloc(hostip_cache, sizeof(HostIP)*5);
    cache_size = 5;

    char ip_address[MAX_IP_ADDRESS];
    resolve_hostname_with_cache("example.com", ip_address);

    return 0;
}
