int main(int argc, char **argv) {
    // Initialize variables
    int line_count = 0;
    FILE *output_file = stdout;
    char *delimiter = DEFAULT_DELIMITER;
    char *output_filename = DEFAULT_OUTPUT_FILE;
    int log_level = DEFAULT_LOG_LEVEL;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) {
            printf("Usage: %s [-h|--help] [input_file|directory]\n", argv[0]);
            return 0;
        } else if (strncmp(argv[i], "-d:", 3) == 0) {
            delimiter = &argv[i][2];
        } else if (strncmp(argv[i], "-o:", 3) == 0) {
            output_filename = &argv[i][2];
        } else if (strcmp(argv[i], "--verbose") == 0) {
            log_level = 4;
        }
    }

    // Process input files and streams
    if (argc > 1) {
        for (int i = 1; i < argc; i++) {
            char *input_filename = argv[i];
            FILE *input_file = fopen(input_filename, "r");
            if (input_file == NULL) {
                printf("Error opening file '%s'\n", input_filename);
                continue;
            }

            // Read lines from the file and count them
            regex_t reg;
            regcomp(&reg, delimiter, REG_EXTENDED);
            int line_num = 0;
            char line[1024];
            while (fgets(line, sizeof(line), input_file) != NULL) {
                if (regexec(&reg, line, strlen(line), NULL, 0) == 0) {
                    line_num++;
                }
            }
            regfree(&reg);

            // Print the line count
            printf("File '%s': %d lines\n", input_filename, line_num);
            line_count += line_num;

            fclose(input_file);
        }

        if (output_file != stdout) {
            FILE *f = fopen(output_filename, "w");
            fprintf(f, "%d total lines\n", line_count);
            fclose(f);
        } else {
            printf("%d total lines\n", line_count);
        }
    } else {
        printf("Usage: %s [-h|--help] [input_file|directory]\n", argv[0]);
    }

    return 0;
}
