['```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class AesCbcDecryptor
{
    public byte[] Decrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, int chunkSize)
    {
        using (var aes = Aes.Create())
        {
            aes.Key = encryptionKey;
            aes.IV = initializationVector;

            var decryptor = aes.CreateDecryptor();

            byte[] decryptedChunk = null;
            byte[] plaintext = new byte[ciphertext.Length];

            for (int i = 0; i < ciphertext.Length; i += chunkSize)
            {
                int readBytes = Math.Min(chunkSize, ciphertext.Length - i);
                var chunk = new byte[readBytes];
                Array.Copy(ciphertext, i, chunk, 0, readBytes);

                using (var memoryStream = new MemoryStream())
                {
                    using (var cryptoStream = new CryptoStream(memoryStream, decryptor, CryptoStreamMode.Write))
                    {
                        cryptoStream.Write(chunk, 0, readBytes);
                        cryptoStream.FlushFinalBlock();

                        decryptedChunk = memoryStream.ToArray();
                        Array.Copy(decryptedChunk, 0, plaintext, i, readBytes);
                    }
                }
            }

            return plaintext;
        }
    }

    public byte[] ValidateAndDecrypt(byte[] ciphertext, byte[] encryptionKey, byte[] initializationVector, int chunkSize)
    {
        var decryptedPlaintext = Decrypt(ciphertext, encryptionKey, initializationVector, chunkSize);

        using (var md5 = MD5.Create())
        {
            var checksum = md5.ComputeHash(decryptedPlaintext);
            var expectedChecksum = new byte[checksum.Length];
            Array.Copy(ciphertext, ciphertext.Length - checksum.Length, expectedChecksum, 0, checksum.Length);

            if (!BitConverter.ToString(checksum).Equals(BitConverter.ToString(expectedChecksum)))
            {
                Console.WriteLine("Decryption error: Invalid checksum");
                return null;
            }
        }

