// Function to count lines in an input source
void process_input_source(InputSource *input, char *delimiter, int *total_lines) {
    if (input->is_directory) {
        // Recursively count lines in all files within the directory
        DIR *dir = opendir(input->name);
        struct dirent *ent;
        while ((ent = readdir(dir)) != NULL) {
            char path[1024];
            sprintf(path, "%s/%s", input->name, ent->d_name);
            InputSource sub_input = {path, fopen(path, "r"), false};
            process_input_source(&sub_input, delimiter, total_lines);
            if (sub_input.file != NULL) {
                fclose(sub_input.file);
            }
        }
        closedir(dir);
    } else if (input->file != NULL) {
        // Count lines in the file
        char buffer[MAX_LINE_LENGTH];
        int line_count = 0;
        while (fgets(buffer, MAX_LINE_LENGTH, input->file) != NULL) {
            line_count++;
        }
        printf("File '%s' has %d lines.\n", input->name, line_count);
    }
}

