public class LargeCsvProcessor
{
    public List<CustomDataModel> ProcessLargeCsvFile(string csvFilePath, Func<CustomDataModel, bool> filterCriteria)
    {
        var dataModels = new List<CustomDataModel>();
        var chunkSize = 10000; // adjust this based on available RAM and dataset size

        using (var streamReader = File.OpenText(csvFilePath))
        {
            var headers = streamReader.ReadLine().Split(',');
            var chunk = new List<CustomDataModel>();

            int lineNumber = 0;
            while (!streamReader.EndOfStream)
            {
                lineNumber++;
                var line = streamReader.ReadLine();
                if (line != null)
                {
                    var dataModel = ParseCsvLine(line, headers);
                    chunk.Add(dataModel);

                    if (lineNumber % chunkSize == 0 || lineNumber == int.MaxValue)
                    {
                        // process the chunk
                        foreach (var data in chunk.Where(filterCriteria))
                        {
                            dataModels.Add(data);
                        }
                        chunk.Clear();
                    }
                }
            }

            // process the last chunk
            foreach (var data in chunk.Where(filterCriteria))
            {
                dataModels.Add(data);
            }
        }

        return dataModels;
    }

    private CustomDataModel ParseCsvLine(string line, string[] headers)
    {
        var dataModel = new CustomDataModel();
        var values = line.Split(',');

        if (values.Length != headers.Length)
        {
            // handle malformed record
        }

        for (int i = 0; i < values.Length; i++)
        {
            try
            {
                switch (headers[i])
                {
                    case "Id":
                        dataModel.Id = int.Parse(values[i]);
                        break;
                    case "Name":
                        dataModel.Name = values[i];
                        break;
                    // add more property mappings as needed
                }
            }
            catch (Exception)
            {
                // handle missing or malformed values
            }
        }

        return dataModel;
    }
