#include <stdlib.h>
#include <string.h>

// Define a structure to represent an NFAPI_RRC_UECONTEXT_T
typedef struct {
    uint32_t ue_id;
    NFAPI_RRC_STATE rrc_state;
    // Allocate a dynamically growing list of PDU structures
    size_t pdu_list_len;
    NFAPI_UL_CCCH_pdu_t** pdu_list;
} NFAPI_RRC_UECONTEXT_T;

// Define a function to manage an array of UE contexts
NFAPI_RRC_UECONTEXT_T* ue_context_array_init(size_t num_uecontexts) {
    NFAPI_RRC_UECONTEXT_T* ue_contexts = (NFAPI_RRC_UECONTEXT_T*)calloc(num_uecontexts, sizeof(NFAPI_RRC_UECONTEXT_T));

    // Initialize the array
    for (size_t i = 0; i < num_uecontexts; i++) {
        ue_contexts[i].pdu_list_len = 0;
        ue_contexts[i].pdu_list = NULL;
    }

    return ue_contexts;
}

// Add a new PDU to the UE context's list
void ue_add_pdu(NFAPI_RRC_UECONTEXT_T* ue, NFAPI_UL_CCCH_pdu_t* pdu) {
    // Lock access to prevent concurrent modifications
    pthread_mutex_lock(&ue->lock);

    // Resize the PDU list if necessary
    if (ue->pdu_list_len == 0 || ue->pdu_list == NULL) {
        size_t new_size = ue->pdu_list_len + 2;
        NFAPI_UL_CCCH_pdu_t** new_pdu_list = (NFAPI_UL_CCCH_pdu_t**)realloc(ue->pdu_list, new_size * sizeof(NFAPI_UL_CCCH_pdu_t*));
        ue->pdu_list = new_pdu_list;
    }

    // Add the PDU to the list
    if (ue->pdu_list_len >= 1) {
        memmove(&ue->pdu_list[1], &ue->pdu_list[0], (ue->pdu_list_len - 1) * sizeof(NFAPI_UL_CCCH_pdu_t*));
    }

    ue->pdu_list[0] = pdu;
    ue->pdu_list_len++;

    // Unlock access
    pthread_mutex_unlock(&ue->lock);
}

// Function to validate the integrity of a UE context's PDU list
bool ue_validate_pdu_list(NFAPI_RRC_UECONTEXT_T* ue) {
    // Lock access to prevent concurrent modifications
    pthread_mutex_lock(&ue->lock);

    if (ue->pdu_list_len < 0 || ue->pdu_list == NULL) {
        return false; // PDU list is invalid
    }

    for (size_t i = 0; i < ue->pdu_list_len; i++) {
        // Validate each PDU's integrity and contents
        if (!ue_validate_pdu(ue->pdu_list[i])) {
            return false; // At least one PDU is invalid
        }
    }

    // Unlock access
    pthread_mutex_unlock(&ue->lock);

    return true; // All PDUs are valid
}

// Function to release resources held by a UE context
void ue_context_free(NFAPI_RRC_UECONTEXT_T* ue) {
    for (size_t i = 0; i < ue->pdu_list_len; i++) {
        free(ue->pdu_list[i]);
    }

    free(ue->pdu_list);

    free(ue);
}

// Function to release resources held by a UE context and its PDUs
void ue_contexts_free(NFAPI_RRC_UECONTEXT_T** uecontexts, size_t num_uecontexts) {
    for (size_t i = 0; i < num_uecontexts; i++) {
        ue_context_free(uecontexts[i]);
    }

    free(uecontexts);
}
