#define MAX_FILENAME_LENGTH 50

char *rename_file(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return filename;

    char buffer[11];
    fread(buffer, 1, 10, file);
    fclose(file);

    time_t timestamp = time(NULL);
    srand((unsigned int)timestamp);
    char random_string[6];
    for (int i = 0; i < 5; i++) {
        random_string[i] = (char)(rand() % 26 + 'a');
    }
    random_string[5] = '\0';

    sprintf(filename, "%s-%ld-seq%05d-%s.txt", buffer, timestamp, (long)file_size(filename), random_string);

    return filename;
}

int file_size(char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return 0;

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fclose(file);

    return size;
}
