NFAPI_RRC_UECONTEXT_T *nfaapi_rrc_uecontext_init(size_t n) {
    NFAPI_RRC_UECONTEXT_T *uecontexts = (NFAPI_RRC_UECONTEXT_T *)malloc(n * sizeof(NFAPI_RRC_UECONTEXT_T));
    for (size_t i = 0; i < n; ++i) {
        uecontexts[i].pdu_list_size = 0;
        pthread_mutex_init(&uecontexts[i].pdu_list_lock, NULL);
    }
    return uecontexts;
}

void nfaapi_rrc_uecontext_add_pdu(NFAPI_RRC_UECONTEXT_T *uecontext, NFAPI_UL_CCCH_pdu_t *pdu) {
    pthread_mutex_lock(&uecontext->pdu_list_lock);
    if (uecontext->pdu_list_size >= uecontext->pdu_list_size + 1) {
        // resize the array
        size_t new_size = uecontext->pdu_list_size * 2;
        NFAPI_UL_CCCH_pdu_t **new_pdu_list = (NFAPI_UL_CCCH_pdu_t **)realloc(uecontext->pdu_list, new_size * sizeof(NFAPI_UL_CCCH_pdu_t *));
        for (size_t i = uecontext->pdu_list_size; i < new_size; ++i) {
            new_pdu_list[i] = NULL;
        }
        free(uecontext->pdu_list);
        uecontext->pdu_list = new_pdu_list;
    }
    if (!uecontext->pdu_list[uecontext->pdu_list_size]) {
        // allocate a new pdu
        NFAPI_UL_CCCH_pdu_t *new_pdu = (NFAPI_UL_CCCH_pdu_t *)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
        memcpy(new_pdu, pdu, sizeof(NFAPI_UL_CCCH_pdu_t));
        uecontext->pdu_list[uecontext->pdu_list_size] = new_pdu;
    } else {
        // update the existing pdu
        memcpy(uecontext->pdu_list[uecontext->pdu_list_size], pdu, sizeof(NFAPI_UL_CCCH_pdu_t));
    }
    ++uecontext->pdu_list_size;
    pthread_mutex_unlock(&uecontext->pdu_list_lock);
}

void nfaapi_rrc_uecontext_validate_pdu_list(NFAPI_RRC_UECONTEXT_T *uecontext) {
    pthread_mutex_lock(&uecontext->pdu_list_lock);
    for (size_t i = 0; i < uecontext->pdu_list_size; ++i) {
        if (!uecontext->pdu_list[i]) {
            // log an error
            printf("Invalid PDU in list\n");
        }
    }
    pthread_mutex_unlock(&uecontext->pdu_list_lock);
}

void nfaapi_rrc_uecontext_destroy(NFAPI_RRC_UECONTEXT_T *uecontext) {
    for (size_t i = 0; i < uecontext->pdu_list_size; ++i) {
