    result.file_summary_file = fopen("file_summary.txt", "w");
    if (!result.file_summary_file) {
        fprintf(error_log_file, "Error opening file summary file.\n");
        return;
    }

    DIR *dir = opendir(directory_path);
    if (dir == NULL) {
        fprintf(error_log_file, "Error accessing directory: %s\n", directory_path);
        return;
    }

