            continue;
        }

        char category[65];
        sprintf(category, "%s_%x_%llx_%.16s",
                file_type,
                (unsigned) time(NULL),
                (long long) ftell(file),
                rand_str(16));

        if (!strstr(category, "_corrupted")) {
            category[64] = '\0'; // Ensure category name does not exceed 64 characters
        }

        // Initialize Item structures and populate list
        for (int i = 0; i < item_list_size; i++) {
            Item *item = &item_list[i];
            item->id = i;
            item->value = (double) rand() / RAND_MAX;
        }

        // Process file contents
        fseek(file, 0, SEEK_END);
        long fileSize = ftell(file);
        rewind(file);

        char buffer[fileSize + 1];
        fread(buffer, sizeof(char), fileSize, file);
        buffer[fileSize] = '\0'; // Null-terminate the string

        // Extract new traffic categories and naming conventions
        int category_count = 0;
        for (int i = 0; i < initial_states_count; i++) {
            if (fsa->states[initial_states[i]].next_state == last_state) {
                category_count++;
            }
        }

        char **file_categories = malloc(category_count * sizeof(char *));
        for (int i = 0; i < category_count; i++) {
            file_categories[i] = strdup(category);
        }

        // Generate and store summary report
        int file_sizes[category_count];
        int file_counts[category_count];

        for (int i = 0; i < category_count; i++) {
            file_counts[i] = 1;
            file_sizes[i] = fileSize;
        }

        fprintf(result.file_summary_file, "Timestamp: %s\n", asctime(localtime(time(NULL))));
        fprintf(result.file_summary_file, "Summary Report:\n");
        for (int i = 0; i < category_count; i++) {
            fprintf(result.file_summary_file, "%s: %d files, avg. size: %.2f KB\n",
                    file_categories[i],
                    file_counts[i],
                    (double) file_sizes[i] / 1024);
        }

        // Write top 10 most frequent file types
        int file_type_counts[256];
        for (int i = 0; i < category_count; i++) {
            char c = file_categories[i][0];
            file_type_counts[c]++;
        }
        for (int i = 0, j = 9; i < 10 && j >= 0; i++, j--) {
            int max_index = -1;
            int max_count = 0;
            for (int k = 0; k <= 'z'; k++) {
                if (file_type_counts[k] > max_count) {
                    max_index = k;
                    max_count = file_type_counts[k];
                }
            }
            fprintf(result.file_summary_file, "Top %d: %c (%d)\n", j + 1, max_index, max_count);
        }

        // Close files and handle errors
        fclose(file);
    }

    closedir(dir);

    // Handle potential deallocation failures gracefully
    for (int i = 0; i < category_count; i++) {
        free(file_categories[i]);
    }
    free(file_categories);

    fclose(result.file_summary_file);
}

char *rand_str(int length) {
