void insert_at(HTTP_REQUEST_PDU_T** list, int pos, HTTP_REQUEST_PDU_T* elem) {
    // Ensure sufficient memory for insertion
    if (*list == NULL || (pos > 0 && (int)(*list + pos - 1)) >= MAX_SIZE) {
        resize_list(list);
    }

    memmove(*list + pos, *list + pos - 1, sizeof(HTTP_REQUEST_PDU_T));
    memcpy(*list + pos, elem, sizeof(HTTP_REQUEST_PDU_T));
}

// Function to delete an element at a specified position in the list
