class PluginLoader {
  constructor() {
    this.loadedPlugins = {};
    this.pluginQueue = [];
    this.cachedPlugins = {};
    this.dependencies = new Map();
    this.queues = new Map();
  }

  loadPlugin(pluginName) {
    if (!this.cachedPlugins[pluginName]) {
      const plugin = require(`./plugins/${pluginName}.js`);
      this.cachedPlugins[pluginName] = plugin;
    }
    return this.cachedPlugins[pluginName];
  }

  addDependency(plugin, dependencies) {
    this.dependencies.set(plugin, dependencies);
  }

  loadDependencies(plugin) {
    if (this.queues.has(plugin)) {
      return Promise.all(this.queues.get(plugin));
    }
    const deps = this.dependencies.get(plugin);
    if (!deps || !deps.length) {
      return Promise.resolve();
    }
    const queue = [];
    for (const dep of deps) {
      queue.push(this.loadPlugin(dep));
    }
    this.queues.set(plugin, queue);
    return Promise.all(queue);
  }

  executePlugin(plugin) {
    return this.loadDependencies(plugin).then(() => {
      const pluginInstance = this.cachedPlugins[plugin];
      if (!pluginInstance) {
        throw new Error(`Failed to load plugin ${plugin}`);
      }
      return pluginInstance();
    });
  }

  loadPlugins() {
    for (const plugin of Object.keys(this.cachedPlugins)) {
      this.executePlugin(plugin);
    }
  }

  errorHandling(err) {
    console.error(err);
    if (err.plugin) {
      delete this.cachedPlugins[err.plugin];
    }
  }
}

module.exports = PluginLoader;
