#include "hiredis/hiredis.h"

#define MAX_CLIENTS 1000
#define BUFFER_SIZE 1024

typedef struct {
    redisContext *rc;
    int client_fd;
} CacheClient;

CacheClient cache_clients[MAX_CLIENTS];
int num_clients = 0;

void init_redis_cache() {
    for (int i = 0; i < MAX_CLIENTS; i++) {
        cache_clients[i].rc = redisConnect("localhost:6379");
        if (cache_clients[i].rc != NULL) {
            printf("Connection to Redis failed - %s\n", redisError(cache_clients[i].rc));
            exit(1);
        }
    }
}

void cache_image(char *image_data, int image_size) {
    for (int i = 0; i < num_clients; i++) {
        redisReply *reply = redisCommand(cache_clients[i].rc, "SET myimage %b", image_data, image_size);
        if (reply == NULL || reply->type != REDIS_REPLY_OK) {
            printf("Error caching image: %s\n", reply->str);
            freeReply(reply);
        }
    }
}

void retrieve_cached_image(char *image_key) {
    for (int i = 0; i < num_clients; i++) {
        redisReply *reply = redisCommand(cache_clients[i].rc, "GET myimage");
        if (reply != NULL && reply->type == REDIS_REPLY_STRING) {
            printf("Retrieved cached image: %s\n", reply->str);
            freeReply(reply);
