        NFAPI_UL_CCCH_pdu_t **new_pdu = (NFAPI_UL_CCCH_pdu_t **)malloc(sizeof(NFAPI_UL_CCCH_pdu_t *));
        *new_pdu = pdu;
        // Add the new PDU to the list
        ue_context->pdus = (NFAPI_UL_CCCH_pdu_t **)realloc(ue_context->pdus, (ue_context->pdu_count + 1) * sizeof(NFAPI_UL_CCCH_pdu_t *));
        ue_context->pdus[ue_context->pdu_count] = new_pdu;
        ue_context->pdu_count++;
