    // Find the PDU with the given ID in the list
    for (int i = 0; i < ue_context->pdu_count; i++) {
        if (((NFAPI_UL_CCCH_pdu_t *)ue_context->pdus[i])->pdu_id == pdu_id) {
            // Remove the PDU from the list and free its memory
            free(ue_context->pdus[i]);
            memmove(ue_context->pdus + i, ue_context->pdus + i + 1, (ue_context->pdu_count - i - 1) * sizeof(NFAPI_UL_CCCH_pdu_t *));
            ue_context->pdu_count--;
            break;
        }
    }
}

