    for (int i = 0; i < ue_context->pdu_count; i++) {
        if (((NFAPI_UL_CCCH_pdu_t *)ue_context->pdus[i])->size >= threshold) {
            // Compress the PDU using a lossless algorithm
            NFAPI_UL_CCCH_pdu_t *compressed_pdu = (NFAPI_UL_CCCH_pdu_t *)malloc(sizeof(NFAPI_UL_CCCH_pdu_t));
