    for (int i = 0; i < ue_context->pdu_count; i++) {
        if (((NFAPI_UL_CCCH_pdu_t *)ue_context->pdus[i])->data != NULL && get_compressed_size(((NFAPI_UL_CCCH_pdu_t *)ue_context->pdus[i])->data) > 0) {
