                    if (!uf.find(i, j)) {
                        System.out.println("Disjoint pair: " + arr[i] + ", " + arr[j]);
                    }
                    System.out.println("Time taken: " + (System.nanoTime() - start) + " ms");
                }
            }
        }
        return uf.getCount();
    }

    public static class UnionFind {
        private int[] parent;
        private int count;

        public UnionFind(int n) {
            parent = new int[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
            count = n;
        }

        public boolean find(int a, int b) {
            if (parent[a] != parent[b]) {
                return false;
            }
            return true;
        }

        public void union(int a, int b) {
            int rootA = findRoot(a);
            int rootB = findRoot(b);
            if (rootA != rootB) {
                parent[rootA] = rootB;
                count--;
            }
        }

        private int findRoot(int i) {
            while (parent[i] != i) {
                parent[i] = parent[parent[i]];
                i = parent[i];
            }
            return i;
        }

        public int getCount() {
            return count;
        }
    }
}
