    private boolean validatePDUList() {
        long age = System.currentTimeMillis() - lastPDUUpdate;
        if (age > AGE_THRESHOLD) {
            purgeOldPDUs();
        }
        return true; // Assuming the list is valid
    }

    private void purgeOldPDUs() {
        // Remove PDUs older than the threshold
        // ...
    }
}

public class DisjointPairCounter {
    public static int countDisjointPairs(int[] array) {
        UnionFind uf = new UnionFind(array.length);

        for (int i = 0; i < array.length; i++) {
            for (int j = i + 1; j < array.length; j++) {
                if (array[i] != array[j]) {
                    long start = System.nanoTime();
                    boolean disjoint = uf.find(i) != uf.find(j);
                    long end = System.nanoTime();
                    System.out.println("Pair (" + i + ", " + j + ") is " + (disjoint ? "disjoint" : "not disjoint") + " in " + (end - start) + " ms");
                }
            }
        }

        return uf.countSets();
    }
}

class UnionFind {
    private int[] parent;
    private int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            if (rank[rootX] > rank[rootY]) {
                parent[rootY] = rootX;
            } else if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                rank[rootX]++;
            }
        }
    }

    public int countSets() {
        int setCount = 0;

        for (int i = 0; i < parent.length; i++) {
            if (parent[i] == i) {
                setCount++;
            }
        }

        return setCount;
    }
}
