    pthread_t thread[10];
    int chunk_index = 0;

    while(file_size > 0) {
        off_t start = file_size >= CHUNK_SIZE ? (file_size - CHUNK_SIZE): file_size;
        off_t end = start;

        Record* current_chunk = records + (chunk_index * CHUNK_SIZE / sizeof(Record));
        for(int i = 0; i < (end - start) / sizeof(Record); i++) {
            // Validate and parse record
            if(validate_record(current_chunk[i])) {
